    parent_name
) VALUES
  (1, 'skill-ae53fbb31ca36bdcab70bec9d53c1c796bda1acd53fcc519c240b7c096610aec', 'Load-Bearing', 'standard', 1, 'STR', NULL, 'Training in managing physical load across the body. This skill represents refined technique in carrying, hauling, and supporting heavy objects using efficient body posture and breathing control. It serves as the foundation for all advanced feats of strength involving static or mobile weight. Those trained in Load-Bearing are known for unshakable footing and calculated strength application under stress.', NULL),
  (2, 'skill-a95e53ed2f2a4b40a24d6de251f4e24db48f49a6fd15562feaf0a6f15fc5ce58', 'Powerlifting', 'standard', 2, 'STR', NULL, 'Focused on the exertion of maximum strength in short, controlled lifts. Powerlifting emphasizes raw force in foundational lift forms—often with explosive or peak-effort movement. While rooted in personal challenge, it’s frequently used to overcome immovable obstacles or demonstrate sheer might. This skill builds the base for more refined and specialized lifting techniques.', 'Load-Bearing'),
  (3, 'skill-0181e034a9a5704a47c62839825ea137d2259a74d32d3b3eecba3a12ec0d0b7a', 'Deadlift Mastery', 'standard', 3, 'STR', NULL, 'The lifter becomes one with the weight—executing a clean, grounded lift with spine-aligned control. This skill reflects perfection in lifting objects directly from the ground, whether for raw strength display or practical heavy hauling. Practitioners can move dead weight with surprising balance and control, avoiding wasted energy or strain. It is the mark of one who knows how to rise with power.', 'Powerlifting'),
  (4, 'skill-f56b9755e66be830baafe7bcf8c966064c2b1471edf186e552fdf77d59609d39', 'Max Squat', 'standard', 3, 'STR', NULL, 'This skill represents the perfected ability to lower and raise heavy loads using leg and core synergy. Max Squat is used when bearing weight that must be braced, absorbed, and controlled before movement. It symbolizes discipline under strain—knowing how to descend without collapse and rise without panic. Those trained in this skill are anchors in moments when stability is everything.', 'Powerlifting'),
  (5, 'skill-0c933be8483a807397605408addcc3e0568949794811a876365d87e9ace4b7ed', 'Clean and Press Pro', 'standard', 3, 'STR', NULL, 'A hybrid of power and control, this skill reflects the lifter’s ability to raise weight in stages and finish with an overhead drive. Clean and Press Pro represents both technical discipline and explosive follow-through. Often used in practical lifting or symbolic acts of victory, it’s a controlled storm of motion. Those who master it carry the mark of precision strength.', 'Powerlifting'),
  (6, 'skill-d50ede40afe8917e8b7603e28b06a3eed1e9590f519a0fc204731bf57b3255de', 'Endurance Carry', 'standard', 2, 'STR', NULL, 'Where Powerlifting is short and explosive, Endurance Carry is slow and relentless. This skill is about bearing weight over time—across distance, terrain, or repeated use. Practitioners know how to pace the body, conserve energy, and lock into a rhythm that carries them far beyond raw strength alone. It’s not a sprint—it’s the will to bear the burden until the job is done.', 'Load-Bearing'),
  (7, 'skill-79258814f8646231394d2e2508efad4e6126bd786ffcf39930998609b143833f', 'Long Haul March', 'standard', 3, 'STR', NULL, 'The art of walking with weight without breaking stride. Long Haul March reflects discipline in posture, footwork, and load adjustment over long distances. It is often trained for migrations, patrols, or missions where there is no relief until the end is earned. The journey isn’t lighter—but you carry it like it is.', 'Endurance Carry'),
  (8, 'skill-7a62becb7381cbc934509d3e85b27a1bc460e32f8a0f5fea5e44dd3ae500f01e', 'Farmers Walk', 'standard', 3, 'STR', NULL, 'A test of grip, stride, and spinal endurance, Farmers Walk trains the body to move under side-heavy or imbalanced load. This skill allows for controlled walking with weight in each hand—common in rural, industrial, or supply-based roles. It’s functional strength at its core, building patience and resilience through motion. When others drag, you walk like the weight belongs to you.', 'Endurance Carry'),
  (9, 'skill-a89ca809462df96890f1325d9bb778e5a5e6b11052037a4dc49e5d9e2499c032', 'Pack Shuffle', 'standard', 3, 'STR', NULL, 'Designed for forward motion under awkward or rear-weighted loads, Pack Shuffle emphasizes adaptability and pace. It is used when carrying full loads across terrain too unstable or narrow for full strides. Practitioners learn how to pivot, rest mid-march, and shift weight subtly with each step. Not fast, not flashy—just unstoppable.', 'Endurance Carry'),
  (10, 'skill-4231d82ef46e66a455461eb3810b9442e2c4c5e410f5d723ec087c1eaa613444', 'Bulk Transfer', 'standard', 2, 'STR', NULL, 'A team skill at heart, Bulk Transfer is the art of coordinating with others to move large or cumbersome objects. It focuses on timing, shared effort, and vocal or gesture-based signaling to maintain balance and prevent accidents. This skill is essential in labor, rescue, and construction scenarios where solo strength is not enough. It turns many into one—and weight into movement.', 'Load-Bearing'),
  (11, 'skill-3ec831c994aaddd72f41dd00d98f4fcd6bbe55cb099c88eda076643a227e5699', 'Coordinated Lift Leader', 'standard', 3, 'STR', NULL, 'This skill designates the one who commands rhythm and cues during a shared lift. A Coordinated Lift Leader ensures safety and unity across a group haul, adapting to shifting terrain or strain levels on the fly. It’s not just about lifting—it’s about directing energy where it''s needed most. Those trained in this role carry both the weight and the team.', 'Bulk Transfer'),
  (12, 'skill-914616277ecceabb9059164a591d6c61d12efbb563373dd50b4c6e5fc2d0359d', 'Group Weight Rhythm', 'standard', 3, 'STR', NULL, 'More than brute effort, this skill teaches attunement to group flow. Practitioners instinctively sync breathing, pace, and movement with others during a shared carry. It reduces shock, tilting, or drift—ensuring smoother motion for everyone involved. In a world where chaos breaks things, rhythm holds it all together.', 'Bulk Transfer'),
  (13, 'skill-aa58a77a748d58603ddad0e2eb50ca11e30cd6cd8664d84df9d8f14360ac07f9', 'Shift Weight Control', 'standard', 3, 'STR', NULL, 'This skill enables subtle redistribution of weight mid-motion—either to assist a struggling teammate or correct imbalance. Shift Weight Control is used in tight spaces, steep angles, or unstable settings where every pound must be placed with intent. It prevents disaster before it starts. The best practitioners make the hardest jobs look smooth.', 'Bulk Transfer'),
  (14, 'skill-0b25251c15ecee784110d34e0aea5ca150c64aa97002f3c6d8946a7a3fdd2cf7', 'Burst Power', 'standard', 1, 'STR', NULL, 'The ability to harness stored strength in a single, high-impact moment. Burst Power is used to deliver rapid, explosive force—whether breaking free from restraints, shoving obstacles, or initiating a powerful strike. It emphasizes controlled detonation of effort, not prolonged application. This skill is the foundation of all techniques where sudden strength must overwhelm resistance.', NULL),
  (15, 'skill-e183ec724f8ef7b3de32f24e6533549e7bc60ca67b7ee18b01c42e2c41455bd1', 'Door Breach', 'standard', 2, 'STR', NULL, 'Training focused on applying concentrated force to barriers, specifically doors, gates, or blockades. Door Breach combines timing, angle, and raw strength to create failure in hinges, locks, or latches. Often used in tactical or emergency situations, it allows entry without finesse—only sheer presence. The goal isn’t subtlety—it’s immediate access.', 'Burst Power'),
  (16, 'skill-e75f7f59f754825406900e136b6898926675b85c46a78825f0b50eb43ad9a753', 'Ram Charge', 'standard', 3, 'STR', NULL, 'A full-body impact designed to displace or disable targets or barriers with brute force. Ram Charge reflects precision in converting speed and mass into a forward strike, often initiated from a short distance. It’s used when there’s no time to slow down and no room for negotiation. Those who master it move like a battering ram in human form.', 'Door Breach'),
  (17, 'skill-37ef045612d37806ad7eb1cd77f36cc39f500deadd6a920e3c58b6090bff0dff', 'Hinge Pop', 'standard', 3, 'STR', NULL, 'A focused application of pressure designed to disrupt a structural weak point. Hinge Pop is commonly used to remove or dislocate mounted barriers like doors, panels, or trap lids. The technique relies on knowing where to strike—and how to do so with minimum wasted effort. It’s quiet, fast, and devastating when used correctly.', 'Door Breach'),
  (18, 'skill-58695f858fd74a50a3159368df3b3762d23e50bc43c5805e928565e157375e54', 'Jam Shear', 'standard', 3, 'STR', NULL, 'This skill targets mechanical or structural jams, applying sharp, decisive bursts of strength to shear, snap, or force movement. Jam Shear is used on tools, locked items, stuck panels, or pressure points that resist normal movement. Practitioners know how to shift their force sideways or diagonally for maximum leverage. In short: when it’s stuck, you make it move.', 'Door Breach'),
  (19, 'skill-3d289de4942a86c81c1dcfc20947b538449025539fb2be4580426d0863d60f21', 'Explosive Sprint', 'standard', 2, 'STR', NULL, 'A rapid, strength-driven dash meant to close short distances with overwhelming speed. Explosive Sprint isn’t about endurance—it’s about sudden propulsion. Useful for takedowns, charge openings, or escapes, this skill prioritizes raw thrust and leg drive over form. You don’t run with it—you launch.', 'Burst Power'),
  (20, 'skill-e323ea1fdcb13e0520495b0d7f2bb57b7c5d3d2be69f4b071b75e161bd314e13', 'Start Dash', 'standard', 3, 'STR', NULL, 'This skill perfects the moment when movement begins—the first step, the weight shift, the launch. Start Dash is trained for those who need the edge in reaction-based movement or combat openings. Whether from stillness or a crouch, it delivers instant motion when time is critical. It’s not how fast you run—it’s how fast you leave the ground.', 'Explosive Sprint'),
  (21, 'skill-f664ce736c6cb8b69f4aab68ac676b2ad11ddca7725340985d9d1e1ee0ec8601', 'Shoulder Tackle', 'standard', 3, 'STR', NULL, 'A kinetic strike using the shoulder to unbalance, topple, or displace a target. Shoulder Tackle converts linear momentum into close-range impact without needing a weapon. It’s used to break lines, burst through crowds, or slam opponents against surfaces. Practitioners are trained to absorb counter-force without losing balance.', 'Explosive Sprint'),
  (22, 'skill-401d2cf669315808fdeaf60add8b92c10228c99750f47cbf98d25389abdb48b2', 'Launch Leap', 'standard', 3, 'STR', NULL, 'A strength-based leap that emphasizes vertical or directional propulsion from a standing or moving position. Launch Leap is used to cross gaps, gain vertical advantage, or surprise targets with airborne aggression. This is not finesse—it’s the violent arc of controlled strength. Practiced users make jumps others won’t even attempt.', 'Explosive Sprint'),
  (23, 'skill-e02dc2fa9a018e5ed4c353db8d966d7b0ec91b635785de9632f09e07c984e263', 'Sledge Impact', 'standard', 2, 'STR', NULL, 'Specialization in delivering full-body or tool-assisted strikes with maximum momentum. Sledge Impact is not about speed—it’s about mass meeting motion. This skill is used when breaking through dense material, battering armor, or demolishing cover. It teaches how to brace for recoil and direct force cleanly into a target.', 'Burst Power'),
  (24, 'skill-6bfef7ec8d9f218a248a760e7db3ad462467d7bb5e1783829d347c4b99e85a69', 'Over The Top Swing', 'standard', 3, 'STR', NULL, 'A rotational strike or lift involving overhead momentum, often used with tools, beams, or improvised weapons. Over The Top Swing relies on coordinated timing of shoulders, spine, and arms to deliver crushing arcs. It’s used to breach cover, disable targets, or redistribute weight quickly. The swing doesn’t just land—it crashes.', 'Sledge Impact'),
  (25, 'skill-0fc661767a4062baf8fbb7658af066804c337e68c7b54e47b4c87ddc7a1be177', 'Rebound Control', 'standard', 3, 'STR', NULL, 'The art of managing reactive force after a strike or impact. Rebound Control is trained to prevent stumbles, drops, or unintended movement following high-force action. It’s especially valuable in confined areas, group lifts, or when wielding heavy tools. Skilled users absorb shock like it was never there.', 'Sledge Impact'),
  (26, 'skill-8bdadff9fc80388332f5092173aec6aa1ab875b59d5399a34a94a782ca47eb27', 'Impact Follow Through', 'standard', 3, 'STR', NULL, 'This skill extends momentum beyond initial contact—ensuring that strikes, lifts, or collisions finish with intent. Impact Follow Through prevents energy loss during critical moments, whether driving a ram, delivering a final blow, or throwing weight into a shove. It is not about stopping—it’s about pushing through the end of force.', 'Sledge Impact'),
  (27, 'skill-d01af42e44ac843babb448af51cb36a7fb8edb243f8409bf7249b0fe311d3498', 'Material Deformation', 'standard', 1, 'STR', NULL, 'This skill represents the application of strength to reshape, distort, or break solid objects through raw force. Material Deformation is the foundation for feats like bending metal, cracking stone, or crushing containers. Practitioners understand how to apply pressure efficiently to force objects beyond their natural limits. It''s a blend of patience, technique, and overwhelming strength.', NULL),
  (28, 'skill-2e1e14990c0c03e8581a72c2b3eb2155d652c4c9a8ab356f3a4a297b9ddf6a63', 'Metal Bend', 'standard', 2, 'STR', NULL, 'Focused on the distortion of rigid metallic objects using pure physical pressure. Metal Bend is used to warp bars, twist frames, or unfasten hardened pieces without tools. It requires constant pressure applied with precision and awareness of weak points. Those who master it can reshape what others see as permanent.', 'Material Deformation'),
  (29, 'skill-cbbcf657e32de9d099b575d1a66ddc089cad50661c185d709f6a78c5a9fda021', 'Iron Rod Twist', 'standard', 3, 'STR', NULL, 'A specialized expression of rotational power applied to long, resistant objects. Iron Rod Twist is used to coil, snap, or spiral rigid rods through torque and grip strength. It is most often performed as a display of control over cold steel or structural materials. To twist iron is to show that resistance is negotiable.', 'Metal Bend'),
  (30, 'skill-f1ec59572fd934206758ec35bd9340226c43429c6ec740fd5db8415fdf1e4205', 'Pry Bar Spread', 'standard', 3, 'STR', NULL, 'This skill focuses on leveraging force outward to split or open firmly locked or sealed spaces. Pry Bar Spread simulates the effect of prying open reinforced objects using nothing but raw arm and shoulder pressure. Practitioners learn to push outward while bracing the body for counterforce. It’s not about finesse—it’s about cracking the uncrackable.', 'Metal Bend'),
  (31, 'skill-51ed5aebc47cd566cf7e5d1504339a8fc946192f99da61380df045970442ee08', 'Horshoe Crush', 'standard', 3, 'STR', NULL, 'A feat of compacted grip strength and sheer will, this skill enables the crushing or folding of ring-shaped metals and similar structures. Horseshoe Crush is often trained for performance, intimidation, or demonstration of dominant strength. It''s one of the clearest visual signals of total hand control under resistance.', 'Metal Bend'),
  (32, 'skill-c638e8998f64bce25f33813e75bb08c0a14a478d2fb9535db96e7bfee0469878', 'Stone Crack', 'standard', 2, 'STR', NULL, 'Trained application of strength to brittle or dense surfaces with the intent to fracture. Stone Crack is used to test walls, break rocks, or disrupt ancient structures during excavation. It relies on consistent pressure and the ability to sense where the stress lines lie. Power meets patience in this calculated art.', 'Material Deformation'),
  (33, 'skill-1a57204cbabe319e69fed289ec1ea4cafe8dde8f411e63ee0a480307a8706bfa', 'Chisel Strike', 'standard', 3, 'STR', NULL, 'Chisel Strike channels controlled bursts of force through a blunt or sharpened edge, often used to begin separation or weaken structures. It''s trained for repeated, targeted impacts where precision and rhythm are more important than raw speed. The wielder becomes the hammer—and the strike becomes the solution.', 'Stone Crack'),
  (34, 'skill-214ca6d42091d6a4f98fa5af12f62993c34cdc28d60bb791a5bc8b4b0bbbe5dc', 'Wedge Split', 'standard', 3, 'STR', NULL, 'A skill in driving a wedge—or acting as one—through an object to force a split. Wedge Split combines angled pressure with patient, escalating force. Practitioners can drive through beams, bone, or barricade given enough leverage. It’s strength used not to lift, but to divide.', 'Stone Crack'),
  (35, 'skill-dcc87986ce64c270da4d1274d1886d54ef0e303d630f74ede98fb03a86ad5514', 'Masonry Fracture', 'standard', 3, 'STR', NULL, 'Mastery of breaking through stonework using repeated strikes or leveraged force. Masonry Fracture is used when precision demolition or breach work is needed without explosives or tools. The character becomes the force that makes the wall fall. It is physical tenacity shaped like a battering mantra.', 'Stone Crack'),
  (36, 'skill-3cf2ae3feb4a5c231305b96018e0045837e010f8d15eb05b9b87042cef17a350', 'Press Crush', 'standard', 2, 'STR', NULL, 'The art of compressing objects between two limbs or surfaces with intense, slow pressure. Press Crush is trained to crush containers, armor, or bone through unyielding closing force. It’s as much about control as it is about power—pressing without shaking, destroying without slipping.', 'Material Deformation'),
  (37, 'skill-483241b921972776cf9377adf2b49c69b48d429b4cb29bd0a8adc07ede4fcf29', 'Container Crush', 'standard', 3, 'STR', NULL, 'A refinement of Press Crush, this skill is focused on breaking enclosed objects such as chests, crates, or canisters. Container Crush is used when access is more important than preservation. The practitioner understands how to break through walls of resistance without needing tools. What’s sealed stays sealed—until you decide otherwise.', 'Press Crush'),
  (38, 'skill-83af58e805bf1d5d64f88fe5c528e1ae94c030883f0a1e75594b43e6d5c88311', 'Panel Buckle', 'standard', 3, 'STR', NULL, 'Specialized in applying force across wide, thin surfaces to cause bending or failure. Panel Buckle is used on gates, vehicle siding, or structural supports where a ripple effect of collapse is required. The user learns how to direct weight, angle, and bracing to fold materials inward or outward.', 'Press Crush'),
  (39, 'skill-b0ae9a1c268457b7096fcb21eae7a9e591219d2a63369013917740aba7294d74', 'Vise Clamp', 'standard', 3, 'STR', NULL, 'This skill represents the application of body or grip as a locking clamp to hold or crush objects between surfaces. Vise Clamp is used to immobilize, crush, or restrain items or enemies. It is often used in interrogation, restraint, or containment scenarios where escape is unacceptable. You don’t let go—because you are the vice.', 'Press Crush'),
  (40, 'skill-1b250ea199bec73d392caad39d1167d6edc43c81f20edead86eea52c52b94fc1', 'Projection', 'standard', 1, 'STR', NULL, 'The art of transferring strength into external motion—throwing, hurling, or launching with force and intent. Projection reflects your ability to shift weight from the body into a moving object. It is the foundation for all physical ranged applications, from tossing tools to throwing enemies. A well-trained throw doesn’t just move—it makes impact matter.', NULL),
  (41, 'skill-1a9c1817a0c751918484123f7dad152ff78819913c663f43865a0c1831f7ed81', 'Distance Throw', 'standard', 2, 'STR', NULL, 'This skill focuses on maximizing the range of thrown objects through perfect timing, explosive power, and release angle. Distance Throw is used when covering ground matters more than precision. From launching ropes to lobbing heavy objects, it’s about getting there fast and far. Your arm becomes a catapult.', 'Projection'),
  (42, 'skill-51cfc0937f839610c560a1bf51dab42d2160d9c3d7cb497fe0818cb153e98e85', 'Hammer Toss', 'standard', 3, 'STR', NULL, 'A rotational throw using core torque and shoulder control to launch a heavy object in a wide arc. Hammer Toss is ideal for weighted weapons, chained tools, or any object requiring spin to fly true. Practitioners understand how to build speed in motion before the final explosive release. The more it whirls, the farther it flies.', 'Distance Throw'),
  (43, 'skill-8472420ee314ea286bd9e68d61ebf9f8a20747ab8f11a1fdea17bd8e29b35ea4', 'Caber Heave', 'standard', 3, 'STR', NULL, 'Based on ancient trials of might, this skill captures the upward-forward launch of tall or awkwardly shaped objects. Caber Heave prioritizes posture, grip shift, and explosive rise from the hips to control tumbling mass. It’s not just about throwing—it’s about launching chaos with intent.', 'Distance Throw'),
  (44, 'skill-cb091c5d314cb8edfabce60e724f9ee8ba83f794f19c0b22ecc0586619c54f84', 'Overhead Fling', 'standard', 3, 'STR', NULL, 'A direct vertical-to-arc throw initiated from above the shoulders. Overhead Fling is ideal when clearing walls, tossing onto roofs, or sending objects over obstacles. It requires stable footing and momentum control to prevent self-injury or loss of direction. Height becomes your weapon.', 'Distance Throw'),
  (45, 'skill-17c9147c261ab0cfc86dd1fca0d3df9247cce0644b608bdaf5e3c82caf206b43', 'Accuracy Throw', 'standard', 2, 'STR', NULL, 'This skill hones the ability to hit specific targets or land objects precisely where needed. Accuracy Throw combines strength with line-of-sight calculation, object balance, and fingertip control. It’s trained for delivering payloads, triggering mechanisms, or striking enemies with certainty. Where you aim, it lands.', 'Projection'),
  (46, 'skill-b4c5015905469303e17649b042aa2896c1db3d9f3508d240be7ac2db208a3048', 'Pinpoint Drop', 'standard', 3, 'STR', NULL, 'A precision throw used for short-range delivery, often from elevation or into confined spaces. Pinpoint Drop allows careful placement of tools, packages, or weight without damage or alert. It blends patience and control—more archery than brute toss. The right hand, at the right angle, at the right time.', 'Accuracy Throw'),
  (47, 'skill-3ced626793fff50490a425a5296a9b6eb0c41ba04de0647672e594cb302ffaf7', 'Window Thread', 'standard', 3, 'STR', NULL, 'A throw trained to slip an object through tight gaps—windows, holes, cages, or between guards. Window Thread relies on posture adjustment, object rotation, and velocity tapering. Practitioners can bypass defenses or deliver aid in ways no other motion allows. It’s finesse cloaked in strength.', 'Accuracy Throw'),
  (48, 'skill-7adfd90ff7393ce536d55370c8ee51af873ed71753bbb611ebc91eb5a28c2028', 'Center Mass Lob', 'standard', 3, 'STR', NULL, 'A heavy-targeted throw focused on delivering impact at the core of a person or object. Center Mass Lob sacrifices spin and flash for reliable, thudding contact. It’s used to unbalance enemies, knock down constructs, or distract at close-to-mid range. You don’t aim for flair—you aim for the middle and make it hurt.', 'Accuracy Throw'),
  (49, 'skill-fcc01da5e53751c97854b9be48d3f96acaf14c436cbf69cde2b2bcbe33260902', 'Arc Control', 'standard', 2, 'STR', NULL, 'Arc Control refines how objects travel after leaving the hand—predicting rise, fall, and curve. Practitioners train to hit moving targets or pass over defenses while adjusting for wind, spin, and weight. It is both science and instinct—throwing not just hard, but smart.', 'Projection'),
  (50, 'skill-3baece2020a74d1b336ca5b2fb17be62af8132b1cd9d7b72e4d604f8b28b5db5', 'High Lobber', 'standard', 3, 'STR', NULL, 'A lofted throw used to reach high platforms, towers, or skyward targets. High Lobber builds on Arc Control by maximizing hang time and vertical reach. Often trained in siege, supply drops, or long-range signaling, this skill ensures the throw crests before it crashes. It’s the art of lobbing upward—and making it count.', 'Arc Control'),
  (51, 'skill-486ed247a603da02c26d48e8c8b165a15ceaced2f017495c0bc6661e62a1f45d', 'Skip Stone Arc', 'standard', 3, 'STR', NULL, 'A technique for sending flat or rounded objects in a low, bouncing trajectory across a surface. Skip Stone Arc is trained for distraction, multipoint impact, or water-based delivery. It combines launch angle, spin, and surface reading into one smooth motion. A throw that dances before it hits.', 'Arc Control'),
  (52, 'skill-e8303e9c054cf5dc3578ec3e0c64d9b594ceba287b0b187c8ab7f9ae42252ba4', 'Ricochet Planner', 'standard', 3, 'STR', NULL, 'The mastery of bounce and deflection, Ricochet Planner allows throws to hit indirect targets via walls, ceilings, or angled surfaces. This is trick-throw territory—used to bypass shields, blind corners, or create diversions. With enough control, even a miss can become a hit.', 'Arc Control'),
  (53, 'skill-a6945c534343dc4235a38c62c827a7e77593e2ab82385a24774c0bd1f6ae4f86', 'Stability & Bracing', 'standard', 1, 'STR', NULL, 'The core skill of rooting one’s body against shifting forces, impact, or uneven terrain. Stability & Bracing trains the use of posture, limb positioning, and muscle control to hold ground under stress. It enables power to be applied without losing footing or direction. Every motion becomes stronger when it begins from stillness.', NULL),
  (54, 'skill-c34ea8af14fa9109523451f5dd76ae80cce053a5b00805cb5d5c5984342b386d', 'Recoil Absorption', 'standard', 2, 'STR', NULL, 'Recoil Absorption allows the body to endure and redirect force without collapse. It is often used when firing large projectiles, catching heavy impacts, or standing through sudden shifts in pressure. Practitioners are trained to flex at the right joints and angles to dampen force like a living shock absorber. Absorbing doesn’t mean yielding—it means surviving.', 'Stability & Bracing'),
  (55, 'skill-e1ff2a7762e403a2812459dc8b0d5783852d9a826f3e98bcfd1f3b24122b8ed5', 'Shot Kick Down', 'standard', 3, 'STR', NULL, 'This skill focuses on the immediate bracing required to neutralize violent backward kick or snap. Shot Kick Down is essential for wielding massive tools, firing siege weapons, or resisting explosive pressure. Users learn how to plant and drop weight mid-action to stop being moved. You don’t fly back—you lock in.', 'Recoil Absorption'),
  (56, 'skill-c60ec8bfe296a7e034363436d956cc22ba37794810581d30f9c61ad3faa549c8', 'Blast Brace', 'standard', 3, 'STR', NULL, 'Blast Brace trains the body to anchor against forward or outward explosions of energy or debris. It is a reflexive stance taught to minimize displacement and protect vulnerable joints. The user becomes a wall, not a leaf. In the moment of blast, your footing decides who falls.', 'Recoil Absorption'),
  (57, 'skill-30b7e850fa9ad4dbf6a692880c968905a37e0430fe68d1f760d756351112361f', 'Force Recoil Mastery', 'standard', 3, 'STR', NULL, 'Mastery in the redirection of powerful rebound or blowback into usable counter-force. Force Recoil Mastery turns reaction into weapon—shifting energy from an enemy’s strike into your own return motion. It’s not just resistance—it’s repurposing. True control means nothing is wasted.', 'Recoil Absorption'),
  (58, 'skill-993b89482ae7d098622e3a736875328c863d5ee4816059104a06b6b5acb4de70', 'Counter-Pull', 'standard', 2, 'STR', NULL, 'A skill used when opposing forces threaten to drag or yank the user off balance. Counter-Pull trains grip anchoring, core tension, and offset alignment to resist directional pull. Whether holding onto a rope, a beast, or a collapsing platform—this skill keeps you where you chose to stand.', 'Stability & Bracing'),
  (59, 'skill-bd7df2820e9e54e6e11ee65bd81d7ef7242a2e031a26cfcad39d8176ff502faf', 'Tug Of War Anchor', 'standard', 3, 'STR', NULL, 'This skill is the peak of being the last line in a pull-based challenge. Tug Of War Anchor turns the body into a fixed point, capable of holding against sustained force. Used in rescues, tethers, or contests of might, this technique is all about locking down while the world pulls. You don’t budge—you are the anchor.', 'Counter-Pull'),
  (60, 'skill-b5719a50459ff1374161a0f8578171cfd441d25f120f3bc5a67a3e1cc4922511', 'Towline Hold', 'standard', 3, 'STR', NULL, 'Designed for long-duration holds under constant directional strain, Towline Hold trains the body to handle progressive fatigue while maintaining grip and stance. It’s often used in transport, climbing, or rescue when constant force threatens to drag the user out of place. You become a living post—the line holds because you do.', 'Counter-Pull'),
  (61, 'skill-2a80d327e74119f75ad8ea2ef2f3bf836fb22927c5ef8ae64411f003f4079331', 'Tension Anchor', 'standard', 3, 'STR', NULL, 'Tension Anchor allows the user to maintain tension across multiple vectors without buckling. Used in crossbeam suspension, live hauling, or group-based load transfers, it enables precise distribution of pull through the whole frame. The strain is real—but so is your control.', 'Counter-Pull'),
  (62, 'skill-246688d9ae826a0ede03e44b2c8f8cb47082cce9c3afb12ebb634a626cf88a7e', 'Reactive Balance', 'standard', 2, 'STR', NULL, 'Reactive Balance trains the body to recover equilibrium after slips, shoves, or failed footing. It’s not just about preventing a fall—it’s about reclaiming position mid-motion. Practitioners learn how to drop weight, roll tension, or twist joints into new grounding. You may be moved, but you are never down.', 'Stability & Bracing'),
  (63, 'skill-6dfa6c1c98571f576d7377362adf6dc6e5d17b40c18b9750d16aa9a8671db023', 'Foot Lock Pivot', 'standard', 3, 'STR', NULL, 'A technique used to pivot or twist under pressure without giving up base stability. Foot Lock Pivot is essential when shifting angles or redirection while bearing weight. It lets the user rotate with purpose—never dragged, never off center. Movement begins in the feet, and ends with control.', 'Reactive Balance'),
  (64, 'skill-fac880e559b3f4eb69da2d2e932dc85f28cb403949b5d73ecbd617d98bb79a4a', 'Wide Stance Plant', 'standard', 3, 'STR', NULL, 'This skill widens the body’s base to resist toppling forces, sway, or imbalance. Wide Stance Plant is used when lifting above the head, holding a flank, or enduring environmental resistance. It turns a person into a platform—one that won’t be moved unless it chooses to move.', 'Reactive Balance'),
  (65, 'skill-3b77a641f427b61f792fe26f13eb5a4e52ce64486586868e75acfb33a6777a24', 'Dynamic Centering', 'standard', 3, 'STR', NULL, 'The refined art of maintaining core alignment while in motion. Dynamic Centering ensures strength flows from the spine and hips no matter the action—lift, strike, pivot, or brace. Practitioners seem immune to stagger or sway. It’s not about standing still—it’s about staying centered even while moving.', 'Reactive Balance'),
  (66, 'skill-7a7bf62e33180cd3a403e69081a320b6ad95cab8a8f17aac8b7926c147428201', 'Grip Mastery', 'standard', 1, 'STR', NULL, 'Grip Mastery is the foundation of strength through the hands—training the muscles, tendons, and nerves for unmatched control. It allows for powerful holds, steady lifts, and secure grips in both calm and chaotic conditions. This skill affects every other form of manipulation, from weapons to climbing to restraint. A firm grasp isn’t just strength—it’s presence.', NULL),
  (67, 'skill-ab8f590250977c71e1def6e77899ac0a2c214b000852ed8c5eb2c1a6fd03eeed', 'Crushing Grip', 'standard', 2, 'STR', NULL, 'A specialization in applying overwhelming force through the hands to crush or disable. Crushing Grip is trained for snapping tools, bending bars, or neutralizing limbs. This is brute power focused into the fingers—meant to immobilize, destroy, or dominate through grip alone. A hold that tightens is a hold that ends things.', 'Grip Mastery'),
  (68, 'skill-bf326007da53c9e1ea4e7e43f756fd42bec490dba1acb4aa56970d47b93e5095', 'Bone Breaker Hold', 'standard', 3, 'STR', NULL, 'The precision use of grip strength to manipulate joints, tendons, and pressure points for pain, damage, or submission. Bone Breaker Hold isn’t a grapple—it’s a verdict. It allows a fighter to disable or control without weapons, relying entirely on anatomical targeting and merciless grip force. One squeeze, and the struggle stops.', 'Crushing Grip'),
  (69, 'skill-88cf42bf2845d5d1d9bfa37f0987dcf42ae2be0ee374ee64f36463a69dde8d11', 'Two Finger Pinch', 'standard', 3, 'STR', NULL, 'A feat of controlled strength and focus, this skill uses minimal contact—often just two fingers—to manipulate, lift, or restrain. Two Finger Pinch is practiced for traps, tools, delicate switches, or subtle pressure applications. Precision doesn’t mean weakness—sometimes less grip delivers more control.', 'Crushing Grip'),
  (70, 'skill-a1d30020f86c545c09aac5708f99fdb6790d69f4fbea6d83a678c6e646fab936', 'Grip Burst', 'standard', 3, 'STR', NULL, 'Grip Burst channels sudden explosive tension through the hands in one violent motion. It’s trained for snapping ropes, breaking restraints, or shocking opponents with unexpected strength. Unlike sustained holds, this is one moment of overwhelming force. When it goes off, it breaks things.', 'Crushing Grip'),
  (71, 'skill-5d3dcf3929c22d478b91fce65593cbfe8ce36e232d55a4c29366a37f07d2012a', 'Endurance Grip', 'standard', 2, 'STR', NULL, 'Endurance Grip trains the ability to maintain holds over long durations or extreme strain. Whether hanging, carrying, or climbing—this skill resists fatigue where others would fail. Practitioners develop layered grip control, shifting stress through muscles and joints like a living winch. You don’t drop until it’s over.', 'Grip Mastery'),
  (72, 'skill-530815f0a04a06189b41e109664563acae46c6e68a6cfc72c8c88b559db1d06a', 'Rope Hang', 'standard', 3, 'STR', NULL, 'This skill specializes in holding one’s full body weight from ropes, vines, or cables for prolonged time. Rope Hang trains shoulder and core assistance to extend grip duration. It’s used in climbing, suspensions, or descents where release means failure. It’s not just about not falling—it’s about never letting go.', 'Endurance Grip'),
  (73, 'skill-5c4e6b67b20d4ff3e298f6d8a61781b3f8c730fb592c2e3a8cf062949a0afc7e', 'Cliff Cling', 'standard', 3, 'STR', NULL, 'A climbing-based skill used to maintain a grip on irregular, natural, or shifting surfaces. Cliff Cling focuses on finger placement, micro-adjustment, and breath control. It''s not about strength alone—but endurance under strain in impossible angles. Practitioners hang where others slide.', 'Endurance Grip'),
  (74, 'skill-60006112ddbff014e1cc3272dc66a9a6b893c0fe81c854d9522e2f140024ad4c', 'Static Clamp', 'standard', 3, 'STR', NULL, 'Static Clamp enables the body to freeze in position with unyielding grip for balance, restraint, or stealth. It''s used to hold positions mid-climb, mid-lift, or mid-fight—without shifting or revealing motion. A single locked position becomes unshakable. This is the stillness that holds everything together.', 'Endurance Grip'),
  (75, 'skill-3a0361c760a94dd8a2dc93fb01ec2a61a0e385b6c22b409c4a08d25334f286d7', 'Fine Torque', 'standard', 2, 'STR', NULL, 'Fine Torque is the practice of applying subtle rotational force through the hands for mechanical or precision use. It’s used to twist, tighten, or align objects that require accuracy without over-application of strength. When a bolt must seal, a valve must adjust, or a mechanism must move just enough—this is the tool.', 'Grip Mastery'),
  (76, 'skill-92dd19190eed3d6a1ad5b8ceb553a2daaca374a94f2665afea896511e8e6300d', 'Valve Twist', 'standard', 3, 'STR', NULL, 'Valve Twist specializes in high-resistance rotational force over repetitive motion, especially on stiff or sealed devices. It’s trained for use in ventilation, hydraulics, or large mechanical objects where grip precision meets grunt force. The turn you make might save a life—or flood a chamber.', 'Fine Torque'),
  (77, 'skill-dd323082df3c7b9088ef951b00d1bdc3f4deca6e0b15e08492366e97dd581da5', 'Fine Gear Tensioning', 'standard', 3, 'STR', NULL, 'A finesse-driven skill for adjusting the balance between tightness and function in gears, pulleys, or small load systems. Fine Gear Tensioning allows manual fine-tuning under pressure. Too loose, and it slips—too tight, and it breaks. This is where hand strength meets mechanic’s instinct.', 'Fine Torque'),
  (78, 'skill-f34230d57ddf9927ecaa8a56c8155dc6e70e0d0b75bf7cc2f07ac540a63464ed', 'Tension Locking', 'standard', 3, 'STR', NULL, 'This skill locks ropes, belts, clamps, or braces into a fixed position using tension and counterforce. Tension Locking is used in rapid-load scenarios or when a mechanism must hold despite movement or pull. You set it, tighten it, and make damn sure it doesn’t come loose.', 'Fine Torque'),
  (79, 'skill-8b22705b4ecfcec6dc7fbd3f4b92559594adee7658b6025f769b5265a716dcd2', 'Agile Movement', 'standard', 1, 'DEX', NULL, 'Agile Movement is the foundation of responsive, fluid physical motion. It represents training in footwork, body control, and coordination across changing environments. Practitioners move with grace, adjust quickly, and reduce wasted motion. All advanced mobility techniques begin here.', NULL),
  (80, 'skill-df7da510a6fe1ab64a57e49687b9b1d239e647850ecb7ba49b542df06a591d11', 'Climbing', 'standard', 2, 'DEX', NULL, 'Climbing develops the body’s ability to ascend or maneuver vertically using arms, legs, and core alignment. It includes scaling natural surfaces, walls, and architectural structures. Practitioners learn grip discipline, route reading, and momentum control. When others stall, you keep rising.', 'Agile Movement'),
  (81, 'skill-9de6093b4dbe51fae25c0a292c6f43698e67d529ab3c11fa964e36e39f858ad0', 'Free Ascent', 'standard', 3, 'DEX', NULL, 'This skill focuses on unassisted climbing—without ropes, ladders, or gear. Free Ascent trains the mind and body to commit fully to vertical movement through calculated handholds and precise weight shifts. It’s raw motion against gravity, no safety net. Those who practice it don’t look down.', 'Climbing'),
  (82, 'skill-eceaeeee37ed543c7fe90f1f9ad3ac5d1bf00110f0b0c5c3f0dadfa2473aa960', 'Overhang Traverse', 'standard', 3, 'DEX', NULL, 'Overhang Traverse specializes in moving across or beneath suspended surfaces like cave ceilings, ledges, or angled obstacles. It trains lateral weight balance, swing transition, and grip endurance. It’s not enough to climb—you have to hang, shift, and move while suspended.', 'Climbing'),
  (83, 'skill-1eab631b806df5fce8ea3d81df49027b10213cb304c3af5e53a846636a6b5bf0', 'Rapid Descent', 'standard', 3, 'DEX', NULL, 'The art of moving downward quickly without losing control or safety. Rapid Descent is trained for rope-free drops, angled slides, or climbing down under pressure. It’s not just falling with style—it’s calculated, committed descent with full-body braking.', 'Climbing'),
  (84, 'skill-058fe66ca2ecca231a7fc064ca0034ab1297e74b2c5ce02523e7613216fbf913', 'Parkour', 'standard', 2, 'DEX', NULL, 'Parkour is the refined art of navigating obstacles through continuous motion. It includes vaulting, leaping, balancing, and redirecting momentum in tight or cluttered spaces. Practitioners view terrain as a pathway, not a barrier. This is speed without pause, motion without break.', 'Agile Movement'),
  (85, 'skill-c6a4cad2566871d02db14f4d881fec8347aa981b73cf76bf52ee74ad4ab9164f', 'Wall Run', 'standard', 3, 'DEX', NULL, 'Wall Run is the technique of using speed and foot placement to ascend vertical or angled walls briefly. It blends horizontal momentum with upward force to reach surfaces others can’t. This isn’t fantasy—it’s footwork, friction, and fearlessness.', 'Parkour'),
  (86, 'skill-2a2c4d6ad05e42fe393138f7e346ce1bf67129de54a5ce61425dffaf6189786b', 'Gap Vault', 'standard', 3, 'DEX', NULL, 'This skill focuses on transitioning over gaps using arms, legs, and torso in a unified burst. Gap Vault is used to clear fences, ledges, or roof spaces with fluid motion and a clean landing. It’s not about jumping farther—it’s about knowing exactly when and how to leap.', 'Parkour'),
  (87, 'skill-7a7cfb9d0fae78ed26b27de56ab8f131dfd265d4cf65ddf680133daaa039213c', 'Precision Landing', 'standard', 3, 'DEX', NULL, 'The ability to land from jumps or falls with minimal noise, shock, or loss of balance. Precision Landing trains foot placement, muscle tension release, and momentum bleed. Whether from rooftop or stairwell, the descent ends where you choose.', 'Parkour'),
  (88, 'skill-aae36d07312f912f02b69e83016721922d43680bacb48bc21046f9eaf8686197', 'Evasion', 'standard', 2, 'DEX', NULL, 'Evasion trains the body to avoid incoming danger through reactive movement. It includes ducking, diving, side-steps, rolls, and dodges—all trained under pressure. It’s not about escaping entirely—it’s about not being hit.', 'Agile Movement'),
  (89, 'skill-4684220a9e459d5255460157b98e87b104db73a27918c07e7930a16a7fb9ddfb', 'Combat Roll', 'standard', 3, 'DEX', NULL, 'Combat Roll enables the user to redirect force and reposition while under direct threat. It’s trained to escape grapples, cross short kill zones, or move under obstacles without exposing vital targets. Where others flinch—you flow.', 'Evasion'),
  (90, 'skill-597060ecc3d64401c8e785a9a4f24f9e28386284ebf1eb950f34087011280eaf', 'Quick Duck', 'standard', 3, 'DEX', NULL, 'A reflexive drop of the torso to avoid incoming force or visual detection. Quick Duck is trained to occur within a breath—slipping under blades, limbs, or watchful eyes. Sometimes the best way to win is simply not being where the strike lands.', 'Evasion'),
  (91, 'skill-e15fc5cb93257999635117ec4d8f47dc14753ad1bce31f68e5827974e2e7cf3e', 'Acrobatic Flip', 'standard', 3, 'DEX', NULL, 'A dynamic movement technique that turns evasion into opportunity. Acrobatic Flip includes flips, twists, and spinning recoveries used to reposition, disorient, or escape. While flashy, it is also efficient—redirecting threat momentum into unexpected space.', 'Evasion'),
  (92, 'skill-41a96526d5536f822d7762a0f024cb27aaab37a80cadc80cdbff47b994229e78', 'Close-Quarters Fundamentals', 'standard', 1, 'DEX', NULL, 'This skill represents basic unarmed combat training—stance, guard, and simple strikes. It focuses on staying balanced while moving, keeping hands where they can protect and attack, and reading an opponent’s intent at arm’s reach. Those trained in Close-Quarters Fundamentals don’t flail; every motion has a purpose, even when brawling turns ugly.', NULL),
  (93, 'skill-ed52e5e2863666864e2c687551710b70a612f16a765438e72c2c57d395a85ba8', 'Combat Footwork', 'standard', 2, 'DEX', NULL, 'The art of moving the body before the blow ever lands. Combat Footwork trains step placement, weight shifts, and angles of approach so a fighter is rarely where the enemy expects. Practitioners flow around force instead of meeting it head-on, turning tight spaces into a personal arena.', 'Close-Quarters Fundamentals'),
  (94, 'skill-b645f562671eeffdc530337112b43e2ff37d369b2e8e6b57d675cef46ea3cd0a', 'Guard Structure', 'standard', 2, 'DEX', NULL, 'This skill refines how the hands, arms, and torso form a living shield. Guard Structure emphasizes efficient blocks, tight guard positions, and quick resets between offense and defense. It keeps the fighter covered without wasting motion—every inch between strike and guard is measured.', 'Close-Quarters Fundamentals'),
  (95, 'skill-8d7f0cf705933b4867c939d20225e3bf9b256710bc8c740013cb66cd1d2297a1', 'Strike Timing', 'standard', 2, 'DEX', NULL, 'Focused on when to strike rather than just how. Strike Timing trains the ability to read openings, slip between an opponent’s motions, and punish hesitation. Those with this skill make even simple blows land like perfect answers to every mistake.', 'Close-Quarters Fundamentals'),
  (96, 'skill-2c65c663e017af748ffee24ea6085b6caab051882381bfa59de629b613faf22c', 'Pivot Step', 'standard', 3, 'DEX', NULL, 'This skill refines the spin and turn of the feet to slide around incoming attacks. Pivot Step lets a fighter rotate around a planted foot to change facing, evade linear strikes, or line up an opponent’s blind side without losing balance. It’s the difference between getting hit and simply not being there.', 'Combat Footwork'),
  (97, 'skill-cc896f66ee2c77ad5bc33397f5b295044f5d4caa421f61946b981580626b7a75', 'Off-Line Advance', 'standard', 3, 'DEX', NULL, 'Instead of charging straight in, this skill teaches angled steps that slip past the center of an enemy’s attack. Off-Line Advance lets a fighter close distance while drifting to safer lines, setting up flanks, throws, or counters. It feels like walking sideways through danger and coming out ahead.', 'Combat Footwork'),
  (98, 'skill-dbf1fd2a9b0ca758083c035a1b5bb307ca43dae95455be2e4034c2557ed5c828', 'Retreat & Re-Entry', 'standard', 3, 'DEX', NULL, 'The practiced dance of yielding ground without ceding control. Retreat & Re-Entry focuses on controlled backsteps, quick guard checks, and sudden surges back into range. When done well, an opponent thinks you’re fleeing—right up until you’re already in their space again.', 'Combat Footwork'),
  (99, 'skill-df76ba32edeae38043c4e64e59568875b32c4d35ca93a9f528e3912e197f8f44', 'High–Low Guard Shift', 'standard', 3, 'DEX', NULL, 'This skill trains rapid changes between protecting the head, torso, and legs. High–Low Guard Shift minimizes gaps when an opponent mixes levels—hooks, body shots, sweeps, and knees. Practitioners learn to flow their guard instead of chasing each strike.', 'Guard Structure'),
  (100, 'skill-a7e1d2e687f04746a9a905fa8a83a9adaf937a80c6f205f90e3a9d71a58925fb', 'Deflecting Blocks', 'standard', 3, 'DEX', NULL, 'Rather than meeting blows head-on, Deflecting Blocks guides strikes away with small angled motions. This reduces impact, opens counter-lines, and keeps the fighter’s frame intact over long exchanges. The best users make heavy hits slide off like they were never meant to land.', 'Guard Structure'),
  (101, 'skill-5ced92018e9a2cbf6ece795816eb9eb9d129f14aed3acdf1aea0b456e3c962e2', 'Clinch Entry', 'standard', 3, 'DEX', NULL, 'Clinch Entry teaches how to close into gripping range without eating a clean strike. It focuses on hand-checks, arm ties, and head position that smother an opponent’s offense. Once inside, the fighter can hold, turn, or feed the foe into a wall, ally, or the ground.', 'Guard Structure'),
  (102, 'skill-05d839a7b636d5a00ebb8db9b9f49c97e4ed842bb872e42ec7dd8193a1893ac1', 'Feint & Draw', 'standard', 3, 'DEX', NULL, 'This skill turns deception into a weapon. Feint & Draw teaches subtle false openings and half-committed strikes that provoke a reaction, exposing the real target. It’s a patient art—bait the mistake, then punish it.', 'Strike Timing'),
  (103, 'skill-3f8586068036b799737712cd1ffd4a22f4ad8a2c6ddf1cd865ef8f20b1ef4b54', 'Interrupting Jab', 'standard', 3, 'DEX', NULL, 'Focused on quick, sharp strikes that break an opponent’s rhythm before they can commit. Interrupting Jab tags advancing foes, spoils wind-ups, and resets their confidence. It doesn’t need to be powerful—just perfectly placed and perfectly timed.', 'Strike Timing'),
  (104, 'skill-474a3f54e00b15de5ede11744ef44db15cdc85cd365fa498acc6af813c6c5bc1', 'Follow-Through Chain', 'standard', 3, 'DEX', NULL, 'This skill trains linking blows together so that one hit naturally feeds the next. Follow-Through Chain reduces wasted recovery, allowing a fighter to flood an opening with controlled strikes. It’s not wild flurrying—it’s a planned cascade that ends the moment the job is done.', 'Strike Timing'),
  (105, 'skill-2d998cb471a020c0c58428d556cb5125365cac15eba3508faf2301e94bd88429', 'Stealth', 'standard', 1, 'DEX', NULL, 'Stealth is the core practice of remaining unseen, unheard, and unnoticed in hostile or sensitive environments. It encompasses posture, breath, balance, and awareness of surroundings. Practitioners know when to move—and more importantly, when not to. True stealth is presence reduced to shadow.', NULL),
  (106, 'skill-facebf5b506af49d746305d9c4cde7117a5e348c07cb1bb5abed39b8bc22ca05', 'Silent Movement', 'standard', 2, 'DEX', NULL, 'Silent Movement is the art of traversing space without producing sound. It trains weight distribution, footfall placement, and ambient noise masking. Whether indoors, outdoors, or across unstable terrain, your steps leave no echo. Sound is a footprint—you leave none.', 'Stealth'),
  (107, 'skill-7aa2af66070015ac949f4620b169fc6ee340cea2b444b147af437cebe3fbf0b9', 'Soft Footfall', 'standard', 3, 'DEX', NULL, 'This skill sharpens the physical discipline of minimizing noise with every step. Soft Footfall is essential for close-quarter infiltration, stalking, or movement on fragile surfaces. It’s not just about going quiet—it’s about being unheard even in total silence.', 'Silent Movement'),
  (108, 'skill-98508d5ea2c3697efbb2af9a9b4be0365191743489be14bd90e9c4cbc452942e', 'Breath Controll', 'standard', 3, 'DEX', NULL, 'Controlled Breathing trains respiratory rhythm and tension release to eliminate telltale signs of stress or activity. Used during ambush, waiting, or hiding in plain sight, this skill can slow pulse, suppress noise, and steady the mind. You vanish not just from sight—but from sound itself.', 'Silent Movement'),
  (109, 'skill-e3bf1075c3f943df63f05131562671a2224981921bb7053b72a41a60a9f2c17f', 'Surface Blend', 'standard', 3, 'DEX', NULL, 'A technique of syncing motion with surface type—carpet, stone, leaves, or sand—so that no step is out of place. Surface Blend teaches foot angle, pace, and pressure unique to each environment. The world becomes your cloak—walk like you belong.', 'Silent Movement'),
  (110, 'skill-6dd015a84cac1a9a4fa9f604f4ba7597de9bd116c47ebab9bfdb036ddfd98ff2', 'Shadowing', 'standard', 2, 'DEX', NULL, 'Shadowing allows a person to follow or observe another without detection. It trains distance management, cover use, timing, and sightline control. This is not stalking with intent—it’s watching without being seen. To follow well is to disappear just behind the edge of perception.', 'Stealth'),
  (111, 'skill-53a05468f6ee9db3a86a05dcd0097392ca297647e51492145d983424545be84a', 'Trail Target', 'standard', 3, 'DEX', NULL, 'A skill used to maintain consistent proximity to a moving subject without exposing yourself. Trail Target accounts for speed, path prediction, and obstacle negotiation. Practitioners remain close enough to observe—yet always just far enough not to be noticed.', 'Shadowing'),
  (112, 'skill-61e9dbf9996ae2bca155d7db465688a77109442f55e4d8eb57995e8af00c023f', 'Blind Spot Ride', 'standard', 3, 'DEX', NULL, 'This technique exploits a target’s natural visual and awareness blind spots—rear arcs, shoulder zones, and mental gaps. Blind Spot Ride allows extended tailing even in open or bright environments. It’s not invisibility—it’s perfect placement in human ignorance.', 'Shadowing'),
  (113, 'skill-29c404dd9b068c8f4610418dd12867d449358e1ea11bb6bad0748eda86c6a366', 'Predictive Cut Off', 'standard', 3, 'DEX', NULL, 'Predictive Cut Off allows a stealth user to move ahead of a target by anticipating their path. It’s used to intercept, ambush, or observe from in front rather than behind. This skill turns passive trailing into silent chess. The target never saw you—yet you’re already there.', 'Shadowing'),
  (114, 'skill-8325e5a49b2040c98e0dd752b368b601018cdf1d6efb49a389d39fbce1277395', 'Concealment', 'standard', 2, 'DEX', NULL, 'Concealment is the trained act of remaining unseen in open or limited-cover environments. It teaches body placement, environmental usage, and stillness discipline. Whether behind a curtain, within a bush, or beneath a bench, you’re not invisible—but you might as well be.', 'Stealth'),
  (115, 'skill-d51bb67453164fe77b52ee1f0f446abc945d83d574259a38ab0559a087db6328', 'Camouflage', 'standard', 3, 'DEX', NULL, 'Camouflage enhances concealment by using clothing, materials, or environment blending to break visual recognition. Practiced users can vanish even when technically visible. Shadows, mud, leaves, dust—it all becomes part of the cloak. It’s not trickery—it’s total immersion.', 'Concealment'),
  (116, 'skill-04261a96e163f12ca27fbfff75b9afeabd4dcc12e8bc7a3567d953e0d6b6bee6', 'Static Hide', 'standard', 3, 'DEX', NULL, 'This skill teaches how to hold a hidden position for extended periods without fidgeting, revealing breath, or giving away body cues. Static Hide is trained for stakeouts, ambush, or surviving sweeps. The body becomes part of the environment—waiting, watching, and undetected.', 'Concealment'),
  (117, 'skill-5ad413305da31619934186671cb8b825528a045360b241e84f603560240f9df0', 'Environment Meld', 'standard', 3, 'DEX', NULL, 'Environment Meld combines movement, material use, and posture to dissolve into the scene—trees, rocks, walls, even furniture. It is both instinct and calculation, requiring moment-to-moment adaptation to the space. You don’t hide in the environment. You become it.', 'Concealment'),
  (118, 'skill-32e692229f5c8918279a46021885878bb5607670db285da923912c42b5b2fe92', 'Melee Weaponry', 'standard', 1, 'DEX', NULL, 'The foundational skill of handling close-range weapons with precision, fluidity, and awareness. Melee Weaponry includes slashes, thrusts, counters, and footwork coordination. It''s not about strength alone—it''s about timing, angle, and body control. This is where blades and fists become extensions of the will.', NULL),
  (119, 'skill-9ae00108b6184d230db0133cd035ea1fcba738dbd2c0f3647b8a55ba069825bf', 'Bladed Weapons', 'standard', 2, 'DEX', NULL, 'A specialization in edged tools—knives, swords, axes, or exotic blades. Bladed Weapons emphasizes cutting lines, recovery angles, and targeting vulnerable points. Practitioners move with grace, minimizing wasted energy and maximizing threat. Each edge becomes a message—sharp, fast, and final.', 'Melee Weaponry'),
  (120, 'skill-04540e9a11e0e31d84906c9b744803854b88a0d9970fef4d25c8dc850efdccc0', 'Edge Flow', 'standard', 3, 'DEX', NULL, 'This skill teaches continuous motion with a blade—linking strikes, blocks, and transitions into an unbroken dance. Edge Flow ensures that the blade never stops moving, forcing opponents to react or retreat. It''s not just attacking—it''s painting with steel.', 'Bladed Weapons'),
  (121, 'skill-0ffdf0272f6d2ef001365a9fb41df50ac706e1e39a06e7fe79b567bbdad8d577', 'Precision Thrust', 'standard', 3, 'DEX', NULL, 'Precision Thrust refines the art of controlled piercing strikes. Used to bypass armor gaps, strike vital zones, or end fights cleanly, this skill is all about point control and depth. The thrust isn’t wild—it’s surgical.', 'Bladed Weapons'),
  (122, 'skill-3dbbb7b6ee18f41a6895760e36171ba4b7f5b4eb180b5aaf05fb1145cd5505e5', 'Parry Riposte', 'standard', 3, 'DEX', NULL, 'This skill trains the instant reversal of momentum—deflecting an attack and immediately countering. Parry Riposte requires nerve, timing, and perfect understanding of distance. When used properly, it punishes aggression with elegance.', 'Bladed Weapons'),
  (123, 'skill-07c0bfd4f136bcb29a792cd99d834f89a5b598e9781c6ab81b962cf4667e4186', 'Blunt Weapons', 'standard', 2, 'DEX', NULL, 'A focus on impact-based weapons like clubs, hammers, and maces. Blunt Weapons favors force redirection, shock generation, and tempo control. It''s not about slicing—it''s about overwhelming. The user doesn’t cut—they crack.', 'Melee Weaponry'),
  (124, 'skill-b5cfb0addf06d4d424a11a8b6c1c74648fb71319b38fb1563cbcfb7a656962d8', 'Crushing Swing', 'standard', 3, 'DEX', NULL, 'Crushing Swing channels full-body force into a downward or sweeping blow. It’s used to break armor, stun enemies, or destroy cover. Practitioners time their swing not just for power—but for rhythm. Each impact lands like punctuation.', 'Blunt Weapons'),
  (125, 'skill-171a58d9144e66d14408a4530897bf8922dbfbd50fb868493a666662c4f38edd', 'Momentum Transfer', 'standard', 3, 'DEX', NULL, 'This skill teaches how to absorb impact and convert it into movement—spinning, repositioning, or chaining into a follow-up strike. Momentum Transfer turns defense into offense and recoil into rhythm. It’s not about stopping—it’s about continuing.', 'Blunt Weapons'),
  (126, 'skill-dc2e1958d79b90a8eb57666d6659d8a04e3eb122707b337404643a92276f010d', 'Guard Break', 'standard', 3, 'DEX', NULL, 'Guard Break is the practiced ability to force through an enemy’s defense using well-placed strikes and mechanical leverage. It''s used to open up shields, stagger stances, or interrupt blocking rhythms. If the wall won’t move, you make it crumble.', 'Blunt Weapons'),
  (127, 'skill-86c6b92e5908b3ccc59dea41a3579fe99f6c413f009405eea4823b6e8e9401b4', 'Dual Wield', 'standard', 2, 'DEX', NULL, 'Dual Wield trains coordination between dominant and off-hand weapons. It includes timing, mirrored motion, and weapon balancing. The goal is harmony, not chaos—two blades, one will. True dual wielders don’t alternate—they operate as one.', 'Melee Weaponry'),
  (128, 'skill-e69ade0595e71bb4a4dd5129aa9ff194d4c20e179cdb82b61e16f9f4c52e6151', 'Cross Slash', 'standard', 3, 'DEX', NULL, 'This technique links weapons in crisscrossing strikes—creating layered pressure and forcing misdirection. Cross Slash is fast, deceptive, and hard to block fully. It’s a rhythm that overwhelms defenses and breaks through timing.', 'Dual Wield'),
  (129, 'skill-77e10fb248ac3067d45c2308a60545bbb9fc9036f34a18ae06937310dabf3130', 'Off Hand Block', 'standard', 3, 'DEX', NULL, 'Off Hand Block uses the secondary weapon defensively—intercepting attacks, creating openings, and resetting rhythm. It reduces dependency on full-body dodges and keeps the user upright in tight engagements. Sometimes it’s not about the weapon—it’s about the window it creates.', 'Dual Wield'),
  (130, 'skill-0167177c1b7e0cc2c535420d2a0e40e33d4a107f091db1501a5de7d539f7c67d', 'Flow Transition', 'standard', 3, 'DEX', NULL, 'Flow Transition is the art of swapping roles between main and off-hand seamlessly during combat. It allows constant unpredictability and opens new strike paths as stance shifts mid-motion. A true practitioner fights as if every angle is home.', 'Dual Wield'),
  (131, 'skill-54ddbeedb989b48cf76384f1262a3c72191781ee4e112cd3aa039d373a781aa2', 'Precision Ranged', 'standard', 1, 'DEX', NULL, 'The foundational discipline of targeting with distance weapons using control, timing, and keen awareness. Precision Ranged isn’t about firepower—it’s about placement. It trains hand-eye coordination, breath management, and muscle memory. From bow to blade, the shot lands where you intend it.', NULL),
  (132, 'skill-40e55266605a042e5a39760ab7de7fb62c4b57cdad69dcc4f1c1594ca6ce9081', 'Bow Mastery', 'standard', 2, 'DEX', NULL, 'This skill reflects refined handling of bows—short, long, or composite. Bow Mastery covers draw control, stance discipline, and recovery timing. It’s trained for repeated, accurate shots under pressure. The bow becomes silent intent in motion.', 'Precision Ranged'),
  (133, 'skill-08b8d703816c032dee865c6d5689eff829897c30bdde74c54bbd96aae40a88c3', 'Quick Nock', 'standard', 3, 'DEX', NULL, 'Quick Nock focuses on rapid arrow placement and release without sacrificing aim. It’s the difference between one shot and three before the enemy reacts. Practitioners rely on rhythm, grip flow, and draw-line memory to maintain speed without sloppiness.', 'Bow Mastery'),
  (134, 'skill-5d321eb66f3c9beaafc4d1f900e99a1cead0c3e4db81ec7bb729b47cbfe2c42a', 'Long Draw', 'standard', 3, 'DEX', NULL, 'Long Draw trains deep pull and full extension for maximum arrow power and stability. It’s not about raw distance—it’s about tension control and consistent release. The arrow doesn’t fly—it commits.', 'Bow Mastery'),
  (135, 'skill-22312aecd5ae1242a27fabaac683b7bb235f920a7021cf134b64c6003dc59365', 'Wind Guage', 'standard', 3, 'DEX', NULL, 'Wind Guage allows the user to adjust aim dynamically based on wind patterns, terrain drafts, and movement. It’s both environmental awareness and instinctive calculation. A practiced archer doesn’t fight the wind—they use it.', 'Bow Mastery'),
  (136, 'skill-238a884a32e6dc93ea9b4e62c3109b5c3979320d82d241b18113024ac4f8ef4a', 'Crossbow Mastery', 'standard', 2, 'DEX', NULL, 'Crossbow Mastery focuses on loading, aiming, and firing precision-based mechanical ranged weapons. It trains brace timing, latch familiarity, and recovery stance. A crossbow doesn’t just fire—it commits with finality.', 'Precision Ranged'),
  (137, 'skill-d4b38525a11ecca9d7bc9dda7d110384bbb4221565eb9c9139a13f7c726a9894', 'Fast Crank', 'standard', 3, 'DEX', NULL, 'Fast Crank enables the user to reload or reset the bowstring mechanism quickly—even in pressured environments. It blends tool familiarity with body leverage. The quicker it resets, the quicker you remain in control.', 'Crossbow Mastery'),
  (138, 'skill-8dc1d83f8d9b8daa0963044af88455fb2e4b15ed3ae4d3a86d83b8869a01b119', 'Precision Latch', 'standard', 3, 'DEX', NULL, 'This skill refines the cocking and locking of the string so that release is smooth, silent, and repeatable. Precision Latch eliminates weapon wobble or mechanical error before the shot. Every bolt loosed feels deliberate—like pulling a trigger with no click.', 'Crossbow Mastery'),
  (139, 'skill-f8e27f829bfdcf55171313358a32dd69b880ed5d081aa37b0c888fb3cc4d1ef4', 'Silent Release', 'standard', 3, 'DEX', NULL, 'Silent Release trains the ability to fire without sound—from the creak of string to the sigh of breath. It is used in ambush, assassination, or animal hunting scenarios. There is no warning. Just a body falling quietly.', 'Crossbow Mastery'),
  (140, 'skill-e6dec761acc0755edfb357ff49a9f19e3e11572e5af4891b04a4eaed4ea4030d', 'Thrown Weapons', 'standard', 2, 'DEX', NULL, 'Thrown Weapons emphasizes accuracy, rotation, and impact force with hand-thrown objects—knives, axes, darts, or custom tools. This skill covers angle judG.O.Dent, spin correction, and release timing. A true practitioner throws not to threaten—but to end things.', 'Precision Ranged'),
  (141, 'skill-b63995980e45cd7d3187382347b80a8b1d9a4553d38816dab3807d86f5db0b26', 'Spin Control', 'standard', 3, 'DEX', NULL, 'Spin Control refines how an object rotates mid-air—ensuring tip-first impact and consistent landing. It’s especially vital with knives, spikes, or any weapon affected by trajectory drift. Throwing is easy. Landing true takes mastery.', 'Thrown Weapons'),
  (142, 'skill-eef612d4996e1febdab1bc313f2b16dc88215ee112a745ae5902466501a1cacd', 'Ricochet Throw', 'standard', 3, 'DEX', NULL, 'This skill allows a user to bounce thrown weapons off hard surfaces to strike indirect targets or disorient. Ricochet Throw blends arc memory, rebound angle, and force balancing. Walls don’t block your shot—they just give you a second chance to hit.', 'Thrown Weapons'),
  (143, 'skill-cbee04813a95e6962e52b0b720677e6edc3ad34f85510a74e7ae20bdc79717a3', 'Multiple Throw', 'standard', 3, 'DEX', NULL, 'Multiple Throw trains the user to release two or more weapons in rapid sequence or simultaneously. Used for crowd control, shock entry, or layered targeting, it’s about overwhelming before they react. One hand throws. The other finishes.', 'Thrown Weapons'),
  (144, 'skill-afdff41f0cf5d3e1d42034f71c38a05a77f8bda728d5e863e1d0708f8d2ff6be', 'Fine Manipulation', 'standard', 1, 'DEX', NULL, 'The base skill of detailed, controlled hand work—whether for theft, repair, or delicate operation. Fine Manipulation covers steady fingers, touch awareness, and micro-movement discipline. It’s not just nimbleness—it’s mastery over the tiny and precise.', NULL),
  (145, 'skill-c16d114d1478a3bfc7807f3a3783ad753303663bb54780a7cd124cad674a5548', 'Sleight-of-Hand', 'standard', 2, 'DEX', NULL, 'Sleight-of-Hand trains the ability to misdirect, conceal, or switch objects in plain view. Often used for theft, escape artistry, or stage deception, it relies on fluidity and confidence. What the eye sees is not what the hand holds.', 'Fine Manipulation'),
  (146, 'skill-db3069b4004955e1c7ddf2d7b271b150de065a006b1aac5ec36e93e0d1241422', 'Palming', 'standard', 3, 'DEX', NULL, 'Palming is the art of hiding small objects in the hand without detection. Practiced users can carry coins, tools, or keys undetected—transitioning them in and out of sight seamlessly. It’s not magic—it’s muscle memory and misdirection.', 'Sleight-of-Hand'),
  (147, 'skill-41f10ad399f023e5e8a0e0950a06156590873a95ab90e9ee873a3b557618ff45', 'Quick Switch', 'standard', 3, 'DEX', NULL, 'This skill focuses on the ability to replace or exchange one item for another rapidly and undetectably. Quick Switch is used in thievery, sabotage, or infiltration where a moment of confusion can shift power. The move is fast—but the setup is everything.', 'Sleight-of-Hand'),
  (148, 'skill-73001f5438ffa2a9783e39cff368f39b197db5857ecdc602def110cce1f4add4', 'Pick Pockets', 'standard', 3, 'DEX', NULL, 'Pick Pockets is the classic skill of removing items from a person’s clothing or gear without them noticing. It trains contact softening, body timing, and approach angle. It’s not about luck—it’s practiced pressure and exit speed.', 'Sleight-of-Hand'),
  (149, 'skill-aa3f86a51dd370e5ea9b43dc870c3550327ed18f0e232226eb5dfe2e498bf283', 'Lock Bypass', 'standard', 2, 'DEX', NULL, 'Lock Bypass trains the use of tension, feel, and tool work to open sealed containers without keys. It emphasizes timing, tactile awareness, and a mental model of lock construction. When done well, the lock never even knows it was opened.', 'Fine Manipulation'),
  (150, 'skill-d002c68d6b8b75749c376060e229e5a1dc6ddda8a94495b9df2351b9b7ef364c', 'Pin Setting', 'standard', 3, 'DEX', NULL, 'Pin Setting focuses on single-pin manipulation to open complex locks with precision. It’s used when speed must be sacrificed for certainty. The user feels each click and knows when it’s real. This is lockpicking as meditation.', 'Lock Bypass'),
  (151, 'skill-58d75039181a999ec21f71c2d7ccddc322560a8c3071c59577d473338caa909d', 'Rake Technique', 'standard', 3, 'DEX', NULL, 'A faster, more aggressive method of picking where multiple pins are disturbed simultaneously. Rake Technique is trained for quick jobs, low-quality locks, or high-pressure breaches. It’s speed over subtlety—a gamble that often pays.', 'Lock Bypass'),
  (152, 'skill-ecd1df33e5f2960d0df226657e05ef193ae9202db37b2ec1e3afef761f9f41e7', 'Bypass Tooling', 'standard', 3, 'DEX', NULL, 'This skill allows use of custom tools—shims, bump keys, magnet rigs—to override lock mechanisms creatively. Bypass Tooling expands the possibilities beyond just pins, including latches, tumblers, and levers. It''s innovation over tradition.', 'Lock Bypass'),
  (153, 'skill-1cc8ca2e455baac3da25a7fd64195d05289fbf66dee1671a2aa938804ca51d42', 'Precision Tinkering', 'standard', 2, 'DEX', NULL, 'Precision Tinkering trains work on miniature or delicate mechanical systems. From clocks to traps to field repairs, it blends analysis and craftsmanship. Your hands don’t guess—they understand.', 'Fine Manipulation'),
  (154, 'skill-552d9cee3077315c821b9507adb3378866236d7d61e320ce16ed67fe0ee28aac', 'Micro Gear Work', 'standard', 3, 'DEX', NULL, 'This skill focuses on adjusting tiny gears and mechanisms by hand or with tools. Used for watches, timers, or intricate devices, Micro Gear Work demands steady nerves and patient rhythm. Each twist could be success—or disaster.', 'Precision Tinkering'),
  (155, 'skill-f5a09f08996730ba767676e5c6bcdb79bfa63b70ca87621d1b7a9f74d7e45c32', 'Delicate Solder', 'standard', 3, 'DEX', NULL, 'Delicate Solder is the use of heat, metal, and timing to bind miniature parts without damage. It''s used for circuit repair, jewelry, or microscopic enhancements. Too hot, and it warps. Too slow, and it fails. Mastery means perfect melt.', 'Precision Tinkering'),
  (156, 'skill-be189baa80a0efbe66189a5847cf7a03a9fcd4868ceb316e1036ce8b2a09de2b', 'Spring Read', 'standard', 3, 'DEX', NULL, 'A specialized skill for interpreting spring tension, trigger mechanisms, and timing systems within devices. Spring Read allows you to predict when something will snap, pop, or break sequence. It’s the difference between disabling a trap—and setting it off.', 'Precision Tinkering'),
  (157, 'skill-ecb824b831c842f3d777627f9ea938e712bd69aaef8cdbba22b890ab0e021f3a', 'Vehicle Operation', 'standard', 1, 'DEX', NULL, 'This is the core skill of physically controlling mounts, vehicles, and mobile platforms. Vehicle Operation includes handling speed, turns, and terrain while maintaining balance and awareness. It''s not about driving—it’s about piloting your environment.', NULL),
  (158, 'skill-08afe7c078be941c96b9821b0485a4a3cfc480e8d291eff835903bd72ee90073', 'Mounted Travel', 'standard', 2, 'DEX', NULL, 'Mounted Travel focuses on controlling animals or rides under motion—horses, beasts, or riding platforms. It trains posture alignment, rhythm sync, and directional command. When you ride, you become part of the motion.', 'Vehicle Operation'),
  (159, 'skill-f174ae3db7ea47471c14b2dbe80f0ee8ceefc3bf3c19c24d0ea00d2d7b09a2ff', 'Balance Recovery', 'standard', 3, 'DEX', NULL, 'This skill trains the ability to recover control during a stumble, buck, or sudden directional shift while mounted. Balance Recovery uses body correction, footwork, and grip adjustment to stay on without falling. One misstep doesn’t throw you—you reset and ride on.', 'Mounted Travel'),
  (160, 'skill-51a5b1cccde54a4f5b4ce8e42ebf5e9ecd9633d1315b341f9a6bdd1dc64a6e40', 'Rapid Mount/Dismount', 'standard', 3, 'DEX', NULL, 'Rapid Mount/Dismount allows quick, practiced transitions onto or off of a mount—under pressure, mid-motion, or in combat. It’s about using momentum rather than wasting it. You''re in the saddle before the enemy even realizes you moved.', 'Mounted Travel'),
  (161, 'skill-4165458fc6f1e9708f6f3d362a801d9f625f0cc8e0da53d6bad59244f9eef5f5', 'Terrain Sprint', 'standard', 3, 'DEX', NULL, 'Terrain Sprint refines high-speed mounted movement across uneven or shifting ground. It’s trained for dashes across battlefields, ravines, or city rubble. You don’t just charge—you thread the wild.', 'Mounted Travel'),
  (162, 'skill-a823e7ba3320e798cf99c50fe2bf65b473a5d19a13552989ea9c8857934fdef9', 'Land Navigation', 'standard', 2, 'DEX', NULL, 'Land Navigation trains control of land-based vehicles in both predictable and chaotic terrain. It includes steering correction, acceleration judG.O.Dent, and route flow. Whether wagon or wheeled machine, it keeps motion under your hands.', 'Vehicle Operation'),
  (163, 'skill-2b8c16cd89727d34b233e6f574a23b58194cd617292eb6eed189f3f466a4de31', 'Rough Terrain Control', 'standard', 3, 'DEX', NULL, 'This skill enables the user to maintain vehicle control on jagged, muddy, or obstacle-filled land. Rough Terrain Control includes bounce compensation, wheel angle adaptation, and friction awareness. When the road disappears, you still drive.', 'Land Navigation'),
  (164, 'skill-b786288f73d479a3c91015f9b85c65b4a319b98787685f68b08757d68663d0cd', 'Drift / Slide Mastery', 'standard', 3, 'DEX', NULL, 'Drift / Slide Mastery allows the controlled loss and regain of traction for tight turns, sudden stops, or show-of-force movement. It trains throttle balance, weight shift, and tire read. Chaos becomes choreography.', 'Land Navigation'),
  (165, 'skill-d3380b14a3f627ff7cb3b77f1f240c66c51ef807292d2eb14ca6ce3f049f23c6', 'Reverse Maneuvering', 'standard', 3, 'DEX', NULL, 'This skill trains spatial awareness and counter-steering while moving backward or sideways. Reverse Maneuvering is vital in tight spaces, retreats, or repositioning without a full turn. You don’t need to face forward to stay in control.', 'Land Navigation'),
  (166, 'skill-c25bc4c158824b929aee6b88cfef07663d25a20eec64848ad5fb94c18375ae0f', 'Water & Air Travel', 'standard', 2, 'DEX', NULL, 'Water & Air Travel teaches basic handling of vessels that float, glide, or fly. It includes current resistance, wind adaptation, and non-ground-based navigation. Movement no longer relies on wheels—it relies on reading the flow.', 'Vehicle Operation'),
  (167, 'skill-b05e2878cd347721984e1b914f432773bc1e4744325c19db5373ad82ef10bef3', 'Glide Path Control', 'standard', 3, 'DEX', NULL, 'Glide Path Control trains the use of lift, descent, and drag to manage air or water trajectory. It’s used for gliders, wingsuits, or lightweight vessels. Smoothness is everything—you don’t drop, you descend.', 'Water & Air Travel'),
  (168, 'skill-fcc8ac7201d46b9b331774d4e157b848432204a92d3a749d56768f143ff3a98b', 'Rapid Launch', 'standard', 3, 'DEX', NULL, 'This skill enables fast takeoff or push-off from a dock, ledge, or ramp. Rapid Launch is trained to use timing and space without collision or stall. In moments where speed saves lives, you’re already airborne.', 'Water & Air Travel'),
  (169, 'skill-d5cd6db47e051b65b0a3e6f295720463f095468714abb2563bbe905d5a64d9d0', 'Gust Correction', 'standard', 3, 'DEX', NULL, 'Gust Correction refines how a user adjusts trajectory when wind or wave forces act unexpectedly. It involves tension read, correction input, and tilt timing. Storms don’t stop you—they challenge you to stay smooth.', 'Water & Air Travel'),
  (170, 'skill-04a13db8350c2b0295d722f9f35454f447def880bdad52dc5000df230b597e13', 'Reactive Defense', 'standard', 1, 'DEX', NULL, 'Reactive Defense is the core skill of avoiding, deflecting, or absorbing attacks in real-time through trained motion. It emphasizes timing, body control, and spatial judG.O.Dent. Practitioners don’t just block—they vanish from danger’s path. This is defense that moves.', NULL),
  (171, 'skill-fc756d6b299ed1e01c1b046b46cb1b82826feacc1cfdd2eebc9cbd562842e290', 'Dodge Mastery', 'standard', 2, 'DEX', NULL, 'Dodge Mastery refines the act of narrowly escaping attacks without leaving combat posture. It includes sidesteps, pivots, and slips executed at just the right moment. It’s not about retreat—it’s about repositioning while staying lethal.', 'Reactive Defense'),
  (172, 'skill-134af2ce96b1e8573070f6318512265c57cc7f1570b4d28c9a1d2e80db07d193', 'Evade Burst', 'standard', 3, 'DEX', NULL, 'This skill allows a sudden, high-speed motion in any direction to escape a strike zone or trap. Evade Burst combines explosive leg power with instinctual timing. One instant, you’re there. The next, you’re gone.', 'Dodge Mastery'),
  (173, 'skill-7dec563c2ae474bb776495ff5196b97bbc1397e71d316f57c648cdde2083b672', 'Slip Step', 'standard', 3, 'DEX', NULL, 'A subtle, minimal-movement dodge that shifts the body just enough to avoid impact. Slip Step is trained for tight quarters, multi-attacker engagements, or when retreat isn’t possible. It’s a whisper of motion that changes everything.', 'Dodge Mastery'),
  (174, 'skill-a82d1f4c941a3c02684bd1d3b6a8443c338b994a23645822b9fc5b9607284724', 'Split Second Shift', 'standard', 3, 'DEX', NULL, 'This skill heightens reaction to the extreme—allowing dodges at the very edge of threat contact. Split Second Shift requires trust in instinct and training beyond thought. It’s not a plan—it’s survival triggered by a breath.', 'Dodge Mastery'),
  (175, 'skill-89c3a8ec14e8fa2b1eb594a8a8ef0ab67df9cfe887d2861b84e64b715a6e3afe', 'Deflect / Parry', 'standard', 2, 'DEX', NULL, 'Deflect / Parry turns incoming strikes aside rather than absorbing or dodging them. It requires timing, angle, and a calm read of motion. This is redirection, not resistance. When done well, it looks like the blow never arrived.', 'Reactive Defense'),
  (176, 'skill-062fe16f9f6854512b9f01f768c7e609cc80cde05fba21c656bc7a5379d28e7e', 'Weapon Redirect', 'standard', 3, 'DEX', NULL, 'A trained technique to guide an attacker’s weapon away from the body using one’s own blade, staff, or tool. Weapon Redirect breaks momentum and control without full blocking. The strike lands—but never where it meant to.', 'Deflect / Parry'),
  (177, 'skill-49cb62167ba126145b051c58130850760f40b90da98e77e7df0c5913f65a5e04', 'Hand Redirect', 'standard', 3, 'DEX', NULL, 'This skill allows the user to deflect strikes with empty hands—pushing aside blades, fists, or projectiles with fingers, palms, or forearms. Hand Redirect is about flow, not force. You don’t stop the strike—you guide it somewhere else.', 'Deflect / Parry'),
  (178, 'skill-662ffe060d6a36afcc56cbf0b6c2e72f79607b17ff433250bff98a1a4556d0b3', 'Momentum Capture', 'standard', 3, 'DEX', NULL, 'Momentum Capture uses an enemy’s own motion to reposition them—guiding their force into a stumble, roll, or counter. It’s trained to turn attacks into opportunities without striking back. The greater their power, the more they lose control.', 'Deflect / Parry'),
  (179, 'skill-ec508c6991bbcb8d9a729d5c9aa0ac10954426129d0ec07fbc4bd6371fc9990f', 'Roll & Recovery', 'standard', 2, 'DEX', NULL, 'Roll & Recovery focuses on converting falling, being thrown, or losing balance into motion that resets position. It trains the user to hit the ground in control—and rise again before the enemy adjusts. You don’t fall—you flow.', 'Reactive Defense'),
  (180, 'skill-5a266c879a9bd508812edf3090b7304699bbb6ff1a98f5ff35882e6f740d1ec9', 'Break Fall', 'standard', 3, 'DEX', NULL, 'Break Fall teaches how to absorb impact during a fall to avoid injury or loss of momentum. It’s used in combat, travel, or acrobatics where landing wrong ends things fast. Hit the ground—but never break on it.', 'Roll & Recovery'),
  (181, 'skill-15a8b5b2a064d1a3fbb461211987ef2ad8a1610ab065fe614dc5af752ca3895b', 'Tumbling Egress', 'standard', 3, 'DEX', NULL, 'This skill enables the user to roll out of grapples, tight spaces, or chaotic zones without exposing vulnerable areas. Tumbling Egress is trained for fluid escapes and fast re-engagement. You leave danger like wind leaves flame—fast, low, silent.', 'Roll & Recovery'),
  (182, 'skill-b699772b4d0ff71853218633334f59aeabb09dfb49b30d96f810007009534ed7', 'Spring Up', 'standard', 3, 'DEX', NULL, 'Spring Up allows a character to rise from prone or fallen position instantly—often mid-motion. It’s a blend of timing, spine alignment, and muscle sync. You don’t get back up—you launch up.', 'Roll & Recovery'),
  (183, 'skill-973885349be027e82d2843af524023bd01458a63421acce8387cb86303744bd5', 'Aerial Operation', 'standard', 1, 'DEX', NULL, 'Aerial Operation is the discipline of navigating, maneuvering, and maintaining control while suspended or moving above ground. It includes jumping, swinging, gliding, falling, and landing safely or tactically. This isn’t just motion—it’s gravity turned into a tool.', NULL),
  (184, 'skill-16af7677630c5df0b394aeced664321eaecbc5527c2d8705a251034dcb20662f', 'Aerial Balance', 'standard', 2, 'DEX', NULL, 'Aerial Balance trains the body to remain upright, stable, and reactive while in the air or on narrow, unstable footing. It includes micro-adjustments, posture shifts, and wind response. The sky doesn’t forgive imbalance—you become your own anchor.', 'Aerial Operation'),
  (185, 'skill-4cecda453de65a0a79bd92b0b3337e77691102ee8ad2c116a2580d268e946b25', 'Ledge Cling Transition', 'standard', 3, 'DEX', NULL, 'This skill allows for hanging from a ledge or grip point and transitioning fluidly to climb, swing, or drop. It’s trained for both stealth and emergency movement. You''re not just holding on—you’re choosing when and how to move.', 'Aerial Balance'),
  (186, 'skill-17534299771cabfac48a2c74e0b520ed0ddc11d434971160d2cb177507fd3903', 'Rope Tension Walk', 'standard', 3, 'DEX', NULL, 'Rope Tension Walk refines movement across tensioned lines—ropes, cables, or narrow beams. It trains center alignment, pace, and wind adjustment. You don’t balance like a dancer—you balance like your life depends on it.', 'Aerial Balance'),
  (187, 'skill-6857629cde7b50d5937809137337932a9e4e4fd5f38f6e08eb26da51407a85f6', 'Wind Balance Recovery', 'standard', 3, 'DEX', NULL, 'Wind Balance Recovery is the reflexive ability to regain control mid-air or on platforms buffeted by gusts or turbulence. It’s used on airships, cliffs, or during long jumps. The wind pushes—you respond without panic, without pause.', 'Aerial Balance'),
  (188, 'skill-0b308661e02224a0e31dddd96b4104b5d797717ae10e432ec2ed723eb09b4c91', 'Lift and Drop', 'standard', 2, 'DEX', NULL, 'Lift and Drop is the study of vertical movement—climbing, dropping, hoisting, or rappelling. It trains rope use, friction control, and jump-drop technique. This is not falling—it’s descending with intention.', 'Aerial Operation'),
  (189, 'skill-c52893c79130df51405864b9770dec48e84652562a3b34cc333d8291262359d9', 'Anchor Descent', 'standard', 3, 'DEX', NULL, 'Anchor Descent focuses on controlled rope or tether-based lowering, especially from dangerous heights. It includes grip cycling, angle awareness, and surface response. You don’t let go of the rope—the rope lets you down when you decide.', 'Lift and Drop'),
  (190, 'skill-052e8170518a227759e332a4603f95a8c97888a03221e6d67c2c1f4ef90115fd', 'Midair Brake', 'standard', 3, 'DEX', NULL, 'This skill allows the user to slow or redirect motion while airborne using limbs, body tension, or tools. Midair Brake is used to hit smaller targets, avoid collisions, or control descent speed. The fall may be fast, but you land like it never was.', 'Lift and Drop'),
  (191, 'skill-a11815c0a24cc1a5c8b5811500a8f7b2e33db2184f277db9eb471c15995ed421', 'Controlled Landing', 'standard', 3, 'DEX', NULL, 'Controlled Landing refines how one hits the ground—absorbing force, minimizing injury, and staying ready. It’s used from drops, leaps, or even forced throws. You don’t crash—you arrive.', 'Lift and Drop'),
  (192, 'skill-15d72697d9ea525c07f4565b37f6edfdca6bd478500989a82598ae2cbcf9dc04', 'Free Movement', 'standard', 2, 'DEX', NULL, 'Free Movement trains mid-air directional control—swinging, leaping, twisting, or shifting during jumps or glides. It’s motion within motion. Gravity doesn’t own you—you negotiate with it.', 'Aerial Operation'),
  (193, 'skill-c0694c743703f05e837baaebbfbe57cb95bdca48b0692b7341f65942be86b9c6', 'Swing Arc Control', 'standard', 3, 'DEX', NULL, 'This skill teaches how to manipulate swing arcs for length, height, and timing. It’s trained on ropes, bars, vines, or hooks. Practitioners can redirect, increase, or kill momentum at will. When you swing, it’s not just to move—it’s to position.', 'Free Movement'),
  (194, 'skill-aadc80b549dae2ceff9cdad5ae74d25936ba2ef30a9b08bc9c6009474e49f064', 'Leap Redirection', 'standard', 3, 'DEX', NULL, 'Leap Redirection is the skill of changing trajectory mid-jump using body twist, terrain contact, or obstacles. It’s used to evade mid-air, reach platforms, or fake direction. You launch once—but you land where they didn’t expect.', 'Free Movement'),
  (195, 'skill-70bb9d8a13969c2f15c3a4943acd79bc9fc68f9245394548a0890b91b1fb2497', 'Glider Pivot', 'standard', 3, 'DEX', NULL, 'This technique controls the shift of direction, tilt, or roll in gliding devices like wingsuits, magical cloaks, or paragliders. It trains airflow reading and body torque. You don’t drift in the air—you steer it.', 'Free Movement'),
  (196, 'skill-fc95189a5804fbfdb36fdadbb4808ec58d9e8a120a21a256a9fdf88adfa68bf2', 'Rigging & Ropework', 'standard', 1, 'DEX', NULL, 'The foundation of working with ropes, cords, and suspension systems. Rigging & Ropework covers tying, securing, and anchoring through technique and tension. It’s more than knots—it’s control over movement, load, and survival.', NULL),
  (197, 'skill-63fee0609d99fbca1cbf0cdb71e28f9acaab7bac1cd4903f393984b61b357616', 'Knot Mastery', 'standard', 2, 'DEX', NULL, 'Knot Mastery refines the tying of secure, purpose-driven knots under pressure or in motion. From harnesses to bindings, each knot has intent. Practitioners tie with speed, accuracy, and muscle memory.', 'Rigging & Ropework'),
  (198, 'skill-047654907321801b16832ae9d34c80b53e52c3cc4d3e41d4c3b757d42a4b08a1', 'Rapid Tie', 'standard', 3, 'DEX', NULL, 'This skill enables fast creation of strong knots using minimal movement. It’s trained for rescue, capture, or setup in urgent situations. Your hands tie faster than most can react.', 'Knot Mastery'),
  (199, 'skill-bdcdf4b1f8ac629133de2b386fbe1ad2d6e2118844c3d4c35fc3c2f6052d00e3', 'Escape Knot', 'standard', 3, 'DEX', NULL, 'Escape Knot teaches how to tie or recognize knots that can be undone from tension or specific motion. It’s used for stealth, survival, or illusion. Bound doesn’t mean trapped.', 'Knot Mastery'),
  (200, 'skill-4cdcd09139689badb9e80a4040fbf89c015bbc2c0d56f57288488a976fed2925', 'Hidden Knot', 'standard', 3, 'DEX', NULL, 'This technique conceals knots within fabric folds, shadows, or other bindings. Hidden Knot makes restraints, traps, or tricks harder to detect or disable. A knot unseen is a knot unbeaten.', 'Knot Mastery'),
  (201, 'skill-7bfe74b4401d370afcbbefc577183743db123a884e0b1ab6049ff402526cb25d', 'Rappelling', 'standard', 2, 'DEX', NULL, 'Rappelling focuses on controlled descent using rope, anchors, and body positioning. It’s trained for cliffs, towers, and vertical access scenarios. Every drop is calculated, every grip tested.', 'Rigging & Ropework'),
  (202, 'skill-7c27f1dd15543da42bf72ad8b1682d2a9ad680e3d52859bcbc61ba523d973552', 'Fast Descent', 'standard', 3, 'DEX', NULL, 'This skill enables rapid downward movement while maintaining safety through friction control and footwork. Often used in breaches, chases, or collapses. The line becomes your lifeline—and your weapon.', 'Rappelling'),
  (203, 'skill-700f83e3986ee725a29191e99483e3332d4fef8468ed24e9176f9cdccd2dd20e', 'Wall Transition', 'standard', 3, 'DEX', NULL, 'Wall Transition teaches how to switch between climbing, wall contact, and rope use mid-action. It blends climbing and descent into a seamless sequence. You’re never between options—you are the transition.', 'Rappelling'),
  (204, 'skill-f6a938e4d507019bd7ae45b4f62860907be28a07c425f9ee636fa2b4b8f25aec', 'Underhang Swing', 'standard', 3, 'DEX', NULL, 'Underhang Swing allows the user to navigate underneath ledges or bridges using rope control and pendulum movement. Trained for access and escape in vertical structures. The drop is dangerous—but it leads to freedom.', 'Rappelling'),
  (205, 'skill-ec2b00f2e5b8fdb1942da2e0651eeee60a087979bd54f9b7d2e9bb993eaff671', 'Load Rigging', 'standard', 2, 'DEX', NULL, 'Load Rigging trains securing and lifting heavy objects with balanced tension and anchor setups. Used in hauling, transport, or building situations. It’s not just weight—it’s motion made safe.', 'Rigging & Ropework'),
  (206, 'skill-50a2adcdf276f8068c1d64184d33d438534276116e8a20f03cfcaa64aac47969', 'Balanced Suspension', 'standard', 3, 'DEX', NULL, 'This skill distributes weight evenly across multiple points to avoid tipping or strain. It’s vital for moving bodies, equipment, or sensitive containers. Balance is what keeps it alive.', 'Load Rigging'),
  (207, 'skill-1e94a06565f0fcdbe5ffd144eaf8177e8735e3891e22f7d88d4d28e8c8481376', 'Quick Release', 'standard', 3, 'DEX', NULL, 'Quick Release trains rigging techniques that allow for instant rope drop or disconnect. It’s used in combat zones, escape plans, or precision deliveries. When time matters, one pull resets the field.', 'Load Rigging'),
  (208, 'skill-9770406251eb1017237035e68751590fbef7bc9b31f7d74dda2a1492c4c0750c', 'Highline Setup', 'standard', 3, 'DEX', NULL, 'Highline Setup allows the user to rig a suspended rope bridge, zipline, or elevated path across gaps. Used for travel, tension lines, or suspended traversal. The void between points becomes a path—because you build one.', 'Load Rigging'),
  (209, 'skill-bd90c7200c5f24be2650c2c92bcb725d7ecaa49e1215d5b08e6c02ccacf3d87c', 'Precision Performance', 'standard', 1, 'DEX', NULL, 'A display of mastery in coordinated, fine-tuned hand and body movements for spectacle, training, or mental control. Precision Performance includes displays like juggling, card work, and object manipulation. It''s not about flash—it''s about focus.', NULL),
  (210, 'skill-4527031e5b27fee382a53acd9445bce9f0abf220e166ff316b388051e8a1573f', 'Juggling', 'standard', 2, 'DEX', NULL, 'Juggling trains rhythm, spatial awareness, and coordination with multiple airborne objects. It''s used for entertainment, training reflexes, or distraction. Each toss is a lesson in timing.', 'Precision Performance'),
  (211, 'skill-12504d0d1f06d78684d357c957eda312115c7b000863e841ee1a3951659a3376', 'Multi Object', 'standard', 3, 'DEX', NULL, 'This skill pushes the limit of how many items can be juggled while maintaining a clean pattern. Multi Object requires balance, breathing, and serious nerve. The chaos becomes choreography.', 'Juggling'),
  (212, 'skill-47910103052faf124a6a2bf0bca16b63f0086037de3de99693b5f95421f7e2c0', 'Bounce Juggle', 'standard', 3, 'DEX', NULL, 'Bounce Juggle manipulates object rebound off surfaces—walls, floors, shields—within a juggling flow. Trained to redirect motion with force and precision. Gravity becomes part of the rhythm.', 'Juggling'),
  (213, 'skill-e3d299a1b8d52cb2cfc261d412efc7f4f075497262a8c203f001697e49192d90', 'Fire Juggle', 'standard', 3, 'DEX', NULL, 'Fire Juggle adds live flame to juggling sequences, requiring perfect catch alignment and burn control. It’s trained for performance—or distraction tactics in extreme scenarios. One slip, and it’s pain. Master it, and it’s mesmerizing.', 'Juggling'),
  (214, 'skill-51bf1d652e4194ad03fae61b8e7bae0295c6c97235afe19b2c2c31103d87a7d4', 'Cardistry', 'standard', 2, 'DEX', NULL, 'Cardistry is the refined manipulation of cards for artistic display, distraction, or subtle movement. It’s not about tricks—it’s about elegance. The cards don’t flutter—they obey.', 'Precision Performance'),
  (215, 'skill-ccffb89f98975aa28aef618d74f93ff035b5ce0fe5ca938c433925e630d15e89', 'One Hand Cut', 'standard', 3, 'DEX', NULL, 'This skill allows full deck shuffles, cuts, or reversals using only one hand. Often used for flair, distraction, or sleight setups. It’s elegance through constraint.', 'Cardistry'),
  (216, 'skill-13a74eb6596d1d8a1db78ae23ee279cacffdfe20612c5ff064a823a101c00d46', 'Flourish Fan', 'standard', 3, 'DEX', NULL, 'Flourish Fan trains the graceful spread of cards into arcs or fans, showing smoothness and control. Often used to create presence or open a scene. Control that looks like art.', 'Cardistry'),
  (217, 'skill-d9f1bb77c78f219899b43e2bdacd5278d2c50e53d4f5f5daf7f4051b1c29c762', 'Throw Catch', 'standard', 3, 'DEX', NULL, 'Throw Catch allows controlled projection and retrieval of cards mid-air. Used for show or sleight setups. When you throw, they think it''s gone—until it snaps back.', 'Cardistry'),
  (218, 'skill-51a413e1b8de98bbacf5648a34824e30af200311e305b1295210c845d8b64c0f', 'Dexterous Display', 'standard', 2, 'DEX', NULL, 'Dexterous Display includes advanced hand feats that impress, confuse, or test skill—coins, loops, knots, and more. It’s coordination put on display. You don’t just move—you demonstrate.', 'Precision Performance'),
  (219, 'skill-25ec31575fd6056af6ed7cfcec7d5c118a0049479c99e9a5b440feb0fae6827d', 'Coin Roll Cascade', 'standard', 3, 'DEX', NULL, 'This skill rolls coins continuously across fingers, wrists, or surfaces without break. A signature of stillness within motion. You don’t drop—it flows.', 'Dexterous Display'),
  (220, 'skill-b6f56b2466f942129eff5b0721f10a952e15ac719c2041389e19610bda1f23c6', 'One-Hand Knot Loop', 'standard', 3, 'DEX', NULL, 'One-Hand Knot Loop trains fast knot formation using only one hand—blindfolded, distracted, or mid-action. For show, escape, or intimidation. They blink—and the knot is done.', 'Dexterous Display'),
  (221, 'skill-5aaa4d0379dd7a03e8fe12405fc7c9b28cdc979c67d4a0e6d8dff2617e0e0973', 'Thread The Needle Toss', 'standard', 3, 'DEX', NULL, 'A high-precision throw through narrow or moving gaps—showcasing focus and judG.O.Dent. Used for performance or challenge. You aim where no one dares—and hit exactly there.', 'Dexterous Display'),
  (222, 'skill-be95e048ff6aaae6e320c1d39091bddbed6979b4739ef8eda3bc3b401daf622b', 'Endurance', 'standard', 1, 'CON', NULL, 'The foundation of grit and stamina, Endurance measures a character''s ability to press forward through pain, exhaustion, and strain. Whether climbing peaks, surviving brutal marches, or outlasting hunger, this skill reflects an inner reserve that refuses to break. It is the quiet strength behind every step taken when others would fall.', NULL),
  (223, 'skill-e7af1129c954575d479ace65c0ed84d924a7b25f64011ed0a85e6d7a5ba2c66b', 'Distance Running', 'standard', 2, 'CON', NULL, 'The art of sustained movement over long distances, Distance Running transforms effort into rhythm. Those trained in this skill find a steady pace that seems to defy fatigue, crossing terrain with a tempered, tireless stride. It''s not about speed—it''s about never stopping.', 'Endurance'),
  (224, 'skill-517c7d5450b91d8391f27dea10e6f3bcf50bb90dfb02895b4b905291a8843a48', 'Marathoner', 'standard', 3, 'CON', NULL, 'Pushing the body beyond its limits, the Marathoner becomes a creature of pure will. They eat miles for breakfast, wear down time itself, and run through storms without flinching. Where others collapse, they only find another gear.', 'Distance Running'),
  (225, 'skill-7632ae12062d447e847943b3e309d9c991c7f4fed3cc8e3035103dd673a4df66', 'Pace Control', 'standard', 3, 'CON', NULL, 'Knowing when to surge and when to conserve, Pace Control is the strategy behind endurance. With this mastery, every breath, heartbeat, and footfall is measured. The runner becomes their own metronome, never wasting energy.', 'Distance Running'),
  (226, 'skill-f8dbb877ff740cd5323abeff0c69d0c1fbacaf8ed64d7cdbfc05b130a8a4de2b', 'Hill Sprint Recovery', 'standard', 3, 'CON', NULL, 'The lungs burn, the slope climbs, but recovery comes fast and clean. This skill reflects the body’s rapid rebound after bursts of punishing effort. The ground may rise sharply, but so does the will to keep going.', 'Distance Running'),
  (227, 'skill-cb0be11585fdd972642e410badba71f9401bb26923f0cfd8b2577cf899d24aa4', 'Pack Trekking', 'standard', 2, 'CON', NULL, 'Built for burdened movement across long journeys, Pack Trekking turns travel into triumph. Whether hauling supplies through forest or canyon, this skill transforms weight from a hindrance into momentum. It’s how the strong carry the world.', 'Endurance'),
  (228, 'skill-9a2de3834ccda5783ca5b7a0570302c6ff60f92bb4f42aa531b84fc7976f0092', 'Weighted Trek', 'standard', 3, 'CON', NULL, 'With load comes discipline. Weighted Trek represents the ability to bear mass over distance without loss of speed or form. The trekker moves with quiet resolve, each step honed through training under strain.', 'Pack Trekking'),
  (229, 'skill-cd2fb1191efe61f896a556db8a5ff0c78d3b94af731bedacef13df2eb66b441a', 'Terrain Traverse', 'standard', 3, 'CON', NULL, 'From desert dunes to mountain paths, this skill allows the body to adapt its gait, rhythm, and resilience to unforgiving ground. Uneven terrain becomes challenge, not obstacle. The path doesn’t change—it’s the traveler who does.', 'Pack Trekking'),
  (230, 'skill-68f81971b03b70418c79915ef6da23246c6fe477091edf3805621389eedac244', 'Endurance Shuffle', 'standard', 3, 'CON', NULL, 'The movement isn''t fast, but it never stops. This skill channels tired muscles into low-effort motion, allowing progress even when energy is nearly spent. It’s how you cross the last miles when strength alone won''t carry you.', 'Pack Trekking'),
  (231, 'skill-895a6f07e660d551c31d6e37e06ad35c3c23f4e0beb17b6b64423a07fa72054f', 'Cardio Conditioning', 'standard', 2, 'CON', NULL, 'Cardio Conditioning builds the heart into a weapon of efficiency. Breath deepens, circulation sharpens, and effort becomes sustainable over time. This is the engine beneath the endurance.', 'Endurance'),
  (232, 'skill-c8e9c63e27e3ac17aefd33876452df0d1adc754567a982a9b5901721c197d066', 'VO₂ Max Boost', 'standard', 3, 'CON', NULL, 'A reflection of peak internal function, this skill enhances the body''s oxygen use to near superhuman levels. More air, more power, less fatigue—fueling performance where others gasp.', 'Cardio Conditioning'),
  (233, 'skill-d9b503bee5285909ff25da2efff6cd01121351ee4fef941ced7ce3da8a647e52', 'Fatigue Resistance', 'standard', 3, 'CON', NULL, 'This is where the body shrugs off exhaustion like rain off armor. Trained to delay the onset of physical fatigue, this skill allows activity to stretch far beyond normal bounds. Tired is no longer a limit.', 'Cardio Conditioning'),
  (234, 'skill-2219fa26cfeca81504a0fa043c1f95f9c52ca0ed76023185ba50df1fa5f50d48', 'Burst Recovery', 'standard', 3, 'CON', NULL, 'Between the sprints, the body rebounds with unnatural speed. This skill grants rapid return from short, intense effort—ideal for those who fight in flurries, then move again. It''s the calm between storms.', 'Cardio Conditioning'),
  (235, 'skill-7aab06cd90b6efabfbc581922a4ad2ddfba2a20a0be4120eb5d0e5e72a59df66', 'Swimming', 'standard', 1, 'CON', NULL, 'A full-body expression of rhythm and breath, Swimming turns the water from a barrier into a medium of motion. It measures your ability to stay afloat, move efficiently, and endure the physical demands of aquatic travel. Whether calm or churning, the water yields to trained effort.', NULL),
  (236, 'skill-d41fcca0a9d502b0f9db1104028867ac90b537e6f80978dc678a2b61eb14f117', 'Speed Swim', 'standard', 2, 'CON', NULL, 'Cutting through water with streamlined precision, Speed Swim emphasizes short bursts of speed and efficiency. Every stroke becomes a blade, every kick a propellant. This is swimming with intent and urgency.', 'Swimming'),
  (237, 'skill-be73ca4c5bbdb9f0c5e41cf47bdadbceddb9366f0d244c8eb67964c69761bd2a', 'Sprint Freestyle', 'standard', 3, 'CON', NULL, 'Designed for explosive velocity, Sprint Freestyle unleashes a torrent of speed over short distances. This is where technique, timing, and raw energy combine to dominate the lane—or the chase.', 'Speed Swim'),
  (238, 'skill-a4008635bc473c73d6bdd5557bd0d5b39cca35b1ab58a2060aaabb4d99156759', 'Flip Turn Mastery', 'standard', 3, 'CON', NULL, 'A signature move of elite swimmers, the flip turn transforms wall contact into momentum. With perfect timing and minimal energy loss, the swimmer becomes a constant flow—never stopping, only redirecting.', 'Speed Swim'),
  (239, 'skill-c300323a9733fa8783f59f19f7a927b85d1dcbc905521a817ca1ee93f4300c60', 'Explosive Start', 'standard', 3, 'CON', NULL, 'The dive is a launch, not a leap. Explosive Start captures the burst of muscular force and breath control needed to launch from the edge with precision and impact. The race begins before you hit the water.', 'Speed Swim'),
  (240, 'skill-01e6fdd9ccbb5ac730cf702ddfb8fc677f2437a5d66d264db8f55a4e2feda7c2', 'Endurance Swim', 'standard', 2, 'CON', NULL, 'This is the slow, steady rhythm that turns oceans into corridors and lakes into lanes. Endurance Swim teaches the body to maintain motion over long distances, conserving energy while resisting fatigue.', 'Swimming'),
  (241, 'skill-47b954c36f02c7e68570b49ffbce0f303bdac65a14d68c2b246eda598b33083b', 'Marathon Swim', 'standard', 3, 'CON', NULL, 'Whether across a bay or down a river, the Marathon Swim is about sustained determination. Hours in the water become a trance of motion, where the body adapts to cold, current, and exhaustion.', 'Endurance Swim'),
  (242, 'skill-031b45109003d4637a1a8998b1216e72c61631ae0b05db111d04444dd09dab58', 'Open Water Navigator', 'standard', 3, 'CON', NULL, 'In unfamiliar waters, this skill grants instinctual guidance. Through feel, landmarks, and body awareness, the swimmer holds a straight path despite waves, wind, or disorientation.', 'Endurance Swim'),
  (243, 'skill-17bbd128a010b32f1126119730bfa641038181aac7fab8808316a9498f58e636', 'Current Negotiation', 'standard', 3, 'CON', NULL, 'The water has its own will—and this skill turns it into an ally. Trained swimmers sense shifts in flow and adjust in real-time, reducing drag and letting the current do part of the work.', 'Endurance Swim'),
  (244, 'skill-854e01993e41f25273c916eaaa7187f9ef11716d36d52e206c4d64e66ed13a52', 'Breath Management', 'standard', 2, 'CON', NULL, 'The difference between comfort and panic in the water, Breath Management trains control under pressure. Each inhale is intentional; each exhale calculated. This is survival through rhythm.', 'Swimming'),
  (245, 'skill-3b8204310faf6d8b3922f4c6ed10da8c4aa8be017ac73ebf7fbd1f6ca6c35d37', 'Breath Hold', 'standard', 3, 'CON', NULL, 'Whether diving deep or waiting for the moment to surface, Breath Hold extends the body’s limits. It transforms gasping urgency into calm focus—controlling the mind as much as the lungs.', 'Breath Management'),
  (246, 'skill-633978b7a7aed8aa3de98942d312643a1dd896b27f2c20245a1fa0118df79191', 'Underwater Glide', 'standard', 3, 'CON', NULL, 'A fusion of breath control and body position, this skill lets the swimmer travel farther underwater with minimal effort. Like a shadow beneath the waves, they conserve energy and avoid detection.', 'Breath Management'),
  (247, 'skill-93ff872802fb33fbbfa306c6e3bffe1e523a1965aeb344c33e06aa0b7af4711b', 'SWB Prevention', 'standard', 3, 'CON', NULL, 'Shortness of breath is dangerous; shallow water blackout is fatal. This skill reflects trained instincts to detect signs of overextension and surface before blackout. It’s how discipline prevents disaster.', 'Breath Management'),
  (248, 'skill-5a813f12898bd9bba9af35946f8077e0699e76b2e602c426064fbcbf4b5c3c86', 'Disease & Toxin Resistance', 'standard', 1, 'CON', NULL, 'This foundational skill represents the body’s natural resilience to illness and internal threats. From foreign pathogens to environmental toxins, it measures how well your system endures and neutralizes invasive forces. It’s not just survival—it’s built-in defense.', NULL),
  (249, 'skill-0f42f10284f47fff975e358cebf32f962d99dc156c5e36930b8d328e6505c085', 'Pathogen Immunity', 'standard', 2, 'CON', NULL, 'Through exposure, training, or genetic strength, the immune system becomes a fortress. Pathogen Immunity reflects an enhanced resistance to biological threats, including viruses, bacteria, and other disease-bearing agents. It''s preparation before infection strikes.', 'Disease & Toxin Resistance'),
  (250, 'skill-14b8ba5b5cc1494c9f135552ebdb7c97a465470c7c6c37c2613324a111525cde', 'Viral Barrier', 'standard', 3, 'CON', NULL, 'This skill strengthens the body''s frontline against viral invasion. Whether airborne or bloodborne, viruses find their progress slowed, weakened, or stopped entirely. Infections struggle to take root.', 'Pathogen Immunity'),
  (251, 'skill-d4b1eb22ab6c47049a242f460ad94562c604802485bf37f5b722dbc9066cebe2', 'Bacterial Shield', 'standard', 3, 'CON', NULL, 'Representing an advanced microbiome and immune coordination, this skill repels bacterial spread. Cuts resist festering, contaminated food is more easily endured, and infection fails to gain ground.', 'Pathogen Immunity'),
  (252, 'skill-8bcd9347dceab5e64a0160faf9eae512743d6c604e959ba64f46c5ab0b83ef08', 'Rapid Fever Response', 'standard', 3, 'CON', NULL, 'Fever becomes a tactical response, not a weakness. This skill trains the body to launch fast, effective thermal defenses against sickness, minimizing downtime and damage from systemic infection.', 'Pathogen Immunity'),
  (253, 'skill-bb255e0dec97ddf6086c69fe608a3438354bda5bb415c3bd82d9886da52fa457', 'Poison Neutralisation', 'standard', 2, 'CON', NULL, 'Where others fall from tainted meals or venomous wounds, this skill reflects the body’s ability to isolate and break down harmful compounds. The reaction is immediate, the defense internal.', 'Disease & Toxin Resistance'),
  (254, 'skill-c1ea857b30dbe57810c43d5fcc952b38c38c6a57a4a992f39f9f2497bbcb5bb6', 'Venom Metaboliser', 'standard', 3, 'CON', NULL, 'The body identifies and breaks down venom at the molecular level, minimizing paralysis, pain, or fatal damage. It’s not immunity—it’s rapid adaptation. The serpent''s bite loses its sting.', 'Poison Neutralisation'),
  (255, 'skill-0110d2980a42b616608dad2d0e431a296d9837b85935587461bcb4f5ecf3cec2', 'Alkaloid Flush', 'standard', 3, 'CON', NULL, 'From toxic plants to ingested poisons, this skill trains the system to purge alkaloids quickly. Nausea fades, clarity returns, and the gut reasserts control before harm spreads.', 'Poison Neutralisation'),
  (256, 'skill-b5f02f9c2718c22fa7d06a3c1aca4f0d001b9e7ce9e926d2eb7842cc6642a7f6', 'Heavy Metal Chelation', 'standard', 3, 'CON', NULL, 'When exposed to dangerous metals—mercury, lead, arsenic—this skill triggers natural chelation responses. The body binds and expels what would otherwise accumulate and poison from within.', 'Poison Neutralisation'),
  (257, 'skill-7420320c0fa1c746ae599db78c917490a944e3e35a6b1dd27f784c7cd0cb4632', 'Biochemical Purge', 'standard', 2, 'CON', NULL, 'The body''s detox systems work in harmony, flushing out residual toxins and restoring homeostasis. It’s not just resistance—it’s internal cleanliness maintained under stress.', 'Disease & Toxin Resistance'),
  (258, 'skill-0896ad914107b0f39fa2ed694670a404a06ffd2809e3f7f4a6f4bad15cc654e8', 'Detox Sweat', 'standard', 3, 'CON', NULL, 'Through skin and salt, the body eliminates toxins efficiently. This skill increases sweat-based purification, reducing internal buildup and supporting immune and organ functions.', 'Biochemical Purge'),
  (259, 'skill-267101fe36371aad2a82335077731ee5bcfaa42c61ce6c5fcf7018812649b98a', 'Hepatic Boost', 'standard', 3, 'CON', NULL, 'The liver becomes a biofilter of unmatched potency. This skill enhances its function, improving toxin breakdown, metabolic regulation, and cellular resilience against overload.', 'Biochemical Purge'),
  (260, 'skill-9db067441bb541df8f6d70a3aca0e7a8d7b4d51a49470299692a1884b70d3960', 'Renal Clearance', 'standard', 3, 'CON', NULL, 'The kidneys become relentless purifiers, rapidly cycling waste and filtering out contaminants. This skill ensures clarity, hydration balance, and resistance to bloodborne toxicity.', 'Biochemical Purge'),
  (261, 'skill-61968f8beb1d0e7a810f41e4c9076a63cd564d2656f5a6f4e25893517fa9dcb1', 'Environmental Survival', 'standard', 1, 'CON', NULL, 'This skill represents the body’s capacity to endure and adapt to hostile environments. From extreme temperatures to low oxygen and airborne hazards, it’s the cornerstone of survival in unforgiving terrain. Whether on icy peaks or toxic ruins, this is the strength to persist.', NULL),
  (262, 'skill-fa1894d9f7220e814f245020350d96a0309e8de3f0cb9ff06f50e165093f224d', 'Thermal Tolerance', 'standard', 2, 'CON', NULL, 'The body trains itself to withstand extremes of heat and cold. Thermal Tolerance reduces the risk of shock or exhaustion, keeping vital systems stable even as the climate turns brutal.', 'Environmental Survival'),
  (263, 'skill-2de99e32f10bc927651adb1cfb40cf94dc13685404b545c957651356aa4dda9d', 'Heat Resistance', 'standard', 3, 'CON', NULL, 'This skill refines your body''s ability to withstand high temperatures. Whether under desert suns or near open flame, your system stays cool, alert, and functional.', 'Thermal Tolerance'),
  (264, 'skill-f5ed42562a847877ac173a23b8da7745e5e16388dff1a70b37d7b2909e4b5352', 'Cold Resistance', 'standard', 3, 'CON', NULL, 'The chill no longer bites as deeply. Cold Resistance reflects the body’s improved circulation and resilience in freezing conditions—frostbite and hypothermia slowed or prevented entirely.', 'Thermal Tolerance'),
  (265, 'skill-17f9dcd6c1d3db0babb82f70b69c837375eb1eb59696bdd4c52d49f862509398', 'Rapid Rewarm', 'standard', 3, 'CON', NULL, 'When cold strikes fast, this skill allows the body to recover core temperature with speed and safety. Shivering becomes efficient heat, and hypothermia is driven off before it settles in.', 'Thermal Tolerance'),
  (266, 'skill-be86b8b08ad2f1784a26108fa0ce2327a688d78b97d92b4b0f86bb1720b971a3', 'Altitude Adaptation', 'standard', 2, 'CON', NULL, 'Above the clouds, air thins and pressure drops—but this skill lets the body adjust. It reflects gradual changes in breathing, circulation, and internal balance at high elevation.', 'Environmental Survival'),
  (267, 'skill-80760ada81c308d0f6d2768903422922f88a8eb4c030473548bfff4b4181f2c0', 'Hypoxia Control', 'standard', 3, 'CON', NULL, 'This skill teaches the body to survive on less oxygen. Breathing deep, blood enriched, the character can stay active longer at altitude with less fatigue or confusion.', 'Altitude Adaptation'),
  (268, 'skill-9fe1e62cc0dea74abf635de34a75c1912d21e35db6e58c7cb33d61388488348a', 'Fast Acclimation', 'standard', 3, 'CON', NULL, 'Where others need days or weeks, this body adapts in hours. Fast Acclimation allows a rapid response to elevation change, minimizing sickness and maximizing performance.', 'Altitude Adaptation'),
  (269, 'skill-730b109696f0ac04f0d0b3bca66c99cde6fe9f0f9c6953c46aad59d098d2f4d7', 'Thin Air Efficiency', 'standard', 3, 'CON', NULL, 'At high elevations, every breath counts. This skill reflects optimized lung and blood function, allowing endurance and clarity where others gasp for air.', 'Altitude Adaptation'),
  (270, 'skill-0ac1d13db6276796aa7723912dca40293d848432ff2c0cfe7be5cd68e0da5c87', 'Atmospheric Endurance', 'standard', 2, 'CON', NULL, 'This skill bolsters internal resilience against polluted, low-quality, or unstable air. It represents adaptation to smog, decay, or post-apocalyptic ruin without losing function.', 'Environmental Survival'),
  (271, 'skill-6ad62dd75ff7437c08fe46fac2e243f3f45965339ab08cfb53fe258c0cdc9133', 'Gas Filtration', 'standard', 3, 'CON', NULL, 'The lungs act as a more efficient filter, reducing intake of harmful particles or gases. This skill delays onset of nausea, disorientation, or collapse from airborne threats.', 'Atmospheric Endurance'),
  (272, 'skill-b50d6f0d9725cad437ceb91959cecc19bd7006a146a438e7cf6aa3e8c6ceae56', 'Smoke Resistance', 'standard', 3, 'CON', NULL, 'Whether in burning buildings or choking wastelands, this skill enables functioning amid smoke. The body learns to pace breath, resist coughing, and remain alert through haze.', 'Atmospheric Endurance'),
  (273, 'skill-b929f752ac8526d0b506daad5813b05fa2de71d66ea13f0366d17a3c4cf55a1c', 'Toxic Inhalation Mitigation', 'standard', 3, 'CON', NULL, 'When surrounded by poisonous air, this skill buys critical time. Through trained breath control and immune responses, the worst effects of airborne toxins are delayed or reduced.', 'Atmospheric Endurance'),
  (274, 'skill-47063563c43bff7d78f0d0da503d3240019be924f0e41971b0b59f890e4f61fe', 'Pain Management', 'standard', 1, 'CON', NULL, 'Pain is inevitable—suffering is optional. This foundational skill trains the body and mind to handle physical trauma without losing control, clarity, or composure. It is the art of staying present through agony.', NULL),
  (275, 'skill-dd375811056e37a15c0f6b3f9c15881f2e07f688e183add3de9d202af14bf3ed', 'Shock Control', 'standard', 2, 'CON', NULL, 'When the body is hit hard enough to shut down, this skill keeps it online. Shock Control represents internal stabilization—keeping heart rate, blood flow, and awareness intact during trauma.', 'Pain Management'),
  (276, 'skill-7cf339366ccdd7dad7acc74eb7694526afab13512ca78e364e231b1debfc5397', 'Pain Mitigation', 'standard', 3, 'CON', NULL, 'This advanced technique allows the mind to override incoming pain signals. Like a gate slammed shut, overwhelming stimuli are delayed or blocked entirely, granting precious moments of clarity.', 'Shock Control'),
  (277, 'skill-a3819963ad1dad1fe48c62126e9e25d1db40500e663753f43d80a194575e61f6', 'Trauma Dissociation', 'standard', 3, 'CON', NULL, 'The self separates from the suffering. Trauma Dissociation is the ability to mentally compartmentalize injury, allowing survival and action in situations where pain would otherwise cripple.', 'Shock Control'),
  (278, 'skill-6efefbf92f0ddf7385e3497422717133dd9a261eae156c17b8bef689c4b06059', 'Nerve Dampening', 'standard', 3, 'CON', NULL, 'This skill reduces the intensity of pain through trained neurological control. Sensations are dulled without losing awareness—allowing wounds to exist without owning the moment.', 'Shock Control'),
  (279, 'skill-e4a9b3f6bda6f37b24ba302b6147452b83a9646b2468f65944b6a16c3becfd33', 'Focus Through Pain', 'standard', 2, 'CON', NULL, 'Some train to fight despite pain—others train to focus because of it. This skill transforms agony into mental clarity, sharpening awareness in the presence of discomfort.', 'Pain Management'),
  (280, 'skill-f1cf4ca3b36a03923f864224bc9973159b880c5f7eecaaf71f5aae8b8eb63b53', 'Mind Over Body', 'standard', 3, 'CON', NULL, 'The pain is there—but it is not in charge. This skill reflects total mental dominance over physical reaction, allowing precise action even when wounded or exhausted.', 'Focus Through Pain'),
  (281, 'skill-33663b1985d23cbcdfdd95e1f732db607d049b551d72a54abe60f93401d0307b', 'Steady Aim Under Pain', 'standard', 3, 'CON', NULL, 'Whether bleeding or burning, this skill holds the hand steady. It reflects the ability to maintain precise physical control—especially for ranged or delicate actions—under active pain.', 'Focus Through Pain'),
  (282, 'skill-758b979378711d677ffd1542c17ca48d3e6c687065590040db0a92606399acc7', 'Controlled Breathing', 'standard', 3, 'CON', NULL, 'Inhale. Hold. Exhale. Controlled Breathing is a tactical response to pain, regulating oxygen, heart rate, and panic to keep focus sharp even when endurance wears thin.', 'Focus Through Pain'),
  (283, 'skill-d89c0460c5ca6bacac9dcbe767e1a174ac33ec242f2d905ac469c2794ed0531f', 'Adrenalyn Surge', 'standard', 2, 'CON', NULL, 'This skill taps into the body’s primal response—flooding it with adrenaline at will. The result is a temporary surge in energy, speed, or strength at the cost of later recovery.', 'Pain Management'),
  (284, 'skill-55600ba57fb01753b308506e1695c20fc57ad7398e82c24a3f9d6151406b428d', 'Safe Spike', 'standard', 3, 'CON', NULL, 'Adrenaline is a weapon, but it must be wielded with care. This skill refines the body’s spike response, increasing control and reducing the risk of cardiovascular collapse.', 'Adrenal Surge'),
  (285, 'skill-de07197699f975152409fc2127900bf378f5b527fb57e1f3bc6016de5f000b60', 'Surge Sustain', 'standard', 3, 'CON', NULL, 'Where others burn out in moments, this skill draws out the rush. Surge Sustain prolongs the beneficial effects of adrenaline, keeping the body in peak state for critical windows of action.', 'Adrenal Surge'),
  (286, 'skill-d5c031a56439e4212ffbbb4e528f7c18f7ff318577f5411c53553d6f781eba77', 'Rapid Crash Recovery', 'standard', 3, 'CON', NULL, 'When the surge ends, the crash comes fast—unless trained otherwise. This skill speeds the body’s recovery from hormonal spikes, restoring balance and preventing collapse after the storm.', 'Adrenal Surge'),
  (287, 'skill-66f06bcd0c6d47d40fc5f6c14e27e64f7ee5d1db755063eef44e282a96f333c9', 'Metabolic Control', 'standard', 1, 'CON', NULL, 'This foundational skill governs the body''s ability to manage energy, oxygen, and temperature under stress. It reflects internal mastery over processes usually left to instinct. Through discipline and conditioning, the body becomes its own command center.', NULL),
  (288, 'skill-0b44c59e646cd559da7be413fd319ead8f57a8d92832743ebb7c80b64506a515', 'Breath Control', 'standard', 2, 'CON', NULL, 'This skill trains precise regulation of the breath to calm nerves, stabilize heart rate, and enhance oxygen efficiency. Whether meditative or combative, control begins with the inhale.', 'Metabolic Control'),
  (289, 'skill-5a0058dc555e6cf62b19f5ccb523ecf3425c30867dbd4cf63c41ab094a82e462', 'Box Breathing', 'standard', 3, 'CON', NULL, 'Used by warriors, divers, and monks alike, Box Breathing slows the mind through a measured rhythm of inhale, hold, exhale, hold. It creates stillness under pressure and balance under strain.', 'Breath Control'),
  (290, 'skill-3a89457ed52c0f831a796f2a66c2f0cc9181b7b93809745640ddd8e54a0a1000', 'CO₂ Tolerance', 'standard', 3, 'CON', NULL, 'This skill enhances the body''s ability to withstand elevated carbon dioxide levels. Useful in breath-hold training or oxygen-poor environments, it reduces the urge to panic and sharpens resilience.', 'Breath Control'),
  (291, 'skill-af7923cc2a6e4d52c1805593894f1c9d09114025c1aa0b047b5be18f47c83178', 'Oxygen Flush', 'standard', 3, 'CON', NULL, 'Oxygen becomes a weaponized resource. This skill trains deep, deliberate breaths to rapidly saturate the bloodstream, flush toxins, and prepare for intense bursts of effort or endurance.', 'Breath Control'),
  (292, 'skill-8e132cd2af3af2e9e216f7f456bba8dab123d9badc5f944e1e27ce0ad6e42a4a', 'Nutrition Cycling', 'standard', 2, 'CON', NULL, 'The body learns to shift between fuel sources with tactical intention. This skill represents trained rhythms of intake and fasting, maximizing energy retention and performance across varied conditions.', 'Metabolic Control'),
  (293, 'skill-56e8d1611330edb1ecdc923d8d19592784e70efc84eba2165184037dc210bf69', 'Carb Load', 'standard', 3, 'CON', NULL, 'Carbohydrates become fuel for sustained bursts of action. This skill allows the body to efficiently store and draw on carbs when rapid energy output is needed, from sprinting to combat.', 'Nutrition Cycling'),
  (294, 'skill-0fde4f06cfd54c1ef222ccd6fc83d22dc93d3d95f627a748898aabb66dadc52c', 'Ketogenic Switch', 'standard', 3, 'CON', NULL, 'The body adapts to burn fat instead of sugar for energy. This skill enables extended endurance with less food, supporting clarity and performance over long durations.', 'Nutrition Cycling'),
  (295, 'skill-5d89cc7f0d7c0a0f9943762c679056cf342ea58864b89cf6c27d8af5c6e76314', 'Glycogen Sparing', 'standard', 3, 'CON', NULL, 'By optimizing energy use, this skill reduces how quickly stored sugars are depleted. It extends stamina and delays exhaustion when energy is needed most.', 'Nutrition Cycling'),
  (296, 'skill-4b707ab6809a414d29a34a47f959af882ed57aa92be2aa3a0460307afb50b494', 'Thermoregulation', 'standard', 2, 'CON', NULL, 'This skill grants improved internal temperature control, reducing performance drop in heat or cold. It trains the body to self-correct when external conditions become extreme.', 'Metabolic Control'),
  (297, 'skill-f694706a404723d3a6cc54ea6aaa0cbcd2aed334a16cee8c03eb871811461498', 'Heat Generation', 'standard', 3, 'CON', NULL, 'Through precise metabolic shifts and muscular tension, this skill allows the body to generate warmth without movement. It is the fire within—activated by breath, focus, and need.', 'Thermoregulation'),
  (298, 'skill-4078b1a7bc24ceeda3c2a3340ca1bb27118b9f2dabcb28c304165666ba3aeb83', 'Rapid Cool', 'standard', 3, 'CON', NULL, 'When heat becomes a threat, this skill promotes swift internal cooling. It lowers risk of overheating and allows performance in conditions that would fell the untrained.', 'Thermoregulation'),
  (299, 'skill-b563839f2f1ddf40cfc715ca76dc5b1608f10fe537bca03dd19a1623d5cccc79', 'Efficient Sweating', 'standard', 3, 'CON', NULL, 'This skill reflects improved water balance and toxin release via sweat. The body cools faster, wastes less fluid, and maintains stamina in prolonged heat exposure.', 'Thermoregulation'),
  (300, 'skill-d61b231ae2382fe3557400562f0bab3f4fe9bbd79cee441e9ae5df84494cf456', 'Recovery & Rest', 'standard', 1, 'CON', NULL, 'Healing is not just passive—it’s an art. This skill reflects the body’s capacity to recover from fatigue, injury, and stress faster and more effectively than average. With proper rest and regulation, resilience becomes renewal.', NULL),
  (301, 'skill-45b8c3cde6f4719ac4fb16c15fde6bc097e308cd4ac75dca39c157ee555c2943', 'Accelerated Healing', 'standard', 2, 'CON', NULL, 'This skill trains the body to prioritize tissue repair, immune activation, and cellular recovery. Cuts close quicker, soreness fades faster, and wounds mend with surprising speed. Healing becomes a reliable response, not a waiting game.', 'Recovery & Rest'),
  (302, 'skill-459cd302f7eaf9b317f9eaa14ac15a16cd02051211ce2b7103a3489b04722e3f', 'Rapid Clot', 'standard', 3, 'CON', NULL, 'The moment blood flows, the body acts. Rapid Clot enables near-instant sealing of minor wounds, reducing blood loss and infection risk even in harsh environments. It’s the difference between limping away and bleeding out.', 'Accelerated Healing'),
  (303, 'skill-e26d92221795e3dcfbe3c752995bbde614c59ec79bd143db73791c72fbf3ecf2', 'Scar Reduction', 'standard', 3, 'CON', NULL, 'Healing leaves fewer marks. This skill refines tissue regrowth and collagen control, minimizing scar formation over time and improving skin and joint recovery. The body repairs with precision, not just speed.', 'Accelerated Healing'),
  (304, 'skill-e62ac50651ebb1cfab353ca9413091e5b4dc14d321f91e5e69fad3fd8611425b', 'Tissue Regeneration', 'standard', 3, 'CON', NULL, 'Beyond simple healing, this skill accelerates the rebuilding of muscles, tendons, and even deeper tissue. Recovery after damage is faster, cleaner, and more complete. It is the groundwork for total restoration.', 'Accelerated Healing'),
  (305, 'skill-5a1c142807339682f99d34a645481e1989b7544c6c53113d8ac3581aab35f85f', 'Sleep Efficiency', 'standard', 2, 'CON', NULL, 'Sleep isn’t just about time—it’s about quality. This skill improves the body''s ability to enter and benefit from deep rest, even with limited hours available. Recovery continues even when time is scarce.', 'Recovery & Rest'),
  (306, 'skill-57c9e0af9cc3df5d65f476b054e835ab69c168a4c7eec581b4fb26086145d232', 'Micro Sleep', 'standard', 3, 'CON', NULL, 'This skill trains the brain to extract restorative value from short bursts of rest. Even a few minutes of stillness can replenish alertness and mental clarity. It’s a tactical recharge—perfect for moments when sleep is scarce but focus is essential.', 'Sleep Efficiency'),
  (307, 'skill-4e8ae4f6536004b15acb1bc19ff1737d324d748e0ec9b9c47853c8bf00419396', 'REM Maximisation', 'standard', 3, 'CON', NULL, 'The most critical sleep cycle becomes more accessible and sustained. REM Maximisation enhances dream-state recovery, benefiting memory, emotion, and mental fatigue. It compresses full-body recovery into minimal time.', 'Sleep Efficiency'),
  (308, 'skill-098ac7f971f1aa30cea6a042c5010a0f0e1f8d28292a6cd165b439cbad2dfa60', 'Circadian Reset', 'standard', 3, 'CON', NULL, 'Whether adjusting to night shifts or jet lag, this skill allows the body to quickly realign its internal clock. Sleep comes when it''s needed—day or night. Rest is no longer at the mercy of schedule or sun.', 'Sleep Efficiency'),
  (309, 'skill-f03d715015a625ee140954b61f1c5a881f8fef8131c0ea993682aed0ae491154', 'Inflammation Control', 'standard', 2, 'CON', NULL, 'Swelling is the body''s alarm—but unchecked, it becomes a burden. This skill moderates internal inflammation, reducing pain, stiffness, and recovery time after stress or injury. It preserves function while accelerating healing.', 'Recovery & Rest'),
  (310, 'skill-252d80bfd4692170dd530a66cf323ecfded0cb8ab93b4b90854d2fb63ef4e828', 'Edema Reduction', 'standard', 3, 'CON', NULL, 'Water retention and puffiness are cleared with precision. This skill promotes lymphatic flow and blood return, minimizing swelling and restoring mobility. Whether after injury or exertion, the body clears excess fluid with practiced efficiency.', 'Inflammation Control'),
  (311, 'skill-4a09163b2c25879a0b2761549bd1c4320997c8f8bb638a898083a92d42b12f4c', 'Anti Oxidation', 'standard', 3, 'CON', NULL, 'Cellular decay is slowed through enhanced free radical management. Anti Oxidation improves recovery from metabolic stress and extends long-term tissue health. It’s restoration at the molecular level.', 'Inflammation Control'),
  (312, 'skill-956f0ba78ccd082bd0e1488c94d205e450d6b7dd9dd6b91780ff09207164df57', 'Pain Modulation', 'standard', 3, 'CON', NULL, 'This skill tunes the body''s internal chemistry to reduce CHAonic pain from inflammation. The edge softens, allowing movement, clarity, and rest to return. It’s a calm layered over internal chaos.', 'Inflammation Control'),
  (313, 'skill-1c93d5cee66779e7a16c67f1bf8e3b9fdb991d00e5ef9ee56a514ebcdbf8d9be', 'Research & Analysis', 'standard', 1, 'INT', NULL, 'This foundational skill reflects a mind built to uncover truth through study, observation, and methodical inquiry. Whether poring over books, databases, or field evidence, it represents the ability to extract meaning from information. The researcher is both detective and scholar—trained to see what others overlook.', NULL),
  (314, 'skill-78ca0bdf7e53f7f7fa6f6cf6d6affac03840fec1ae954798c8c3bf89997879bf', 'Library Research', 'standard', 2, 'INT', NULL, 'This skill is honed in archives and forgotten shelves. The character can efficiently navigate complex collections of written knowledge, extracting what’s needed while others get lost. It’s the art of finding answers buried in centuries of ink.', 'Research & Analysis'),
  (315, 'skill-5623fceb6adca72c96e023757c31fbd774782248cd2a89158ac7e4082d89e8b8', 'Catalog Mastery', 'standard', 3, 'INT', NULL, 'Knowing the systems behind the systems, this skill allows mastery of organizational structures in libraries, vaults, or record halls. With it, even misfiled or hidden knowledge can be swiftly located.', 'Library Research'),
  (316, 'skill-e7310467ce4230387613354d7e9fb80cf41200dbfddf7fd5517bb2c5c16f80b9', 'Cross Referencing', 'standard', 3, 'INT', NULL, 'This skill connects scattered facts across sources, weaving them into a clear picture. The researcher sees patterns, contradictions, and confirmations others miss—building conclusions from fraG.O.Dents.', 'Library Research'),
  (317, 'skill-3fc0c8471bfe0d042735389658c1f833e0bee83483096f1554562409f59963e7', 'Rare Text ID', 'standard', 3, 'INT', NULL, 'The ability to recognize valuable or obscure texts by script, language, or binding. With this skill, a character can identify works of historical, magical, or scientific importance—even if written in forgotten tongues.', 'Library Research'),
  (318, 'skill-b01508d05b6a7dcf211e891cedfead2a6534271cae2d2c9f922816755ac199cd', 'Data Mining', 'standard', 2, 'INT', NULL, 'This is the ability to extract meaning from massive pools of raw information. Whether digital or analog, the mind sorts noise from signal, looking for anomalies, gaps, or gold.', 'Research & Analysis'),
  (319, 'skill-15a01c3a095bef5e5363bee72ba2a334c90c0c6ecb3af48b4f3c13771f5c393c', 'Pattern Recognition', 'standard', 3, 'INT', NULL, 'The brain becomes a net that catches rhythm, anomaly, and trend. This skill allows the character to detect recurring structures and underlying causes—even in chaotic data.', 'Data Mining'),
  (320, 'skill-f7f123eff9809e0e65b8b0bd7603ec3e0fec1a0ac9c00cbfa9335ddf944f060d', 'Big Data Handling', 'standard', 3, 'INT', NULL, 'Vast volumes of info become manageable. This skill reflects mental organization and mental stamina to work with massive datasets without overload, collapse, or loss of detail.', 'Data Mining'),
  (321, 'skill-ce78e49333d1329dc930123e4bee821c14b23e81f5811a63e96bada29508a09a', 'Trend Projection', 'standard', 3, 'INT', NULL, 'The future leaves fingerprints. This skill allows the character to forecast likely developments by recognizing early patterns and extrapolating long-term outcomes.', 'Data Mining'),
  (322, 'skill-e5b2efc594cf63a3f417bc62cf7d4d484b60778583378043cc679b9e6cd41a55', 'Forensic Analysis', 'standard', 2, 'INT', NULL, 'This skill focuses the intellect on evidence—material, chemical, or circumstantial. It enables deep examination of clues left behind, especially in the wake of crime, sabotage, or decay.', 'Research & Analysis'),
  (323, 'skill-d0a3d04d5ef7961c10c96d31bc3b72553fae5d2d42d959f7f097a803dee83c9b', 'Evidence Chain', 'standard', 3, 'INT', NULL, 'This skill tracks the origin, journey, and context of discovered materials. It maintains logical chains of custody, meaning every finding stands as usable, traceable truth.', 'Forensic Analysis'),
  (324, 'skill-81fcaa0c4a15cf4c19200cd628c66c6d251dd3bac2e23493d338766bc8f8e842', 'Trace Material ID', 'standard', 3, 'INT', NULL, 'Microscopic fibers, dust, fluids, or blood—all become voices. This skill trains the eye and mind to spot and interpret the smallest evidence with forensic clarity.', 'Forensic Analysis'),
  (325, 'skill-883db1e7fa3e44d56cf59da11188495d7df5e49556d3a340b2a9e1b685f510cb', 'Scene Reconstruction', 'standard', 3, 'INT', NULL, 'The mind becomes the lens through which a moment is reborn. With limited clues, this skill re-creates what happened, in what order, and how—even when no witness survives.', 'Forensic Analysis'),
  (326, 'skill-8c85b6639e62e10b8330a8b883004b43c119053d7d62b512a98c77eb069627a7', 'Engineering', 'standard', 1, 'INT', NULL, 'This foundational skill reflects a mind wired for invention, structure, and precision. Whether crafting machines, analyzing load-bearing designs, or solving power flow, Engineering is the language of functionality. It turns raw materials into purpose-built creations.', NULL),
  (327, 'skill-94858baf06e606e14f22c92d8d4178d55882d9467eb57f721a4ac31d349936c0', 'Mechanical Design', 'standard', 2, 'INT', NULL, 'Focused on moving parts, levers, gears, and kinetic systems, this skill turns imagination into mechanical function. It’s how blueprints are born, refined, and made real.', 'Engineering'),
  (328, 'skill-6a8919ae89f4d5b472df7f5bb1574b051d4b84a59305cad5a105c55b77414340', 'Gear Tuning', 'standard', 3, 'INT', NULL, 'A machine is only as smooth as its gearing. This skill allows fine adjustments to timing, resistance, and torque, maximizing efficiency and longevity.', 'Mechanical Design'),
  (329, 'skill-47096357679d5d4f7ac21c99131e24df6e952aa98c0422a0cb47200a677f4a26', 'Kinetic Optimisation', 'standard', 3, 'INT', NULL, 'The art of motion itself—this skill refines how energy is transferred, reducing waste and boosting performance. It’s not just design—it’s fluid execution of force.', 'Mechanical Design'),
  (330, 'skill-d89b3035d0b4b612e9490f4dd7955e9968b28b32ff7a97cdc34ed911a43cf0b5', 'Micro Mechanisms', 'standard', 3, 'INT', NULL, 'Clockwork, miniaturized linkages, or tight-space engineering—this skill grants mastery over precise, small-scale mechanics. It’s the difference between functional and flawless.', 'Mechanical Design'),
  (331, 'skill-46dc436f4c0627a3538886e8b2d1aa7acae109cbf1c617a01e3be05cc84daf99', 'Electrical Systems', 'standard', 2, 'INT', NULL, 'Circuits, voltage, and current become a fluent language. This skill represents the design, repair, and understanding of electronic flow in devices and power structures.', 'Engineering'),
  (332, 'skill-14bea0eaf93727d7e9fa0548596c8f0d93b1f75e9c4ec7db0180d98f2e4f3330', 'Circuit Prototyping', 'standard', 3, 'INT', NULL, 'This skill reflects the ability to create functional circuit layouts by hand or tool. Whether from scrap or silicon, it brings the invisible lifeblood of power to life.', 'Electrical Systems'),
  (333, 'skill-4b70eb34507a663beeddef67479a663e0621be8195a6fe7a7dec19f32a724a3a', 'Signal Diagnostics', 'standard', 3, 'INT', NULL, 'With this skill, no short or surge goes unnoticed. It trains the mind to read and trace signal integrity across complex boards and repair what''s unseen.', 'Electrical Systems'),
  (334, 'skill-dc6d5d9c30d01f95a8be7a3ec78e09019b560953452f2b321a7e4bc9cc8a829d', 'Power Regulation', 'standard', 3, 'INT', NULL, 'Power without control is failure waiting to happen. This skill allows the engineer to balance energy demands, preventing overload and sustaining precision output.', 'Electrical Systems'),
  (335, 'skill-6ffb157b22d7362f2853f2474fe62a533ad79c705c620f7269dac2bc69c57398', 'Structural Fabrication', 'standard', 2, 'INT', NULL, 'From bridges to bunkers, this skill covers load-bearing designs, material use, and construction principles. It builds strong from blueprint to beam.', 'Engineering'),
  (336, 'skill-9d2642e4772f320b0f27677985eefaa7c1152782c25556f512fb8eec73082407', 'Load Calculation', 'standard', 3, 'INT', NULL, 'Before the first brick is placed, this skill determines how much force a structure can bear. It calculates tolerances, balances stress, and prevents collapse before it starts.', 'Structural Fabrication'),
  (337, 'skill-0fa6f67f06c80ebdab2d0ac739e0779300a1801c5f9f060d6cc9e28ac7c091ba', 'Stress Analysis', 'standard', 3, 'INT', NULL, 'This skill detects points of weakness before they break. It reflects an instinct for where pressure collects and how to reinforce or redistribute it in real time.', 'Structural Fabrication'),
  (338, 'skill-857504206a6bb9ab10a86011a41526aad0f9065cec055fc9870b1fba4cfa5f14', 'Modular Construction', 'standard', 3, 'INT', NULL, 'Built to move, change, or expand—this skill focuses on adaptive design. Structures become systems of interlocking parts, allowing repair, upgrade, and reconfiguration in the field.', 'Structural Fabrication'),
  (339, 'skill-98b020582a7ed7113e1c0000a3b25870984a2d7e7f5f7b4a6af3b05d132d2ec2', 'Systems Interface', 'standard', 1, 'INT', NULL, 'This skill reflects a mind capable of interfacing with mechanical, digital, or artificial systems. Whether navigating user layers or machine logic, the user doesn’t just operate systems—they understand their language. It''s intuition for structure, code, and flow.', NULL),
  (340, 'skill-e42a0269524940c12a02b8615db66bddefba3ca2425c22627c5684e5ad17f9e3', 'Logic Patterning', 'standard', 2, 'INT', NULL, 'Behind every function is a pattern, and this skill trains the brain to see and shape those sequences. It enables efficient scripting, clean logic loops, and error prevention through structural clarity.', 'Systems Interface'),
  (341, 'skill-78a4e48f7f80e751e11b875e903f8700b68bffb2b5f2f72fb36d894ce904a465', 'Pattern Streamlining', 'standard', 3, 'INT', NULL, 'The clutter of complex logic is stripped away. This skill refines convoluted systems into lean, elegant structures—maximizing speed, function, and legibility.', 'Logic Patterning'),
  (342, 'skill-73a743a314056f1d21a549962bd7b08b445136812aef6220e00f6217f9abfff6', 'Sequence Refinement', 'standard', 3, 'INT', NULL, 'This skill allows for targeted improvements within logic chains, optimizing process steps for clarity and reliability. Even if one link fails, the system can adapt and reroute.', 'Logic Patterning'),
  (343, 'skill-80bc64f099ac7d8675d2e1082a1e7bd27ed4156126436f7045dc3e123ad4dc28', 'System Fluency', 'standard', 3, 'INT', NULL, 'The system becomes second nature. This skill grants instinctual navigation and command over digital or mechanical frameworks, allowing on-the-fly configuration without hesitation.', 'Logic Patterning'),
  (344, 'skill-98764142f37efe64af194aa9c259df51223eef5547c99cb60f1fe19222dee641', 'Intrusion Defense', 'standard', 2, 'INT', NULL, 'This is the mind of a digital sentinel. Intrusion Defense enables the identification of weaknesses, unauthorized access, or corruptive inputs within any structured system.', 'Systems Interface'),
  (345, 'skill-fdb26f63f7a592516fca598dd85e0cb8023253af63877694b5aab5e96458ffe6', 'Vulnerability Mapping', 'standard', 3, 'INT', NULL, 'This skill creates a mental overlay of system weaknesses, visually or intuitively highlighting exploit paths. It’s both offensive planning and defensive foresight.', 'Intrusion Defense'),
  (346, 'skill-3f05579e8679fa24c5062b8923878d021759c1df173f325e23ca2a1591dd5586', 'Exploit Engineering', 'standard', 3, 'INT', NULL, 'When a system breaks, this skill decides how and where. It enables intentional crafting or prevention of code exploits, backdoors, and system overrides.', 'Intrusion Defense'),
  (347, 'skill-83ec8b6f7dc9bdc2ccbef1ab0a299589e3b3992c28d21bf0d82d7afcc238b6a1', 'Layered Safeguards', 'standard', 3, 'INT', NULL, 'No system is secure without redundancy. This skill develops multiple layers of defense—detection, misdirection, and failsafe protocols—to prevent both brute force and stealth intrusions.', 'Intrusion Defense'),
  (348, 'skill-9d72084fb2380cc38aab81b90edc460935546e2c677cd248bf512f755a7d6e90', 'Synthetic Cognition', 'standard', 2, 'INT', NULL, 'This skill reflects the merging of thought and artificial processes. Whether AI, drone logic, or mental projection into machines, the mind shapes the synthetic without delay.', 'Systems Interface'),
  (349, 'skill-d1eeacc86681fd3ff1a82b414d91da49f2045772e12eb4b724bae3f5b75a7033', 'Cognitive Shaping', 'standard', 3, 'INT', NULL, 'The user can adjust how artificial minds or scripts think, react, or learn. It’s not just programming—it’s behavioral engineering for machines.', 'Synthetic Cognition'),
  (350, 'skill-be943d9f005d358bd05548ff4684483c8bdb72e4543e2219133e9d37cf6ee315', 'Command Tuning', 'standard', 3, 'INT', NULL, 'When systems respond to commands, this skill ensures they respond correctly and efficiently. It refines outputs, reduces latency, and adapts intent to machine-specific dialects.', 'Synthetic Cognition'),
  (351, 'skill-7ef7c060ff70195b49c6a3db6d094869eb17970db6647ad8f8bb1ad1cabf5ef9', 'Independent Constructs', 'standard', 3, 'INT', NULL, 'This skill enables the creation or mentoring of synthetic systems capable of limited self-direction. Constructs gain adaptive protocols and semi-autonomous reasoning through refined design.', 'Synthetic Cognition'),
  (352, 'skill-a82ce870f999b01b17b9135b72d1f4b6d31217aec9cbee69d5bfc9659018ca06', 'Medicine', 'standard', 1, 'INT', NULL, 'Medicine is the disciplined study of the body, its ailments, and the means to heal or intervene. This foundational skill reflects clinical thinking, emergency responsiveness, and anatomical understanding. Whether in sterile hospitals or muddy fields, knowledge becomes life-saving action.', NULL),
  (353, 'skill-a232163263c32f908c66498189a3eb771460672f6a029ab0c7d285b8926ae41b', 'First Aid', 'standard', 2, 'INT', NULL, 'The immediate response to injury or illness before advanced care arrives. First Aid emphasizes stabilization, control, and efficiency under pressure—turning panic into precision.', 'Medicine'),
  (354, 'skill-6e6800a686868ee200c3b27bde7ee1b2abe97cfb52ed1c4e19bf9f2ca42db0db', 'Haemorrhage Control', 'standard', 3, 'INT', NULL, 'When blood flows fast, this skill slows it. It reflects rapid tourniquet use, pressure point knowledge, and clotting techniques that prevent fatal blood loss in the critical window.', 'First Aid'),
  (355, 'skill-a999e916a6780f4747c876abaed71f53be310b04d304434ed0cfa5860b0f2647', 'Fracture Stabilisation', 'standard', 3, 'INT', NULL, 'Bones may break, but movement must stop. This skill enables splinting, alignment, and immobilization to reduce further injury until full treatment is possible.', 'First Aid'),
  (356, 'skill-c0af527c0490551bacb37271ac4b65f0bb183080d0f8533b212931823f2ec7e8', 'Triage Prioritisation', 'standard', 3, 'INT', NULL, 'When many are wounded, choices must be made. This skill identifies who can be saved, who needs immediate help, and who must wait—ensuring resources are spent wisely.', 'First Aid'),
  (357, 'skill-e0621c15bb9efbfcadbc86690996935874c81453c85f134af95a06b8f49cd88b', 'Clinical Diagnostics', 'standard', 2, 'INT', NULL, 'This skill reflects the ability to interpret signs, symptoms, and test results to reach an accurate diagnosis. It’s part science, part deduction, and part intuition honed by study.', 'Medicine'),
  (358, 'skill-9eac3914ba06d612a1566a9953316401351839bfc61d8083a7fbbf9f53c069e3', 'Symptom Differential', 'standard', 3, 'INT', NULL, 'Every cough isn''t the same. This skill isolates similar symptoms to determine root causes, narrowing the possibilities with clarity and precision.', 'Clinical Diagnostics'),
  (359, 'skill-2a2c74883a65581d5b2c4df9afd17c0e440b565122f63266a8ffd67c9b879f2e', 'Lab Test Interpretation', 'standard', 3, 'INT', NULL, 'From blood work to imaging results, this skill extracts meaning from data. It turns numbers and visuals into actionable medical insight.', 'Clinical Diagnostics'),
  (360, 'skill-c5f115aba328b9c4c095bdb0bee661bdb89d3fed3b5fa21b8ccbc9c304d86021', 'Pharmacology Dosing', 'standard', 3, 'INT', NULL, 'Medicines are only as safe as their dosages. This skill reflects precise understanding of administration, interaction, and body weight response—avoiding both under-treatment and overdose.', 'Clinical Diagnostics'),
  (361, 'skill-4c06a922cd6763c2fc4513651f1004d8b82770138cec56b79f20075b2d087f48', 'Surgical Procedure', 'standard', 2, 'INT', NULL, 'A steady hand and a sharp mind—this skill enables invasive intervention with practiced care. It covers pre-op setup, field readiness, and core technique understanding.', 'Medicine'),
  (362, 'skill-e3d1df38fddaa04a7b48efd1a9ced31321139e2e0a55288c41206d484cf0d9e6', 'Incision Precision', 'standard', 3, 'INT', NULL, 'Every cut must count. This skill represents surgical accuracy—minimizing damage, blood loss, and recovery time through exact blade placement.', 'Surgical Procedure'),
  (363, 'skill-fa414bde61fedc39a3db747d53cb75a57582c95e23316600e33651bd5ad9e259', 'Suture Technique', 'standard', 3, 'INT', NULL, 'Flesh needs stitching, and this skill provides the finesse to do it cleanly. From battlefield closures to operating table threads, it ensures wounds are sealed and safe.', 'Surgical Procedure'),
  (364, 'skill-af0bf55583efabb5e171298fbe98641d7d2107208026bbfbd8a4665b7cf86340', 'Field Sterilisation', 'standard', 3, 'INT', NULL, 'Infection is as deadly as injury. This skill allows improvisation of sterile environments and tools in non-clinical settings—preserving safety when standards can’t be guaranteed.', 'Surgical Procedure'),
  (365, 'skill-de0152f952776f09f537d309f1f3f0ec7369c8df1297071e946952f798c86063', 'Chemistry', 'standard', 1, 'INT', NULL, 'Chemistry is the study of substances, their transformations, and the forces behind those changes. This skill allows the user to manipulate matter on a molecular level, crafting, combining, and breaking down with intent. Whether in lab or field, knowledge becomes reaction.', NULL),
  (366, 'skill-a23f3e1e3ab47f3ad14772d7a9973af4b3fb7e5ed135df499db1ee1f61e305ed', 'Synthesis', 'standard', 2, 'INT', NULL, 'This skill represents the creation of compounds from simpler materials. Whether concocting a medicine, alloy, or adhesive, it allows for intentional molecular assembly.', 'Chemistry'),
  (367, 'skill-d8a5d5f57da8969695e925c1971b0bb4975f5492fd2d9a2d057b65e0b27a5bd3', 'Organic Synthesis', 'standard', 3, 'INT', NULL, 'Focused on carbon-based chemistry, this skill enables the crafting of biochemicals, plant extracts, and medicinal reagents. The user navigates complex reactions with biological precision.', 'Synthesis'),
  (368, 'skill-f141f63b2db82d3fb26f30d3550c0c03bb58534ae9e1bf28cdee0f20621efdb6', 'Polymeric Casting', 'standard', 3, 'INT', NULL, 'Plastics, resins, and elastomers take shape under trained hands. This skill covers the controlled formation and molding of long-chain molecules for use in tools, armor, or insulation.', 'Synthesis'),
  (369, 'skill-f4ca7644fcb971c0d1ca2f81457cc75b064c5b1ad7407c9fee89af78410699a7', 'Compound Purity', 'standard', 3, 'INT', NULL, 'Impurities ruin function. This skill refines the user’s ability to isolate and perfect substances—ensuring stable reactions and maximized potency in every result.', 'Synthesis'),
  (370, 'skill-f44e85c4b8ea2addc796f8beab6600e801d767ccd26c800dce6d88fdaa5eb4e6', 'Analysis', 'standard', 2, 'INT', NULL, 'The counterpart to synthesis, this skill focuses on identifying substances through observation and testing. It breaks the unknown into known components.', 'Chemistry'),
  (371, 'skill-9f1e30d3a1dd018336b5e2314066a0d9ff8ea5c5d8831f7bda2f2695fab44e95', 'Spectrography', 'standard', 3, 'INT', NULL, 'Using light to decode matter, this skill allows precise identification of elements and compounds via spectral signature. Even trace amounts reveal themselves to a trained eye.', 'Analysis'),
  (372, 'skill-41d635576ad486f6067a5e6a59b45dbd08becf4b967d4f4720daa1c9f51296cf', 'Titration Mastery', 'standard', 3, 'INT', NULL, 'A careful drop at a time, this skill balances acid, base, and beyond to reveal concentrations and reaction points. It reflects patience, control, and accuracy under chemical tension.', 'Analysis'),
  (373, 'skill-dc73465aefa405b42b44e73431ecbbf228d2956c2f694d2075de72d007752d05', 'CHAomatography', 'standard', 3, 'INT', NULL, 'This skill enables the separation and study of mixtures through flowing media. Whether ink, blood, or poison, components reveal themselves in layered color and structure.', 'Analysis'),
  (374, 'skill-da4c27510a875d8405d2421ad1a6d375b132c4482cb1576bfcd6a27d0b8ef507', 'Energetics', 'standard', 2, 'INT', NULL, 'Focused on energy release and control, this skill handles the chemistry of combustion, explosion, and propulsion. It is fire wielded with intellect.', 'Chemistry'),
  (375, 'skill-c2c68ffc3f1e273071c27a3c7212b7d79b531a7f2019fb095d8e1fd81409ec1b', 'Propellant Formulation', 'standard', 3, 'INT', NULL, 'This skill designs fuel sources—solid, liquid, or hybrid—with exacting balance. Burn rate, thrust, and containment are engineered into reliable performance.', 'Energetics'),
  (376, 'skill-0d4c246911833a2140ef103f023e97649e6ed4d9cb32d155d7d83ff4a87f2de8', 'Controlled Detonation', 'standard', 3, 'INT', NULL, 'Not all explosions are chaotic. This skill ensures timing, force, and direction are all intentional, reducing risk while maximizing result. Precision meets power.', 'Energetics'),
  (377, 'skill-f91d640970481c4557fbc85d2444948dae47351c8683e78be56a88cbed03bb8a', 'Stability Testing', 'standard', 3, 'INT', NULL, 'Heat, impact, pressure—this skill determines what a compound can survive. It prevents accidents and ensures that volatile materials are handled with the respect they demand.', 'Energetics'),
  (378, 'skill-dc45dfad16ef8220aceaf09fe9a4c8e17e377d1ec41b544972ab99bc0e8b0468', 'Cryptography & Linguistics', 'standard', 1, 'INT', NULL, 'This skill reflects mastery over language, symbol, and secrecy. It encompasses the decoding of ancient tongues, creation of private scripts, and manipulation of meaning across cultures. Where others see noise, this mind sees structure.', NULL),
  (379, 'skill-cb2e987adeaca5c78f186eba9ae91e5517d958f945fc58525c97d670004e24fa', 'Language Deciphering', 'standard', 2, 'INT', NULL, 'From runes to dialects, this skill allows understanding of unfamiliar languages through pattern, root, and sound. It’s decoding without a dictionary—reconstructing meaning from exposure.', 'Cryptography & Linguistics'),
  (380, 'skill-bfd6824c276cc26f75109334704db48618a3d64b0c9f2d3a43e3e5ed14421afb', 'Dead Tongue Reading', 'standard', 3, 'INT', NULL, 'Forgotten languages leave clues. This skill enables reading and partial reconstruction of extinct or lost tongues from fraG.O.Dents, syntax echoes, and linguistic lineage.', 'Language Deciphering'),
  (381, 'skill-6e5e9df6cdf4d573efb1cfc4c9ea97cc07ad7160d69b2fc03a37c3f90615efd0', 'Accent Acquisition', 'standard', 3, 'INT', NULL, 'Mimicry meets fluency—this skill allows the speaker to rapidly adapt pronunciation, cadence, and inflection. It smooths communication and masks origin.', 'Language Deciphering'),
  (382, 'skill-37dd671b0fc5fdb1d832e0cad1d973e73b9c76ecec4fe77038bff5b423951379', 'Rapid Translation', 'standard', 3, 'INT', NULL, 'With only brief exposure, the user can grasp context and meaning from foreign speech or script. This skill accelerates comprehension, even across unfamiliar or hybrid languages.', 'Language Deciphering'),
  (383, 'skill-c3742c707c00d32df8403d814e29174d8f7687ed04b53c679a44af49580f30c9', 'Code Making', 'standard', 2, 'INT', NULL, 'This skill creates secure systems of hidden meaning. From encryption protocols to secret alphabets, it ensures only the intended reader can unlock the message.', 'Cryptography & Linguistics'),
  (384, 'skill-4a5fd7ea89b10be963a80ac114ec7e6eba00967037a2747bf596224d865ef223', 'Cipher Construction', 'standard', 3, 'INT', NULL, 'The bones of encryption. This skill enables the creation of substitution, transposition, or hybrid ciphers with layers of defense. Each system built is its own puzzle.', 'Code Making'),
  (385, 'skill-4af30e70ba0a9b39a7e6a9980dd254125d726e1d7a34855f5ebf1ee35310d37f', 'One Time Pad', 'standard', 3, 'INT', NULL, 'This advanced cryptographic method uses random keys that can never be reused or cracked. With this skill, near-perfect secrecy is achieved—if the key is never compromised.', 'Code Making'),
  (386, 'skill-2c430fb10dcd04d9345548fda2a562e5902e939a2b0666ce0e3cb1cb7f552e02', 'Steganographic Embed', 'standard', 3, 'INT', NULL, 'Hiding messages in plain sight—within images, texts, or audio—this skill allows for concealment so subtle it escapes detection entirely. A word within a pattern, a whisper in the static.', 'Code Making'),
  (387, 'skill-afd96145e45c26766a2c76c55ef2361e9f9586d620e11b6bab8b307dfdb0bc6d', 'Symbol Interpretation', 'standard', 2, 'INT', NULL, 'From graffiti to cave etchings, this skill extracts meaning from nonverbal signs. It deciphers symbols, pictographs, and glyphs by form, placement, and cultural logic.', 'Cryptography & Linguistics'),
  (388, 'skill-8be0ab2382cc4fbf185645d8ec54092ae0a02d054325a488aad4bd1d2e27ebdb', 'Semiotic Analysis', 'standard', 3, 'INT', NULL, 'This skill breaks down how signs and symbols generate meaning. It allows deep understanding of context, usage, and embedded ideology—critical in decoding constructed messages.', 'Symbol Interpretation'),
  (389, 'skill-ccc699a48aa931b43caf001240c322f0483daa722e16e2e37f00c3451bf4344e', 'Cultural Context', 'standard', 3, 'INT', NULL, 'Symbols only matter if you know the world they came from. This skill ties markings and words to the belief systems, fears, and values of the people who made them.', 'Symbol Interpretation'),
  (390, 'skill-6a7145b91473ee3f850f10a9bbada804afd621950674a0679e4c7e7cea5b8245', 'Pattern Keying', 'standard', 3, 'INT', NULL, 'Where repeated shapes, rhythms, or structures exist, this skill identifies them and reveals hidden layers of meaning. It’s the key that unlocks the pattern inside the symbol.', 'Symbol Interpretation'),
  (391, 'skill-edc64a34c2bf282845a5b043a728017e130228cec9c6445a5daf507b52431e69', 'Tactical Planning', 'standard', 1, 'INT', NULL, 'Tactical Planning is the mental framework for anticipating, organizing, and executing action in dynamic environments. It balances short-term precision with long-term vision, ensuring preparedness under shifting threats. Every move is made with layers of purpose.', NULL),
  (392, 'skill-527060fe28fe0fd8ed227adf9119f564889a2e2e4d55f1a5a3dfe2fe7c585411', 'Strategy Modelling', 'standard', 2, 'INT', NULL, 'This skill enables simulation of possible outcomes based on known assets, terrain, and behavior. Strategy Modelling visualizes moves before they happen—building winning plans before the first step.', 'Tactical Planning'),
  (393, 'skill-dcb71ad9c2b57759d1969be5fd940d94b1c999bb63dd971670467d81b39d0ff9', 'Battlefield Sim', 'standard', 3, 'INT', NULL, 'Whether virtual or mental, this skill constructs battlefield scenarios with live variables. It allows pre-action testing of tactics, revealing blind spots and opportunities alike.', 'Strategy Modelling'),
  (394, 'skill-6c42dd8107ae87e06c49c2e827de9347658d178af72d54a979ebf8de8ed6ab12', 'Risk Assessment', 'standard', 3, 'INT', NULL, 'No plan survives without evaluation. This skill identifies where failure is most likely, weighing cost, timing, and benefit to strengthen decision-making under pressure.', 'Strategy Modelling'),
  (395, 'skill-4a1912586e569f87c883291c857d3c82ccb846ade385479811aa216dbfaddc29', 'Object Prioritisation', 'standard', 3, 'INT', NULL, 'In chaos, focus becomes survival. This skill enables rapid triage of goals, threats, and objectives—ensuring what matters most is handled first.', 'Strategy Modelling'),
  (396, 'skill-0ffbf9672bc02cfceb1ea53f401e3d0ccacee80aa071e7082d11e38a77fffff7', 'Resource Allocation', 'standard', 2, 'INT', NULL, 'This skill turns limited assets into strategic advantage. Whether assigning people, gear, or time, it ensures nothing is wasted and every tool has a purpose.', 'Tactical Planning'),
  (397, 'skill-a47df8ef424fe1d97c1c5f061b67f7afa9fcddc3720cb2386da6729f30f14f19', 'Supply Chain Map', 'standard', 3, 'INT', NULL, 'Knowing where things are is as vital as having them. This skill visualizes the full supply path from source to use, exposing breaks, delays, or excess.', 'Resource Allocation'),
  (398, 'skill-dd9e57a946792d6c87641a9416fcb02df9e9e3c2d7092320ea5c3102ad048c0e', 'Efficiency Analysis', 'standard', 3, 'INT', NULL, 'This skill tracks performance and waste across operations. By identifying lag, overuse, or redundancy, it sharpens systems to run lean and strong.', 'Resource Allocation'),
  (399, 'skill-a67b4b4a75c402f19b18506c8b07fae1e133be02fd5c534a7aae14ea953013b4', 'Redundant Routing', 'standard', 3, 'INT', NULL, 'Backup paths, alternate drop points, or fallback logistics—this skill designs secondary flows to prevent mission failure if the primary plan breaks.', 'Resource Allocation'),
  (400, 'skill-d596bb0e999c62c6ab80d2eb3a147ca1e5461db21d331ff8bed4bef77906340f', 'Contingency Crafting', 'standard', 2, 'INT', NULL, 'The unexpected is expected. This skill enables the creation of backup plans layered into the main strategy, ready to activate if things go wrong.', 'Tactical Planning'),
  (401, 'skill-fec2d7e96aae3de0ae85a71bf5774085e745a6304ad2f1d4073436e313deb3a3', 'Fail Safe Design', 'standard', 3, 'INT', NULL, 'This skill embeds protections into systems, operations, or tech to prevent catastrophic failure. Even in collapse, it ensures something still works.', 'Contingency Crafting'),
  (402, 'skill-8321f5baa6f948950ec6a7a90380014a8518f47ea9a3ac4d4f6ab44c75ec5ad5', 'Exit Route Recognition', 'standard', 3, 'INT', NULL, 'Knowing when and how to leave is as strategic as knowing when to strike. This skill maps retreat paths, extraction zones, or fallback positions—always with time to act.', 'Contingency Crafting'),
  (403, 'skill-c32f67721062eb570abd09889f63fea702d2fffcfa0cba813bc6243252bd4038', 'Adaptive Response', 'standard', 3, 'INT', NULL, 'This skill trains flexible thinking in live conditions. When plans fail, it enables rapid recalibration without hesitation—turning failure into improvisation.', 'Contingency Crafting'),
  (404, 'skill-6611032577e5a7b3a146e7b2111117b71a2a7b0fa4ef2861353816730a4f4a02', 'Innovation', 'standard', 1, 'INT', NULL, 'Innovation is the art of applied creativity—taking the imagined and making it real. It covers conceptual breakthroughs, adaptive solutions, and systems that didn''t exist until now. The innovator solves what others accept.', NULL),
  (405, 'skill-0b11461126e01a7fef654ca2063336a9170cc523702b7245f113dc08ac9821b5', 'Prototype Ideation', 'standard', 2, 'INT', NULL, 'This skill captures the early stages of invention—sketching, modeling, and mentally testing new designs. It''s not about polish, but about having the boldness to begin.', 'Innovation'),
  (406, 'skill-692aafcae43dd3e3e7cfd33260b3ab333293b3de8e2bbe90a8af117005db3a04', 'Rapid Prototype', 'standard', 3, 'INT', NULL, 'When time is tight, this skill builds functional models fast. Whether from scrap or kit, it gets the concept in-hand and working with minimal delay.', 'Prototype Ideation'),
  (407, 'skill-64b76b0569bd83cecdf50fc76b797ab4adbab939017dc356dd126b2c972286ce', 'Proof of Concept', 'standard', 3, 'INT', NULL, 'An idea means little until it functions. This skill validates whether a design can do what it claims, isolating the core test that proves viability.', 'Prototype Ideation'),
  (408, 'skill-2205a9a393bd0bff4596d71ba0540f5058b9b04beaefff2fa309622fc8259761', 'Design Iteration', 'standard', 3, 'INT', NULL, 'The first version is never final. This skill enables fast, efficient tweaks to an idea—reworking flaws, improving strengths, and driving version after version forward.', 'Prototype Ideation'),
  (409, 'skill-bdecdcde938a10ed102c9c8051b070b442a5df3aa563aa4889fd473e8a91a005', 'Improvisation', 'standard', 2, 'INT', NULL, 'With limited tools or materials, the innovator adapts. This skill represents quick thinking, unconventional use of parts, and making things work under pressure.', 'Innovation'),
  (410, 'skill-2a6e8b09536d2766f98fd4a32e3cb623840d890478ac0d0bd19f003294de1550', 'Jury Rig', 'standard', 3, 'INT', NULL, 'When systems fail, this skill gets them running again—maybe ugly, but functional. Jury Rig reflects fast fixes, stopgap solutions, and field-ready patchwork.', 'Improvisation'),
  (411, 'skill-cba3ba3c0c2fe42e946d399bac16dd05dd2bc9c391db4d8ad23c6d01133a16b5', 'Field Repair', 'standard', 3, 'INT', NULL, 'Beyond the workshop, this skill keeps gear alive under rough conditions. From broken drones to cracked helmets, the innovator restores function when failure isn’t an option.', 'Improvisation'),
  (412, 'skill-4b7f31e080bce7a84f6d55a49a7d916503dff48eb4741c17e3cf4821ce216150', 'Material Substitution', 'standard', 3, 'INT', NULL, 'When the ideal part isn’t available, the innovator finds an alternative. This skill allows for safe, effective swaps using local, salvaged, or even organic components.', 'Improvisation'),
  (413, 'skill-8e72869103f39ec3d1e0f8fc8021554280e711cf634e9592e5ad96dc256f36e5', 'Optimisation', 'standard', 2, 'INT', NULL, 'Every system has room to improve. This skill sharpens designs, workflows, or outputs for greater effectiveness—often through small, elegant changes.', 'Innovation'),
  (414, 'skill-1d55f2928c48077bc17282a4c437cca7fc88e93cc23bd558c1f5694e36db9e6a', 'Process Streamline', 'standard', 3, 'INT', NULL, 'This skill identifies bottlenecks and oversteps in any process. It trims excess and accelerates outcomes, turning a good system into a great one.', 'Optimisation'),
  (415, 'skill-01d41dfa262754ac0bca73c305517b847c91910789ebb22c885037dd2ae9aafe', 'Cost Reduction', 'standard', 3, 'INT', NULL, 'Efficiency is more than speed—it’s also expense. This skill finds ways to produce the same result with fewer resources, lower energy, or simpler inputs.', 'Optimisation'),
  (416, 'skill-4b92b5aadb83255316a58ac7bf3118aa4d8a5479215ec19a4aa411776df111da', 'Performance Boost', 'standard', 3, 'INT', NULL, 'Every system can go further. This skill extracts more output, power, or reliability from existing designs—without needing to rebuild from scratch.', 'Optimisation'),
  (417, 'skill-0096f3fdd1241d7a463ca8fe528e3ab63702ba051afce52f68144f39e6e671c8', 'Channeling', 'magic stabalization', 1, 'INT', NULL, 'Channeling grants your character the ability to act as a conduit for supernatural energy. Whether divine, arcane, or elemental, this skill determines how much mana or power can be safely drawn into the body. The more practiced the channel, the more intense and sustained the force they can wield. Required to effectively channel magic from any sphere.', NULL),
  (418, 'skill-6d19d7f84196d56a66868899bd94c012b6a7154eb180c76d75ee737428246e79', 'Meditation', 'magic regeneration', 1, 'INT', NULL, 'Meditation cultivates internal stillness and spiritual clarity. Through this practice, your character recovers mana, centers their will, and fortifies their connection to unseen energies. Meditation is required to restore mana after magical exertion.', NULL),
  (419, 'skill-1702eb2b18067d7f1613d064ed4a8dd4f06f9a76ea254031d8e53fed926967bb', 'Spellcraft', 'magic access', 1, 'INT', NULL, 'Spellcraft is the intellectual mastery of magical form and function. With it, characters access magical spheres and manipulate spell structures with intent and precision. This skill grants access to magical spheres for casting spells.', NULL),
  (420, 'skill-486e22f86c69014c43d5ccf749ea2e3d2c59f6bac787decda4b859e3672780f9', 'Talismanism', 'magic access', 1, 'INT', NULL, 'Talismanism is the art of embedding magic into objects—stones, metals, parchment, or bone. It grants access to the same spheres as spellcraft, but through crafted focus rather than cast command. This skill grants access to magical spheres for talisman-based use.', NULL),
  (421, 'skill-9327b46b590a1441bb4a7272b4982906f3983000365e69057b14e0c7baa5ffb7', 'Perception', 'standard', 1, 'WIS', NULL, 'Perception reflects your ability to notice, interpret, and respond to subtle cues in your surroundings. It governs all sensory input—sight, sound, motion, and presence—and helps detect what others overlook. Whether watching from afar or catching a whisper nearby, this skill tunes the mind to the world.', NULL),
  (422, 'skill-e35422d09ba60c7c091f2755e5736c3ab2f60c8362bbc47e8b2339cbb92a3889', 'Visual Acuity', 'standard', 2, 'WIS', NULL, 'This skill hones the eyes to spot details, shifts, and movement others miss. Visual Acuity enables clearer recognition at distance, in motion, or under stress. It''s about seeing with intent, not just eyesight.', 'Perception'),
  (423, 'skill-953d42db0e1caced5e4a5d8377c57ec3ba7fee44f0231151ce99a3d2a4308a34', 'Long Sight', 'standard', 3, 'WIS', NULL, 'Long Sight allows recognition of distant shapes, figures, or terrain features with remarkable clarity. It extends the visual horizon beyond normal range.', 'Visual Acuity'),
  (424, 'skill-0c2be5caf1c2125930c4a296e6bbfb647de600904badc58b6038d56281357eb2', 'Low Light Vision', 'standard', 3, 'WIS', NULL, 'This skill enhances the ability to see in dim or near-dark environments without relying on artificial light. It draws on natural adaptation and trained sensory recall.', 'Visual Acuity'),
  (425, 'skill-342776df06920c5d3bab5a5173b87e2ef45f2239dca69e8aff2cbbb93a1ce277', 'Motion Detection', 'standard', 3, 'WIS', NULL, 'With Motion Detection, even the slightest shift draws attention. This skill allows your eyes to prioritize movement instinctively, useful for tracking, spotting ambush, or trailing prey.', 'Visual Acuity'),
  (426, 'skill-d169c5f62f0cf10ac2b2a87c04f067b6d30107955f083773f10556797dd3de0f', 'Auditory Acuity', 'standard', 2, 'WIS', NULL, 'Auditory Acuity sharpens hearing to catch whispers, shifts in tone, and subtle environmental cues. It trains the ear to isolate sound and react to it with precision.', 'Perception'),
  (427, 'skill-e22c171356418994eec1829bde983870c32b0171c81bf229cb9b68a8179f12b1', 'Acute Hearing', 'standard', 3, 'WIS', NULL, 'This skill pushes hearing to its limit—identifying small sounds, distant footsteps, or quiet speech in noisy environments.', 'Auditory Acuity'),
  (428, 'skill-cc49f840eb54799dc0f6b5151b1bd44e7a8bb06fb8822cf038785e2acc926b22', 'Frequency Filter', 'standard', 3, 'WIS', NULL, 'Frequency Filter allows the brain to ignore background noise and tune into specific audio ranges. It’s like having an internal noise gate.', 'Auditory Acuity'),
  (429, 'skill-e7b6ecb695bf9776329f47d5a83e417516c5907ed29ce430552c4608b105b3e0', 'Echo Read', 'standard', 3, 'WIS', NULL, 'Echo Read interprets sound reflections to detect spatial changes or unseen movement. It enables primitive echolocation-style awareness.', 'Auditory Acuity'),
  (430, 'skill-11740cc8809aec7afdbac843eb572cdd3064bb0d577ae440f90e3116f7b02f84', 'Situational Awareness', 'standard', 2, 'WIS', NULL, 'Situational Awareness connects sensory information into a unified field of understanding. It represents alertness to threat, position, and opportunity from all directions.', 'Perception'),
  (431, 'skill-539f44b9f99819452724b3b48a0c789549ddce0b4df5fae4e36d62e03768cf73', 'Peripheral Alert', 'standard', 3, 'WIS', NULL, 'Peripheral Alert trains the mind to process input from the edges of vision. It catches side movement, shifting shapes, and sudden threats without full focus.', 'Situational Awareness'),
  (432, 'skill-0b0f11d586d6317ace09f8d46eb3345cacac851412b50ea61c3537840ef67756', 'Quick Scan', 'standard', 3, 'WIS', NULL, 'This skill allows a fast but meaningful sweep of an environment, noting exits, individuals, or danger in mere moments.', 'Situational Awareness'),
  (433, 'skill-ca93be140955ef798b3fa88e53e4a47719ca11e262e90201572341ad7e0b0c90', 'Blind Spot Detection', 'standard', 3, 'WIS', NULL, 'The user develops an instinctive sense for what isn’t being watched. This skill identifies zones of vulnerability in combat, patrol, or observation.', 'Situational Awareness'),
  (434, 'skill-e43ba08557cbb4f19ed7684fe3cdbf5426fa2c145b8baced5e4fcec410c4e46c', 'Insight', 'standard', 1, 'WIS', NULL, 'Insight allows your character to read beneath the surface of words, actions, and silence. It reflects an intuitive grasp of motive, truth, and future consequence. From body language to tone shifts, it turns subtle clues into deep understanding.', NULL),
  (435, 'skill-94039131a5bf8d1bc6286869c60a222abddd4dd98f3b92f914fc6490b43bd7c3', 'Motive Reading', 'standard', 2, 'WIS', NULL, 'This skill focuses on deciphering why someone is acting the way they are. It detects concealed goals, internal conflict, or emotional pressure that shapes behavior.', 'Insight'),
  (436, 'skill-993d87acf127a8c40fa12a2851d81429cdcc2fee5f14dd8f929adf2f3ed8f1c6', 'Emotion Decoding', 'standard', 3, 'WIS', NULL, 'This skill isolates emotional states based on micro-expressions, tone, or gesture. It reads what’s felt even when nothing is said.', 'Motive Reading'),
  (437, 'skill-c2300a70e15e60dea7c151938de93283b9486bcf2b216bfc79194cf2e2716f7c', 'Agenda Exposing', 'standard', 3, 'WIS', NULL, 'With this skill, characters can unravel long-term motives or secret goals. It senses not just what someone wants now—but where they’re heading.', 'Motive Reading'),
  (438, 'skill-34f536a0ff95f74b854c8dd2c2a102844f33f54edcd1a6184a8c8d2f76de3b33', 'Pattern Spotting', 'standard', 3, 'WIS', NULL, 'This skill recognizes behavioral repetition and hidden cycles in speech, movement, or decision-making. It’s the tool for reading people like puzzles.', 'Motive Reading'),
  (439, 'skill-b18b31714eeebabbd1cfa879ce997efc78b1c8d4ceef28b1f4f9b79b0b2e33d5', 'Lie Detection', 'standard', 2, 'WIS', NULL, 'This skill trains perception to catch moments of dishonesty or distortion. Whether through tension, over-explaining, or misplaced details, deception leaves clues.', 'Insight'),
  (440, 'skill-407f59d8eed1ff78324cf060414b64943c62549af7bb72bc27581de030172c42', 'Pulse Check', 'standard', 3, 'WIS', NULL, 'Pulse Check reads stress responses—voice shifts, heart rate cues, or physical tells—under questioning. It''s not proof, but it''s strong suspicion.', 'Lie Detection'),
  (441, 'skill-368af878b07da5f08659c776bc8a1fd13e40177f926370b775f85fe37f560320', 'Verbal Tell', 'standard', 3, 'WIS', NULL, 'This skill analyzes word choice, filler, and sentence structure to reveal discomfort or deception. The truth struggles to hide in speech.', 'Lie Detection'),
  (442, 'skill-fef2bf34b8134de127e3d3207f8ee3bcada66a62f07b0152ec9756bf91446475', 'Body Language Reading', 'standard', 3, 'WIS', NULL, 'Posture, fidgeting, gaze—this skill interprets physical cues that betray truth or falsehood. The body speaks what the mouth avoids.', 'Lie Detection'),
  (443, 'skill-19d7378db33d9a91e2e9c67ec046f9b86e47952a9ad67be786d56b5201db5b35', 'Intuitive Forecast', 'standard', 2, 'WIS', NULL, 'This skill sharpens instinct toward what’s coming next. It takes small signals—social, environmental, emotional—and makes fast internal predictions.', 'Insight'),
  (444, 'skill-a959737cea3ea6c8411bc56982295aa1e5b37e96caf4aa63599de10eeee4ba32', 'Gut Alert', 'standard', 3, 'WIS', NULL, 'Gut Alert triggers when something is wrong—timing, words, or atmosphere. It’s an emotional warning, backed by unseen patterns.', 'Intuitive Forecast'),
  (445, 'skill-d73938cfc587a99b303799c3405577b50c5acaacc468b693f72a17f60b2b3727', 'Best Guess Projection', 'standard', 3, 'WIS', NULL, 'This skill forms logical predictions based on limited information. It’s the art of filling gaps in real time with tactical intuition.', 'Intuitive Forecast'),
  (446, 'skill-1427c8469418b0413c1a8185b9bcf26dc1c953a3d38162475596408574d8b747', 'Probability Reading', 'standard', 3, 'WIS', NULL, 'The user becomes skilled in weighing outcomes, assigning risk, and sensing which path is most likely. It is not calculation—it is practiced foresight.', 'Intuitive Forecast'),
  (447, 'skill-4032ee4038775060258f8e68061309aed9bfdea5b574f24324ab7f065202d052', 'Survival', 'standard', 1, 'WIS', NULL, 'Survival reflects the ability to live, travel, and adapt in wilderness environments without dependence on civilization. It includes the instincts and training needed to locate resources, read nature, construct shelter, and endure unpredictable conditions. A skilled survivor turns harsh terrain into home, and danger into routine.', NULL),
  (448, 'skill-5a95db2aa8e5d0883be7b8968983b8ea67d91f1e7ae5463b97258986a93de1be', 'Tracking', 'standard', 2, 'WIS', NULL, 'This skill allows a character to identify and follow trails left by people, animals, or creatures. It involves reading broken twigs, altered paths, disturbed ground, and even air currents. Tracking is the art of seeing stories written in the dirt.', 'Survival'),
  (449, 'skill-379579949eaedc2ff7e2909395b54f9d5882f60918811bedb4b3d0f9a4bcc881', 'Footprint ID', 'standard', 3, 'WIS', NULL, 'Footprint ID allows the user to determine size, species, gait, and even emotional state from a single track. Through precise interpretation, it reveals everything from weight and gear to urgency or injury.', 'Tracking'),
  (450, 'skill-df805241db980ab51b97b4c70332287fdd990c47cf33f3d32b0cf84f81338809', 'Scent Trail', 'standard', 3, 'WIS', NULL, 'This skill enables following a trail through lingering scent markers—natural or artificial. Whether tracking blood, sweat, pheromones, or smoke, the user can isolate and pursue a specific target over time.', 'Tracking'),
  (451, 'skill-09dc9cfc98639f2a9bffa8e4ae94ce82e8c26eb28c4a687547e37fd0362275b9', 'Long Trail Pursuit', 'standard', 3, 'WIS', NULL, 'Long Trail Pursuit grants endurance and clarity when following a trail over vast terrain or across days. It includes interpreting environmental shifts, rerouted paths, and older or disrupted trails.', 'Tracking'),
  (452, 'skill-6414818051f5d18853e77a14cfa7b16d254c3082630d0e66b3342e6951041316', 'Wilderness Foraging', 'standard', 2, 'WIS', NULL, 'Foraging involves identifying and collecting edible, medicinal, or useful plants and resources in the wild. This skill separates nourishment from poison, resource from danger. A true forager feeds others without ever drawing steel.', 'Survival'),
  (453, 'skill-8beaa4a80628e0558705bcee3a1a1809742de37e0d400d6aec263473388c9e81', 'Edible Plant ID', 'standard', 3, 'WIS', NULL, 'This skill provides encyclopedic familiarity with wild flora. It enables recognition of safe, nourishing plants even in unknown regions, including seasonal shifts and regional variants.', 'Wilderness Foraging'),
  (454, 'skill-4de103550b7404c0000ae3b8e717b8fcd322e9604340627a5dc77edaa9572f56', 'Water Locate', 'standard', 3, 'WIS', NULL, 'Water Locate grants the ability to read terrain, vegetation, animal behavior, and geological signs to uncover hidden or distant sources of fresh water. In dry places, this is life magic without the spell.', 'Wilderness Foraging'),
  (455, 'skill-478ad03542387a10cd5e65b06841402701a192fda0f5668edbeab84e09c578b5', 'Trap Setting', 'standard', 3, 'WIS', NULL, 'Trap Setting involves crafting and placing snares, deadfalls, trip lines, or other mechanisms to catch animals or deter intruders. It combines environmental blending with mechanical precision.', 'Wilderness Foraging'),
  (456, 'skill-bd4247786ccf28e466ac2c3802e939c19da95b611c229b7173dcc2658f65f848', 'Sheltercraft', 'standard', 2, 'WIS', NULL, 'Sheltercraft teaches how to build protective structures using natural or salvaged materials. It includes insulation, wind resistance, concealment, and time-efficient construction. Shelter is survival’s first breath.', 'Survival'),
  (457, 'skill-62b84ea3991583a6da9e97f423c953a92c853d895e8ace32e56bc804bd8a04bf', 'Quick Shelter', 'standard', 3, 'WIS', NULL, 'Quick Shelter emphasizes speed and necessity. It enables rapid deployment of functional shelters using minimal tools—ideal during storms, combat retreats, or exhaustion.', 'Sheltercraft'),
  (458, 'skill-6d580e7bbb82f576d45a4a643ea3b054f65c2f6f4f4572c9ce6828322e59b3b8', 'Camouflage Camp', 'standard', 3, 'WIS', NULL, 'Camouflage Camp blends the campsite into the environment, hiding signs of fire, scent, waste, or movement. This skill is favored by those who know eyes are always watching.', 'Sheltercraft'),
  (459, 'skill-985ec2d6bfd2560ed3e1869ef0903b0300793d3614a7abceca99680b03bb3e32', 'Hazard Proofing', 'standard', 3, 'WIS', NULL, 'Hazard Proofing reinforces shelter against fire, predators, flood, rockfall, or collapse. It includes smart site selection, pressure release techniques, and layered defense.', 'Sheltercraft'),
  (460, 'skill-57794bdeddd908748d80f827d22b534019ac4de886dde656caef927cbb839537', 'Investigation', 'standard', 1, 'WIS', NULL, 'Investigation is the pursuit of truth through focused observation, questioning, and deduction. It combines logic, intuition, and method to uncover hidden facts and reconstruct events. Whether probing a crime scene or unraveling a lie, this skill brings darkness into the light.', NULL),
  (461, 'skill-6150356a21aa0912981f4da16f8883ee7619f2ced5f42d0ba2d29d5f0e406df1', 'Evidence Gathering', 'standard', 2, 'WIS', NULL, 'This skill covers the physical collection and preservation of clues from any location. From footprints to fibers, it ensures no detail is lost—and nothing is contaminated.', 'Investigation'),
  (462, 'skill-8f2e3a984340205a5a361036023e79746333051caa99b811e9c724ea06d9c400', 'Trace Collection', 'standard', 3, 'WIS', NULL, 'Trace Collection focuses on retrieving microscopic or residual materials: hairs, dust, fibers, ash, and more. It detects what others would overlook.', 'Evidence Gathering'),
  (463, 'skill-b66128fb3883a1c6e20dcbd3ffe98e43d482c8e33a8cb85fe146f3442cbadf51', 'Tool Mark ID', 'standard', 3, 'WIS', NULL, 'This skill allows the identification of marks left by tools, weapons, or forced entry. It reconstructs what object was used, how it was used, and by whom.', 'Evidence Gathering'),
  (464, 'skill-4ce2285de8ab37da1bc19066f572e52c2cc7a1afd555c5a164c54ff24e19d4d3', 'Scene Mapping', 'standard', 3, 'WIS', NULL, 'Scene Mapping organizes all found evidence spatially—recreating the exact layout of events as they unfolded. It turns chaos into a readable timeline.', 'Evidence Gathering'),
  (465, 'skill-fa01dd9a58f815cbd128b8ede58a60324b1a0a24eb313383193739f23217bf9d', 'Interview Technique', 'standard', 2, 'WIS', NULL, 'Interview Technique covers the process of questioning witnesses or suspects. It involves tone control, observation, and eliciting useful information without overt pressure.', 'Investigation'),
  (466, 'skill-25b7b8259a88526fd5a01b51f10c1f52065e7e5420e35b829fc12aeeec0c0238', 'Rapport Building', 'standard', 3, 'WIS', NULL, 'Rapport Building creates emotional connection and trust quickly, even under tense or hostile circumstances. It opens people up—without them realizing.', 'Interview Technique'),
  (467, 'skill-408eb7e552e15f0745d5b0bbe1aa53550e17773f17f3d9edd84c0c85221e115e', 'Micro Expression Reading', 'standard', 3, 'WIS', NULL, 'This skill analyzes momentary facial cues that betray emotion: surprise, anger, fear, deceit. It’s the investigator’s window into unspoken truth.', 'Interview Technique'),
  (468, 'skill-cce58f8a533b46c394fa707434669561d3f940ce68d031f7908695b535765567', 'Statement Analysis', 'standard', 3, 'WIS', NULL, 'Statement Analysis breaks down language patterns to expose inconsistency, bias, or evasion. The choice of words often reveals more than their meaning.', 'Interview Technique'),
  (469, 'skill-7eb5051757c6f06b65554d1359a1924e636ab29a7485c68c0cfe220cb13a02ec', 'Analytical Profiling', 'standard', 2, 'WIS', NULL, 'This skill enables the construction of behavioral profiles based on habits, choices, and triggers. It creates a psychological footprint of the unknown.', 'Investigation'),
  (470, 'skill-a31bf9358b72766d9d853a24aa2064030cace906ad062c83520a83b7f6185644', 'Behavior Pattern', 'standard', 3, 'WIS', NULL, 'This skill identifies recurring behaviors across time, space, or victims. It shows method, repetition, and evolution—often invisible at first glance.', 'Analytical Profiling'),
  (471, 'skill-b588eeee34398bff335ac2fa2ea9f1f0304b702a544eff0f0b0360b9cd829247', 'MO Correlation', 'standard', 3, 'WIS', NULL, 'MO Correlation links actions or crimes by method, signature, or motive. It connects scattered clues across distance or time.', 'Analytical Profiling'),
  (472, 'skill-a3f8a0cf10d9f45639126c81875f1cf66b466488e6a59c7f2cad807997ffa825', 'Predictive Modeling', 'standard', 3, 'WIS', NULL, 'Using current evidence and behavior analysis, this skill predicts likely next moves or outcomes. It’s less about certainty, and more about calculated probability.', 'Analytical Profiling'),
  (473, 'skill-cdafea8ee7c5b62db31e1dde7d54c897e948b74995f97bcf83a3ae2ab509b7dd', 'Animal Handling', 'standard', 1, 'WIS', NULL, 'Animal Handling reflects a deep understanding of animal behavior, needs, and communication. It includes building trust, controlling movement, calming fear, and bonding across species. Whether in stable, field, or wild, this skill turns instinct into cooperation.', NULL),
  (474, 'skill-c2fb788c7deedbeaa296e424d4c2921b871a4f6cb4cf393c1c1105653ab399b4', 'Training', 'standard', 2, 'WIS', NULL, 'Training teaches creatures repeatable tasks through reinforcement, command, and patience. It transforms potential into dependable action.', 'Animal Handling'),
  (475, 'skill-38d76f0e23cbfda46fb49c2e46c6c95272a06c538e92ca0b708a92f56c56d7ef', 'Obedience Drill', 'standard', 3, 'WIS', NULL, 'This skill instills absolute compliance to verbal or gestural commands. It creates dependable, disciplined companions ready to act without hesitation.', 'Training'),
  (476, 'skill-32e1732d4710371aa2274417a8ca772f726aba56e785faa8559e1974ca638aa1', 'Trick Conditioning', 'standard', 3, 'WIS', NULL, 'Trick Conditioning enables the teaching of complex or performative behaviors for show, distraction, or utility. From bowing to bell-ringing, intelligence is awakened.', 'Training'),
  (477, 'skill-242815e86e606900553715f47d1a39d8e35db1f676af2ef8e5713774f4eb328e', 'Pack Coordination', 'standard', 3, 'WIS', NULL, 'This skill synCHAonizes multiple animals for cooperative behavior—movement, defense, or formation. The handler becomes a silent conductor of the pack.', 'Training'),
  (478, 'skill-c1e6de2c54a06869a6154313e99a9def7de567d21dd0e900282268dfb793188a', 'Riding', 'standard', 2, 'WIS', NULL, 'Riding covers the ability to mount, direct, and stay balanced on domesticated or semi-domesticated animals. It includes awareness of gait, behavior, and terrain response.', 'Animal Handling'),
  (479, 'skill-4cb093bfe9205ba42b65c6a789a8fb53b21fbb9a2a76f9dae498c7b6339fb4a3', 'Bareback Mastery', 'standard', 3, 'WIS', NULL, 'This skill allows full control and balance without tack or saddle. It emphasizes harmony with the animal’s rhythm and movement.', 'Riding'),
  (480, 'skill-21ff82cd23981f42590ae2794d13a12311fe5a14485947f74a9e6de681648b44', 'Mounted Combat', 'standard', 3, 'WIS', NULL, 'Mounted Combat grants the ability to fight from atop a creature—timing strikes, pivoting, and directing while moving. It turns rider and mount into one force.', 'Riding'),
  (481, 'skill-d04e9cdd1c098b4c4e9cd2e026f54cafa8ba0366575af957a2b385c4d0277a85', 'Rapid Dismount', 'standard', 3, 'WIS', NULL, 'This skill allows for safe, controlled, and swift dismount from a moving or rearing mount. It minimizes risk and enables fast transition to ground combat or escape.', 'Riding'),
  (482, 'skill-894cdc25f34eb05f36941bc3c8a360bae36bf3fe9d69326aec25ee30cbd1a742', 'Beast Empathy', 'standard', 2, 'WIS', NULL, 'Beast Empathy builds intuitive rapport with creatures through scent, posture, tone, and presence. It opens communication without dominance.', 'Animal Handling'),
  (483, 'skill-9a44589aee650f948055660d3c2ce4b1ef4291eb10a5ec571fe19a5f3efdc2e1', 'Calm Beast', 'standard', 3, 'WIS', NULL, 'Calm Beast diffuses fear, aggression, or panic in animals through subtle cues and confident energy. The wild learns to trust.', 'Beast Empathy'),
  (484, 'skill-b0c3c5bdfd62a21e6c12bef1bec3e0bd35d36f303e14a6816bf3cac786c172ef', 'Scent Blend', 'standard', 3, 'WIS', NULL, 'This skill masks or modifies the user’s natural scent to reduce threat, trigger familiarity, or blend with a herd.', 'Beast Empathy'),
  (485, 'skill-51d1182204a6d428221e73131fe8f146b181d6b2d684a4f0eb98decfa8160401', 'Pack Communing', 'standard', 3, 'WIS', NULL, 'Pack Communing allows mutual nonverbal understanding within bonded creatures. It enables mood sensing, silent direction, and shared instinct in the field.', 'Beast Empathy'),
  (486, 'skill-96310a9e291471337001fcff3965b57d72bba445636036fa600a20e817c68516', 'Mental Fortitude', 'standard', 1, 'WIS', NULL, 'Mental Fortitude is the inner armor of the mind—the ability to withstand fear, resist manipulation, and maintain clarity under duress. It reflects emotional control, psychological resilience, and mental discipline. A strong mind does not break—it bends and returns sharper.', NULL),
  (487, 'skill-fdf09cdfc26cccf610edccd7f9b558e1ce0a793a4ee57f8306df9058f1aa929b', 'Resolve', 'standard', 2, 'WIS', NULL, 'Resolve builds resistance against internal collapse. It shields against panic, dread, sorrow, or confusion when the world becomes overwhelming.', 'Mental Fortitude'),
  (488, 'skill-bf381d9a983c929903962e39423420fabb3cbcb5511f1e6cee28f50ead33fe05', 'Fear Resistance', 'standard', 3, 'WIS', NULL, 'Fear Resistance enables action in the presence of terror. It suppresses the instinct to freeze or flee and allows thought to continue when the heart races.', 'Resolve'),
  (489, 'skill-76916e6aa66d48f85f09ab299696f5b2da6def38c66877b6a8bdda5c09b620c4', 'Despair Shield', 'standard', 3, 'WIS', NULL, 'This skill strengthens willpower against despair, hopelessness, or emotional sabotage. It helps the user hold their center when all seems lost.', 'Resolve'),
  (490, 'skill-50696420cf308284864f45359167b02b99eb6a6e1c6593255593bbd8ab01973c', 'Pain Gate', 'standard', 3, 'WIS', NULL, 'Pain Gate filters the body’s pain signals before they reach the conscious mind. It doesn’t erase pain—but it places it behind a locked door.', 'Resolve'),
  (491, 'skill-bdc4f42527047f250096bd05eecbb75fd01b16d61638b1ec89d278b172daa6f7', 'Concentration', 'standard', 2, 'WIS', NULL, 'Concentration trains the mind to anchor itself to a single thought or task, excluding all else. It turns awareness into a laser instead of a floodlight.', 'Mental Fortitude'),
  (492, 'skill-bdbfccb829dbed3af607d5381571ceb26a6b906b7a9e194ebc79c2e32b7034bb', 'Selective Focus', 'standard', 3, 'WIS', NULL, 'Selective Focus allows the user to tune in to one stream of input while ignoring all others—perfect for combat, study, or meditation.', 'Concentration'),
  (493, 'skill-41e1cfac1ad1f897f9286f38020251f33bf8e9ff5581792fd918d803f6b04e7b', 'Distraction Ignoring', 'standard', 3, 'WIS', NULL, 'This skill builds immunity to ambient noise, visual clutter, and emotional interruption. It protects attention in chaotic or hostile environments.', 'Concentration'),
  (494, 'skill-e6d8f2f8c9a3ac15cdfbf5cf6949603a8c09caaeceb2cb4084b9ca8871fa28cc', 'Meditation Lock', 'standard', 3, 'WIS', NULL, 'Meditation Lock enables a deep mental state that cannot be broken easily. Even under stress, the user can remain in inner stillness until they choose to return.', 'Concentration'),
  (495, 'skill-69dccf59c656ef1a2317d3e583d4c87d026b0ef12a9623fb83e25c8308dded24', 'Lucid Dreaming', 'standard', 2, 'WIS', NULL, 'Lucid Dreaming allows awareness and agency within sleep. It grants memory of dreams, control over dreamspace, and defense against psychic intrusion.', 'Mental Fortitude'),
  (496, 'skill-18ff06e8c2810231e7ef84f4628914660fdd531fa0ac92e2433f268b0dcfd97c', 'Dream Recall', 'standard', 3, 'WIS', NULL, 'This skill preserves vivid, complete memories of dream experiences—turning fleeting images into usable knowledge or clues.', 'Lucid Dreaming'),
  (497, 'skill-dc7be52cb75d72375c99a2513583f27e986bdf396ffb673498db37be14b8ca69', 'Dream Control', 'standard', 3, 'WIS', NULL, 'Dream Control allows conscious influence over dreams: shaping events, summoning symbols, or directing outcomes while asleep.', 'Lucid Dreaming'),
  (498, 'skill-a494a9150d83387f683323f09cb4cee5634f7baca9b45314d99d3e9156779440', 'Nightmare Ban', 'standard', 3, 'WIS', NULL, 'This skill enables the user to confront or dispel nightmares—whether psychological, magical, or foreign in origin. Fear has no dominion where the dreamer commands.', 'Lucid Dreaming'),
  (499, 'skill-d70d5a7909ed5910fbc67667c7464f0b53fd935653afb327e53067bb7ca578ca', 'Navigation', 'standard', 1, 'WIS', NULL, 'Navigation is the ability to find your way across wilderness, cities, or unknown terrain using landmarks, tools, or instinct. It includes orienteering, mental mapping, and orientation in both natural and constructed spaces. A skilled navigator is rarely lost—and never for long.', NULL),
  (500, 'skill-0c4a73cd65be5837b877807dcbc7d60656b3a28ff29ea8377ba3ad37779100ba', 'Wayfinding', 'standard', 2, 'WIS', NULL, 'Wayfinding is the practical art of moving across distance with direction and purpose. It relies on reading terrain, sun, stars, water flow, and other natural signs to maintain accurate travel.', 'Navigation'),
  (501, 'skill-4513afbc278c50f89752c125455b2cb58923ca6c7c3b72275437c675f3c45481', 'Dead Reckoning', 'standard', 3, 'WIS', NULL, 'This skill allows navigation based on last known location, movement speed, and elapsed time—without the need for visible landmarks. It’s used in fog, night, or dense environments.', 'Wayfinding'),
  (502, 'skill-d73ecd68f55748113e0790b5ea9eb0c6b3b981bb74b6282575898e30055e1425', 'Terrestrial Compass', 'standard', 3, 'WIS', NULL, 'Terrestrial Compass grants intuitive orientation, allowing the user to instinctively feel cardinal directions—even when disoriented, underground, or magically disrupted.', 'Wayfinding'),
  (503, 'skill-337707b8f454a95d0411de397159e53a5fcea873b2e3c3474bfa5abe98deb82e', 'Trailblazer', 'standard', 3, 'WIS', NULL, 'Trailblazer grants the ability to forge new paths through wild terrain while minimizing hazard and leaving clear markers. It’s not just finding the way—it’s creating one.', 'Wayfinding'),
  (504, 'skill-46438c10cb3fbb2677cd221d55c09e1098351257987038c6c6dfc2e74dd6e62e', 'Cartography', 'standard', 2, 'WIS', NULL, 'Cartography is the structured recording and interpretation of terrain through maps, sketches, or glyphs. It allows travelers to leave information behind or share it with others.', 'Navigation'),
  (505, 'skill-f54a82d2ef48f5638d567f0de0bb8f574205578022dc141701a90f132aa677f4', 'Rapid Sketch Map', 'standard', 3, 'WIS', NULL, 'This skill allows quick creation of functional field maps—usable even when rushed, fatigued, or under pressure. Clarity over beauty.', 'Cartography'),
  (506, 'skill-a6f9cdcf56c5f8e4839c5986f206a5e3537137c38cc3bddcae89ae6dd53134c6', 'Surveying Grid', 'standard', 3, 'WIS', NULL, 'Surveying Grid introduces mathematical precision—aligning map details to consistent scales and coordinates. Essential for construction, defense, or advanced planning.', 'Cartography'),
  (507, 'skill-8d04d61afc81d137db4a419ca44f82c4d92572100ef61b2c472dbffb755b9c98', 'Terrain Mapping', 'standard', 3, 'WIS', NULL, 'Terrain Mapping creates detailed elevation and obstacle diagrams, useful for travel, siege, or escape planning. It sees not just the place—but how the place works.', 'Cartography'),
  (508, 'skill-9a906684629723e9a3662ef2a3acd031a79a333a76185f9c11c56913b1830826', 'Urban Orientation', 'standard', 2, 'WIS', NULL, 'Urban Orientation trains the mind to track spatial relationships in dense, shifting environments. It maps buildings, alleys, sewer grates, and choke points in memory.', 'Navigation'),
  (509, 'skill-a5008ddbfa3efa4a81ea0c192a86b2aad60498cf5b270a8f7a3fd76a01301576', 'Subsurface Routing', 'standard', 3, 'WIS', NULL, 'This skill grants an instinctive understanding of tunnels, catacombs, basements, and underground transit paths. Perfect for infiltration, escape, or smuggling.', 'Urban Orientation'),
  (510, 'skill-299eae342470ebd49c2eb951961906bcab32ccf1d391d7bb3f32ba6c60cad4a0', 'Shortcut Analysis', 'standard', 3, 'WIS', NULL, 'Shortcut Analysis spots fast or hidden routes others overlook—gaps in fences, alley angles, or rooftop paths. Every space becomes a tool.', 'Urban Orientation'),
  (511, 'skill-f5ce856021de9945b9e0b176421cfc03abc6a8b2b7381e4b96929d0c26d4f1b5', 'Evacuation Pathing', 'standard', 3, 'WIS', NULL, 'This skill enables rapid creation of exit plans in real time—accounting for crowds, blockages, or environmental collapse. It’s used by those who expect things to go wrong.', 'Urban Orientation'),
  (512, 'skill-52cc580bfa0fe077b96c662bf5ad172635cc5acd2e2f5b9a146de4b6fac97d1c', 'Herbal Lore', 'standard', 1, 'WIS', NULL, 'Herbal Lore is the ancient study of plants and their hidden powers—curative, toxic, or alchemical. It requires both intuition and experience to safely work with herbs across regions, climates, and seasons. A master of this skill sees medicine where others see weeds, and poison where others see beauty. The land itself becomes both a toolkit and a weapon.', NULL),
  (513, 'skill-b903e0d4d8ad39f42f0bd7fc95b1b4790cc6d23d18c8f6f47234ae32b2625ee2', 'Medicinal Herbs', 'standard', 2, 'WIS', NULL, 'Medicinal Herbs focuses on plants that restore, soothe, or cleanse. From poultices to teas, it teaches how to extract life-giving properties from nature’s bounty. This skill forms the core of natural healing without magic.', 'Herbal Lore'),
  (514, 'skill-d738c4657d16ea75f1f374e30c67eae632405baf8bdb6751a74125078b16b337', 'Antiseptic Application', 'standard', 3, 'WIS', NULL, 'This skill allows for the creation of topical mixtures that prevent infection, reduce swelling, and sterilize wounds. It emphasizes clean preparation, sterile wrapping, and field-ready treatments. The difference between rot and recovery often lies here.', 'Medicinal Herbs'),
  (515, 'skill-3a61624de9107b6a71a41c48e2946560d929bf4131436b1446a6ce11417fab09', 'Analgesic Mix', 'standard', 3, 'WIS', NULL, 'Analgesic Mix covers the creation of pain-relieving formulas through oils, tinctures, and compresses. It teaches precise dosage, delayed release, and targeted effect—relief without clouding judG.O.Dent.', 'Medicinal Herbs'),
  (516, 'skill-7ae395ba1aabc3bf9e6eabf4d5ecd890be0f8db61e5d6f6c543658a40475c842', 'Healing Poultice', 'standard', 3, 'WIS', NULL, 'A Healing Poultice draws infection, closes minor wounds, and accelerates natural recovery. This skill blends texture, heat, and herb layering to maximize effectiveness during rest. It is the healer’s silent ally.', 'Medicinal Herbs'),
  (517, 'skill-4269081537712f9b47605f53ffb7757791cc4104502b81e5d6cc2f61e2ca4fc9', 'Toxic Botany', 'standard', 2, 'WIS', NULL, 'Toxic Botany is the art of identifying and harnessing dangerous plants for offensive or defensive use. It explores paralysis, nausea, confusion, and even death—through seeds, saps, and spores. This knowledge walks the edge of taboo.', 'Herbal Lore'),
  (518, 'skill-89938b429ea541a2ae2a7cc07d63dea279aedd46d2b594ae1c386fa64d9a06cd', 'Neurotoxin Extraction', 'standard', 3, 'WIS', NULL, 'This skill isolates precise chemical agents that disrupt nerve signals—leading to paralysis, spasms, or failure of control. Extraction requires ritual, timing, and deadly accuracy.', 'Toxic Botany'),
  (519, 'skill-1d1023b4295a87352128ae60106c1ecbceec42161b0ec2a0dddf3f9ff91e2b53', 'Irritant Dust', 'standard', 3, 'WIS', NULL, 'Irritant Dust creates airborne powders that blind, choke, sting, or disorient. It is used for nonlethal control, escape tactics, or distraction. The skill includes drying, grinding, and blending agents to trigger biological reflexes.', 'Toxic Botany'),
  (520, 'skill-e1087c737d277d40aa149775ca564d484b0fa427374640c6275c1641b19c60b7', 'Paralytic Concoction', 'standard', 3, 'WIS', NULL, 'This skill enables creation of mixtures that lock joints, slow movement, or collapse muscle function temporarily. Used correctly, it leaves a target helpless but alive.', 'Toxic Botany'),
  (521, 'skill-e7991e60d2672a21fe4fa46ba8a65f6c0484878854a0887cdce95c1686c16241', 'Alchemical Reagents', 'standard', 2, 'WIS', NULL, 'Alchemical Reagents are herbs refined for use in potions, enchantments, or chemical reactions. This skill teaches solvent pairing, heat reaction, and component isolation for high purity. It blends science with instinct.', 'Herbal Lore'),
  (522, 'skill-3415079dc60cef7c4c27ffb726b74bbab1cf1aed1b6966a3dc5490aa61f23625', 'Solvent Infusion', 'standard', 3, 'WIS', NULL, 'Solvent Infusion suspends an herb’s active essence into oil, alcohol, or acid, allowing long-term storage or concentrated release. It’s the cornerstone of potioncraft and ritual use.', 'Alchemical Reagents'),
  (523, 'skill-3a80e8e8b647166ebbec961caf61ee4383bb28862dab729defc77521849b607b', 'Catalyst Powder', 'standard', 3, 'WIS', NULL, 'Catalyst Powders spark reactions—magical or chemical—when added to brews, flasks, or spells. This skill demands precision milling, drying, and activation timing.', 'Alchemical Reagents'),
  (524, 'skill-a92ba150255fc20ba74891e6e21ab35bbe42cc358558f54cd17fbad2ebc6a900', 'Essence Distillation', 'standard', 3, 'WIS', NULL, 'This skill extracts a plant’s purest effect into liquid or crystalline form. It is delicate, powerful, and volatile—used for rituals, elite potions, or rare salves. Only the most disciplined dare push this far.', 'Alchemical Reagents'),
  (525, 'skill-8d0fc54c895c941747e5333d88d756fa4b6be1f125ffcb3472d50fcfd6a49aba', 'Dreamcraft', 'standard', 1, 'WIS', NULL, 'Dreamcraft is the conscious exploration and manipulation of dreams—whether your own or others’. It bridges the waking and unconscious worlds, revealing hidden meanings, memories, and futures. Those skilled in Dreamcraft walk through their mind as if it were terrain, and shape dreamspace as others shape clay.', NULL),
  (526, 'skill-fa300229f32b246d7c954e3fde177c966f17c13982a8a1586ffe245817f1803f', 'Dream Interpretation', 'standard', 2, 'WIS', NULL, 'Dream Interpretation focuses on reading and decoding symbolic language within dreams. It discerns what images mean emotionally, spiritually, or prophetically. This is the key to unlocking messages woven in metaphor.', 'Dreamcraft'),
  (527, 'skill-4e0f4e0dc53913f35b4fa7cc9cb743dbd8cdc0edaaf6e004c9847e6831d2fe6a', 'Symbol Decoding', 'standard', 3, 'WIS', NULL, 'This skill grants deep fluency in interpreting dream-symbols based on culture, personal resonance, or archetypal structure. A sword isn’t always a weapon—sometimes it’s guilt, power, or protection.', 'Dream Interpretation'),
  (528, 'skill-91bda37498794714f1e098a05dc05d5159394ec39403d3467cf7aa74483b0134', 'Emotional Resonance', 'standard', 3, 'WIS', NULL, 'This skill detects the emotional truth behind dream elements, even when disguised by imagery. It reveals what the dreamer feels but cannot name.', 'Dream Interpretation'),
  (529, 'skill-04585871035e3200fe833c1be7079596f0541c451588f3cae5e5c2069e76733a', 'Memory Unseal', 'standard', 3, 'WIS', NULL, 'Memory Unseal allows repressed or forgotten experiences to rise into dreamspace. Through careful reflection and guidance, the sleeper recalls what was lost—or hidden.', 'Dream Interpretation'),
  (530, 'skill-eba9cb262e4105bf00104761042dc1f84bc745c2edcb034da2040c3f87bf8062', 'Lucid Dream Navigation', 'standard', 2, 'WIS', NULL, 'Lucid Dream Navigation grants control within the dream. It allows movement between dream layers, shaping of surroundings, and preservation of awareness while sleeping.', 'Dreamcraft'),
  (531, 'skill-59e0b081d85735ff682940da25be4c71218aa12bd9c690c32b80674de17361ad', 'Dreamwalk Control', 'standard', 3, 'WIS', NULL, 'This skill allows conscious direction of action, location, and interaction within dreams. Whether flying, hiding, or confronting, the dream becomes a chosen path.', 'Lucid Dream Navigation'),
  (532, 'skill-f1a4d1bd68335807eb22351507f5d8694735283cde2178e0899bfe6754ba4a15', 'Dream Door Forge', 'standard', 3, 'WIS', NULL, 'Dream Door Forge creates gateways within the dream—portals to memories, other dreamers, or archetypal realms. Used by mystics, walkers, and dreambound.', 'Lucid Dream Navigation'),
  (533, 'skill-88b379136e00b17db9422f834aba108703d5082769223a49185bb6d61e692f0d', 'Nightmare Override', 'standard', 3, 'WIS', NULL, 'This skill grants the power to confront, reshape, or banish nightmares at will. It prevents fear from seizing control of dreamspace—and reclaims sovereignty.', 'Lucid Dream Navigation'),
  (534, 'skill-3249a4ed6de128b42c00908a1b6f869e846725eda3062c40395975435c7d297e', 'Prophetic Dreaming', 'standard', 2, 'WIS', NULL, 'Prophetic Dreaming tunes the mind to dreams that reveal fraG.O.Dents of the future. It may arrive as symbol, scene, or feeling—but the message is real. This is not control; it is reception.', 'Dreamcraft'),
  (535, 'skill-ceddd6a1d5320274f3575e8016c7ed430379cc490b5ec9314d61e1730ed95b9d', 'Premonition Trigger', 'standard', 3, 'WIS', NULL, 'This skill increases the frequency and clarity of foresight dreams, often through ritual, herbs, or intention. It awakens the sleeping mind to possibility.', 'Prophetic Dreaming'),
  (536, 'skill-e65b878d58bb90f2fa5e908b54f855952b64bfc7ea0fa8142c91f04b087edd9c', 'Parallel Vision', 'standard', 3, 'WIS', NULL, 'Parallel Vision allows the dreamer to glimpse simultaneous outcomes, timelines, or selves. It grants insight into the consequences of choice before waking.', 'Prophetic Dreaming'),
  (537, 'skill-77fb0bb91f62b3b71f351d9a134ac77d845c307dead2ad45d7ae73d0a745ad84', 'Destiny Thread', 'standard', 3, 'WIS', NULL, 'Destiny Thread reveals the single, strongest line through fate within a dream. It grants the dreamer a glimpse of the pattern pulling all else forward—if they can accept its truth.', 'Prophetic Dreaming'),
  (538, 'skill-2b93b177b55445f513d73ff1f0f30376d6ec181bcc1bd5cd19cccb970f4ee0d2', 'Faith', 'magic access', 1, 'WIS', NULL, 'Faith is unwavering conviction rooted in belief, devotion, or sacred law. It represents spiritual certainty and inner alignment with divine principles. This skill is required for access to magical spheres via the path of Faith.', NULL),
  (539, 'skill-25fe36108392295ccc168f7c3572ee59b65d673db877db8ecae595e7735145d6', 'Prayer', 'magic regeneration', 1, 'WIS', NULL, 'Prayer is the disciplined act of speaking, reaching, or listening to divine presence. Through it, a character may call on spheres granted by their deity, receiving insight, strength, or magical effect. This is your sphere access skill for the Faith path.', NULL),
  (540, 'skill-67acf560e238730acee341d27e3aa704829cd3ca4ccaa79b7f267d9baa9eb591', 'Devotion', 'magic stabalization', 1, 'WIS', NULL, 'Devotion is sustained spiritual focus—ritual, mantra, or obedience—that strengthens the soul’s connection to its source. It multiplies the power of one''s Faith during magical or divine restoration. Used with Faith to determine mana recovery.', NULL),
  (541, 'skill-1c64dabc8baecea15a52119daae6ab9608a6136f44993c04048da089be6c0905', 'Psionic Focus', 'magic access', 1, 'WIS', NULL, 'Psionic Focus trains the mind to exclude all noise and lock onto a singular goal. It is mental stillness forged into action. Required for access to psionic disciplines.', NULL),
  (542, 'skill-f3b40e42dd5804438eb228335aa57b091cc3cb89d056c37b36052e2e6416ac51', 'Psionic Channeling', 'magic stabalization', 1, 'WIS', NULL, 'Psionic Channeling allows the user to act as a conduit for mental or psychic force. It governs how much psionic energy can be safely drawn, stored, or directed. Used with Psionic Meditation to determine energy recovery.', NULL),
  (543, 'skill-62f07aff4eeb45447cea273660c7f486b6afe0ea6b1bb67db966910b9d13ef6d', 'Psionic Meditation', 'magic regeneration', 1, 'WIS', NULL, 'Psionic Meditation builds calm within the storm of thought. It enables the user to recover spent psionic energy and stabilize their internal field. Used to multiply psionic regeneration through mental clarity.', NULL),
  (544, 'skill-31438ab594c695ac18f323d9ca4f2f233439710322f6cbf452385fa9415d53b0', 'Persuasion', 'standard', 1, 'CHA', NULL, 'The foundational skill for influencing thoughts, emotions, and behavior through charm, tone, and compelling language. Persuasion opens the door to cooperation without coercion, turning resistance into willingness and transforming interactions into opportunity.', NULL),
  (545, 'skill-c79e1f0e3efc3a43ee115f3675a56cfde44b66b11d04d15c62b59849aa2cbfb3', 'Negotiation', 'standard', 2, 'CHA', NULL, 'The practiced art of reaching mutual benefit through conversation, compromise, and strategy. Negotiation thrives in tense standoffs, business deals, and political meetings—where stakes are high and every word has weight.', 'Persuasion'),
  (546, 'skill-b8b8f3a7eb596b1a60abfd04060b933a72326090b3ebe45bde67634ad4c8dfa8', 'Win Win Bargaining', 'standard', 3, 'CHA', NULL, 'A diplomatic approach to deal-making that prioritizes shared benefit over dominance. This technique leaves both sides feeling heard, valued, and willing to engage again. Especially useful in alliances, trade, or team cohesion.', 'Negotiation'),
  (547, 'skill-16a9aaa7be67c7a7e67d36cb699633d70f3ff69456a4c9a27f26bdcbee7464fc', 'Hard Ball Tactics', 'standard', 3, 'CHA', NULL, 'An aggressive form of negotiation focused on leverage, intimidation, or strategic threats. Ideal for pressing advantage or forcing concessions in cutthroat dealings, though often at the cost of goodwill.', 'Negotiation'),
  (548, 'skill-955382c90a770c3931d768a3520e36e762659ca5fd67d8eaa0a4600b208b0f01', 'Concession Cue', 'standard', 3, 'CHA', NULL, 'The intuitive sense for when and how to offer just enough to break a stalemate without undermining your position. It’s the art of giving up little to gain much—often unlocking progress with a single, well-placed gesture.', 'Negotiation'),
  (549, 'skill-c1cb74e23f5ffd0793b66266c01ba4e9f189466fb2027bc9faf5d32ee9c36ea4', 'Diplomacy', 'standard', 2, 'CHA', NULL, 'The high art of peaceful engagement across differing interests, nations, or ideologies. Diplomacy defuses conflict, fosters alliances, and ensures that the wrong word doesn''t start a war. It’s language as armor and olive branch.', 'Persuasion'),
  (550, 'skill-098bd1dbabdaf0086b06cf2d8908921e3c65145c643acb6a93c3aa0671277bbd', 'Protocol Fluency', 'standard', 3, 'CHA', NULL, 'Mastery of etiquette, cultural customs, and ceremonial nuance. This fluency earns respect in formal settings and prevents unintentional offenses that could derail progress or provoke retaliation.', 'Diplomacy'),
  (551, 'skill-c10f2297c0c51d84a1884d0d8e855e10425e702ba5329ed6521f5b199325665d', 'Crisis Mediation', 'standard', 3, 'CHA', NULL, 'The ability to maintain control, de-escalate tension, and restore communication during volatile or emotionally charged conflicts. It’s diplomacy under fire—when stakes are high and words must be chosen with care.', 'Diplomacy'),
  (552, 'skill-47906ed38e34c49db7fb2eda59818e31b9e9512e77b749dbac8f2a485cef2a7b', 'Treaty Draft', 'standard', 3, 'CHA', NULL, 'The crafting of binding agreements with foresight, legal weight, and diplomatic finesse. Treaties shaped through this skill endure pressure, resist exploitation, and signal power through precision.', 'Diplomacy'),
  (553, 'skill-be2c9ce17278c9311853dd3769e394cde004258b23e1ed82a9a18c0fe8302319', 'Inspiration', 'standard', 2, 'CHA', NULL, 'The capacity to ignite passion, hope, or resolve in others through tone, presence, or message. Inspiration rallies hearts when logic fails and elevates morale when odds turn grim.', 'Persuasion'),
  (554, 'skill-3188388b48c408fe0bb343ddfc499a4bf439949cd0ef60342ddcfed95e22bd6c', 'Rally Speech', 'standard', 3, 'CHA', NULL, 'A powerful oration designed to unify, embolden, or galvanize a group. Whether before battle or at the brink of despair, the right words delivered at the right time can shift fate.', 'Inspiration'),
  (555, 'skill-4a9d8f1fcb4aff2adb5e6a8c7d575985cabab1d038f410f367e62829b393439e', 'Morale Boost', 'standard', 3, 'CHA', NULL, 'The steady practice of uplifting others through encouragement, empathy, and recognition. Morale Boost reinforces emotional resilience, especially during hardship, uncertainty, or long-term stress.', 'Inspiration'),
  (556, 'skill-201fa7e504077ccb17e1eb178079baf97972445b962f8621ea5fa03bb5a3176b', 'Vision Casting', 'standard', 3, 'CHA', NULL, 'The ability to speak a dream so clearly that others begin to believe in it. Vision Casting turns abstract ideas into shared purpose, rallying followers to pursue goals that may not yet exist—but feel within reach.', 'Inspiration'),
  (557, 'skill-f335963305b48079a7992623c1321163b5111dd1db00e985d7c69a2b57e72cbe', 'Deception', 'standard', 1, 'CHA', NULL, 'The core ability to obscure truth, manipulate perception, or create entirely false narratives. Deception doesn’t rely on brute strength or logic—it thrives on confidence, timing, and the subtle art of misdirection.', NULL),
  (558, 'skill-bb1c5404897afe72ecf50bf5b2ab9c0328d73c4c398271800fa5c5c25cde7a27', 'Bluffing', 'standard', 2, 'CHA', NULL, 'The craft of projecting certainty behind a false claim. Bluffing works by making others question their instincts—whether at a poker table, during interrogation, or when caught in a lie.', 'Deception'),
  (559, 'skill-cca7b4796f80d65ba7eb35a9b789ce34b9c28c03bb3ec3e39e25e2c1d82c5d16', 'Quick Lie', 'standard', 3, 'CHA', NULL, 'The rapid delivery of a falsehood with no hesitation, often used to redirect suspicion or buy precious seconds. It''s a survival mechanism for fast talkers under pressure.', 'Bluffing'),
  (560, 'skill-3c39613c7a2cbfb904423f55ecdd8194b9ae781d9b7fd5e50fdc4af4ee3ead96', 'Plausible Detail', 'standard', 3, 'CHA', NULL, 'The strategic insertion of small, believable facts that make a lie harder to detect. These anchors ground fiction in just enough reality to disarm doubt.', 'Bluffing'),
  (561, 'skill-ae7e1667824a7e23a1b2ac7bf1eaa61d99ee01fa0d9d3403ca100efb6f322aa1', 'Confidence Ploy', 'standard', 3, 'CHA', NULL, 'The use of unshakable demeanor, commanding tone, and assertive posture to make a falsehood seem undeniable. Sometimes people don’t believe what’s said—they believe how it''s said.', 'Bluffing'),
  (562, 'skill-83180b745cbfaa82c9d056446b5656446f033296674eb2dda3193d00b8620407', 'Disguise', 'standard', 2, 'CHA', NULL, 'The act of altering physical appearance, voice, or demeanor to mask identity. Disguise isn''t just makeup and costumes—it’s posture, habits, and the ability to vanish in plain sight.', 'Deception'),
  (563, 'skill-9db233d8114c8d0c4673c31588d8483c09c9402cc62c6ddccd8638091b8dc5d3', 'Costuming', 'standard', 3, 'CHA', NULL, 'Mastery over outfits, accessories, and visual cues that can establish new roles or backgrounds. From noble silks to peasant rags, each stitch sells the story.', 'Disguise'),
  (564, 'skill-77007ac2d4a4f1d423cf87bc2faf1880b13fba2e56663cd0ca9f861383cf9fce', 'Voice Mimicry', 'standard', 3, 'CHA', NULL, 'The ability to replicate vocal tone, cadence, and mannerisms—useful for impersonation, infiltration, or sowing confusion. In the right hands, a single phrase can open locked doors.', 'Disguise'),
  (565, 'skill-f5192b0b8d8ba5364f0435af78c8f8ec72e6d544507dec65ec80c452d4bd8761', 'Identity Swap', 'standard', 3, 'CHA', NULL, 'The complete assumption of another persona, including their habits, gestures, and history. At this level, even close allies might be fooled… or replaced.', 'Disguise'),
  (566, 'skill-2a355d87d5fe8d3cec7761683fe00ca61556b5ebad144392c4ac42c65ca3a75c', 'Forgery', 'standard', 2, 'CHA', NULL, 'The creation or alteration of physical documents to simulate authenticity. From fake IDs to royal decrees, forgery opens doors and covers tracks.', 'Deception'),
  (567, 'skill-1fe556318e73de57fbb636cae655d2e80b745c1719c701b0bb7e72cc4b1720b7', 'Signature Copy', 'standard', 3, 'CHA', NULL, 'Precise replication of handwriting, seals, or marks. Ideal for validating forgeries, falsifying orders, or stealing identity in ink.', 'Forgery'),
  (568, 'skill-639a37097b5ee52537bb278d9d9ae869dfc54ead7d9df63d4458def6f57cb764', 'Document Aging', 'standard', 3, 'CHA', NULL, 'Techniques for making fake materials appear ancient, damaged, or timeworn. This adds a layer of realism that helps forgeries pass inspection or fool historians.', 'Forgery'),
  (569, 'skill-1ebed7cd9ab4209eb536d0fc6239d02b32f60ed4287cbc6b153eddfd83b7a44d', 'Security Hologram', 'standard', 3, 'CHA', NULL, 'The reproduction of magical seals, digital signatures, or arcane emblems. Useful in high-tech or enchanted settings where illusion must match complexity.', 'Forgery'),
  (570, 'skill-f7dd05f430d74cebde8f9681162152b6f56c7c2b9f161217972b5c058e4fe02e', 'Performance Arts', 'standard', 1, 'CHA', NULL, 'The expressive mastery of emotion, rhythm, and presence across visual, vocal, and physical mediums. Whether to entertain, provoke, or inspire, performance transforms talent into influence and the mundane into magic.', NULL),
  (571, 'skill-2ad0acb649d2c730cc017f32dd8f6383333107badf2a2888a42c82ad155fa288', 'Acting', 'standard', 2, 'CHA', NULL, 'The ability to convincingly portray characters, personas, or emotional states not your own. Acting bridges illusion and reality—whether on stage or in subterfuge.', 'Performance Arts'),
  (572, 'skill-365f3c98d78eff3c74aeac385ada0009c2e01fab7764abd5968a68f32f841ec6', 'Method Performance', 'standard', 3, 'CHA', NULL, 'Full emotional and physical immersion into a role, blurring the line between performer and character. This depth of embodiment creates performances that are hauntingly real.', 'Acting'),
  (573, 'skill-28f8a4f0d659f50762c43efac022a9f05781eec8934148d2cb25e3a4536dd2fe', 'Improvised Scene', 'standard', 3, 'CHA', NULL, 'The spontaneous crafting of dialogue and action without script or planning. This skill shines under pressure—when only instinct and imagination remain.', 'Acting'),
  (574, 'skill-d17a18711325418032735cc78cb7ce3736f7678c2db3ea1c2d8d64637dd8326e', 'Stage Presence', 'standard', 3, 'CHA', NULL, 'The commanding aura that draws and holds attention effortlessly. A strong presence doesn’t beg to be seen—it demands it with posture, pause, and poise.', 'Acting'),
  (575, 'skill-80f189984e5ca70287d13342f6daa0db45cba3c131c4e46dc81360f3a4c4f690', 'Music', 'standard', 2, 'CHA', NULL, 'The emotional manipulation of sound through melody, rhythm, and harmony. Music bypasses thought to strike the heart directly—whether through joy, sorrow, or awe.', 'Performance Arts'),
  (576, 'skill-df1a88d4ef0b25f7b094e5b2764f8cc192feafc4ce29e7f752fc6710c5a74783', 'Instrument Mastery', 'standard', 3, 'CHA', NULL, 'Technical fluency and expressive control over one or more instruments. Mastery enables improvisation, resilience under pressure, and deep emotional resonance.', 'Music'),
  (577, 'skill-c59af34dcbfd40b4971a6e07e1bcd6161667b244e0905a18082012808c9184f7', 'Vocal Control', 'standard', 3, 'CHA', NULL, 'The precise shaping of breath, tone, and inflection across spoken and sung voice. Whether enchanting an audience or commanding a room, voice becomes a weapon and a brushstroke.', 'Music'),
  (578, 'skill-25a1088dc66c901db533de531563e413718f4bf58d77edf18b13cdea75b35aa7', 'Crowd Sync', 'standard', 3, 'CHA', NULL, 'The ability to sense and ride the emotional wave of an audience, adjusting tempo and delivery to amplify connection. When performed properly, the crowd moves as one.', 'Music'),
  (579, 'skill-ef43637c9f58b3fe8bf5e9f99eca2b31da4e9e8b448664625f882cf39feb3afc', 'Storytelling', 'standard', 2, 'CHA', NULL, 'The art of delivering tales that inform, inspire, or deceive. Storytelling transfers culture, binds groups, and makes abstract truths personal through character and conflict.', 'Performance Arts'),
  (580, 'skill-ba6d3bd564743b068b4265232e18e3d07e947b405c4ddeafba0db9be861d1c97', 'Narrative Weaving', 'standard', 3, 'CHA', NULL, 'The layering of subtext, theme, and subtle cues into stories that operate on multiple levels. The listener leaves entertained—but also changed.', 'Storytelling'),
  (581, 'skill-c6b8a578b8ea8bdd1f3538c085d052a410e74a2f2c349d154cad7b32d2d66e86', 'Dramatic Timing', 'standard', 3, 'CHA', NULL, 'The mastery of pauses, reveals, and escalation that give words their punch. Whether invoking laughter, dread, or silence, this skill controls emotional rhythm.', 'Storytelling'),
  (582, 'skill-51a9b399cdb9e745e74db5b1d022dd525ba784680017bacdfff8370e3f5d9518', 'Audience Hook', 'standard', 3, 'CHA', NULL, 'The technique of gripping attention from the very first sentence. Hooks plant curiosity, emotional investment, or surprise, ensuring the listener can’t look away.', 'Storytelling'),
  (583, 'skill-9e720e53885580b1e0c5866c98e04988f0b0d071037fb54621a5180ba29e72e7', 'Leadership', 'standard', 1, 'CHA', NULL, 'The ability to guide, unite, and empower others toward a shared objective. Leadership transforms will into motion and chaos into structure. It is not about control—it’s about conviction, presence, and the ability to inspire trust.', NULL),
  (584, 'skill-5d347fd948b66308f502c3f65c8f7e12ff1c5cf8c760bcdfb188ae1ec7b8b618', 'Command', 'standard', 2, 'CHA', NULL, 'The executional side of leadership—delivering decisive orders that maintain discipline and direction. Command thrives in urgent moments when hesitation risks collapse.', 'Leadership'),
  (585, 'skill-152878bc252b510c3029a0aac9dabb74ba591753ace7bf374c6c81b378831dfb', 'Clear Orders', 'standard', 3, 'CHA', NULL, 'The skill of issuing short, specific, and instantly understood directives. A well-placed command can cut through noise, panic, or indecision with surgical precision.', 'Command'),
  (586, 'skill-2a18cf9928d41c7bb06972128fc9cb11140c57c63ad7b0e478e35e708bd47ce9', 'Crisis Control', 'standard', 3, 'CHA', NULL, 'The ability to impose calm and clarity during chaos. Crisis Control is what separates a true leader from a loud voice—guiding others when plans fall apart.', 'Command'),
  (587, 'skill-9da94171ca11f6d77b5df77b02cbbc076ed17fe33ac9b62e45680f5c6d819a02', 'Chain of Command', 'standard', 3, 'CHA', NULL, 'The establishment and reinforcement of role hierarchy within a group. This ensures efficiency, accountability, and the smooth handoff of power under stress.', 'Command'),
  (588, 'skill-0740b176ff0385463e046c017ac9756c7f7cd6922f8e6060c76cb130d04821ab', 'Strategic Communication', 'standard', 2, 'CHA', NULL, 'The deliberate use of words, tone, and timing to deliver critical information that aligns goals and minimizes confusion. It’s not what you say—it’s when, how, and to whom.', 'Leadership'),
  (589, 'skill-60b9074a44d15514bce50f72bf6af4ec908e149c01ea4c12a882b54d5f588c37', 'Briefing Clarity', 'standard', 3, 'CHA', NULL, 'The ability to deliver mission objectives, roles, and contingencies in ways that are actionable and unforgettable. Everyone leaves the room knowing exactly what they must do.', 'Strategic Communication'),
  (590, 'skill-220262fcfed776bdbfd10b972f6b965412d44fec54bbd9ce97bab311436f772a', 'Rally Pointing', 'standard', 3, 'CHA', NULL, 'The verbal or symbolic act of refocusing scattered teams under stress. Whether calling a charge or issuing a fallback, this skill restores cohesion and momentum.', 'Strategic Communication'),
  (591, 'skill-abd408c2c17dc2d323c1760b6fe03b246da17dca360484e7ee9d41ac6f2f4a28', 'Dynamic Re Tasking', 'standard', 3, 'CHA', NULL, 'The flexible redirection of team roles or objectives mid-operation. A leader with this skill doesn’t panic when the plan breaks—they adapt without losing unity.', 'Strategic Communication'),
  (592, 'skill-57a49f0774888764c6cf6fa5a9fe3869f190c7abb97c954dde830be658a39a64', 'Mentorship', 'standard', 2, 'CHA', NULL, 'The long-form cultivation of others’ growth, skill, and character. Mentorship is the slow fire that forges future leaders, craftsmen, or heroes through presence and patience.', 'Leadership'),
  (593, 'skill-37fab3346bc842f1a691c3658361c2af24ba68eaaab3ab08a49142dedd0fa7f4', 'Skill Coaching', 'standard', 3, 'CHA', NULL, 'The focused refinement of a specific talent through guidance, demonstration, and feedback. This builds both competence and confidence.', 'Mentorship'),
  (594, 'skill-99fcd2e12e56bc9d07769037ad54eb1926d6de689550dccc5567e316885afe84', 'Morale Nurturing', 'standard', 3, 'CHA', NULL, 'The steady reinforcement of emotional stability, encouragement, and purpose—especially during long campaigns or personal struggle.', 'Mentorship'),
  (595, 'skill-506059b5df7ff80c758540e37d1aa5a53cd2983fdb3df5503da8c83b85d985cf', 'Talent Cultivation', 'standard', 3, 'CHA', NULL, 'The act of spotting hidden potential and creating space for it to thrive. This skill sees the greatness in others before they do—and helps bring it to the surface.', 'Mentorship'),
  (596, 'skill-11f3f5f0330d9142b9f17cb8a665fdd828a509a9d4052abbb017e1e1cca7c9b8', 'Streetwise', 'standard', 1, 'CHA', NULL, 'The instinctive social navigation of gritty, unpredictable, or illicit environments. Streetwise isn’t book smart—it’s survival smart, built from hard knocks, fast talk, and watching your back.', NULL),
  (597, 'skill-2052c0dbecd00db754701868b2c235cdd1d5e9c3f41e94559f591989a0a93e67', 'Underworld Contacts', 'standard', 2, 'CHA', NULL, 'The cultivation of useful relationships in the criminal, fringe, or gray zones of society. These aren’t friends—they’re assets, each with a price and a pulse on what’s hidden.', 'Streetwise'),
  (598, 'skill-f27cffe0a49182c40ad7ad605ca3941eefe742e90be2d6ca3847112158e87bb3', 'Informant Network', 'standard', 3, 'CHA', NULL, 'A web of eyes and ears across streets, slums, ports, or dens—each passing along information for coin or favor. When something happens in the shadows, you hear it first.', 'Underworld Contacts'),
  (599, 'skill-cf7662c16b9b02f4e3051cf3a3ba89d325bd90fa3ede41be3a301993d3ae3dfc', 'Favour Trade', 'standard', 3, 'CHA', NULL, 'The subtle bartering of services, secrets, and leverage instead of coin. This is the economy of trust and threat—where reputation buys more than gold.', 'Underworld Contacts'),
  (600, 'skill-f5e74d4936004be4c70d77fe99d41d8a0bb31fc7e451384ca079353e7e275457', 'Safe House Locator', 'standard', 3, 'CHA', NULL, 'The ability to identify, access, or maintain hidden bolt-holes and neutral shelters across cities. Knowing where to vanish—or stash others—can mean survival or silence.', 'Underworld Contacts'),
  (601, 'skill-347fc2d1146ded8c2c66720bdf55196aa57275e4ab438cc374a8042c0df8709a', 'Black-Market Trade', 'standard', 2, 'CHA', NULL, 'A savvy grasp of illegal, restricted, or underground commerce. From weapons to rare ingredients, this skill knows where to find it, who’s selling, and how to avoid getting burned.', 'Streetwise'),
  (602, 'skill-1a6b224b0293ff53bae5c78659b887f7eda897dace4c32e22fbcb9e465008d1b', 'Hot Goods Appraise', 'standard', 3, 'CHA', NULL, 'The ability to quickly assess stolen, counterfeit, or smuggled items for value, origin, and risk. It’s part fence, part forensics, part street intuition.', 'Black-Market Trade'),
  (603, 'skill-4b01e66c61c2ee77d35c4f39da0b2fc329b17616a51c921ee31f4f4fbbde6499', 'Off Book Deal', 'standard', 3, 'CHA', NULL, 'Negotiating transactions that leave no trace—no witnesses, no ledgers, no strings. These deals operate outside law, guild, or faction, but not without danger.', 'Black-Market Trade'),
  (604, 'skill-35033bea4a103669c3c86b2dbe5a201d9e39580354db982a765e6d40a69c1822', 'Smuggling Route', 'standard', 3, 'CHA', NULL, 'Knowledge of hidden tunnels, bribed officials, and detour paths to move goods unseen. This skill is both a mental map and a rolodex of risky partners.', 'Black-Market Trade'),
  (605, 'skill-f9d9411fef371ad81d9ff36d7e7d131baedda129d9a666de33ab573c5738a45e', 'Urban Survival (Social)', 'standard', 2, 'CHA', NULL, 'The day-to-day etiquette, slang, and posture needed to avoid standing out—or offending the wrong group—in densely populated or hostile zones. It’s camouflage through behavior.', 'Streetwise'),
  (606, 'skill-6e24066c2b3c505f82263b2c3db93828cd2ad5c22a8c041e564cdd1d4d28324e', 'Local Slang', 'standard', 3, 'CHA', NULL, 'The vocabulary, tone, and rhythm of regional or criminal dialects. Speaking the local code keeps you inside the tribe—and outside suspicion.', 'Urban Survival (Social)'),
  (607, 'skill-41461f74e813574df5d9c871811ab061e101fa59eddfd7ed9805a4d4a64c72db', 'Turf Etiquette', 'standard', 3, 'CHA', NULL, 'Knowing which streets are controlled by whom, what colors not to wear, and when to speak or stay silent. This prevents casual mistakes from becoming fatal ones.', 'Urban Survival (Social)'),
  (608, 'skill-f2ac7cfc77000829c1ebcda4a48b92e94f18fab04231937344b75a2ac47cb8df', 'Exit Sense', 'standard', 3, 'CHA', NULL, 'A sixth sense for escape routes, choke points, or blind spots in any urban sprawl. It’s the instinct that kicks in before things go loud.', 'Urban Survival (Social)'),
  (609, 'skill-a2aafcd43617e5c03f47a06e889ac6635f517942d808cd91619f4b41a95337f8', 'Intimidating Presence', 'standard', 1, 'CHA', NULL, 'The ability to command space, silence rooms, or shake confidence without lifting a finger. This isn’t about shouting or violence—it’s the raw, unspoken sense that you are not to be crossed. It simmers beneath words, carved in posture and gaze.', NULL),
  (610, 'skill-5b28bb0ad152fbe9a6978bebb3655139598f1676418b397ce97b538d8592fb3c', 'Menacing Glare', 'standard', 2, 'CHA', NULL, 'The use of intense eye contact to unsettle, dominate, or provoke hesitation. It communicates threat without noise—just pressure, like a predator sizing up prey.', 'Intimidating Presence'),
  (611, 'skill-deaa6aa8cdfc525967cf74fe55e96ba72f85b4b3be0d70ca0a6cf763f76b93b4', 'Predatory Stare', 'standard', 3, 'CHA', NULL, 'A gaze that instills primal fear, as if you already know how they’ll fall. It pierces false bravado and awakens instinctive dread in the weak-willed.', 'Menacing Glare'),
  (612, 'skill-71f96c7807c402bea51be3bc95774098b6063c06ea2b4130767faac2578c7e22', 'Fear Spike', 'standard', 3, 'CHA', NULL, 'The sudden projection of hostility or intent that sends adrenaline surging through the target. A fear spike is fast, sharp, and destabilizing—designed to make them flinch first.', 'Menacing Glare'),
  (613, 'skill-ca6af02acb2c2de18c31a34f36238f878c12c5645e633a04b8e1adc2560e0b78', 'Resolve Drain', 'standard', 3, 'CHA', NULL, 'A sustained, silent stare that chips away at inner fortitude. Confidence erodes with each passing second under your eyes, until even the bold begin to waver.', 'Menacing Glare'),
  (614, 'skill-0e1f08ed41dd739dcdcb09416245f3e7580daec485aa6cd5673dd85ce0c9f91b', 'Dominant Stance', 'standard', 2, 'CHA', NULL, 'The calculated use of posture, height, and spatial control to assert physical and psychological superiority. It tells the room who’s in charge without needing a word.', 'Intimidating Presence'),
  (615, 'skill-78f11616930fe4256c5a0b229e09122bb35e878daa26b6de0009c375837daefa', 'Alpha Presence', 'standard', 3, 'CHA', NULL, 'A fully embodied aura of control that suppresses challenge and invites compliance. Others feel compelled to follow, defer, or step aside, often without knowing why.', 'Dominant Stance'),
  (616, 'skill-1c168ca7ff6bbf1e0b982db27cb5278a3820255ca56e0abaef37373b2a6a14df', 'Space Invade', 'standard', 3, 'CHA', NULL, 'The deliberate violation of another’s physical boundary to provoke fear, discomfort, or retreat. Used precisely, it destabilizes even confident opponents.', 'Dominant Stance'),
  (617, 'skill-b6da2cdd690496379fddb190a28f58760a51c87503f015a6a132c597857dd882', 'Commanding Posture', 'standard', 3, 'CHA', NULL, 'A physically grounded stance that projects unwavering authority. It doesn’t demand attention—it makes others feel off-balance if they don’t give it.', 'Dominant Stance'),
  (618, 'skill-61657161cea274f4e6f3761dce1e8ac6cfa08f2be5291145407cfb981a5f5004', 'Threat Projection', 'standard', 2, 'CHA', NULL, 'The performative expression of danger—through tone, implication, or gesture. This skill doesn’t promise violence directly, but it lets everyone know it’s on the table.', 'Intimidating Presence'),
  (619, 'skill-4400937d843888664ae461faef2b007ad0c78fc7f9614f4d00bf8e657bd21688', 'Verbal Menace', 'standard', 3, 'CHA', NULL, 'The calculated use of tone, pacing, and implication to make a threat hit deeper than the words alone. A good verbal menace leaves targets questioning what’s real and what’s bluff.', 'Threat Projection'),
  (620, 'skill-dd13299cc842ca7a2c8763778bb50fd076f6ab88aac8bdd3f6e5fe4a7a9f1379', 'Weapon Display', 'standard', 3, 'CHA', NULL, 'The subtle—or overt—presentation of arms to send a message. It’s not drawn to attack; it’s revealed to remind. When done right, no blood need spill.', 'Threat Projection'),
  (621, 'skill-bf3d408efa6cafd0eed111a596d67a59169f7010a0bebe025de82dc8231df4fb', 'Psychological Edge', 'standard', 3, 'CHA', NULL, 'The layering of mind games, veiled threats, and strategic pressure to keep opponents off balance. It’s not about overpowering—it’s about making them second-guess every move.', 'Threat Projection'),
  (622, 'skill-fefdcdb71779b768562667473b56f837b5c9391f0d2b3edcf38f0c1e5a9c499b', 'Networking', 'standard', 1, 'CHA', NULL, 'The practiced ability to form lasting, meaningful connections across varied circles. Networking isn''t just about shaking hands—it''s about positioning yourself as a presence people remember, respect, and invite into opportunity. Relationships become leverage, and conversations become doors.', NULL),
  (623, 'skill-4dc8549f173ee3c1badb650bf33d5f7575f1b71dd66c5fd418047ce31400e69a', 'Influence Networks', 'standard', 2, 'CHA', NULL, 'A cultivated web of allies, advocates, and gatekeepers capable of shaping perception or opening unseen pathways. These networks span factions, guilds, and social layers—quietly pulling strings behind polite smiles.', 'Networking'),
  (624, 'skill-896044b95c44b337d4e1a8f63022eb222d4b8d01444cc6281855f4079b90e08b', 'Public Impact Timing', 'standard', 3, 'CHA', NULL, 'The ability to read the moment and strike socially when it will echo the loudest. Whether launching an idea or exposing a truth, this skill makes sure eyes and ears are waiting.', 'Influence Networks'),
  (625, 'skill-2cb3627c44218ea54adec02e7c46978f4c2c4f7490f25ffc31938420786e3ae9', 'Message Targeting', 'standard', 3, 'CHA', NULL, 'The refinement of message, tone, and method to fit the intended audience with surgical precision. The same truth lands very differently when spoken in the right dialect, at the right table.', 'Influence Networks'),
  (626, 'skill-2436d95238ddbcafceb8ac2a1a1e648ed0ccecf32bc71750230f5d96e944ce76', 'Message Control', 'standard', 3, 'CHA', NULL, 'The ability to guide what spreads and what stalls—through silence, redirection, or subtle reinforcement. It’s not about censorship; it’s about social engineering, quietly sculpting public memory.', 'Influence Networks'),
  (627, 'skill-15486fc51ee3392c0ba72f4596fb3aff43adc20c8e9e051421b59d055f88b4c1', 'Professional Circles', 'standard', 2, 'CHA', NULL, 'The art of moving within formal hierarchies—guilds, orders, firms, or factions—without losing individuality. This skill opens closed doors through recognition, merit, and mutual gain.', 'Networking'),
  (628, 'skill-d82436f7fca073b508fcc625750d954316c843b4d4480ba32e2d01b1026d462f', 'Elevator Pitch', 'standard', 3, 'CHA', NULL, 'The mastery of condensing ideas, goals, or value into a brief, compelling exchange. Used well, it can shift power structures in less than a minute.', 'Professional Circles'),
  (629, 'skill-0c8a6bb069b0419c4d766b9c9d3948de80c485c67245097fbc053b680d0b73aa', 'Credibility Leverage', 'standard', 3, 'CHA', NULL, 'The strategic invocation of titles, achievements, or affiliations to strengthen perception. People trust authority—this skill ensures you appear to hold it, even when the weight behind it is paper-thin.', 'Professional Circles'),
  (630, 'skill-c544f0bef4a045de415d32ce76ba65d5127b508bb698db33938560b6f9fbc6f1', 'Trade Gossip', 'standard', 3, 'CHA', NULL, 'The quiet collection and deployment of insider whispers, reputation shifts, and whispered rivalries. Sometimes the most dangerous truths are half-true and casually spoken.', 'Professional Circles'),
  (631, 'skill-77a6cdd4356d1f16b0efc77b257d1c5303bc56b37ced09dbd88f88e85a566282', 'Event Schmoozing', 'standard', 2, 'CHA', NULL, 'The social grace to thrive in crowded, noisy gatherings filled with masks, motives, and potential. It’s less about what you say, and more about who remembers you afterward.', 'Networking'),
  (632, 'skill-a33776d359111fd96a077e734c7cea3537a45b8de0ca07aef99f475c56127209', 'Ice Breaker', 'standard', 3, 'CHA', NULL, 'The instant opener that softens resistance, sparks curiosity, or turns strangers into listeners. A good ice breaker rewrites the room within seconds.', 'Event Schmoozing'),
  (633, 'skill-0d6a29bea06b7b29cac17ab9247d25c7275512b8669c1019146188524796a3ce', 'Follow Up Rapport', 'standard', 3, 'CHA', NULL, 'The skill of transforming fleeting moments into long-term connection through timing, tone, and genuine investment. True influence begins after the first handshake ends.', 'Event Schmoozing'),
  (634, 'skill-af6d8d0067b85e98282acb5a544ff3af529070569c428f631291a5db99912883', 'Gift Exchange', 'standard', 3, 'CHA', NULL, 'The tactical use of meaningful offerings—symbolic, practical, or personal—to create unspoken obligation and lasting goodwill. A single well-chosen gift can say what words never could.', 'Event Schmoozing'),
  (635, 'skill-0a5d8bcf10c1c26bece039824a35981e1495bd15a228f97f984353972693d8fa', 'Etiquette & Culture', 'standard', 1, 'CHA', NULL, 'The practiced fluency in social rituals, customs, and respect codes across different peoples and nations. Etiquette isn''t about faking refinement—it’s about speaking the silent languages that govern status, trust, and access. This skill opens doors that strength or wit cannot.', NULL),
  (636, 'skill-267f68120ec1d89c1fa5b10625f2544c7f0321f5694eb759f4152931925a7134', 'Formal Etiquette', 'standard', 2, 'CHA', NULL, 'The mastery of high-court behavior, ceremonial process, and ritualized interaction. In places where tradition rules and reputation is currency, this skill keeps you from misstep and elevates your standing.', 'Etiquette & Culture'),
  (637, 'skill-0fd5be61b3bdb2a8ac3bb083a54aa4f61c5a8cf6d65013bb9d2cb58846339917', 'Table Manners', 'standard', 3, 'CHA', NULL, 'The precise execution of dining conduct across noble feasts, merchant banquets, or alien hospitality. Knowing when to speak, toast, or remain silent can determine the success of a negotiation—or your survival.', 'Formal Etiquette'),
  (638, 'skill-bf4f77cc107ca7804f87cdd312fe2b3d43ff482c9bc77069b7b852c779e2098e', 'Gift Protocol', 'standard', 3, 'CHA', NULL, 'The subtle language of giving and receiving, from tokens of alliance to rituals of tribute. A gift given poorly offends; a gift given with timing and symbolism can change destinies.', 'Formal Etiquette'),
  (639, 'skill-b3f888d0df2ffa460d478a3efca513e754bcb647cd76e588ff6b00d55f031950', 'Dress Code', 'standard', 3, 'CHA', NULL, 'The understanding of wardrobe as social signal. Whether ceremonial robes or mercantile badges, your attire communicates allegiance, rank, and intent before you speak a word.', 'Formal Etiquette'),
  (640, 'skill-45b153c87249cc66b2bdd2fe0bc22ad472fda4df913092a48191cfa9cb0327d1', 'Cultural Insight', 'standard', 2, 'CHA', NULL, 'The ability to intuit and interpret foreign values, sacred symbols, and unspoken rules. It is the difference between a traveler and a trespasser—between being welcomed or watched.', 'Etiquette & Culture'),
  (641, 'skill-b2ed4e22de4e9f8648eb661207d283526e8bbd109e5d5b757144e82085b69d66', 'Custom Recognition', 'standard', 3, 'CHA', NULL, 'The skill of identifying which rituals, practices, or expectations define a given group. Recognizing what is normal—without needing to ask—is a sign of deep respect.', 'Cultural Insight'),
  (642, 'skill-121c6a7e33c4b7e552df1d95e8ae9b4c07432f9cd35afc156b242007a5f298ea', 'Taboo Avoidance', 'standard', 3, 'CHA', NULL, 'The instinctive ability to sidestep social landmines—actions or words that would insult, shame, or provoke. Sometimes survival depends not on what you say, but on what you wisely do not.', 'Cultural Insight'),
  (643, 'skill-1cf275f4cfffa9c100c180ed2f931f75d812e39d6c50b114c2714429193b73b9', 'Respect Gesturing', 'standard', 3, 'CHA', NULL, 'The physical and verbal signals that show humility, honor, or reverence to hosts, elders, or figures of power. A simple gesture, properly placed, can dissolve hostility or elevate diplomacy.', 'Cultural Insight'),
  (644, 'skill-c5c3e361e5a0309fdd1844d48a5ee34a2fbffb51b40da5fdb62a151b3c139022', 'Language Etiquette', 'standard', 2, 'CHA', NULL, 'The understanding of social tone, syntax, and hierarchy embedded in speech. Some cultures bow with their bodies—others with their words.', 'Etiquette & Culture'),
  (645, 'skill-0c67c5bdfcec3b37a18a6faf53529adfdb5a888e9299331117f6f50266a5fefd', 'Honorific Use', 'standard', 3, 'CHA', NULL, 'The correct deployment of titles, suffixes, and verbal hierarchies that show respect or submission. In the wrong place, the wrong title can cost respect—or blood.', 'Language Etiquette'),
  (646, 'skill-9eaa490c78be1a41bec70b07161ae4d16951abce0bfb562f69c6c1453f45774b', 'Polite Address', 'standard', 3, 'CHA', NULL, 'The shaping of introductions, requests, and responses to avoid offense while establishing rapport. Mastery here turns awkward exchanges into graceful entrances.', 'Language Etiquette'),
  (647, 'skill-9c7bdc74da831a1c704e93c4bf9990b5b6aaf1c770f4a4a81f6f028fa7e82074', 'Diplomatic Tone', 'standard', 3, 'CHA', NULL, 'The ability to embed neutrality, flexibility, or ambiguity into language without sacrificing clarity. This skill allows one to speak boldly while sounding inoffensive—and to criticize without ever being accused.', 'Language Etiquette'),
  (648, 'skill-a3b7128538c528494058c97dbaa37e17c63f23666306884757dacc31a0c9a616', 'Resonant Performance', 'magic access', 1, 'CHA', NULL, 'The ability to weave sound, emotion, and will into a living performance. This isn’t music for entertainment—it’s a crafted vibration meant to ripple through reality. With this skill, the bard’s voice becomes a conduit for resonance-based magic.', NULL),
  (649, 'skill-029baa87f3d34d934f870bad89f8f4d8d95adc9c248819834f0fc25b110abf8c', 'Harmonic Awareness', 'magic stabalization', 1, 'CHA', NULL, 'A passive sensitivity to the balance and vibration in people, places, and soundscapes. Harmonic Awareness doesn’t create magic—but it lets you hear what others miss. This awareness is what fuels your Bardic Resonance manna pool.', NULL),
  (650, 'skill-b64107d6d5fc9d621e6b721bf8c2607e3e6b4f8b1b6458e174980626da311cd6', 'Resonance Attunement', 'magic regeneration', 1, 'CHA', NULL, 'The internal discipline to align your spirit with external harmonics. Whether listening to ley lines, empathic fields, or musical scales, this attunement refines your ability to recover and channel resonance.', NULL),
  (651, 'skill-b3a927cf63131517aecbd7b5934a4a84bdeb5116d56579d7e5917f5140201dce', 'Charm', 'sphere', 2, 'INT', 'WIS', 'Charm governs magic that influences emotions, impressions, and social dynamics. Whether through enchantment, aura shifts, or spoken compulsion, it bends interaction in the caster’s favor. This sphere doesn’t command minds—it nudges them gently, invisibly.', 'Spellcraft'),
  (652, 'skill-340623fff341d5e624906fa750b945e31a9505d7138f3f538fc98db94918c394', 'Heart’s Influence', 'spell', 3, 'INT', 'WIS', 'At its simplest, Heart’s Influence stirs faint ripples of courage and warmth in a single target, bolstering their spirit against fear. With practice, it grows into an aura of confidence that strengthens allies and unsettles enemies, its resonance reaching across groups and moments. At higher mastery, this spell allows the caster to manipulate emotions on a wide scale—binding hearts in unity, crushing resolve with dread, or even reshaping entire battlefields by weaving inspiration and despair together. At its pinnacle, the spell saturates all within reach with overwhelming emotional resonance, creating harmony or hysteria that can turn the tide of nations.', 'Charm'),
  (653, 'skill-341fc53cc72e344c703d3a95f714ba0b4f2eb2c5ddd05b96c1fd1975e31e07af', 'Soothing Presence', 'spell', 3, 'INT', 'WIS', 'A warm glow surrounds the caster, subtle at first like a flicker of candlelight. The air feels lighter and calmer, and tension seems to slip away from those nearby. Allies within the aura feel their heartbeat steady and the haze of fear dissipate. Even the smallest gestures of the caster—a smile, a word, a touch—carry unusual weight, encouraging those who might falter. On the battlefield, this translates into steadier hands on weapons and calmer minds in the face of danger. The spell does not control its recipients, but it cushions their emotions and strengthens their courage. Tactically, this is a powerful way to counter fear-based abilities, intimidation, or morale-breaking effects. It also helps allies hold formation, preventing panic when faced with overwhelming odds. In the lore of Charm, Soothing Presence is seen as one of the most humane applications of influence, showing that charm magic is not always about manipulation but about uplift. Many see it as the first step on a path of emotional mastery, teaching casters to nurture before they ever learn to dominate.', 'Charm'),
  (654, 'skill-c6b97e9f78f71e932ef7f837f49ff3be60d78bb422c680a23bdc03b0a410c5cd', 'Momentary Dread', 'spell', 3, 'INT', 'WIS', 'A sudden weight falls across the battlefield as the caster locks eyes with their chosen foe. The victim feels as if shadows lengthen unnaturally and the air grows heavy with foreboding. For an instant, the caster’s presence seems far larger and more dangerous than their form should allow. A chill runs down the target’s spine as instinct screams that they are prey before a predator. On the battlefield, this pause is enough to disrupt attacks or halt movement. Even though the fear lasts only a heartbeat, hesitation can cost lives in combat. Tactically, Momentary Dread is used to open small windows of advantage, letting allies press forward while the foe falters. The spell is subtle—its power lies in the mind, not in physical damage. It is one of the earliest lessons in how fear can be as sharp a weapon as steel. In the lore of Charm, this spell is a warning to young practitioners: influence can easily tip into coercion, and fear is the easiest, but often most dangerous, emotion to wield.', 'Charm'),
  (655, 'skill-af3e765349d486b01620e3241692982034bfb7ef786819bf70b7d2d4e2768f3c', 'Rallying Cry', 'spell', 3, 'INT', 'WIS', 'With a surge of confidence, the caster unleashes a cry that resonates like a battle hymn. The sound carries beyond the limits of ordinary speech, filling allies with renewed energy and unshakable courage. Warriors who were wavering steady their blades, and companions on the brink of collapse rise to their feet once more. On the battlefield, this spell creates an immediate shift in morale, helping groups withstand overwhelming odds. It does not command, but rather empowers, lifting spirits and banishing doubt. Tactically, Rallying Cry is most effective when an ally line is faltering, or when enemies are attempting to break ranks through intimidation. The spell can turn a rout into a stand or a desperate push into a charge. Its manifestation is not only heard but felt as a warm vibration in the chest of every ally. In the lore of Charm, Rallying Cry is remembered as the magic of leaders who fought not with domination, but by inspiring others to greatness. Tales tell of armies saved by a single voice carrying across the field.', 'Charm'),
  (656, 'skill-7e82b92cfdb5996a91e5c5eca4daf2d4f574f2172cbed812347b8a27f522f470', 'Seed of Doubt', 'spell', 3, 'INT', 'WIS', 'The caster whispers words, subtle or shouted, that bypass reason and settle directly in a foe’s mind. The victim feels hesitation gnaw at their confidence, a creeping uncertainty that clouds judG.O.Dent. Even the strongest warrior falters when they question themselves at the critical moment. On the battlefield, this spell weakens enemy resolve, making them more likely to hesitate, miss, or fail to press their advantage. Tactically, Seed of Doubt shines when aimed at enemy leaders or those directing battle flow, as their hesitation ripples through their ranks. The spell manifests as a moment of silence or distraction, like a heartbeat skipped before action. For allies watching, it appears as if the enemy hesitates without reason. In lore, Seed of Doubt is often considered the darker side of Charm, showing how influence can undermine rather than uplift. Practitioners are warned that sowing too much doubt can backfire, eroding trust even among allies. Some say overuse of this spell marks a caster’s own spirit with hesitation.', 'Charm'),
  (657, 'skill-de9eecdc6d7cc3831c98b85caf6f3ff24c5f25d7786306fdf21f1bde6cdc9398', 'Shared Bond', 'spell', 3, 'INT', 'WIS', 'A silvery thread of resonance weaves outward from the caster, linking allies with a sense of connection. Each member feels not only their own heartbeat but the presence of their companions, as if standing shoulder to shoulder even at a distance. On the battlefield, this creates a unity that sharpens reactions and builds trust, preventing confusion in chaotic clashes. The spell manifests as a faint glow or shimmer between allies’ forms, invisible to enemies unless they are attuned to magic. Tactically, it allows allies to coordinate more effectively, gain confidence in each other’s presence, and resist attempts to isolate them. The emotional link does not transmit speech or thoughts, but it conveys trust and reassurance in the heat of battle. In lore, Shared Bond is celebrated as one of Charm’s noblest forms—rather than domination or fear, it highlights companionship and unity. It is said that ancient companies of soldiers stood unbroken because they carried this invisible thread between them. To this day, it is taught as a spell of solidarity more than combat.', 'Charm'),
  (658, 'skill-d86a4e9501ca1ba429ccd41b02359538d18357a529d2351b5c70003aac8707f1', 'Chains of Devotion', 'spell', 3, 'INT', 'WIS', 'The caster speaks a phrase laced with irresistible charm, and shimmering bands of emotional resonance lash out like invisible chains. These bonds do not bind flesh, but compel the target’s own heart and will to hold them in place. Victims often stand willingly, eyes glazed with adoration or loyalty, as if chained by their own devotion. On the battlefield, this immobilizes foes who would otherwise threaten allies, buying precious time. Tactically, it serves as a control spell that turns an enemy’s emotions into their prison, forcing them to hesitate or stand down. The manifestation appears as glowing strands of light or shadows of tethered hands, though some casters’ versions appear entirely invisible. Lore warns that Chains of Devotion is among the most dangerous charms, for it forces will into service without true consent. Ancient tales describe rulers who abused this spell to hold entire courts in thrall, their courtiers “bound” in loyal admiration until their spirits broke. Practitioners must balance its usefulness with the weight of moral consequence.', 'Charm'),
  (659, 'skill-994d8c0900c5b75975e80d0c7b105015857cf5d6dd18a06c12529029b3312f8c', 'Harmony’s Veil', 'spell', 3, 'INT', 'WIS', 'A soft, resonant hum spreads outward as the caster raises their hands, weaving an emotional tapestry that blankets the battlefield. Allies feel an uplifting harmony, their movements synCHAonizing with uncanny precision, while enemies hear dissonance in the same resonance, their strikes faltering under waves of unease. To those within the aura, the world seems divided—friends feel like a choir in perfect unison, foes like discordant notes struggling to be heard. On the battlefield, this spell strengthens ally coordination while subtly breaking enemy morale. Tactically, it allows one spell to both buff allies and debuff enemies simultaneously, making it versatile for chaotic engagements. Its manifestation is felt as both sound and sensation, the battlefield almost singing with resonance. Lore recalls that ancient charmers could shift entire wars by creating fields of harmony and disharmony, where one side surged forward while the other collapsed. Harmony’s Veil is remembered as a weapon of generals and peacemakers alike.', 'Charm'),
  (660, 'skill-ff3b63587f6bb4c3a7a522dfca77269ed4237d4f8e9b69a38fd0974670ff2b63', 'False Idol', 'spell', 3, 'INT', 'WIS', 'The caster radiates an aura that twists perception, projecting an illusory mantle of divinity or authority. Enemies perceive the caster as impossibly awe-inspiring or terrifying, while allies feel an unshakable reverence. To those affected, the caster’s words carry irresistible weight, and their commands seem like truth spoken from on high. On the battlefield, this effect can cause enemies to hesitate, allies to obey instinctively, and entire groups to treat the caster as more than mortal. Tactically, it creates both intimidation and loyalty in one spell, allowing manipulation without a single weapon raised. Its manifestation varies: some glow with holy light, others with dread shadows, but all command obedience. Lore whispers of false prophets and tyrants who bent cities to their will with this magic, their subjects worshipping a lie made real. To wield False Idol is to flirt with corruption, for those who play god may forget they are mortal. Even after the spell fades, the memory of awe or dread lingers in its victims.', 'Charm'),
  (661, 'skill-d0af6dab77ee0a51f32f049ab3f4d13ea74aef07fe4024486b483097ff23f1e6', 'Symphony of Souls', 'spell', 3, 'INT', 'WIS', 'As the caster raises their arms, the air fills with a haunting harmony that resonates through every living heart within reach. Allies hear the melody as triumphant and uplifting, a song that steels their will and guides their movements in unison. Enemies hear the same tune as a discordant cacophony, each note scraping their confidence and unraveling their courage. The battlefield itself seems to pulse with music, as though invisible strings connect every combatant to the caster’s rhythm. Allies find themselves striking in concert, their voices rising together in strength. Enemies stumble, their formations faltering, their movements just a step behind. Tactically, this spell allows the caster to simultaneously strengthen their allies and collapse enemy morale across a massive zone. Its manifestation may take the form of sound, light, or even raw sensation—different for each who hears it. Lore says the greatest charmers once brought entire armies to their knees with a single song, rewriting the fate of battles in moments. To hear the Symphony is to feel your heart conducted by another’s hand.', 'Charm'),
  (662, 'skill-bd7254475c6b345fef4bec3953a5ac7e064e9985668053d0eb37c4b13d45c9e2', 'Puppet Strings', 'spell', 3, 'INT', 'WIS', 'With a subtle gesture, the caster conjures glowing threads of resonance that extend outward like strands of silk. These strings latch onto enemies’ limbs and minds, jerking them into unnatural movements. To allies, the scene looks as though foes have become marionettes, forced to stumble or strike against their will. Victims may feel their own bodies betray them, each step and action guided by an unseen puppeteer. On the battlefield, this spell can disrupt formations, force enemies to attack allies, or hold them in place. Tactically, Puppet Strings is devastating for coordinated foes, as their strength is turned against them in confusion. Its manifestation varies—threads of light, shadow, or even invisible pulls—but all give the eerie sense of domination. In lore, Puppet Strings is remembered with dread, often tied to tyrants who bent whole squads of warriors into unwilling puppets. It represents one of the most morally dangerous frontiers of Charm: not persuasion, but total usurpation of another’s will. Even after the strings fade, victims often remember the horror of betrayal by their own bodies.', 'Charm'),
  (663, 'skill-427f7c7a39dcf0b94e256a39aa2ec5ed925853a70b9a6b3ca02b0a73a59a5bc2', 'Dominion of the Heart', 'spell', 3, 'INT', 'WIS', 'With a single resonant command, the caster’s presence floods the battlefield and beyond, saturating every heart with irresistible influence. Allies feel a surge of transcendent unity, their fears erased, their courage unbreakable, as if bound together by a single indomitable spirit. Enemies, however, feel their wills collapse under the weight of the caster’s dominance, their thoughts bending toward submission, despair, or adoration. The very air shimmers with emotional resonance—each breath carrying the weight of obedience and awe. On the battlefield, soldiers drop their weapons, leaders hesitate, and entire armies may rally or crumble depending on the caster’s intent. Tactically, this spell can end conflicts in an instant by breaking morale on a massive scale, or by turning vast numbers of foes into unwilling pawns. Its manifestation is unique to each caster—some appear as radiant icons of divine glory, others as overwhelming shadows of terror—but all are unforgettable. In lore, Dominion of the Heart is whispered as the ultimate test of Charm magic, a spell capable of rewriting not just battle but history itself. Those who wield it risk not only backlash but their own humanity, for commanding the hearts of thousands can blur the line between leadership and tyranny. Even after the spell fades, legends, trauma, or loyalty forged in its wake may persist for generations.', 'Charm'),
  (664, 'skill-52c8e02987ccb1b0eef9c7c966aebf03c92a159aafda37fbcf03f4838dbcd48d', 'Death', 'sphere', 2, 'INT', 'WIS', 'Death magic manipulates the forces of decay, entropy, and spiritual release. Practitioners may weaken vitality, sever life essence, or commune with the recently departed. It is a quiet, inevitable current—not chaos, but conclusion.', 'Spellcraft'),
  (665, 'skill-152b9c48e869552b480fa736f11e135b9c6c6d6c4340fd7ac0927e1e68792c56', 'Whisper of the Grave', 'spell', 3, 'INT', 'WIS', 'At its most basic, the spell allows the caster to brush against the veil between life and death, conjuring faint whispers of the departed. At Apprentice level, the voice is vague, indistinct, and carries only fraG.O.Dents of insight—sudden chills, fleeting words, or impressions from nearby spirits. At Novice, the whispers sharpen, and a caster can call forth a shade to briefly converse or answer questions. By Mastery, the spell allows binding: the caster may command a spirit to linger, granting minor boons or performing small tasks. At High Mastery, multiple spirits may be summoned at once, some even manifesting visibly to defend their summoner. At Grand Mastery, the veil parts fully—the caster may draw entire hosts of spirits or even anchor a soul into a phylactery, beginning the dreaded path toward lichdom. The progression mirrors the practitioner’s journey from timid listener to full master of the dead.', 'Death'),
  (666, 'skill-14dec215dd9b78c35998b8f637e149bfc6d4df752097830f018bcd9e92e5b87d', 'Grave Chill', 'spell', 3, 'INT', 'WIS', 'The caster lays a corpse-cold hand upon the living, channeling a sliver of the grave’s frigidity into flesh. A rime of spectral frost creeps from the touch, leaving skin pale and breath briefly misted even indoors. The chill is not merely temperature—it is the numbing echo of stillness that follows the last heartbeat. Muscles tense, fingers stiffen, and a tremor of weakness ripples through the target’s frame. The necrotic bite pricks the life-thread and hurts just enough to remind the body that it can end. This is a novice’s strike: precise, close, and intimate, demanding nerve rather than spectacle. It is favored in cramped crypts, alleys, and doorways where distance is a luxury. Against wary foes, it opens a window for allies to press in or withdraw. Even after the touch fades, the memory of death’s nearness lingers for a beat. Instructors warn that the spell should be practiced on cadavers before used in the field, both for ethics and for steadiness of hand.', 'Death'),
  (667, 'skill-79d219c58315274245b4afc10e1c137cbec4175de25007557135f3283cab2ea2', 'Bone Puppet', 'spell', 3, 'INT', 'WIS', 'The caster crooks a finger and wills an abandoned bone to stir, not creating life, but lending it a moment of borrowed motion. The fraG.O.Dent jitters upright like a marionette without strings, head swiveling toward the chosen foe. It scuttles or hops a few steps, clacking rhythmically as if remembering how to move. The sight alone shakes many opponents; the touch snags ankles and grips sleeves with impossible insistence. This is not a true servant, merely a surge of grave-force shaping residue into nuisance. In tight quarters, the puppet buys a heartbeat, spoiling timing and wrecking footing. Veterans use it to interrupt a draw, a cast, or a sprint for cover. When the power lapses, the bone collapses into stillness as if embarrassed to be seen. Animals shy and balk at the clicking thing; children whisper that the dead are learning again. Those who command greater arts later will raise soldiers—this is the first lesson in control.', 'Death'),
  (668, 'skill-fa38f6ac4063391289153945b802b56e9913b492f1c14df2f012a5221b3bc82f', 'Grave Grasp', 'spell', 3, 'INT', 'WIS', 'The caster slams their hand or staff into the ground, causing skeletal arms and spectral claws to erupt from the soil. These grasping remnants claw upward, clutching at ankles and dragging the living toward stillness. The ground itself seems to mourn, groaning with hollow echoes as the dead claw their way into the present for but a moment. Victims find their legs bound, balance disrupted, and breath stolen by panic as the unseen clutch tightens. The spell is especially potent in graveyards or battlefields, but it can manifest even in stone halls as shadowy hands. Tactically, it halts an enemy line or slows a charge, making it invaluable for necromancers buying time. Foes who fail to free themselves often become easy prey for allies’ strikes. The macabre display unnerves all who witness it, reminding them of mortality waiting beneath their feet. The clutching grasp fades into dust and shadow when its brief work is done.', 'Death'),
  (669, 'skill-53862b5987f751bf81ddd2bfc231f5d900028a17a92705ce5f64b5b04d014d99', 'Death’s Shroud', 'spell', 3, 'INT', 'WIS', 'The caster exhales a pall of necrotic vapor, a shroud that blankets the area in ghostly fog. Within the shroud, the air grows heavy, lungs struggle, and a sickly pallor settles on all caught inside. The mist muffles sound, distorts sight, and makes the living feel the weight of the grave pressing down. Those affected grow sluggish, their limbs aching as vitality ebbs. In combat, the shroud is a tool of attrition, breaking enemy morale and softening resistance for allies to exploit. Its oppressive chill unnerves beasts, sending them into panic, and soldiers fear to enter its haze. Necromancers often use the spell to prepare ground for greater rites, since it marks territory with death’s flavor. The shroud lingers only briefly before dissipating into wisps of darkness. Even once gone, the memory of its suffocating pall tends to linger on its victims.', 'Death'),
  (670, 'skill-7c5bf78c20c4e19ed2000e61714d225e121cf50ede4d051d806c7de552c21848', 'Bind Undead', 'spell', 3, 'INT', 'WIS', 'By intoning words of command, the caster projects their will across the tether between life and death, seizing the strings of an undead creature. The undead briefly stiffens, its will overwhelmed, then turns to obey the caster’s command. Whether skeletal sentry, shambling ghoul, or wandering spirit, the spell asserts dominance and bends the creature to necromantic purpose. At this novice level the control is fragile, lasting only moments, but even a brief shift in loyalty can decide a skirmish. Commanded undead can be redirected to guard an ally, attack their former master, or simply be ordered to freeze in place. The spell is especially feared among enemy necromancers, as it can break their lines of minions in an instant. Failure to maintain the command risks backlash, the creature lashing out in instinctive fury before returning to freedom. With mastery, casters learn to stretch this control further, but even in its briefest form it is a potent battlefield tool. The power whispers of the mastery of lich-kings, who no longer ask but dictate the flow of undeath.', 'Death'),
  (671, 'skill-54c02792ca8dc64b972f13cdcd678a27ded8b01bb9b12e38e0386dd565e28148', 'Wailing Legion', 'spell', 3, 'INT', 'WIS', 'The caster rends open a wound between the mortal world and the spirit realm, allowing a chorus of lost souls to pour through. Their wails echo with sorrow and rage, shaking the courage of all who hear them. The spectral horde swirls in a wide zone, clawing and shrieking at anything living caught within. Enemies stagger, their minds rattled and their movements slowed under the psychic weight of death’s memory. The battlefield becomes a haunted place—shadows stretch unnaturally and every heartbeat feels out of place. Tactically, the spell halts charges and breaks formations, as few can stand steady in the presence of so many dead. Those struck by the wails falter in initiative, losing their tempo. The display lingers briefly, a terrifying wall of sound and presence. When the rift closes, silence falls with a suffocating suddenness.', 'Death'),
  (672, 'skill-5d3075712d0814ad3caa2d9b1a752ae5cb9631510d25a6988c1d78ba7e647621', 'Marrow Rot', 'spell', 3, 'INT', 'WIS', 'The caster invokes a curse that seeps directly into the bones of their victim. Flesh blackens around marrow as necrotic energy hollows the skeleton from within. Targets struck feel their limbs weaken, their structure betraying them with sudden fractures or painful weakness. On a battlefield, this spell is a precision strike against heavily armored foes—those who rely on bones and body to carry them through combat. Victims may collapse outright or stagger under the crushing weight of decay. The spell spreads quickly within one target, then echoes outward to a second as rot leaps from bone to bone. This creates panic as enemies see their comrades suddenly falter. Tactically, the spell turns strong frontliners into liabilities, unable to support their own armor. Even after the spell fades, the ache of hollow marrow lingers.', 'Death'),
  (673, 'skill-2877f7763eeb5f7b2cb927cb73671cda484a059786c982925eed6ea149b8afb8', 'Crypt Lock', 'spell', 3, 'INT', 'WIS', 'By weaving necrotic force into space itself, the caster seals a chosen area as though it were a tomb. Black iron chains and spectral locks appear from nothing, binding doorways, walls, and even the air itself. Creatures caught inside feel their bodies press downward, as if gravity has doubled, making escape nearly impossible. Those who try to flee find exits sealed by spectral wards, trapping them in an ethereal cage. Tactically, the spell cuts off retreat or confines enemies for destruction. Allies can strike from outside while the trapped foes are forced to endure. The pressure is suffocating, reminding all within that they stand in death’s prison. Once the duration ends, the chains vanish, but many recall the sound of locks clicking shut long after.', 'Death'),
  (674, 'skill-4067bb4ac5e166f9168165ef7238624123ca8d4cef75a933e65e745d6f83018f', 'Pale Harvest', 'spell', 3, 'INT', 'WIS', 'The caster raises their arms and draws forth the life of everything caught in their sight. A pall of pale light spreads across the battlefield, dimming flames, wilting leaves, and draining the vigor from flesh. Victims stagger as their vitality seeps away, pulled in threads of ghostly silver toward the caster. Each strand curls into the necromancer’s chest, bolstering their vitality as others weaken. The battlefield becomes eerily quiet, as if the world itself holds its breath while life is stolen. Tactically, this spell serves both offense and sustain, softening enemy ranks while keeping the caster alive. Even mighty champions may falter as their strength is siphoned by invisible hands. Allies feel the drain too if they stray too close, making this a risky but devastating choice. When the spell ends, those who survive are left weakened, trembling at the knowledge their essence was tasted by death.', 'Death'),
  (675, 'skill-fe716795cfec6c9692a07e149a030d4c8d3933bd2e6ce29a7647f050db507113', 'Grave Cataclysm', 'spell', 3, 'INT', 'WIS', 'The caster slams their will into the ground, cracking reality as necrotic force erupts outward. Bones, blackened soil, and spectral fire burst from beneath the battlefield in a tide of ruin. The eruption consumes the area in a storm of shrieking skulls and grave-dust, draining vitality and slowing all caught within. The terrain twists as earth collapses into shallow pits littered with skeletal fraG.O.Dents, turning the battlefield into treacherous ground. Those struck feel their flesh weaken, their speed fail, and their courage shatter. The air hums with a dirge-like resonance, a reminder that death is the only true dominion. Tactically, this spell halts armies, shatters morale, and forces foes into chaos as allies exploit the weakened ground. Survivors crawl from the devastation marked by lingering necrotic burns. Even once the cataclysm fades, the terrain remains scarred, a haunted place that resists healing and growth. The spell is feared not only for its destruction, but for how it reshapes the land itself into a graveyard of its own making.', 'Death'),
  (676, 'skill-386c592f2009be1807e6645fb730ea2f21c4b607fa0b9e21473bec9603863ca7', 'Eternal Black Sun', 'spell', NULL, 'INT', 'WIS', 'The necromancer tears open the veil of death itself, birthing a blackened sun that hangs in the sky above the battlefield. This orb radiates necrotic energy in pulsating waves, its light not illumination but a suffocating shadow that extinguishes all warmth. The living feel their life-force wither as their flesh cracks and bones ache under its gaze. Corpses on the field stir, skeletal hands and half-rotted forms rising as the sun’s pulse animates the dead in grotesque parody of life. The terrain warps into a blighted wasteland, flowers withering, rivers slowing, and air thickening with death’s rot. Even spirits are caught, dragged screaming toward the orb, where they circle in endless orbit as a crown of wailing souls. Tactically, the spell halts entire armies: the living are weakened, the dead rise, and morale collapses under the crushing aura. When the black sun fades, nothing remains untouched—soil stays barren, survivors suffer lingering decay, and the memory of the sun’s shadow becomes legend. This is not merely a spell, but an apocalypse contained within a single will.', 'Death'),
  (677, 'skill-79ad4f01e6447ef191f9a8348544486c1f0b1ea1b7919478e982ecc9ba989f02', 'Divination', 'sphere', 2, 'INT', 'WIS', 'Divination reveals what is hidden—past, future, truth, or lie. It sharpens intuition, enhances perception, and peels back the veil. This magic doesn’t guarantee answers—it opens the door to seeing them.', 'Spellcraft'),
  (678, 'skill-dee5808406ccdc43d179246810d34f48fab40e059bc06fadd7e16997a5777a07', 'Glimpse of Truth', 'spell', 3, 'INT', 'WIS', 'A faint shimmer overlays the caster’s vision as veils peel away from sight. Small hidden objects, concealed markings, or faint traces of magic are revealed briefly. The spell does not grant deep insight, but it’s enough to uncover traps, notice hidden compartments, or detect if magic lingers on an object.', 'Divination'),
  (679, 'skill-2a85bdaebe624d9c336c96e83474db9458cef2c246438b2abb03762502c40b45', 'Echo of the Hunt', 'spell', 3, 'INT', 'WIS', 'The caster closes their eyes and whispers the target’s name. A brief, intuitive flash points toward the target’s last known direction within short range. The vision is momentary—just enough to set the pursuit in motion.', 'Divination'),
  (680, 'skill-7998d9b5724b03fa07403fe8f6657646a44e20e2498735a0ffddb969e652ddec', 'Whisper of Tongues', 'spell', 3, 'INT', 'WIS', 'A soft hum fills the caster’s mind as words spoken around them clarify. The spell briefly translates unfamiliar languages into a faint, intuitive understanding. Syntax remains broken, but intent and meaning become clear for a fleeting moment.', 'Divination'),
  (681, 'skill-87d51860f5b8d3c142b4b800d204db504e148c30773bd10563e4abefcbbfb99a', 'Eye of Secrets', 'spell', 3, 'INT', 'WIS', 'The caster’s eyes glow with pale silver light as illusions and lies falter. Within a short radius, hidden doors, concealed glyphs, and invisible entities are outlined faintly. Allies in the area also gain a brief bonus to their perception, making it harder for foes to hide.', 'Divination'),
  (682, 'skill-cc86ccd9b20151650c47a2dd2ae4310030f281d2531fab15b02de34916f6ebbd', 'Whispered Fate', 'spell', 3, 'INT', 'WIS', 'Whispering softly, the caster glimpses the threads of probability. For the next few moments, they foresee enemy intentions and ally actions. Allies react faster while enemies hesitate as golden filaments tug at choices not yet made.', 'Divination'),
  (683, 'skill-1d93becb2e04dc715c4ba5d63dc6490fe05d15e0c0bf574e4e602a27f0179963', 'Voice of the Lost', 'spell', 3, 'INT', 'WIS', 'The caster tunes their senses to lingering echoes. Within a small radius centered on themselves, faint whispers of recent conversations or presences can be heard. This spectral resonance also reveals the strongest emotion that clung to the space.', 'Divination'),
  (684, 'skill-3b3ba2fc953f3f1d6dd8eec0c4655845e3dd3bf8792abe5b23729b2ceeb2d4da', 'Far-Seer’s Eye', 'spell', 3, 'INT', 'WIS', 'The caster’s pupils glaze to mirrored glass as a silent, invisible sensor blossoms at a distant point in space. A faint, rippling bead of distortion forms a 10‑foot sphere, relaying clear sight and muffled sound back to the caster’s senses. Subtle glyph-threads tether the sensor to the caster, steadying the view even as the world turns around it. Veils thin: invisibility silhouettes as pale outlines, and lingering auras stain the air with color. The sensor can be planted in advance and released on a cue, ideal for ambushes or surveillance. Though distant, its presence is slightly concealed, like heat-haze on stone. The caster feels a whisper of wind and the grain of surfaces as if fingertips brushed them. Enemies appear slightly desaturated, making motion easier to track. The effect lasts briefly, but a skilled diviner chains placements to maintain coverage. Used well, it turns any battlefield into a watched board.', 'Divination'),
  (685, 'skill-edfc2207a19bda3ec0dd97e58125207e1e1b75a89c476c7673bb5af0d924cd6b', 'Expose the Flaw', 'spell', 3, 'INT', 'WIS', 'A thread of cold understanding darts from the caster’s gaze and stitches itself into chosen foes. Their postures give away timing; armor gaps seem to widen; breath hitches just before they move. Pale sigils float over joints, seams, clasps, and blind‑angles—visible to allies as brief glints. The caster names a target’s weakness, and the party’s strikes fall truer. Each casting churns probability, turning hesitation into certainty. Even guarded foes feel watched, and the pressure slows their hands. For a fleeting exchange, every ally sees what the diviner sees. When the marks fade, the memory of angles lingers a heartbeat longer.', 'Divination'),
  (686, 'skill-306df248f145aa8d4dbdac44b9bdbfb694980f13b10fcff37488e891b2bb8f14', 'Oracle’s Reposition', 'spell', 3, 'INT', 'WIS', 'The caster inhales futures and exhales a correction. In the instant before a blow lands, allies flicker along the lines of possibility and reappear a pace aside. Footfalls land where strikes are not; spears find only air as echoes of the allies remain behind. The diviner’s hand cuts three short arcs, mapping safe squares on an unseen grid. A heartbeat of acceleration hums through those moved, a sharpened edge to their timing. The jump is modest but decisive—doorways cleared, traps avoided, flanks seized. Each extra success pulls the path a little farther, as if the future leaned to help. The motion is velvet‑smooth and near‑silent, like thought. For an eyeblink, the world seems to remember two positions at once. Then it chooses the safer one.', 'Divination'),
  (687, 'skill-f797a320c932849c23fb7d86a5c976a3c5123f4bf17d3b4730e722a1a22a05fa', 'All-Seeing Veil', 'spell', 3, 'INT', 'WIS', 'With a ripple of silver light, the caster unfolds an immense dome of awareness. Within its boundaries, every secret is dragged into the open: illusions dissolve, concealed foes glow faintly, hidden passages etch themselves into view, and even whispers carry unnaturally clear. The veil does not discriminate—friend and foe alike are laid bare, their weaknesses scrawled across the vision of all who stand inside. The effect is overwhelming, but unmatched for unraveling deception and setting the battlefield in perfect clarity.', 'Divination'),
  (688, 'skill-e9153dd83804bd694cff6d981b40874a23f86244637c229c5fd4c70b2943d073', 'Threads of Fate', 'spell', 3, 'INT', 'WIS', 'The caster’s hands weave luminous filaments of golden thread that lash out to up to five visible targets. Each thread binds into the target’s aura, exposing possible futures. The caster and allies glimpse moments before they occur—attacks before they land, movements before they begin. Targets bound by the threads stagger as their futures rebel against them, suffering slower initiative and faltering strikes. Every ally tied into the weave senses where to step next, as if fate itself whispered the path.', 'Divination'),
  (689, 'skill-ad8d41c888cf97c7dab88bd9b9adc89315f2f52310cd4d76a606ad844a1f9f1f', 'Revelation of Eternity', 'spell', 3, 'INT', 'WIS', 'The caster’s form blazes with cascading runes of light, each glyph representing a hidden truth. With a single breath, the veil between what is and what could be tears wide open across the battlefield. All illusions, lies, and concealments collapse instantly; every creature in sight is outlined in blinding clarity, their weaknesses and fates scrawled openly in threads of fire visible to all. For three full rounds, the caster and their allies perceive not only the present but fraG.O.Dents of immediate futures—the swing of a blade before it moves, the crack of a spell before it forms. Enemies reel under the unbearable exposure, their actions faltering as destiny itself resists them. Though awe-inspiring, the Revelation also leaves the caster drained, their mind battered by too many truths at once. This spell is both a blessing and a terror, a force that can end wars—or unmake the diviner in its backlash.', 'Divination'),
  (690, 'skill-7b74b418a352d67108173c20c1b16b4b726bad8606be65711ff924dbf9a40670', 'Earth', 'sphere', 2, 'INT', 'WIS', 'Earth magic calls upon stone, soil, and structure. It grounds movement, reinforces forms, and shapes terrain. This is the magic of endurance, weight, and immovable presence.', 'Spellcraft'),
  (691, 'skill-d1e29f20149166c9841668ed494985b181621287ddb91d89dfd1974e5dce976d', 'Stone Pebble', 'spell', 3, 'INT', 'WIS', 'The caster flicks their hand and a small pebble rips free from the ground or nearby debris, propelled forward with unnatural force. At its base form, the spell is little more than a magically-guided stone, useful for training, pestering foes, or distracting enemies. Yet, the spell’s simplicity hides its potential: as the practitioner’s mastery deepens, the pebble grows into heavier stones, razor shards, and eventually boulders hurled like meteors.', 'Earth'),
  (692, 'skill-6916a817771c83f4d1c7680b103396c087ea4483708f342cf77ff2f29c703047', 'Earthen Tangle', 'spell', 3, 'INT', 'WIS', 'From beneath the target’s feet, roots and hardened soil surge upward to clutch at their legs. The ground molds into crude, earthen hands that grasp and restrain. Victims find their steps falter, slowed as the soil pulls at their movements. The spell embodies Earth’s protective nature, stopping threats before they reach allies.', 'Earth'),
  (693, 'skill-c27fed393f79587c0a1afce9fd14ae6e32fa0c3877e2544a8b5c2d16b0daa67d', 'Stone Skin', 'spell', 3, 'INT', 'WIS', 'The caster calls the essence of stone into their body, forming a skin of hardened earth across their flesh. The rocky coating muffles blows and dulls blades, giving the caster resilience in combat. While heavy, it protects against the most immediate strikes, buying precious time to act. Apprentices use this spell to learn Earth’s duality as both shield and weapon.', 'Earth'),
  (694, 'skill-c6b30a950f78a18eeb008ba71c9fce2a0ad6a3527f8275eda8da4966b6e4885e', 'Stone Spikes', 'spell', 3, 'INT', 'WIS', 'With a sharp gesture, jagged spikes of stone erupt from the ground in a sudden and violent display. The eruption pierces upward, skewering anything caught in its line of effect. The terrain itself becomes hazardous, slowing or discouraging enemies who might try to cross. This spell exemplifies the Earth sphere’s ability to weaponize the ground beneath their feet.', 'Earth'),
  (695, 'skill-171aec647a9aa4508f1a947c8fc627cd255699ac7117e35928f24b944d10e118', 'Earthen Grip', 'spell', 3, 'INT', 'WIS', 'The ground itself stirs as the caster commands the earth to rise like a living hand. Jagged roots or rough stone fingers burst upward, clutching the target tightly. The victim finds themselves pinned in place, struggling against the raw weight of the earth. This spell highlights the Earth sphere’s ability to control both terrain and movement through natural force.', 'Earth'),
  (696, 'skill-1bf2452cb1078603a9fdb74842b78276cfc7d0811172969d46201759dfc8ef56', 'Rock Armor', 'spell', 3, 'INT', 'WIS', 'The caster draws upon the surrounding earth, shaping it into a protective shell of stone that clings tightly to their form. Jagged shards, hardened plates, and compacted dust fuse into armor, granting a formidable bulwark against attacks. Though heavy and restrictive, the armor greatly reduces harm and makes the caster appear as an immovable force upon the battlefield. This spell embodies the enduring resilience and patience of the earth.', 'Earth'),
  (697, 'skill-4039cf4e726569246e2d51e138456731cc763e07ff79226a1f4586d03d37772c', 'Stone Spire', 'spell', 3, 'INT', 'WIS', 'With a crushing roar, the ground beneath the target heaves violently upward, forming a jagged stone spire that erupts from the earth. The sudden upheaval impales or crushes anything caught above it, while also altering the terrain to create a natural barrier. The battlefield shifts dramatically as the earth itself rebels against intruders, leaving both tactical cover and a lasting scar in the land.', 'Earth'),
  (698, 'skill-1fe13d8a7004fc4b11e783d22e044c2a4c0905921ba97286d653e0a27a14e6f3', 'Earthen Grasp', 'spell', 3, 'INT', 'WIS', 'The ground churns and splits as massive stone hands burst upward, seizing their target with crushing force. The grip is unyielding, locking the victim in place while jagged rocks tighten around them. This spell embodies the implacable will of the earth—unyielding, unrelenting, and impossible to ignore. Those caught in its grasp find themselves at the mercy of stone itself.', 'Earth'),
  (699, 'skill-03bb96a0b0e1005480a22a69357f152bde58cb738a4703a5364b43598490a9dd', 'Stone Maelstrom', 'spell', 3, 'INT', 'WIS', 'The caster slams their staff or fists into the ground, unleashing a violent surge of stone and shale. The terrain erupts into spinning shards, creating a deadly whirlwind of jagged rock that tears through all within its reach. The battlefield becomes a grinding storm of stone, turning stable ground into a death trap. Such violent upheaval embodies earth’s raw fury, combining natural might with destructive will.', 'Earth'),
  (700, 'skill-abbf46aa7988761a5ad91f8578b40e2b6180bc0accc02351b87430fd843f8c45', 'Continental Rift', 'spell', 3, 'INT', 'WIS', 'The caster calls upon the primal might of the earth, tearing the battlefield apart with a sudden fissure. The ground splits open violently, swallowing enemies, toppling structures, and leaving behind a scar of devastation. The spell embodies the sheer destructive and uncontrollable power of tectonic upheaval, turning stability into chaos.', 'Earth'),
  (701, 'skill-bb93cff8851d49accdf69b665b0339e1cf15f56c036ebbea5c9d424f798e247d', 'Avalanche', 'spell', 3, 'INT', 'WIS', 'The caster commands a mountainside or conjures an overwhelming surge of rock and debris. A massive wall of stone and snow crashes down, crushing enemies and reshaping the battlefield. This spell demonstrates earth’s power not just to defend but to utterly overwhelm, burying foes in a tide of destruction.', 'Earth'),
  (702, 'skill-e28a6107cba414a2ef18dfa9f6cb45ff8ed1ffc9b74b94d8003e968e858e91e8', 'Worldshaper’s Bastion', 'spell', 3, 'INT', 'WIS', 'The caster draws upon the primal core of the earth, summoning an immense fortress of stone and living rock from beneath the battlefield. The terrain buckles upward as massive walls, towers, and barriers erupt into being, reshaping the battlefield into an impregnable bastion. This is not mere protection—it is domination of the land itself, bending stone to the caster’s indomitable will.', 'Earth'),
  (703, 'skill-4bdeddab2769c2f3cb618cea6f5c9bc45de6704f3c683f1ca5854bfadce13138', 'Enchantment', 'sphere', 2, 'INT', 'WIS', 'Enchantment alters properties of items, imbuing them with effects temporary or lasting. It’s the subtle reinforcement of armor, the glow in a blade, or the whisper of warmth in a cloak. Magic locked into matter.', 'Spellcraft'),
  (704, 'skill-4e977da3bb5d984b6bd1b63bdb26fe0424d471bf15d8948ca685973c0437b560', 'Arcane Imbuement', 'spell', 3, 'INT', 'WIS', 'The caster channels raw arcane resonance into a chosen item, weaving patterns of light and resonance that cling to its form. At Apprentice level, the effect is simple—an item glows faintly, radiates warmth, or carries a subtle sense of magical presence, marking it as touched by arcane hands. At Novice level, these enchantments sharpen into functional enhancements: a blade that bites harder, a shield that soaks more impact, or a trinket that glimmers with utility. By the time the caster reaches Mastery, multiple items may be empowered at once or layered with several minor effects, each enchantment persisting longer in the fray. At High Mastery, the caster can create battlefield relics whose power lasts beyond combat, resonating for a day or more, their presence shifting the tide of encounters. At Grand Mastery, the enchanter crafts overwhelming temporary artifacts—items burning with multiple enchantments at once, operating at the peak of mortal magic but still destined to fade when their woven resonance unravels. The spell’s beauty lies not in permanence but in the mastery of shaping fleeting brilliance into power.', 'Enchantment'),
  (705, 'skill-b89fc9d90d2829956c0ff68446734317f5249296efc82a73707073e3e41425a6', 'Cleanse', 'spell', 3, 'INT', 'WIS', 'The caster focuses their will into an object, purging dust, grime, spiritual residue, and unstable arcane traces that linger within it. At first, this manifests as a faint shimmer across the surface, like dew evaporating in dawnlight, leaving the object visually pristine. Beyond the physical, faint distortions of corrupted mana or lingering magical interference are dissolved, creating a stable lattice ready for new enchantments. This spell is indispensable for enchanters who wish to lay a flawless foundation before attempting more complex work, for even the smallest impurity can cause later enchantments to falter or backfire. While it bears little direct combat use, Cleanse is a ritual of care, discipline, and foresight. Its role is subtle yet essential: ensuring that what is built upon the object will endure.', 'Enchantment'),
  (706, 'skill-027dcc20c7ede0fca28ae4c3d4fbd673df26222c1c3595984555dfe031831598', 'Gleam', 'spell', 3, 'INT', 'WIS', 'With a touch and a whispered word, the caster causes an object to radiate with soft brilliance. At its simplest, the spell produces a steady glow bright enough to light a dark chamber or guide allies through shadowed halls. The enchantment is more than simple illumination: blades may shine with a polished gleam, armor may shimmer with a lustrous sheen, or jewelry may radiate a subtle aura of charm. Though temporary, the effect makes the object appear more alluring, impressive, or mystical. This small spark of artistry demonstrates enchantment’s role beyond combat, blending beauty and function into everyday tools.', 'Enchantment'),
  (707, 'skill-addf64e883fcf56b6537e922468ec757861ab2f89e428bd67f4c685be1dad115', 'Runeward', 'spell', 3, 'INT', 'WIS', 'The caster traces a glowing sigil across a surface or object, imbuing it with protective resonance. When triggered, the rune flares with light and creates a brief warding field, shielding the bearer or area from harm. At its simplest, Runeward hardens an object or bolsters a shield with resilience, but clever enchanters etch it on walls, doors, or even clothing for versatile defense. The ward fades quickly after activation, its strength spent, leaving only faint ash-like residue where the rune once glowed.', 'Enchantment'),
  (708, 'skill-50c5fd5492c125f259a19fb704106279c8ec29308bc42ce5548a594cb051f34a', 'Weapon Spark', 'spell', 3, 'INT', 'WIS', 'The caster lays a hand upon a weapon, causing it to hum with energy. For a short time, each strike resonates with a chosen element—flame, frost, lightning, or raw arcane force. Sparks trail from its edge or tip as it moves, making the weapon feel alive in the wielder’s grasp. While temporary, this enhancement can turn even a common blade into a potent tool of battle, glowing with dangerous promise. When the effect fades, the weapon reverts to mundane steel, the resonance discharged.', 'Enchantment'),
  (709, 'skill-ca4d4d6eb2c7dcc35fa6b02b762002263d4aa62ef5cb6422b93edce59237c159', 'Echo Seal', 'spell', 3, 'INT', 'WIS', 'By pressing their hand to an object, the caster leaves behind a faint shimmering sigil. This mark resonates with the caster’s mana, allowing them to detect or recall the object from a short distance. Adventurers often use Echo Seal to track stolen gear, mark hidden caches, or coordinate with allies through subtle signs. To those attuned, the mark glimmers faintly, like a heartbeat of light pulsing through the material. While temporary, it provides a valuable way to maintain awareness and control over objects across the battlefield or in exploration.', 'Enchantment'),
  (710, 'skill-d2b29764af3ea56b3b8bba2469938ce27685292b500025701cbdcd9e6f18dede', 'Attune Item', 'spell', 3, 'INT', 'WIS', 'The caster channels steady waves of mana into a chosen item, saturating it with a stable mystical aura. The object vibrates faintly, glowing with soft resonance as its lattice aligns to receive further enchantments. Unlike fleeting buffs or battle-spells, this attunement lingers long after combat, unlocking the object’s capacity to bear complex magical bindings. Attune Item represents a rite of passage for all enchanters who pursue permanence: the moment when an ordinary tool becomes a vessel for lasting power. To observers, the object radiates potential, as though waiting for the next inscription or binding ritual to complete its transformation. While Attune Item carries no combat advantage on its own, it is indispensable in the progression toward artifact creation.', 'Enchantment'),
  (711, 'skill-0ebfdfd515f300cdb6ddf50a979ed13aea67236f9258c299f8fc9b623fc8ce5c', 'Edge Sigil', 'spell', 3, 'INT', 'WIS', 'The caster presses two fingers to a weapon’s spine or grip and sketches a swift rune that flares, then settles into a steady ember-glow. A faint hum builds in the metal (or haft), as if the tool were breathing in time with the caster’s pulse. When swung or loosed, the weapon sheds threadlike sparks that trail each motion and vanish as they meet flesh, wood, or stone. The sigil does not sharpen steel; it weaves a temporary strike-channel that converts motion into raw resonant harm. Fighters feel the rhythm immediately—hits land heavier, parries bite, and even glancing blows carry weight. The effect is focused and short-lived, ideal for decisive pushes or finishing strikes. Smiths call it “borrowed edge,” a reminder that true sharpness returns to the mundane when the glow fades. Observers see only a disciplined flare, not a gaudy blaze; this is craftsmanship, not spectacle. When the sigil collapses, the weapon cools in a heartbeat, leaving no mark but memory.', 'Enchantment'),
  (712, 'skill-39fd2e505b5b06bfc0118a44a34ff2a9261ac8c418ca34321749a827b636d9c9', 'Bulwark Sigil', 'spell', 3, 'INT', 'WIS', 'The caster lays a palm on a shield rim, breastplate ridge, or layered leathers, tracing a compact ward-knot that sinks beneath the surface and steadies the wearer’s stance. A subtle pressure surrounds the bearer, like a firm wind always pushing from the right direction. Blows land duller; edges hesitate; impacts disperse across a web of unseen lines. The armor does not thicken—its resonance learns to catch force and pass it sideways. Veterans recognize the feeling: a quiet confidence that turns panic into poise. The sigil shines only when struck, a brief hexagonal shimmer that snaps out as quickly as it appears. For a short window, the wearer stands like a wall, and the wall remembers how to stand. As the rune unwinds, the armor exhales, returning wholly to its natural weight.', 'Enchantment'),
  (713, 'skill-10cd318a0c89b150a207bb0f9cbc3cd3e8dcc8518b362e61e9a2d4b6c503c66c', 'Permanency', 'spell', 3, 'INT', 'WIS', 'The enchanter places a steadying hand on a prepared item while tracing a tight weave of runes in the air. The existing enchantment’s pulse is caught and held, then stitched from “active spell” into “native property.” A soft pressure hush spreads, and the room’s motion feels slightly slowed as the rite aligns. Minute filigree lines appear and sink beneath the surface, leaving only a faint watermark to trained eyes. The process is focused rather than flashy, and most casters perform it outside battle. Its tactical value lies in removing upkeep—turning a time-limited boon into a constant feature of the item. On success, the bound effect no longer counts as a running spell; it is part of the object. The result resists ordinary dispels and endures as long as the item endures. Those who treat this step like a flourish often fail; those who respect pacing leave works that outlast their age.', 'Enchantment'),
  (714, 'skill-9760ce545aea360d7c161b1ce43869b03e548b3f68b7e34e4d78004748087bc2', 'Arsenal Field', 'spell', 3, 'INT', 'WIS', 'The caster sketches a circle in the air and snaps it downward; a pale ring blossoms on the ground, then rises as a faint dome. Within the field, allied weapons thrum with a hard, bright resonance that rides each swing and shot. Edges seem to catch the air a fraction longer; strings and bow-limbs settle into perfect line; hafts feel weightless at the instant of impact. The field does not scorch or dazzle—its craft is quiet power, turning trained motion into decisive harm. Enemies sense the difference as glancing blows start to bite and clean hits drive deeper. The perimeter holds steady, its surface resisting intrusion like taut silk, keeping the enchantment’s pattern from fraying under chaos. Commanders time charges to the field’s rise, pouring strength through a narrow window. When the dome fades, the light goes with it, leaving steel honest again. Smiths say it is the sound of a workshop’s best day, trapped for a moment on a battlefield.', 'Enchantment'),
  (715, 'skill-f5606daf50576cb095002efb234e6c9f81364f3444c5e76003516fc5c9f78706', 'Ascendant Weapon Sigil', 'spell', 3, 'INT', 'WIS', 'The caster traces a seven-stroke rune along a weapon’s line—pommel to tip, grip to head—each stroke flaring, then sinking as if drawn into a hidden vein. The weapon answers with a low, steady tone that riders feel in bone and tendon. On the next breath it moves like a memory you never earned: weight perfectly placed, angle already found, follow-through already true. Every impact plants a bright echo that shivers the target’s guard, while the weapon itself drinks chaos and returns clarity. A secondary mark knots beneath the guard as a silent oath, ready to burst once against hostile magic that tries to seize the wielder or smother the strike. The air around the weapon seems fractionally thicker, as if the world agrees to carry the arc a little farther. This is not permanence; it is ascension on loan—enough to decide a duel, break a line, or write a legend for a day. When the sigil unwinds, the tone fades to silence and the weapon is only what it truly is, though the hand that held it remembers.', 'Enchantment'),
  (716, 'skill-dc9f28b12dd1818ee42ffc92ecb940386214598837348d30d3c6c0b7b57e34c9', 'Fire', 'sphere', 2, 'INT', 'WIS', 'Fire magic is raw power—heat, combustion, and destruction. It consumes, clears, and transforms. Practitioners learn to wield not just flame, but the hunger and momentum that fire brings.', 'Spellcraft'),
  (717, 'skill-025dbd0e026054e5f10564f385de6bbcc74e6b77ac4d225a684def297ea6b2d3', 'Flaming Dart', 'spell', 3, 'INT', 'WIS', 'A small but potent dart of fire kindles at the caster’s fingertips. With a flick, it darts toward a nearby foe, scorching them with searing flame. While simple at first, this spell is designed to evolve with the caster’s growing mastery, steadily transforming from a modest spark into a devastating barrage of fiery bolts.', 'Fire'),
  (718, 'skill-a239db0adf8de4781dc8bafeb74510b2cd55018c98a44dde1a07004172103299', 'Ember Flick', 'spell', 3, 'INT', 'WIS', 'A flick of the caster’s hand sends a tiny ember darting forward, glowing with a bright orange spark. Upon striking its target, it bursts with a sharp sting of heat that sears exposed flesh or ignites loose cloth. While the damage is minimal, its reliability makes it a favorite among students learning control of flame. Outside combat, it is often used to light candles, torches, or even kindling.', 'Fire'),
  (719, 'skill-787af8806321ea033f41555146d67ca2ac67fbf83550d9d535c850ffb2bf565a', 'Heat Veil', 'spell', 3, 'INT', 'WIS', 'The caster pulls warmth from the air and bends it into a thin shimmering veil that surrounds their body. This protective field softens the bite of fire, dampening flames that would otherwise sear flesh. Though temporary, it provides a moment of resilience in the heat of battle, allowing the caster to endure sudden bursts of flame. Beyond combat, the technique is sometimes used to withstand brief exposure to harsh environments such as volcanic vents or furnace rooms.', 'Fire'),
  (720, 'skill-8c63641e902026b650d6583d46003f14bd2edc2c5338f84e9dc021e0aafdcd92', 'Scorching Ray', 'spell', 3, 'INT', 'WIS', 'The caster focuses raw fire into a concentrated beam of searing heat that streaks across the battlefield. The ray strikes with precision, burning through armor and igniting whatever it touches. It is more potent than an ember or dart, able to cause real harm in combat, yet it still retains the speed of a direct strike. Outside of combat, the ray is often employed as a tool for cauterizing wounds or smelting small bits of ore, showcasing the utility of controlled flame.', 'Fire'),
  (721, 'skill-af6fe1985244557af9534dd497c270a036e9e762fe3d2c1c9c8a8af505d1d281', 'Flame Wall', 'spell', 3, 'INT', 'WIS', 'With a forceful gesture, the caster draws flame from the ground or air, shaping it into a blazing barrier. The wall crackles and roars, blocking passage and punishing those who attempt to cross through. While short-lived at Novice mastery, it provides both offense and defense, forcing enemies to choose between delay or injury. Many practitioners use it as a means of herding foes or controlling the flow of battle.', 'Fire'),
  (722, 'skill-d589250a993f17ac2855625f3b80598a332dc41df05dcc5cf48ab9a75755914a', 'Cinder Burst', 'spell', 3, 'INT', 'WIS', 'The caster snaps their hand or stomps the ground, causing a sudden burst of embers to flare outward. The cinders scorch lightly but can catch clothing, hair, or dry terrain on fire, creating momentary chaos. Though not devastating in raw damage, it is effective at disrupting groups of enemies or flushing out those in hiding. Practitioners often use this as a warning flare, a combat opener, or a flashy way to make a point in tense negotiations.', 'Fire'),
  (723, 'skill-d15aebd5962aa0602752b8f203c0aa26b3da8220d39261f6204a02bec0aa35e8', 'Inferno Wave', 'spell', 3, 'INT', 'WIS', 'The caster thrusts both arms outward, summoning a sweeping tide of flame that races across the battlefield. The wave engulfs everything in its path, scorching earth, armor, and flesh alike while leaving a smoldering trail. Few defensive lines hold against its raw force, and even survivors are often left reeling in smoke and embers. Beyond combat, this spell has been used to clear forests, demolish buildings, and intimidate entire crowds at once.', 'Fire'),
  (724, 'skill-c475fc0ab7052f12ba95a9d71c7c4d451b33c83043c893515c5951c201cd427b', 'Pyroclasm', 'spell', 3, 'INT', 'WIS', 'The caster slams their staff, fist, or foot into the ground, splitting it with a booming crack. A geyser of molten flame bursts upward, then rains down in chunks of blazing rock and searing sparks. The impact leaves craters and fire patches scattered across the battlefield, reshaping the terrain with raw destructive force. Many consider Pyroclasm the signature mark of a true battle-mage, equal parts spectacle and devastation.', 'Fire'),
  (725, 'skill-92ad3384322d05b9c95d2cc75b42b04cfd32de21b97ebc09e513d4ba2c59e014', 'Phoenix Surge', 'spell', 3, 'INT', 'WIS', 'The caster’s body ignites in radiant fire as they hurl themselves skyward, exploding outward in a blaze that takes the form of fiery wings. The flames crash down in a wide burst, incinerating enemies while leaving the caster briefly shrouded in heat and light. This spell is often viewed as both a weapon and a statement — the mark of Fire’s rebirth and ferocity. In myth, Phoenix Surge is sometimes said to channel a fraG.O.Dent of elemental spirit through the caster.', 'Fire'),
  (726, 'skill-7a11b477eb14dedb98c35155d35c0ba89e0dfa21fd60aac1bd562071263fcda9', 'Hellstorm Crucible', 'spell', 3, 'INT', 'WIS', 'The caster rends the sky itself, conjuring a boiling storm of fire and ash. Columns of flame fall randomly within the targeted zone, while the heat bends air and movement falters. The crucible both burns and restrains, forcing enemies to fight against searing gales as the ground cracks beneath them. More than raw destruction, it is imprisonment by living fire, and few can endure its duration.', 'Fire'),
  (727, 'skill-3e03edee82458a2ff4bf147d9349992092c790fc856d81f766928426fbaf47f7', 'Infernal Maelstrom', 'spell', 3, 'INT', 'WIS', 'The caster manifests a spiraling vortex of fire and superheated wind that pulls everything toward its center. The flames whip around like a tornado, reducing visibility and making movement nearly impossible. Enemies are battered by fire damage each round and dragged into the core, where heat and pressure intensify. The spell turns the battlefield into a lethal furnace, consuming terrain and opponents alike.', 'Fire'),
  (728, 'skill-283e90b79d0d3912f143cea9ec688ca999264ee780b760d38bb9f1e5c0155d71', 'Worldfire Convergence', 'spell', 3, 'INT', 'WIS', 'The caster rends open the firmament, merging earth, air, and sky into a living apocalypse of fire. A colossal inferno sphere manifests, filling the battlefield with flame and heat so intense it warps the land itself. Within the inferno, space bends unnaturally—time slows, movements stutter, and those caught are dragged helplessly by currents of searing wind. Outside the core, flaming chains lash outward, binding and dragging enemies into the furnace. No battlefield, forest, or city can withstand its fury; it is a spell of endings.', 'Fire'),
  (729, 'skill-171aac72c04f6eaa2516d2dbf87b4916b98903ce6567359ed1b23e60c4ad78fa', 'Illusion', 'sphere', 2, 'INT', 'WIS', 'Illusion magic crafts what isn’t there—light, sound, shape, and shadow. It doesn’t force belief, but tempts the senses to accept falsehood. This sphere is the art of deception, disguise, and distraction.', 'Spellcraft'),
  (730, 'skill-8047482c388681ada7365cb7b3de35bd00dc5d8f49b87b77db66406e4384116b', 'Phantom Flicker', 'spell', 3, 'INT', 'WIS', 'A simple illusion of sound or light, Phantom Flicker distracts a single target with a false noise, glimmer, or flicker in their peripheral vision. The effect is fleeting but effective, buying a crucial moment for allies. On the battlefield, it can spoil an enemy’s aim or force them to glance away at the wrong time. Beyond combat, it serves as a tool of trickery for espionage or escape, misdirecting guards or onlookers. Its strength lies in subtlety rather than grandeur, but in the right hands it can shift the course of a skirmish.', 'Illusion'),
  (731, 'skill-e2b55e88c413bc3ca9e0334db70bf712258d6d9e9d1d681af53ae2856b36893d', 'Veiled Step', 'spell', 3, 'INT', 'WIS', 'Veiled Step cloaks the caster in faint shadows, their outline bending as if wrapped in heat haze. For a brief moment, their presence becomes harder to track, making it useful for repositioning or slipping from an enemy’s gaze. The effect is subtle, not true invisibility, but it can tilt the odds in stealth or combat. In the lore of Illusion, this spell is the first step toward merging with shadows themselves, a glimpse of the deeper shadowmancy to come.', 'Illusion'),
  (732, 'skill-52508ca0178b8e9472dc37f13188bf073657abfbca489917f3f8adc1d48a40fc', 'False Face', 'spell', 3, 'INT', 'WIS', 'False Face allows the caster to briefly alter their appearance—shifting facial features, changing hair or clothing colors, or masking themselves with a simple disguise. While the illusion will not withstand close physical scrutiny, it is convincing enough at a glance. Adventurers use it to pass as someone else in tense situations, escape notice in a crowd, or hide their true identity. In combat, it can disorient foes for a moment, forcing them to hesitate before striking.', 'Illusion'),
  (733, 'skill-75e81b0823f4f1c23f06f4072414b8bac20be6365815b9ff74ccc39e3a93e0d9', 'Phantasmal Echoes', 'spell', 3, 'INT', 'WIS', 'Phantasmal Echoes wraps up to three allies in rippling afterimages that lag a fraction behind each motion. To onlookers, each ally appears to split and rejoin, as if several half-real bodies were occupying the same space. Strikes aimed at one image pass cleanly through while the true form slides aside by inches. The illusions are purely visual but remarkably convincing at combat distance. A trained eye may notice a faint shimmer along edges where light refracts incorrectly, yet chaos often masks the tell. The echoes adapt to stance and footwork, keeping tempo with the bearer’s breath and weight shifts. Archers misjudge gaps, spearmen lunge a hair too soon, and blades carve only light. Outside battle, an escorted group seems larger, bolder, or more formidable than it is. The spell is favored by skirmishers and couriers who must cross contested ground without wearing heavy armor. It is illusion at its most praG.O.Datic: not to terrify, but to make enemies miss.', 'Illusion'),
  (734, 'skill-2291bfe48d6f8b38c5475a4bcaad3c6d644ecffb2f52f2cc5aa5270b1d76a510', 'Specter’s Whisper', 'spell', 3, 'INT', 'WIS', 'Specter’s Whisper threads false voices into the minds of up to three creatures within earshot. A guard hears a captain calling from the far corridor; a duelist hears their mentor’s warning at the wrong moment; a mage hears a chant that never began. The sound arrives with directionality and texture, carrying footfalls, breath, or distant clatter as the caster desires. To outside listeners, the air is silent, creating dissonance that unsettles those affected. The whispers cannot force obedience, yet hesitation creeps into timing and judG.O.Dent. A wary target might pause, pivot, or break formation to confirm the ghostly call. In crowded alleys, the effect is devastating, sending patrols chasing echoes. The spell excels at sowing doubt before an ambush or masking an orderly retreat. Subtle casters use it as a scalpel; brash ones as a drumbeat of panic. It is the lie you half-believe because you want to believe it.', 'Illusion'),
  (735, 'skill-b46398e9f4065d9d6badf700ce7683f45ab452a5e9dcf82f68ac6f2d4ed2a99b', 'Glamour Veil', 'spell', 3, 'INT', 'WIS', 'Glamour Veil dresses up to three allies in coordinated masks of light and shadow, aligning colors, edges, and silhouettes into a shared deception. With a breath, plain clothes catch moon-sheen, badges bloom on breastplates, and faces assume borrowed dignity. The glamour flows across seams and armor plates, matching the gait and posture the caster imprints. At a distance, the group reads as guards, couriers, or visiting dignitaries; at arm’s length, small tells remain for the attentive. The veil also blurs micro-movements, lending poise and confidence where nerves might betray. In a melee, the same harmonized styling helps allies slip lines and re-form, the enemy’s eyes sliding off their true positions. Street crews use it for quick jobs; agents for exit plans when a room turns cold. The spell rewards planning: choose a role, hold formation, speak like you belong. When belief and illusion meet halfway, doors open.', 'Illusion'),
  (736, 'skill-a375e15f87e34e387eed48d4046602762890e8582283cd25023bfa43b52ab734', 'Phantasmal Army', 'spell', 3, 'INT', 'WIS', 'A tide of shimmering figures surges onto the battlefield, indistinguishable from real soldiers. Their armor clinks, weapons gleam, and voices shout war-cries. Enemies struggle to tell friend from foe, often wasting attacks or retreating under the pressure of numbers. While the illusions cause no direct harm, the confusion they sow can collapse formations and turn morale against itself.', 'Illusion'),
  (737, 'skill-d03e4e227e9991ad3a636f361560c5300ba96892b39e2d6eea2bfa103fe5824d', 'Veil of Shadowstep', 'spell', 3, 'INT', 'WIS', 'The caster blurs into shadow, creating afterimages with every movement. To enemies, it appears they are in several places at once. Attacks strike empty air, while the caster glides across the battlefield unseen. Though not true teleportation, the trickery is enough to dodge blows and reposition with ease.', 'Illusion'),
  (738, 'skill-e31a271fb8bbf3707490f2b7b5fb55dacb56b89587c0cea3d3cc9ac1f9af3d9c', 'Maze of Mirrors', 'spell', 3, 'INT', 'WIS', 'With a sweeping gesture, the caster conjures a labyrinth of reflective walls, bending light into impossible corridors. Enemies are trapped inside shifting passages, seeing countless false versions of themselves and their foes. The maze is disorienting, often leading to hesitation, failed strikes, or even allies striking at phantoms.', 'Illusion'),
  (739, 'skill-536067553c3a0dc03018aa5aac769c5e6f23034520e8e8cfdddf7e93a85a997e', 'The Shattered City', 'spell', 3, 'INT', 'WIS', 'With a wave, the battlefield fractures into a false ruin: collapsing towers, broken streets, phantom screams of unseen citizens. Enemies stumble through rubble that is not there, ducking falling stones that never land. The illusion engulfs a wide zone, overwhelming senses with sights, sounds, and tremors of disaster. Though the destruction is false, those within lose orientation, strike shadows, and retreat from phantom collapse. To allies, it can feel like standing in two realities at once—the present battlefield and a city’s last moments frozen in nightmare.', 'Illusion'),
  (740, 'skill-da86a4e30b75afe2824bdc4ef1eee796d76be54d239ec3e8167e5a5961bbcb09', 'Nightmare Menagerie', 'spell', 3, 'INT', 'WIS', 'The caster tears open the veil between thought and shadow, unleashing a stampede of phantasmal beasts that stalk enemies with terrifying realism. Wolves of smoke, serpents of shadow, and chimera stitched from memory surge through the battlefield. Their howls, roars, and jaws are all illusions, yet the mind makes them real enough to paralyze. Enemies swat at monsters that pass through steel, but fear roots them in place. The zone becomes a hunting ground of nightmares, with every corner another predator’s lair. For allies, the field is chaos but survivable—they can recognize the beasts for what they are if guided. This spell embodies Illusion at its peak: terror as a weapon.', 'Illusion'),
  (741, 'skill-91bc4a66a174aea2115a2a4041ea4cdbe546da98aa2b4a328a56c16ea0d313bc', 'Eclipse of Truth', 'spell', 3, 'INT', 'WIS', 'Reality itself bends under Eclipse of Truth as the caster layers sight, sound, and sensation into a single overwhelming deception. The battlefield is swallowed by darkness as a false eclipse rises overhead; shadows twist into predators, terrain folds into labyrinthine corridors, and even the passage of time seems uncertain. Enemies cannot trust their eyes or ears—ally and foe blur together, weapons strike at illusions, and orders dissolve in chaos. Some fall into phantom pits or retreat from collapsing walls that do not exist; others stand paralyzed as shadow beasts circle. For allies, the spell is no less disorienting, though prepared minds can cling to the caster’s guidance. The effect reaches beyond combat: survivors carry doubts of what is real, haunted by lingering visions long after the eclipse fades. At this level, illusion ceases to be trickery—it becomes an alternate truth, imposed on all who behold it.', 'Illusion'),
  (742, 'skill-63bd7065ef1e165a04255d4048836ce126dfe2b6a0777722ad3a5c6013129d19', 'Life', 'sphere', 2, 'INT', 'WIS', 'Life magic nurtures growth, vitality, and biological resilience. It restores wounds, accelerates healing, and stirs dormant energies within the living. It is magic that encourages the body to remember itself.', 'Spellcraft'),
  (743, 'skill-28b72a29a435d069e1f7d2c444065a44bb3cb2c7be800f553fab9fc88df113c9', 'Vital Wellspring', 'spell', 3, 'INT', 'WIS', 'The caster taps into the raw flow of vitality itself, channeling threads of luminous life-energy into allies. At Apprentice level, this manifests as a simple restorative glow, sealing minor wounds and granting a fleeting warmth of resilience. As Novice, the spell matures into true battlefield healing, knitting flesh while bolstering vigor against toxins. By Master, the Wellspring becomes a font of renewal—its flow able to touch multiple allies, restoring vitality and fortifying their endurance for an entire round. At High Master, the caster not only heals but also shields, weaving protective wards that repel sickness, poisons, and curses while steadily restoring vitality for hours. At Grand Master, the Wellspring blossoms into a radiant beacon of life itself: a resurrection-tier miracle that heals all allies within reach, restores vitality lost to constitution drains, and shields the living with an aura of growth that can even revive the fallen under the G.O.D.’s ruling. This spell showcases the Life sphere’s highest calling—preserving, renewing, and exalting the force of existence itself.', 'Life'),
  (744, 'skill-dcbd6bd52618c41dbfd89c1c559882f18fa3df5570eafe7013d7d1739074d43f', 'Soothing Pulse', 'spell', 3, 'INT', 'WIS', 'With a gentle gesture, the caster channels a warm pulse of life-energy into a chosen ally. A faint glow spreads from their palm, mending scrapes and easing pain. The warmth lingers briefly, calming nerves and restoring a small measure of strength. In battle, the spell serves as a quick patch to keep allies moving, though its effects fade swiftly after release. Outside of combat, the pulse can ease minor injuries or aches, a comforting reminder of the caster’s bond to the living essence of the world.', 'Life'),
  (745, 'skill-b7b2563020d9b9847dae9e25d1eec1615d17c9e8175dc4f487f15fd6f2bdbe28', 'Vital Exchange', 'spell', 3, 'INT', 'WIS', 'The caster willingly shares their own life-force with another, a delicate tether of green-white energy transferring vitality. While it restores an ally’s vigor, the strain leaves the caster weakened, a trade that must be weighed carefully. This spell embodies the raw truth of Life magic: healing often carries cost. The exchange is immediate, the caster feeling their own warmth slip away as their ally rises with newfound strength. It is a tool of sacrifice, a means to keep comrades alive when every heartbeat matters.', 'Life'),
  (746, 'skill-625785f722c6322a43e7d8bc0886e1d0e758ac5fb0948ede334fa931673d8645', 'Renewing Wave', 'spell', 3, 'INT', 'WIS', 'A soft hum builds in the caster’s chest before spilling outward as pale-green light, rippling like water across the ground. The wave carries the scent of rain and new leaves, calming hearts and steadying breath. Tiny cuts knit, bruises lighten, and the sting of battle dulls in an instant. Companions feel a shared lift—enough to keep formation, reload, or press an advantage without breaking stride. The magic is precise rather than overwhelming, meant for skirmishes and quick recoveries. It favors coordination: staying close allows the group to catch the same pulse and rise together. Though its glow fades quickly, the aftermath lingers in morale and focus. Veterans learn to move into the caster’s radius at the right moment, treating this wave as a timing tool rather than a cure-all. In quiet, the same ripple can soothe frightened villagers or steady a wounded animal long enough for proper care. Life’s intent here is simple: a communal breath, then back to the work of living.', 'Life'),
  (747, 'skill-407e4dbd9704cb0025ec83b10503537f79969fa1c5696adba6b561166e4338e1', 'Cleansing Aegis', 'spell', 3, 'INT', 'WIS', 'A slender thread of living light coils around the target’s wrist, then unfurls into a thin, luminous shell. The shell tastes of mint and iron on the tongue, a telltale sign that foreign agents are being pushed out. Black veins lighten, bile settles, and a fever’s heat breaks with a soft hiss. The aegis focuses on purging a present affliction rather than fortifying endlessly. Once the impurity is canceled, a faint strength lingers—just enough to keep the body vigilant until the next exchange of blows. Fighters learn to time the touch between strikes, letting the shell snap into place and burn a toxin out before it spreads. Healers favor it in plague-wards and snakebite country alike, where speed beats ceremony. While the light lasts only a short while, its comfort steadies minds and restores discipline. The spell is not a panacea; some curses and eldritch blights resist mere life-light. Even so, when applied swiftly, it divides the living from the dying.', 'Life'),
  (748, 'skill-997dc7fa0870aed0cb4cfc8d905b633395ca49bc7c899b3346053e963abbf5b7', 'Verdant Bloom', 'spell', 3, 'INT', 'WIS', 'The caster presses a palm to the earth and feeds it a draught of raw vitality. Soil thickens, roots surge, and green shoots spear upward in a sudden hush. Vines loll across stone, softening hard cover and breaking harsh lines of sight into a gentle lattice. The ground takes on a living spring, as if the battlefield itself exhaled after a long drought. Archers duck behind fresh fronds; blades catch on pliant stems; feet learn caution where there was only dust. Though the growth appears in an instant, it feels natural, not summoned from nowhere but awakened. The effect is most potent in poor soil, where life yearns for any excuse to return. Commanders use it to sculpt lanes, mark rally points, or give pursuit a moment’s pause. Afterward, the plants remain until torn down, burned, or starved. In this way, the spell turns a moment of magic into a lasting change in terrain.', 'Life'),
  (749, 'skill-c69e7aa22f70fc7c0004b3eb8c93b65f43916599b534cc1726ace3d91772b547', 'Verdant Bastion', 'spell', 3, 'INT', 'WIS', 'The caster slams their staff into the ground, and roots explode outward in a glowing spiral, forming a protective circle of living wood and flowers. Within this bastion, allies feel their wounds knit shut and curses unravel as the verdant energy pulses each step. Enemies who attempt to enter or remain inside find themselves tangled by living vines, their movements slowed and restricted by the earth’s embrace. The bastion becomes a fortress of vitality: a place where life surges, poison burns away, and foes are punished for encroaching on sacred ground. The contrast is striking—healing warmth to allies, and choking restraint to enemies. In the midst of battle, this spell turns open ground into a fortress of resilience and control.', 'Life'),
  (750, 'skill-8df8cc984402af02aee596edc1bdc1eb0f91e32241a2fd5aee19eb87a35551a0', 'Chain of Vitality', 'spell', 3, 'INT', 'WIS', 'Threads of green-silver light lance outward from the caster, linking multiple allies in a glowing web. Each thread pulses with shared energy, allowing damage to bleed across the web and vitality to flow in return. When one ally takes a blow, part of it is suspended, delayed in a shimmering ripple of time, only to be dispersed safely later among the group. Meanwhile, each heartbeat sends healing pulses through the chain, mending small cuts and bruises. The battlefield impact is immense: groups bound by this spell become harder to break, their strength pooled across the bond. Yet the link is perilous; if one falls, backlash ripples out, punishing the others. The sight of glowing life-threads weaving allies together is both beautiful and terrifying, reminding foes that the group stands—or falls—as one.', 'Life'),
  (751, 'skill-fb87fd340f6a50d451878d87f9269f27b1609b436fc3ed0fd778b2b1379c6624', 'Vital Genesis', 'spell', 3, 'INT', 'WIS', 'When the caster kneels and thrusts hands into the earth, a surge of raw vitality bursts forth. Grasses, vines, and saplings erupt from barren ground, covering the battlefield in living green. Enemies caught in the growth find roots and branches snaring their limbs, pulling them to the earth with relentless force. At the same time, the plants exude rejuvenating energies, mending wounds of nearby allies and giving them renewed strength. The battlefield shifts completely: once-barren land becomes living terrain that shapes combat, offering cover, healing allies, and hindering foes. The smell of rain, soil, and blooming life overwhelms the senses, making it clear that nature has claimed dominion. Even after the magic fades, the plants remain as natural obstacles and proof of the caster’s will.', 'Life'),
  (752, 'skill-771eb7ac00b68fae2105af675a90d7c0ba08e44ff2c3cba782b47ef4c4a810c0', 'Eternal Bloom', 'spell', 3, 'INT', 'WIS', 'The caster strikes the ground with their will, and a colossal surge of life erupts outward. Flowers burst into bloom across barren stone, trees sprout where none stood before, and a shimmering emerald light radiates in all directions. Allies within the zone feel their wounds close, poisons unravel, and their spirits fortified with each pulse of vitality. Enemies caught inside find the very growth of nature turning against them—roots seize their ankles, their limbs are slowed, and the aura of life drains their strength. The battlefield itself transforms into a sanctuary and a prison: allies thrive while enemies are ensnared. Even when the magic fades, the greenery remains as a testament to the caster’s dominion.', 'Life'),
  (753, 'skill-061f2434f971f446faa1faa0de29cf8016bd8f6966cfd50580dd4c625d53cd80', 'Cycle of Rebirth', 'spell', 3, 'INT', 'WIS', 'The caster calls upon the primal rhythm of existence: life, death, and rebirth. A radiant sphere of golden-green light blossoms, filling the battlefield with the sound of heartbeats. Allies feel their wounds close and vitality return, while the bodies of the fallen stir—the spell suspends the finality of death itself. Those slain within the zone are temporarily restored to fighting form, bound by threads of borrowed life force, though the cost echoes through time. Enemies caught in the sphere feel their vitality siphoned away, their essence drawn into the cycle to empower the living. The spectacle is awe-inspiring: warriors rising from death’s edge, foes faltering as their strength is stolen, and the air heavy with the thrum of fate itself. Yet when the cycle ends, the balance demands payment—those revived must stabilize or perish once more.', 'Life'),
  (754, 'skill-da4237e0378d7c7e5d6cf3d148b64fee3eed299a6d2b4aae784cc3574a03195e', 'Genesis Dominion', 'spell', 3, 'INT', 'WIS', 'The caster unleashes the ultimate expression of life’s dominion, a miracle that transcends battle and reshapes reality itself. With a thunderous pulse, the battlefield blossoms into a living biome: towering trees erupt from stone, rivers of green light course through the ground, and the air fills with the scent of bloom and rebirth. Within this sanctum, allies feel their wounds knit closed instantly, their spirits bolstered, and even the dead rise once more, pulled back into the cycle. Enemies, however, feel their vitality stolen, their limbs bound by vines, and their senses drowned beneath the overwhelming weight of life’s surge. Time itself bends within the zone—death is delayed, wounds resist permanence, and the very concept of decay is suspended. When the dominion ends, the terrain remains forever altered: a lush forest born in the span of heartbeats, an eternal reminder of the caster’s mastery.', 'Life'),
  (755, 'skill-f61f534bf24cb550fc94d84afa9d0e310ee4c5411ae8dd21e4957af8db1de964', 'Negation', 'sphere', 2, 'INT', 'WIS', 'Negation is the sphere of undoing—canceling spells, disrupting enchantments, and halting magical effects mid-cast. It doesn’t create; it silences. Practitioners become guardians against the uncontrolled.', 'Spellcraft'),
  (756, 'skill-28001e548ed9147eb289bff064265a255b2d582be2b0f6e6a7f402630050fe20', 'Arcane Snuff', 'spell', 3, 'INT', 'WIS', 'A sharp gesture scatters sparks of unweaving energy, snuffing out a minor magical effect. The unraveling looks like ink dissolving in water, eating away at the glow of enchantment until it vanishes. This works best on small cantrips, wards, or simple utility spells.', 'Negation'),
  (757, 'skill-93401489b158a1c24d837659adccd2b0898d8c8fad30e768d1ef8014cfd82595', 'Detect Enchantment', 'spell', 3, 'INT', 'WIS', 'A shimmering ripple passes over an object as the caster studies it. Enchantments reveal themselves as faint runes or colored veils hovering over the surface. The caster gains a sense of whether the magic is beneficial, harmful, or neutral.', 'Negation'),
  (758, 'skill-fa63bc3b95478e176238bcb7254014e1aadb2d331823dd89e6f3d6825a5ed229', 'Unravel Spark', 'spell', 3, 'INT', 'WIS', 'The caster traces a quick sigil in the air and snaps their fingers, unraveling a single minor magical effect from a creature or object within reach. The effect gutters out in a shimmer of gray dust.', 'Negation'),
  (759, 'skill-0c23afda2dc506832934baebc617155762cc90645a284a35c09270b31da4d4dc', 'Dampen Aura', 'spell', 3, 'INT', 'WIS', 'With a slow exhale, the caster mutes the magical resonance of a creature or object. For a brief moment, its aura flickers and weakens, making detection more difficult and suppressing minor benefits of enchantments. A faint gray haze clings to the target during the effect.', 'Negation'),
  (760, 'skill-31f4981b81768d693368eb0ecf581570c137ef32aea37a8f33529485d5d257ec', 'Spell Shatter', 'spell', 3, 'INT', 'WIS', 'The caster projects a jagged pulse of black-white static at a foe, attempting to rip active magic apart. The energy arcs like cracking glass, snapping through ongoing protections or buffs. If the casting pushes against an unfamiliar weave, the strain can bite back.', 'Negation'),
  (761, 'skill-dd3b11dde8b937716e063a38609869c6b5d5f42aed7124ec31d15c5aca93fc06', 'Unweave Glyph', 'spell', 3, 'INT', 'WIS', 'The caster kneels and presses a hand over a rune or ward, pulling loose the threads of its power without triggering it. Lines fade like smoke in a draft as sigils collapse into inert marks. The work takes a focused moment, ideal for traps and seals.', 'Negation'),
  (762, 'skill-dcf711f870abdc7f50dc70ae15f9fb434eac9f3dff23616961bb4cf53641abac', 'Arcane Lockdown', 'spell', 3, 'INT', 'WIS', 'The caster slams their hand into the air, and a shimmering lattice of black-silver sigils cages the battlefield. Within this dome, all ongoing magical effects strain as if under pressure; wards sputter, summoned creatures flicker, and enchantments lose their grip. The effect is localized, forcing spellcasters to contend with a hostile zone of unraveling magic.', 'Negation'),
  (763, 'skill-b871fd283ad3ad0a47eb5a647beb1d015c9d95cab3c2777bb28e6ea5cf80d7d3', 'Mirror of Reversal', 'spell', 3, 'INT', 'WIS', 'With a cutting gesture, the caster conjures a polished obsidian mirror of crackling light. The next spell cast against them or an ally is caught, refracted, and hurled back at its originator. The mirror flashes once before shattering, its shards dissolving into motes of light.', 'Negation'),
  (764, 'skill-54a7554de92ab4076e92423b84fd9ce03638cdc26aa8b2cff820beec175e97a5', 'Seal of Silence', 'spell', 3, 'INT', 'WIS', 'The caster inscribes a glowing seal mid-air; once complete, it detonates in a hush that devours all sound and snuffs magical chants. Casters inside the radius find their words vanish, gestures falter, and spellwork collapses into stillness. The silence is oppressive, broken only when the seal fades.', 'Negation'),
  (765, 'skill-d77e4b347d5adc60bc167ebd5b32ccb5be5ac2717497836a9f7bb94511c20d27', 'Annihilation Field', 'spell', 3, 'INT', 'WIS', 'With a thunderous gesture, the caster tears open a roiling sphere of black static and jagged white arcs. Within its boundaries, all spells unravel—wards collapse, enchantments dissolve, conjured creatures falter, and protective barriers shred. The zone devours both ally and enemy magic, leaving raw silence where no spell can persist. The air hums like shattered glass vibrating in place, reality itself groaning under the negation.', 'Negation'),
  (766, 'skill-33a64ddfbdd7510311043928f5683705947ac557c0d29e422ec09a52cb33cc9a', 'Reflective Maelstrom', 'spell', 3, 'INT', 'WIS', 'The caster spreads both arms, spinning an immense whirl of mirrored shards and black light around themselves. For a short time, hostile spells that strike the maelstrom are caught, refracted, and flung outward in chaotic arcs. Some rebound on their originators, others scatter to random foes, tearing apart order itself. The storm roars with a thousand voices of half-cast spells, until it finally shatters in a cascade of broken energy.', 'Negation'),
  (767, 'skill-a2df2ca9a5cb3397229bc57a1fb2c2b3d6433c9bf8bdaa003d6668071114e6ad', 'Oblivion Veil', 'spell', 3, 'INT', 'WIS', 'The caster raises both arms and reality itself shudders. Black fractures crack open in the air, bleeding silence that swallows sound, color, and light. Within this vast shroud, all magic is unmade: wards collapse like sandcastles, enchantments are shredded to threads, conjured beings vanish screaming into void, and even ongoing spells of Grand Master tier falter beneath the unraveling weight. The Veil is not mere dispelling—it is *denial of the arcane’s existence*. The shroud spreads outward in a rolling wave of static silence, extinguishing magic wherever it passes. Both allies and enemies are stripped of their arcane power, left bare to steel and will alone. The air tastes of ash and stillness. When the Veil ends, the world does not immediately recover—magic takes minutes, even hours, to return to balance in the area. The spell is legendary, feared, and whispered of as a weapon that can unmake entire battlefields, kingdoms, or worlds if sustained.', 'Negation'),
  (768, 'skill-ae0facccf0a3723adefbdfe700c097b6c843dbfd06e5cd325602ec13b2361f8b', 'Soul', 'sphere', 2, 'INT', 'WIS', 'Soul magic interacts with the inner essence of living beings. It can strengthen willpower, reveal karmic echoes, or reach into the deepest layers of identity. This is a sacred magic—personal, powerful, and deeply felt.', 'Spellcraft'),
  (769, 'skill-a25cda5c317754a87556d2fdc33818defc2a4a4c866f8ddcf81bcfd291d32236', 'Soul’s Whisper', 'spell', 3, 'INT', 'WIS', 'The caster places a hand upon a creature or object and opens their inner senses. At its most basic, faint echoes of the soul can be felt—warmth, presence, and vitality—hinting at the unseen patterns that bind life to spirit.', 'Soul'),
  (770, 'skill-c89a3c8810d0f8e8a0284fde904269de4954ca9192345fb25fd47285639c7f98', 'Ancestral Aegis', 'spell', 3, 'INT', 'WIS', 'A faint halo of motes gathers at the caster’s brow, like dust caught in lamplight, then sinks into the skin with a comforting warmth. A whisper of remembered voices—ancestors, mentors, guardians—threads through the caster’s thoughts and steadies the breath. The world’s clamor softens; edges of panic round off; doubts lose their bite. On the battlefield this presents as poise under pressure: hands stop shaking, the heart stops racing, and grim determination replaces fear. The effect does not force bravery; it clarifies the will so it can choose. Subtle ripples in the soul make it harder for wandering spirits to probe or tag the caster with a quick reading. Tactically, it’s best triggered just before a charge, when enemy fright tricks or possession attempts are expected. It synergizes well with teams that rely on resolve under fire, buying a brief window to act cleanly. Old wardens taught it as a first defense: know yourself, then the enemy. The glow is barely visible unless one looks from the corner of an eye—and then it’s gone.', 'Soul'),
  (771, 'skill-a77086f038a2627a10f4cc4eb327d501d78fbb4dfaba626ec19f183162794281', 'Lifethread Gift', 'spell', 3, 'INT', 'WIS', 'A silver thread of light unwinds from the caster’s chest to their palm, pulsing with each heartbeat. On touch the filament leaps into the ally like a spark to tinder, and warmth floods bruised flesh and flagging spirit. The caster feels a brief tug—as if missing a step on a stair—then steadies as the transfer finishes. Wounds do not knit theatrically; they simply stop worsening, and color returns to the cheeks. In the scrum this is a swift triage, shoring up a friend who must not fall before the next exchange. Veterans learn to slide a hand along a forearm in passing, gifting strength without breaking stride. The rite is taboo for theft: it cannot rip life from the unwilling, only give freely. It is most efficient when the team rotates guard over the healer, letting quick touches keep the line intact. Soul schools teach it on day one with a simple rule—“Spend what you can stand.” The thread fades like breath on glass the moment the gift is given.', 'Soul'),
  (772, 'skill-4d3d5c5c6f2fd669c54eb397edbb15b7e09d0165696f6f6efdb6a5079f15317d', 'Echo of Emotion', 'spell', 3, 'INT', 'WIS', 'A pale shimmer flits across the caster’s eyes as their perception slips beyond the physical. Every heartbeat in the area becomes a drum, every surge of feeling a ripple against the skin. The caster perceives not thoughts, but emotional signatures—fear tightening like a fist, anger sparking like static, calm flowing like water. On the battlefield this allows instant reading of morale, revealing who is faltering, who is about to lash out, or where hidden malice waits. Outside of combat it can be used to gauge truthfulness or the general atmosphere of a crowd. The effect is not invasive—it is more like hearing the tone of a voice without knowing the words. Mystics describe it as “colors of the heart” bleeding briefly into sight. The air smells faintly of incense when cast, though no smoke burns.', 'Soul'),
  (773, 'skill-ee2bef6949be6105a0da452dd084ebea99c36eae1b4ce96490f44d4bb16aeb8d', 'Soul Bind', 'spell', 3, 'INT', 'WIS', 'Threads of pale silver light snake from the caster’s hand and lash around the target like ribbons caught in wind. The strands sink beneath the skin with a chill, anchoring the soul to its vessel and denying easy escape. The victim feels a sudden weight, as though an unseen hand is pressing them into place. Their movements drag, will feels tethered, and a sense of exposure creeps in as though the caster’s gaze reaches deeper than flesh. On the battlefield this halts quick retreats, prevents teleportation, or simply slows a foe long enough for allies to strike. The effect is not cruel by design—it was originally taught to prevent wayward spirits from fleeing before rites could be completed. To onlookers, the target appears wrapped in faint glowing threads that fade after a moment.', 'Soul'),
  (774, 'skill-c44a743e5412f4b853e8dd9de8599b891b7d9f29e3e32e506657466daed38a9d', 'Warden’s Lantern', 'spell', 3, 'INT', 'WIS', 'The caster raises a hand and conjures a ghostly lantern, its flame a cold white glow that reveals far more than light should. Shadows recoil unnaturally; hidden spirits are dragged into pale outline; invisible bindings are traced like spiderwebs in frost. Within the glow, allies feel safer, as if a quiet guardian watches over them. The lantern hovers just above the caster’s shoulder, moving as they move, and hums faintly with the sound of distant bells. On the battlefield it denies concealment tricks, unmasking cloaked foes or spirit-born threats. In social or investigative play it unmasks disguises of the soul, though not mundane masks. The glow fades after the round, leaving only a faint chill.', 'Soul'),
  (775, 'skill-4c970b7a2d93b556cb9216bac67ded6840ce7eb816b0074e0383e5f478b0d34e', 'Astral Chains', 'spell', 3, 'INT', 'WIS', 'Spectral chains burst from the caster’s hands, lashing out with an echoing rattle that vibrates in the bones. The chains are not physical—they bind the essence of a foe. When struck, the target feels the weight of entire lifetimes pressing down, dragging them into stillness. Ethereal shackles clamp around limbs and soul alike, glowing faintly with runic script. Onlookers see the victim slow as if time itself is reluctant to carry them forward. The battlefield shifts: one dangerous opponent is suddenly anchored, slowed, and exposed. The spell was first woven by temple guardians to hold possessed vessels until exorcisms could be attempted. Caster feels tugged at the wrists as if the chains are bidirectional, straining spirit against spirit.', 'Soul'),
  (776, 'skill-d578f5e559417b114b5d93bd4314f46498fbf98cf6258ce9503dd794aafecc60', 'Guardian Spirit', 'spell', 3, 'INT', 'WIS', 'The caster calls upon a spectral guardian, a tall shimmering figure that hovers protectively at their side. The guardian’s form is indistinct—some see a knight, others a robed ancestor, others a beast-totem—but its presence radiates unyielding defense. With a sweep of its arm or wing, it deflects incoming strikes; its mere aura dissuades hostile spirits from approaching. The guardian lasts only moments, but in that span it can turn aside a fatal blow or drive back dark entities. When it fades, its last glance carries silent encouragement, like a parent sending their child into the storm. In combat, allies cluster close, trusting the phantom bulwark. The caster, however, feels the weight: summoning a guardian demands opening one’s soul as anchor, leaving them subtly drained once it departs.', 'Soul'),
  (777, 'skill-29727072885506602c7e0dddb809c67a02ec0ba13c70d935f03440de0263dbf6', 'Astral Step', 'spell', 3, 'INT', 'WIS', 'The caster’s body flickers like a candle in wind, then splits into two forms—one remaining faintly visible, the other stepping through unseen corridors of soul-space. For an instant the caster feels stretched, like two notes of the same chord vibrating at once. Then, in a blink, they reappear yards away, leaving behind a fading after-image that bursts in a ripple of ghostly static. Onlookers gasp as the caster crosses impossible distance, circumventing barriers or repositioning behind foes. Though swift, it is not effortless: each step through the astral tears at the edges of one’s being, leaving a ghost-ache in marrow and mind. In lore, this spell is the first initiation into true astral travel, teaching soul mages how to slip sideways into realms between moments.', 'Soul'),
  (778, 'skill-0a3c957175d1c49e015e18d8ded0c59d1137ef50f4dbcf22e42217c450aa8031', 'Astral Maelstrom', 'spell', 3, 'INT', 'WIS', 'The caster exhales sharply, and the air warps into a spiraling vortex of pale light and shadow. Ethereal tendrils lash outward, seizing spirits and flesh alike, pulling them toward the churning center. Within the maelstrom, voices scream in forgotten tongues; fraG.O.Dents of broken dreams swirl like debris. The zone distorts movement and balance, dragging enemies together while slowing their actions. Allies feel a similar tug but are cushioned by faint wards if within the caster’s favor. Onlookers see the battlefield bend unnaturally, like a whirlpool in water made of ghostlight. This spell is dangerous even to its wielder—losing grip could pull their own soul into the tide.', 'Soul'),
  (779, 'skill-19d1ad0f6cd8a457b0b11a9489d0ca152f7d864790752223a5d2b8e9a23ea1df', 'Pale Legion', 'spell', 3, 'INT', 'WIS', 'The caster closes their eyes and breathes out a plume of frost‑white essence. From the mist rise spectral warriors, translucent figures armed with ethereal weapons, their forms flickering like memories of battles long past. They march in silence, forming a phalanx around the caster and their allies. Each strike of the legion chills the spirit of enemies, sapping resolve and body alike. The summoned host is not fully real—they are echoes—but their presence overwhelms foes with fear and pressure, forcing openings for the living to exploit. Allies gain strength and courage from the guardians, fighting harder under the gaze of the ancestral host. When the spell ends, the legion fades into drifting motes, saluting before dissolving into nothing.', 'Soul'),
  (780, 'skill-672634062d4319aab90bf0cad84224ad4d2d2f1a2af1a3f410c8cd8727114b6c', 'Eclipse of Eternity', 'spell', 3, 'INT', 'WIS', 'The caster’s eyes blacken as their soul flares outward, blotting the battlefield in a twilight dome of stillness. All sound warps into muffled echoes, colors fade to gray, and every creature feels their heartbeat thunder in their ears. Within the eclipse, souls are bared: phantoms of past deeds flicker around bodies, ancestral voices whisper in a dozen tongues, and mortality presses down like a weight. Enemy spirits find their anchors fraying; allies feel spectral hands at their shoulders, steadying them. The caster stands at the center, arms outstretched, threads of light and shadow stretching from their body into every creature in sight. The dome does not simply restrain or reveal—it judges, binding foes in place, bolstering allies, and threatening to pull the very essence of the unworthy into the void. Even when it ends, the battlefield feels hushed, as though the world itself pauses to recover from what it just witnessed.', 'Soul'),
  (781, 'skill-072168a7718b7c3eba3f03d0bcfb5d3d34d4d710763ad5866fe31df39d8d8160', 'Summoning', 'sphere', 2, 'INT', 'WIS', 'Summoning calls creatures, spirits, or constructs across space, time, or realms. Whether temporary allies or long-term bindings, it brings the beyond into the present. Summoners must balance force with control.', 'Spellcraft'),
  (782, 'skill-92b36d1c0ad3c6ca3726d7b17e8870fbd0f20112a4a1f17805accff190ec00df', 'Find Familiar', 'spell', 3, 'INT', 'WIS', 'A ritual of whispered names and a chalk‑marked circle calls forth a minor spirit in the guise of an animal companion. The familiar manifests with flickering eyes and a faint otherworldly hum, obeying simple commands and sharing quiet impressions with its summoner. It can deliver touch‑range spells and scout cautiously, but it is fragile and unwilling to engage in lethal violence unless the G.O.D. rules otherwise. Concentration keeps the bond taut; breaking it releases the spirit in a harmless puff of motes.', 'Summoning'),
  (783, 'skill-c98fce54836ddb26acbf1e41ecf6ce1fa0233145e7c33fc6337414809b6dfeae', 'Call Trinket', 'spell', 3, 'INT', 'WIS', 'The caster slips their hand through a fold in space and retrieves a small object they already own—belt, pouch, or pack—into their palm. The item arrives with a faint shimmer and settles as if it had always been there. Ideal for clutch moments when rummaging would cost too much time.', 'Summoning'),
  (784, 'skill-e05f447e065830e0ad4ea712019cdb40d0c80f9d6b034a613535a509a0e9faf6', 'Spirit Lantern', 'spell', 3, 'INT', 'WIS', 'The caster calls a gentle wisp from a neighboring plane, a palm‑sized mote that hovers at shoulder height and radiates steady light. It thrums softly, circling the caster and bobbing at points of interest with timid curiosity. While harmless, its presence is comforting and useful in darkness, provided the caster maintains focus.', 'Summoning'),
  (785, 'skill-102f937a708f24b21ef25c85b1696d2d27224961cc9af6e014b304c8203efcc5', 'Summon Pack Beast', 'spell', 3, 'INT', 'WIS', 'With a guttural call and a trace of planar energy, the caster summons a loyal but simple beast—a wolf, hound, or other medium animal—to fight or carry loads. The beast bursts into being with a shimmer of dust and growls at the caster’s foes. It obeys basic commands, vanishing when the spell ends. This spell shows how Target + Summon + Duration combine for battlefield utility.', 'Summoning'),
  (786, 'skill-a98fbe297478289bdba820aea8c3bc591cd81babfa9933f79d35b24ee8b9606c', 'Phalanx of Echoes', 'spell', 3, 'INT', 'WIS', 'The caster stomps the ground and ghostly soldiers march forth, semi-transparent echoes of ancient warriors. They form a loose wall, blocking passage and striking with spectral weapons. Though weak individually, together they harry enemies and shield allies. This demonstrates AoE + Summon + Shape synergy.', 'Summoning'),
  (787, 'skill-f7c927a143fc90a31e43e21de7840f5bf0039f6bb415e646e324d6a3a7e5e126', 'Retrieve from Beyond', 'spell', 3, 'INT', 'WIS', 'The caster reaches through a thin veil and draws an unattended object from afar. A book from a library shelf, a dropped weapon, or even a set of keys can be yanked into the caster’s hands. The air ripples as the object slides across space into the summoner’s grasp. This spell showcases Target + Summon + Spatial flavor.', 'Summoning'),
  (788, 'skill-86eedb7ed2c916e0c87c6ff2936c68f2854a4a5379b89e86e8003b43e0c96fb1', 'Summon Warband', 'spell', 3, 'INT', 'WIS', 'With a thunderous chant and the rending of unseen veils, a half-dozen spectral warriors march forth in disciplined formation. Each wields a shimmering weapon and shields allies in their ranks. Their arrival echoes with the clash of unseen battlefields. The warband provides a temporary fighting force, able to harry enemies and defend positions. This spell demonstrates how multi-target + Summon + Duration + modifiers showcase scaling armies.', 'Summoning'),
  (789, 'skill-2fe06ed7fd084ee0793d3fecc4862f3a3e8758dd1e2113f1c93ec9abc7bef7be', 'Obsidian Guardian', 'spell', 3, 'INT', 'WIS', 'By driving a shard of onyx into the earth, the caster summons forth a towering construct of stone and shadow. The guardian rises, broad-shouldered and immovable, its eyes glowing with runes of protection. This demonstrates Target + Summon Major + Control synergy.', 'Summoning'),
  (790, 'skill-2b37765c826ba0c9b06ae04563ff5592d2b4dab8576dff723981509c323afe27', 'Circle of Binding', 'spell', 3, 'INT', 'WIS', 'A glyph of glowing runes forms in a wide circle, dragging forth a struggling outsider. The creature claws and roars as glowing chains lash it to the circle’s edge. This demonstrates AoE container + Summon Major + Control + Shape.', 'Summoning'),
  (791, 'skill-077837ce5207211f2905e84adf1fde04c3f08c2d0da154182001511ca3266446', 'Concord of Ten Thousand', 'spell', 3, 'INT', 'WIS', 'Runes lattice the air as rifts crack open. A disciplined cohort marches in—summoned individually—while a concurrent battle‑aura rolls over the field. Allies feel the rhythm and move in unison; enemies stumble and are shoved back by shield‑pressure as the air itself thickens. This build explicitly separates the “army creation” (Target + Multi‑Target + Summon) from the “formation field” (AoE + Buff + Debuff + Spatial + nested Control), so readers can see the modular assembly.', 'Summoning'),
  (792, 'skill-21b95c9543849393de5d8031dd2912cac9c6345e9d861d9d24bf3a6bfcd7e020', 'Seal of the Eclipsed Gate', 'spell', 3, 'INT', 'WIS', 'A bi‑CHAomatic ring unfurls and a gate to twin planes yawns wide. Two opposed outsiders are pulled through to clash while a time‑drag bubble locks the battleground. Gravity sways, courage surges in allies, and foes feel their will slow. This layout shows outer Temporal/Spatial anchoring a Spatial zone, with separate Target containers for two major summons, plus a dedicated Control container that immobilizes both.', 'Summoning'),
  (793, 'skill-2f903e64027554318e07b697feea3015c9d45000dbe03dbc2b2c345fa3615346', 'Eternal Concord of Realms', 'spell', 3, 'INT', 'WIS', 'When this spell is cast, the battlefield itself becomes a convergence of planes. A monumental sigil ring burns into the ground, rising as a three-dimensional cube of glyph-lattices. Within the shimmering walls, armies stride forth: titanic guardians from one plane, spectral attendants from another, and shifting terrain drawn from both. Gravity flexes, the ground reshapes into ridged fortifications, and pact-threads lash every summoned to the caster’s command. Enemies who step into the cube are slowed and staggered by time-drag while allies feel a surge of courage and speed. At the caster’s word, the sigil flares again, banishing a chosen cadre of enemies in chains of light. The construct endures for the duration, undeniable proof that summoning is the art of weaving containers, not just opening doors.', 'Summoning'),
  (794, 'skill-e72adc3233986587dd0a11d466c8d45cf4030f596f5c8ce6b47b301ad4aa5fe4', 'Time & Space', 'sphere', 2, 'INT', 'WIS', 'Time & Space magic manipulates flow, position, and perception. It may accelerate or delay actions, fold distances, or create pockets of stillness. This is a delicate sphere—one misstep can echo far beyond the present.', 'Spellcraft'),
  (795, 'skill-3e4ebc87785d0a9aae2412f1d1101bb476f5db95b2434f559ee8aaafdda04b9b', 'Momentary Step', 'spell', 3, 'INT', 'WIS', 'The caster flickers through space in the blink of an eye, stepping up to 15 feet to a visible space. Air ripples where they stood and snaps where they arrive, a faint echo lagging half a heartbeat behind. Perfect for slipping a grab, dodging into cover, or threading through tight terrain without provoking pursuit.', 'Time & Space'),
  (796, 'skill-e584c215dc170a7145462749ea5aee81d12364b410e7db085d40a6fafb146865', 'Temporal Glimpse', 'spell', 3, 'INT', 'WIS', 'The caster catches a flicker of the immediate future, as though a page from time briefly turned ahead. This allows them to adjust their reaction at the last moment, granting an edge against danger. The glimpse lasts only a heartbeat, fading before it can cause paradox.', 'Time & Space'),
  (797, 'skill-158f9d9e29e68f87201a77f6bee453c8c5942a19a4f050a2e670ef37ecc0d191', 'Slow Tether', 'spell', 3, 'INT', 'WIS', 'With a subtle gesture, the caster tugs at the flow of time around a single target. The victim’s movements feel heavy, their steps dragging as though they wade through water. Though brief, the effect can tip the scales in fast-paced combat.', 'Time & Space'),
  (798, 'skill-dfdb97c7287979b9e4554299ae9932a3fbd8ebfc374c854c9676c519929c7bdb', 'Blink Step', 'spell', 3, 'INT', 'WIS', 'The caster vanishes in a flicker of warped light and reappears at a chosen spot within 60 ft. Air snaps with displaced sound, and afterimages linger for a heartbeat. Useful for bypassing obstacles, dodging strikes, or slipping through gaps mid-battle.', 'Time & Space'),
  (799, 'skill-9d0083f697b42b71deafa64ecb341a2fe543417f8566a7d3f6392e2da786a620', 'Stasis Snare', 'spell', 3, 'INT', 'WIS', 'With a twisting gesture, the caster slows a foe’s time-flow, binding them as if trapped in syrupy air. Their limbs drag, thoughts stumble, and reaction falters. The snare fades after a round, but in that window, allies can strike freely.', 'Time & Space'),
  (800, 'skill-39880c9727d9d0eed64ff5f110531cc4ade4cd00d8def2fea907d2ec9476d167', 'Spatial Anchor', 'spell', 3, 'INT', 'WIS', 'The caster tears open a faint ripple in space and chains their foe to it. The target feels an invisible weight, like gravity fixed them in place. They cannot easily flee or be moved, pinned by unseen bonds of distance itself.', 'Time & Space'),
  (801, 'skill-7aeb624944114d84e8ea4da075195d1a24d64874d42ba75d25d7dbce1410fc2d', 'Worldstride', 'spell', 3, 'INT', 'WIS', 'The caster collapses their presence into a singular point, reemerging anywhere in the world within the same heartbeat. The transition is silent but marked by a faint smell of ozone and a shimmer like heat waves. Though instantaneous, the journey passes through dangerous void-currents—failed attempts can scatter pieces of the caster across the fabric of reality. This is the iconic “true teleport,” granting unmatched strategic freedom.', 'Time & Space'),
  (802, 'skill-830880db386529175e3214b637602a93128526f826ee07f872e5ea080cec7dd8', 'CHAono-Burst', 'spell', 3, 'INT', 'WIS', 'With a thunderous pulse, the caster creates a temporal bubble that distorts the speed of all caught within. Allies feel their actions accelerate, blades and spells blurring; enemies slow, staggering as though time is syrup. Within this zone, battles resolve in seconds that stretch like hours.', 'Time & Space'),
  (803, 'skill-de9109cc630b4829d3f44ffa9f8be244608727954ea6a7e97a66363aac567307', 'Spatial Rend', 'spell', 3, 'INT', 'WIS', 'The caster tears a jagged wound in space, creating a rift of crushing pressure. The distortion drags foes inward, bending light and air around it like a collapsing star. Those trapped near its edge feel bones stretch and weapons twist, while the center threatens annihilation.', 'Time & Space'),
  (804, 'skill-c974e17b8e7321ce8c12983de3d0ed4a289821f579bbe0925b0181a4bc8e8d80', 'Gate', 'spell', 3, 'INT', 'WIS', 'The caster rends reality into a stable shimmering archway, connecting two distant points. Through it, armies can march, caravans can pass, and entire cities can exchange goods in moments. The gate is not without peril: void echoes leak around its edge, and improper anchoring risks flinging travelers into the abyss between places. While open, the portal is a glaring beacon of power that distorts air, gravity, and magic around it.', 'Time & Space'),
  (805, 'skill-f56975e81ce6487f9649728c0f0cad519c9a6003520181479430adc8f8a87c55', 'CHAono-Stasis Field', 'spell', 3, 'INT', 'WIS', 'The caster freezes an entire battlefield in a shimmering dome of suspended time. Arrows halt in midair, flames pause as statues of fire, and creatures stand trapped in half-motion. Inside, only the caster (and optionally chosen allies) can still act, moving between frozen foes like phantoms through a painting. When the field collapses, all delayed events complete in an instant.', 'Time & Space'),
  (806, 'skill-605a1ca4e73556f36f6a2739b28759fc36acd350133eb4941ba8c3b010da6818', 'Infinite Labyrinth', 'spell', 3, 'INT', 'WIS', 'With a sweeping gesture, the caster folds reality into an endless maze of doors, corridors, and mirrored halls. Space twists into recursive geometry: enemies turn corners and find themselves back where they started, allies are scattered into parallel passages, and entire armies can vanish into the shifting construct. Distances stretch infinitely; even a single step may take hours, while a mile collapses into an arm’s reach. The labyrinth persists as a living paradox until it unravels, often leaving geography scarred and minds fractured. Villages may find themselves displaced miles away, fortresses may be turned inside-out, and those who wandered within may emerge days older or younger, or not at all.', 'Time & Space'),
  (807, 'skill-a0569b6bfb1f6aaf0be66e17715e7af83823d3fc7babc5fac833bc0f8950f9bc', 'Transmutation', 'sphere', 2, 'INT', 'WIS', 'Transmutation alters the inherent nature of things. Lead becomes gold, water becomes gas, weakness becomes strength. This is the magic of change—refined, radical, or reversible.', 'Spellcraft'),
  (808, 'skill-8e2959d3436ad255960ff44c7e509b3792e3de79a92682801896420c92c4c972', 'Mend Stone', 'spell', 3, 'INT', 'WIS', 'The caster runs their hand across cracked stone, and the fraG.O.Dents fuse back together with a faint earthen glow. Chips and fractures vanish, leaving the surface restored to functional strength. This spell is often used for quick battlefield repairs or sealing breaches in walls.', 'Transmutation'),
  (809, 'skill-02748d4d5a80e0a8a28627d0afe2fe241522e17d83f1294e4cb6803ac36aede1', 'Purify Water', 'spell', 3, 'INT', 'WIS', 'By dipping a hand into murky water, the caster draws out impurities which condense into a faint cloud before dissolving. The liquid clears instantly, becoming safe to drink. A classic spell for survivalists and travelers alike.', 'Transmutation'),
  (810, 'skill-30aa6a01ec77d04b93bcc9d5793bf3858ee63ad22fa4f0b335f7c829a1e751cf', 'Resize Trinket', 'spell', 3, 'INT', 'WIS', 'A small trinket glows with shifting light as the caster wills it larger or smaller. The object changes size temporarily, useful for concealment, smuggling, or convenience.', 'Transmutation'),
  (811, 'skill-cf3c924fffd2437968da2c822ee8f0c88f110a8ad0dd0f48807094a3c35ff3d3', 'Shape Metal', 'spell', 3, 'INT', 'WIS', 'The caster traces heatless sigils and the worked metal ripples like wax before settling into a new, serviceable form. Bars bend, plates seal, and crude hinges appear in moments. The effect is fast field‑craft, not master smithing; edges dull, tolerances are rough, and intricate mechanisms won’t survive. Sparks dance across the surface as stresses redistribute, then fade when the form locks.', 'Transmutation'),
  (812, 'skill-5d3418c3744d4a0bdc9270fee2500e2a85c63ce216f42b63d368d54e2beb503e', 'Enlarge Object', 'spell', 3, 'INT', 'WIS', 'With a firm command, a mundane object swells to twice its size and weight. Shields become bulwarks, ladders bridge gaps, and tools gain brute leverage at the cost of finesse. The transformation glows briefly, then stabilizes for a short time before snapping back to normal.', 'Transmutation'),
  (813, 'skill-756d9d789c93bddb2172a06aa3ff3b28cf02dfa76940ccc489ef006d2c152a9c', 'Stone to Mud', 'spell', 3, 'INT', 'WIS', 'Stone darkens, slumps, and collapses into heavy mud under the caster’s touch. Walls sag, flagstones bog, and solid cover turns to a sucking mire in an instant. The created mud is mundane and remains unless otherwise altered by the scene.', 'Transmutation'),
  (814, 'skill-b6cd480c3fb5793352cd2fb80d7348a36d15ade594e00dc6ed6bcb4e19d1099b', 'Forgeheart Wall', 'spell', 3, 'INT', 'WIS', 'The caster slams their hands into the ground, forcing stone to surge up and harden into gleaming alloy. The wall hums with metallic resonance, shielding allies and reshaping the battlefield. Sparks and heat flare as mundane rock becomes a transmuted barrier, persisting until destroyed or dissipated.', 'Transmutation'),
  (815, 'skill-bb661b612515a47a5c4ddb7d429b5c3149b9bc64cfe8b3d89b931f2bb705a705', 'Chimeric Fusion', 'spell', 3, 'INT', 'WIS', 'By binding two objects together, the caster fuses their essences into a hybrid form. A sword merges with a shield to become a cleaving guard; stone melds with wood into rigid planks. The union lasts only briefly, after which both items warp or splinter under the strain.', 'Transmutation'),
  (816, 'skill-9c7c1899fa94b023e704e3ae8e0a21e8fd152723185b7a56463a1f20cf510661', 'Mass Resize', 'spell', 3, 'INT', 'WIS', 'With a sweeping gesture, the caster alters scale itself. Weapons grow absurdly large or comically small, ladders stretch into bridges, and crates shrink into handheld bundles. The battlefield bends as proportions rebel against natural law.', 'Transmutation'),
  (817, 'skill-2dd137277ae4a86d415731c5f6100f44e2874e6f2c335a536976ae2f2d9e1240', 'Worldshaper’s Maw', 'spell', 3, 'INT', 'WIS', 'With a violent roar, the caster rends the battlefield itself. Stone liquefies, soil folds inward, and a jagged pit yawns open. Weapons and armor caught within warp and twist, their integrity failing. The area becomes an unstable zone where earth and matter ripple as if alive, threatening to drag all into the collapse.', 'Transmutation'),
  (818, 'skill-31f56b175348b25bed5367f67bdeeafad21255e5a4f40125bc8a3e709f2b0bdc', 'Eternal Alloy', 'spell', 3, 'INT', 'WIS', 'The caster draws disparate elements together into a single indestructible form. Stone, wood, iron, and crystal fuse into an everlasting alloy that defies time. Weapons forged in the zone gain mythical hardness; walls reforged cannot be broken by mortal strength. The spell showcases true mastery of matter’s essence, creating material outside normal physics.', 'Transmutation'),
  (819, 'skill-757409625101d4905e5c53c11cfdf9113ca254d2187a857a69920c8d7c925512', 'Genesis Transmutation', 'spell', 3, 'INT', 'WIS', 'At the pinnacle of alchemy, the caster becomes architect of reality itself. The battlefield trembles as stone flows like rivers, metals fuse into new alloys, and forests bloom or petrify in moments. Entire districts can be reshaped—mountains flattened into plains, deserts turned into fertile valleys, rivers redirected in their courses. The spell is not creation ex nihilo, but absolute reconstitution: what exists is rewritten into a new form. The effort shakes both the caster and the land, for such transformations echo beyond the moment of casting.', 'Transmutation'),
  (820, 'skill-4b7e172afd07683e8e12fd8bea360920535010006a497822d67568dbd26bc043', 'Transformation', 'sphere', 2, 'INT', 'WIS', 'Transformation reshapes form without altering substance. Flesh turns to fur, limbs become wings, size expands or contracts. It’s the sphere of self-reinvention and adaptive physicality.', 'Spellcraft'),
  (821, 'skill-f5142e2a7f291fa35f09d6287116cf20b2b469ec9bb3f4f3419913ba20b1319a', 'Quickshift: Webbed Grip', 'spell', 3, 'INT', 'WIS', 'Grants subtle webbing between fingers for temporary swim/climb aid. Appears as faint aquatic lineage and fades quickly.', 'Transformation'),
  (822, 'skill-aa7c02acdda3e13d942a4a654411411df4aa47135d5ff72008ef2342af004cc0', 'Skin of Scales (Lesser)', 'spell', 3, 'INT', 'WIS', 'Faint scales ripple over skin, granting momentary resilience. Subtle sheen, effective vs. cuts for one combat step.', 'Transformation'),
  (823, 'skill-a2f35f7cae7c41c45dbeff31482fa12063b5722ca14a99c9c49ee9286f2e0d3d', 'Nocturne Pupils', 'spell', 3, 'INT', 'WIS', 'Eyes shift to slitted nocturnal form, enhancing low-light sight but impairing bright vision.', 'Transformation'),
  (824, 'skill-254ede6df099dea8caabf915b22b3f5dea6ce0b5cce5d5da6e897ad0833cc6ca', 'Gills of the Shorefolk', 'spell', 3, 'INT', 'WIS', 'Throat splits lightly along the sides with faint frills that filter water. A bubbling inhale in the river becomes oxygen-rich breath. The skin darkens to damp hues while in use. Perfect for short-term underwater scouting or ambush setups.', 'Transformation'),
  (825, 'skill-5cac2e87d1dc2dcd3ed902691e5fee71c674a99a890afc8bc394b6dc7e7c2e29', 'Chameleon Veil', 'spell', 3, 'INT', 'WIS', 'Skin ripples with shifting piG.O.Dent, echoing the colors of walls, brush, or stone. To the eye the caster melts into their surroundings, though motion may still betray them. The body feels slick, like standing in a shadow that clings.', 'Transformation'),
  (826, 'skill-60cbe868e4c5dae86aeffbc6b6829790befe734cb863e0fdfd20aae2bb03827d', 'Beast’s Limb', 'spell', 3, 'INT', 'WIS', 'One of the caster’s arms bulges and shifts, bones elongating, nails sharpening into claws. Strength surges through the altered limb, muscles coiling with animal force. The arm feels alien but powerful.', 'Transformation'),
  (827, 'skill-f999369b1b03f32bb47e2fbbbdcfe56bad52e7664b06469a64491cfae792d7e5', 'Wings of the Raptor', 'spell', 3, 'INT', 'WIS', 'From the caster’s back burst broad pinions of sinew and feather. Each beat stirs air with heavy gusts, carrying them skyward with instinctive precision. To onlookers, the transformation is awe-striking, a sudden declaration of predatory dominion. In combat it allows flight above walls and foes, changing the battlefield into three dimensions.', 'Transformation'),
  (828, 'skill-433fec865fe06bec527d9e0fb1a69a2bcc5a29ae318cf4b1b71343817a448332', 'Packform Shift', 'spell', 3, 'INT', 'WIS', 'Several allies sprout lean muscle and sharp canines, their frames twitching with bestial energy. Their eyes glow with the same primal hue, their unity undeniable. The battlefield feels suddenly crowded with predators hunting as one.', 'Transformation'),
  (829, 'skill-ce0d213eccbced907f9ce9fc8ca34d8147584a9c333c15b88489cb29bd936c18', 'Fleshbind Curse', 'spell', 3, 'INT', 'WIS', 'With a guttural word, the foe’s limbs twist inward, their body reshaping against their will. Muscles knot, joints lock, and for a moment they are trapped in a body that betrays them. The effect is grotesque but short-lived, leaving lingering ache when it ends.', 'Transformation'),
  (830, 'skill-c6e3d545927aa265d609af23b5a3e99407a4ae7a70e2a0d237cc8581d751ed59', 'Avatar of Chimera', 'spell', 3, 'INT', 'WIS', 'Caster’s body tears and reforms, merging aspects of lion, serpent, and eagle into a terrifying hybrid. A mane bristles, scales plate across skin, and taloned wings unfurl with brutal majesty. Every movement is accompanied by a chorus of alien growls and shrieks. On the battlefield, this is both empowerment and intimidation: claws rend, wings buffet, tail lashes, and enemies falter before the monstrosity.', 'Transformation'),
  (831, 'skill-ba6a5a08a514c080f97c7d64d1df76b2fea05b3eb062cdd3d9a9b4c1c6bdba63', 'Plagueform Wave', 'spell', 3, 'INT', 'WIS', 'From the caster’s outstretched palm bursts a ripple of mutagenic force, spreading like distorted heatwaves. Flesh in the wave contorts: enemies twist into weakened, brittle forms, while allies briefly harden and grow resilient. To observers, the effect is horrific — a tide of simultaneous empowerment and decay across the battlefield. It leaves an aftertaste of dread even after the shapes fade.', 'Transformation'),
  (832, 'skill-a8b6ff76ba20152099b27b715258c4439f3c65879175ef270c572ece1654c169', 'Genesis Metamorphosis', 'spell', 3, 'INT', 'WIS', 'The caster becomes the axis of a living storm, radiating waves of rewriting force. Across a vast radius, allies erupt into perfected hybrid forms—gills, wings, claws, armored hides—each tailored instinctively to their needs. Enemies caught within the wave convulse, bodies betraying them as limbs twist, senses fail, and vitality drains away. Terrain itself grows warped: trees sprout flesh-like vines, stone ripples as if breathing, rivers teem with hybrid fish. The battlefield is transformed into a nightmare of shifting biology. This spell is legend: where it falls, tales of gods reborn in flesh and terror are whispered for centuries.', 'Transformation'),
  (833, 'skill-0f4168490e38b8447e11ba4bd656aa11b925bd22af30bac464bc153fdb608501', 'Water', 'sphere', 2, 'INT', 'WIS', 'Water magic embodies flow, pressure, and adaptability. It may cleanse, crush, or conceal. Practitioners learn to harness water’s many forms—vapor, ice, and tide alike.', 'Spellcraft'),
  (834, 'skill-918582355db6a52b94021559c8bf2a6878921bb4305ed17e4e3daa7d275648d7', 'Aqua Lash', 'spell', 3, 'INT', 'WIS', 'A crisp ribbon of water coils from the caster’s hand and snaps forward with a clean, cutting strike. The impact stings and splashes, dousing embers and leaving a cool mist in the air. Simple and efficient, it’s a starter technique that scales with the practitioner’s growing command of water and storm.', 'Water'),
  (835, 'skill-8a6faedb245d0508cc52684cfa3b263c5dc1a143018d2dee3af08cc02694e3d5', 'Ripple Shot', 'spell', 3, 'INT', 'WIS', 'A bead of water swells at the caster’s fingertip, clear and sharp as glass. With a flick, it shoots forward in a straight line, whistling faintly as it cuts the air. On impact, the droplet bursts in a splash that stings flesh and dampens armor, leaving slick trails where it strikes. While minor in force, its precision and speed echo the inevitability of ripples spreading across a still pond.', 'Water'),
  (836, 'skill-45b0edf3c0359a88a17e62f9e64c52f5bac52c3ae304bba0e1e0505666094380', 'Soothing Stream', 'spell', 3, 'INT', 'WIS', 'The caster channels a thin stream of cool water over a wound, the liquid glowing faintly as it closes cuts and restores vitality. The soothing stream leaves behind a feeling of calm renewal, though it requires the caster’s steady hand to maintain focus.', 'Water'),
  (837, 'skill-87a4a57fe373f71b21b995367c1aef213342b73441c5a0156c7cbc3f481494bb', 'Tide Push', 'spell', 3, 'INT', 'WIS', 'With a sweeping gesture, the caster conjures a sudden surge of water in a broad cone. The tide crashes forward like a small wave, striking all caught in its path with surprising force. Enemies are shoved back, footing is drenched, and light objects scatter in the spray. Though lacking raw damage, the sheer momentum of water creates space and disrupts enemy formations.', 'Water'),
  (838, 'skill-181963deceaf4503c82cca6a465901a666b4f6036866ac3c550d3f2c87eb3f51', 'Charged Grasp', 'spell', 3, 'INT', 'WIS', 'The caster channels water’s conductivity, charging their hand with crackling energy. Upon contact, a jolt of lightning arcs into the target, coursing along moisture and metal with violent precision. The strike seizes muscles, shocks nerves, and can arc faintly into adjacent water sources. Though risky to use in melee, its raw electrical surge embodies the dangerous synergy between water and storm.', 'Water'),
  (839, 'skill-c90dbaebeb177a647e8161d96c9e67efdf9a2250c9e13a7a6dbf629a2ff5e78f', 'Bubble Veil', 'spell', 3, 'INT', 'WIS', 'The caster surrounds themselves in a thin veil of swirling water bubbles. Each droplet refracts incoming blows, scattering force and dispersing energy like ripples through a pond. The veil does not block attacks entirely, but it softens the impact of weapons and dampens fire, lightning, or other elemental strikes. With focus, the caster maintains the shimmering barrier, its surface endlessly flowing to absorb punishment.', 'Water'),
  (840, 'skill-201303dd5096e0e377f26a0730ee711ecc3fc34ec006876f62eb345e5116589c', 'Riptide Grasp', 'spell', 3, 'INT', 'WIS', 'The caster conjures a surge of water shaped like grasping tendrils, which whip outward to seize a foe. The torrent coils around their body, striking with bruising force before constricting them in place. Each moment of resistance only tightens the watery grip, dragging the victim down as though drowning in an invisible current.', 'Water'),
  (841, 'skill-cf925bf86a1d0644fba1a246c63fa462227fcfadcd5ac92ba36eb1df0621e88d', 'Stormcall Surge', 'spell', 3, 'INT', 'WIS', 'A swirling storm node manifests at the chosen point, a sphere of roaring wind and crackling arcs. Lightning lashes outward at everything within its reach, searing flesh and metal alike. The very air thickens with pressure, movement falters as though wading through a tempest, and sound is muffled by the roar of static. The spell teeters on the edge of control — one slip, and the storm may turn on its master.', 'Water'),
  (842, 'skill-7fbaf71f2920f5e336d8f410efb34156010cfa92f60944661bd827bb0e7694c7', 'Tide Wall', 'spell', 3, 'INT', 'WIS', 'The caster raises a surging wall of water that roars up like a tidal barrier. Projectiles slam into it only to be caught and dragged downward, their momentum swallowed. Fire gutters and dies as the wall steams, its volume absorbing the heat. For the spell’s brief existence, allies can rally behind its cover, fighting as if shielded by the sea itself.', 'Water'),
  (843, 'skill-ca4ea50c3d07f61a021a3cefb62413d1c3dfa8f3ab74e2e6166a141987b74a78', 'Maelstrom', 'spell', 3, 'INT', 'WIS', 'The caster summons a roaring vortex of water and distorted space. The swirling maelstrom drags everything within its reach toward the center, battering victims with crushing currents. The pull is irresistible, and even the air warps within, making escape sluggish and clumsy. The vortex threatens to consume friend and foe alike, and without firm focus, even the caster may be swept into its grasp.', 'Water'),
  (844, 'skill-4f8e878f349cc95aa388888a304d84ba7a858abba35054dfc152b485bf7980bb', 'Tempest Crown', 'spell', 3, 'INT', 'WIS', 'The caster becomes the eye of a raging storm, lightning crackling outward in a halo of electrified rain and warped air. Foes near the caster feel their movements sluggish, their strikes unsteady, and bolts of lightning lash them without warning. Allies within the storm’s heart are shielded by surging waves of force, though the caster risks being caught in the overload of their own tempest.', 'Water'),
  (845, 'skill-664e6afbc490bcf86ffed73be3d0beda68f3479d91bbe7fc30db4f8e08ff18db', 'Leviathan’s Awakening', 'spell', 3, 'INT', 'WIS', 'The caster calls forth the Leviathan — not a creature, but a world-shaking embodiment of water’s wrath. A towering avatar of surging tides erupts, its body churning with lightning arcs and warped space. Within its massive form, time stutters: movements freeze mid-stroke, voices drown in silence. Tentacles of current and flood lash outward, sweeping foes from their feet, restraining them in suffocating torrents. At its core, those seized by the Leviathan are pulled into a watery void — banished beyond reality to drown in silence until the spell ends. Allies quake, the land itself buckles, and even the caster risks being consumed by the ancient tide they dared awaken.', 'Water'),
  (846, 'skill-9b58e68145a79ca0e19957f3e5c88fd92ff2e28a7bd09ed30ee365fc4f9aafe0', 'Wind', 'sphere', 2, 'INT', 'WIS', 'Wind magic channels movement, breath, and directional force. It guides arrows, lifts voices, and carries storms. Wind is both freedom and fury, guided by precision or set loose with abandon.', 'Spellcraft'),
  (847, 'skill-4ddf37291f945db2ede035ae91b25eb0f19547c7e85f5bc3c23d893ab38ed2b5', 'Gust of Renewal', 'spell', 3, 'INT', 'WIS', 'A focused burst of air surges outward from the caster, shoving a target back and clearing the immediate space of smoke or dust. Though minor at first, the spell grows with the caster’s command of wind, evolving from small shoves into sweeping gales that can topple armies.', 'Wind'),
  (848, 'skill-be2454da013602a13c67bbad97161410499bb49416de38f7e6d00a05d8cae17d', 'Cutting Draft', 'spell', 3, 'INT', 'WIS', 'A sharp hiss splits the air as the caster flicks their hand, sending a razor-thin current of compressed wind toward a foe. The draft slices flesh and cloth with invisible precision, leaving shallow cuts. In combat it’s a light, quick strike to sting and distract; outside battle it can part rope, banners, or parchment with effortless neatness. While dangerous, the force lacks depth—armor and stone remain untouched.', 'Wind'),
  (849, 'skill-25b02a04f1341d19b9a6ba8bcb06b6532a934753c4fdbc39bcf5b6150f5daf9e', 'Air Needle', 'spell', 3, 'INT', 'WIS', 'A pin-thin filament of compressed air snaps from the caster’s hand with a soft hiss. It slices skin and cloth, leaving a sting more felt than seen. In battle it’s a precise poke to draw blood; in the field it cleanly parts rope or parchment. The magic fades the instant the pressure is released.', 'Wind'),
  (850, 'skill-4408334b4a68474b6e3719350b1e7f88d8a7670f36916052e37f8b7c7ffd8b9a', 'Suffocating Grasp', 'spell', 3, 'INT', 'WIS', 'The caster clenches their hand, and the air within a foe’s lungs vanishes in an instant. Victims clutch at their chest as breath fails them, leaving them staggered and terrified. Though brief, the spell disrupts combat rhythm and can decide a duel in seconds. In lore, wind mages call this the “Grasp of the Airless Hand.”', 'Wind'),
  (851, 'skill-013cc12ff51d7738279e96f1308e36989ae9928413527ddd315cc0e9c5e3eaed', 'Wind Step', 'spell', 3, 'INT', 'WIS', 'Wind gathers around the caster’s legs and chest, lifting them in a sudden burst. The mage is carried forward on a compressed current, surging across the battlefield with startling speed. To others it looks like a blur of displaced air, not disappearance—an agile sprint made supernatural by elemental force. In lore, duelists spoke of Wind Steppers as those who never stood where the blade struck.', 'Wind'),
  (852, 'skill-eebd8ca7dbedc7895f5fb43c41c650681f6923e725a4545a1c67b8dd883363c3', 'Whispering Zephyr', 'spell', 3, 'INT', 'WIS', 'The caster breathes a word into the air, and the breeze carries it to another within range. The voice is heard as though whispered directly at the target’s ear, clear and unmistakable. In combat this allows silent coordination; in lore, wind messengers were prized among spies and lovers alike.', 'Wind'),
  (853, 'skill-ab0a9cb16469bb4f27ba511769e0051fd3589c726988cd9419606cf4254f2445', 'Cyclone Prison', 'spell', 3, 'INT', 'WIS', 'Air erupts into a towering spiral, enclosing enemies in a shrieking vortex. The cyclone drags them inward, battering with debris and pressure. On the battlefield it isolates groups, cutting them off from allies while whittling them down. In lore, Wind Masters are said to “build cages from breath itself.”', 'Wind'),
  (854, 'skill-a8f9e4220a958dd5263ffa48554595876ba08d8422d7163835635c16692c1bb0', 'Suffocating Dome', 'spell', 3, 'INT', 'WIS', 'Air rushes outward with a sudden roar, then vanishes into a dead hush as the caster forms a dome of stillness. Inside, the very breath is stolen: lungs burn, voices choke silent, and flames gutter out. Soldiers stagger and claw for air, their cries muted by the weight of emptiness. To generals, it is a weapon of terror; to sages, the “Silent Glass,” proof that even wind can become absence.', 'Wind'),
  (855, 'skill-2318c00c9670f8a2d826d3bc7e2684840c5b80a650477d669b8cbcaf450af26b', 'Tempest Barrage', 'spell', 3, 'INT', 'WIS', 'The caster summons a roaring gale threaded with lightning, hurling arcs of air blades and storm bolts across the battlefield. Foes are slashed, knocked prone, and their morale falters in the cacophony. In story, such storms are omens of gods stirring.', 'Wind'),
  (856, 'skill-5869e65eb0e37c862bb343eb6a02f97a0b87f768d68f535b3e10e9582d5425ed', 'Storm Nexus', 'spell', 3, 'INT', 'WIS', 'Dark clouds coil overhead as a roaring cyclone forms, crackling with lightning. Within its sphere, winds howl with shredding force, hurling foes to the ground while bolts arc wildly. The battlefield becomes a maelstrom of fury: sight obscured, movement crippled, and even the caster risks being caught in the chaos. In lore, it is said that summoning the Nexus calls the attention of storm gods themselves.', 'Wind'),
  (857, 'skill-42f00489a0d74a49d9753e325b98429506f14c45a1c7050359060d43617200b1', 'Worldstorm', 'spell', 3, 'INT', 'WIS', 'With a sky-shattering roar, the mage tears open the heavens. A rift in the firmament births cyclones, lightning, and sheets of rain. Yet the true horror is not the damage—it is the reshaping of the world itself: forests flattened, rivers redirected, and battlegrounds unrecognizable. Armies vanish in the maelstrom, while legends speak of entire kingdoms scarred forever by a single invocation.', 'Wind'),
  (858, 'skill-ef1b36fb0642930a6a0da6186174d279b48cd6bdb99d3a75842cf21122f34bce', 'Clairsentience', 'discipline', 2, 'WIS', NULL, 'Clairsentience expands perception beyond normal senses. It allows the user to detect presences, gain insight through intuition, or see what others cannot. This discipline doesn’t guess—it knows.', 'Psionic Focus'),
  (859, 'skill-4d254f8c5b9dc5ba3736fce930bd3baed0bb28bfbd8bcbf9aa833975d6384ebf', 'Object Echo', 'psionic skill', 3, 'WIS', NULL, 'By brushing their hand across an object, the psion glimpses faint echoes of its most recent interactions. Fleeting impressions of touch, emotion, or use bleed into the caster’s awareness—enough to sense who last handled the object or the strongest emotion tied to it.', 'Clairsentience'),
  (860, 'skill-a4c08023a0d3d13e44017bdf0cb1ca67753650eb75a12b96fc91dafde25d7d2c', 'Danger Sense', 'psionic skill', 3, 'WIS', NULL, 'A sudden surge of awareness heightens the psion’s instincts. Subtle shifts—creaking boards, held breath, hostile intent—flare in the mind, letting the psion react a beat ahead of danger.', 'Clairsentience'),
  (861, 'skill-f1d0efff5c6b63eb2c6965eaa5b8257f410721324c61898669b9a05735518262', 'Aura Glimpse', 'psionic skill', 3, 'WIS', NULL, 'The psion narrows their focus upon a living aura and, for a heartbeat, perceives the colors and ripples of surface emotion and intent—truths that flicker just beneath the mask.', 'Clairsentience'),
  (862, 'skill-6603a466fec65c137ebf5c335a35b1f57e555094b8dab352439f7ff1987d55c8', 'Thread of Fate', 'psionic skill', 3, 'WIS', NULL, 'By focusing on a person or object, the psion glimpses a faint thread of probability extending into the near future. They sense whether danger, opportunity, or neutrality is most likely within the next few steps. These insights are vague but allow preparation against imminent shifts.', 'Clairsentience'),
  (863, 'skill-e83282037deebf5a6dae6dd4c3a34f8d694da8f18b526b243f0a64be50c392a9', 'Echo Reading', 'psionic skill', 3, 'WIS', NULL, 'The psion attunes to a room or area, sensing the lingering echoes of presence. Footsteps, words, or emotions reverberate faintly, painting an impression of who or what has been there recently. In crowded places, impressions blur together, requiring focus to isolate useful details.', 'Clairsentience'),
  (864, 'skill-c51a89e8d55a9fcc8333987b79303143effca341c74aa174d760a69d9f09412a', 'Aura Veil Pierce', 'psionic skill', 3, 'WIS', NULL, 'With effort, the psion pushes past surface impressions to pierce deeper layers of an aura. Subtle flickers reveal concealed motives, illness, or lies woven into intent. For the spell’s span, they may test truth against aura flow, discerning deception with greater clarity.', 'Clairsentience'),
  (865, 'skill-a94282d01545674405728d470fb6ca7692e924e58962ecb77bb9c901c00183e4', 'Web of Insight', 'psionic skill', 3, 'WIS', NULL, 'The psion threads together the unseen ties between people, objects, and places in their sight. Lines of connection glow faintly, revealing who is bonded, hostile, or tied by recent events. In combat, this allows anticipating coordinated moves and uncovering hidden relationships between enemies and allies alike.', 'Clairsentience'),
  (866, 'skill-b4b34e2b9cc57282b4179ba9ed57b90210feb883a8818044661069a28429e6ab', 'Foresight Step', 'psionic skill', 3, 'WIS', NULL, 'By splitting awareness across branching futures, the psion glimpses what is about to occur moments ahead. They align their body with the “most favorable” path, moving or acting with uncanny timing. Enemies’ strikes are anticipated, allies’ openings foreseen, and actions unfold as if rehearsed.', 'Clairsentience'),
  (867, 'skill-955991b561a261a49ee1c8bfc0bdbca4c0e769a1f95890da9ad1e7773ba99e19', 'Echo Chamber', 'psionic skill', 3, 'WIS', NULL, 'The psion extends their mind across a large chamber, filling it with the resonant “echo” of perception. Whispers, movements, and hidden passages vibrate like struck chords, revealing all presences and motions within. Illusions falter in this resonance, their frequencies discordant to the psion’s tuned awareness.', 'Clairsentience'),
  (868, 'skill-0065d97ac55cda783520c9941d90747e02e6c05d99125dcd925075fa211d24cc', 'Threads of Destiny', 'psionic skill', 3, 'WIS', NULL, 'The psion perceives dozens of branching futures radiating from those around them, shimmering like spiderwebs of probability. For a brief span, they may tug these threads to steer fate slightly—guiding allies away from danger and into opportunity, while making enemies stumble into misfortune. The battlefield feels orchestrated, as if every motion had already been rehearsed.', 'Clairsentience'),
  (869, 'skill-9c040530d5e7db2ce67e1bc23a79ca4da837f23d6ebf9e33edc349c66340f48c', 'World’s Whisper', 'psionic skill', 3, 'WIS', NULL, 'The psion sinks into the resonant hum of the land itself, their awareness spreading across a vast zone. Every heartbeat, every breath, every concealed presence sings into their perception. Nothing can hide—the psion feels footsteps underground, invisible creatures in the air, even shifting emotions of an entire crowd. Enemies find stealth impossible while this resonance lasts.', 'Clairsentience'),
  (870, 'skill-1dd0f720dae15f93c5e3a126754700df7e212b15e0bf8d825f0c3896cfa369de', 'Eyes Beyond Time', 'psionic skill', 3, 'WIS', NULL, 'The psion opens their perception beyond the linear flow of time. For an instant, they stand within a storm of countless pasts, presents, and possible futures. They glimpse every strike before it lands, every deception before it is spoken, every hidden thing before it moves. For a fleeting span, the battlefield bends to their awareness—foes stumble into predicted blows, allies move in perfect synCHAonicity, and even the flow of events seems to “correct” itself around the psion’s foresight.', 'Clairsentience'),
  (871, 'skill-6e741bf3e435a0a6dc7489db2f99e5e80f7c30934821e731493ef4fabeb2b60c', 'Metacreativity', 'discipline', 2, 'WIS', NULL, 'Metacreativity draws from the mind to manifest objects, structures, or tools into temporary existence. It is imagination made tangible—an expression of will shaping the real.', 'Psionic Focus'),
  (872, 'skill-cc8275d4dc249f5fec96210976ec4e528d01874053c6ce4be0468b52a23dddad', 'Mind-Forge Tool', 'psionic skill', 3, 'WIS', NULL, 'A thin gleam knots in your palm and unspools into a crisp, semi-solid tool shaped by intent. The construct looks like faceted glass overlaid with faint runes, yet it handles like tempered steel. You decide the form as it appears—lockpick, screwdriver, pry bar, piton, chalk stylus, or another simple implement. The tool hums with a quiet resonance that steadies the hand and resists slipping, but when the moment passes it fractures into motes of light.', 'Metacreativity'),
  (873, 'skill-c093fa7ca27b2ba7079da503cee657ad40bdbffe6c3f6c1ecfe16f98be453eed', 'Force Buckler', 'psionic skill', 3, 'WIS', NULL, 'A disc of force blossoms from your forearm like a blooming, hex-tiled shield. The surface ripples to meet incoming strikes, redistributing momentum across a psionic lattice. It is weightless to you but solid to anything that touches it, and when the urgency fades the shield contracts to a coin of radiance and winks out.', 'Metacreativity'),
  (874, 'skill-32baa6a053061a913839715b21aa2736f7d22668cc235fc143cb7814acf7c620', 'Psi-Edge Blade', 'psionic skill', 3, 'WIS', NULL, 'A slender blade of condensed intent extrudes from your grip with a low, harmonic hum. Its edge is a hair-thin seam of light that lengthens or shortens to match your style. The weapon balances perfectly, guiding the wrist into clean cuts. The edge is more agreement than matter, and it fades if your focus drifts.', 'Metacreativity'),
  (875, 'skill-905a42ed458890b2ea045424fcf4b7d334a8e4b7650e0547fbe5847f4d2112ac', 'Ectoplasmic Barrier', 'psionic skill', 3, 'WIS', NULL, 'Your outstretched hand sketches glowing lines in the air that harden into a semi-transparent wall. The barrier hums with psionic energy, faint hexagons rippling across its surface like overlapping shields. Arrows thud and flatten, spells splash into harmless sparks, and charging foes are brought to a sudden halt. The wall’s integrity depends on your focus and dissipates once the moment has passed. The effect is as much psychological as physical—opponents hesitate when faced with a defense literally pulled from thought.', 'Metacreativity'),
  (876, 'skill-c6fc96e9dc2aea7691544440a1955efbb48c42877be978f175797fb824f5c4bc', 'Ephemeral Ally', 'psionic skill', 3, 'WIS', NULL, 'You extend your will outward, and translucent light condenses into the shape of a hound-like guardian. The construct moves with eerie precision, guided by your subconscious commands. Its body is semi-solid, enough to bite or block an enemy, but collapses into misty shards if struck down. The ally acts as an extension of your mind, defending flanks or harassing vulnerable targets. Though fragile, its sudden manifestation shifts momentum on the battlefield.', 'Metacreativity'),
  (877, 'skill-0a89eac077d2982a7786892f3401543e67d6b86587506c62d5d67452bd1dc159', 'Force Lance', 'psionic skill', 3, 'WIS', NULL, 'A spear of crystallized thought projects from your hand and shoots forward in a straight, piercing line. The lance glows with a sharp inner fire, humming as it cuts through air and armor alike. Enemies struck feel the weight of will as much as impact. The lance dissipates after impact, shattering into sparkling fraG.O.Dents of psionic residue. It is as much a test of the caster’s focus as it is a weapon, demanding precision of aim.', 'Metacreativity'),
  (878, 'skill-e4e0c891fff78d5f9476adeaa34a2aa176066bba80428707e7f60ba8b95aec10', 'Citadel of Thought', 'psionic skill', 3, 'WIS', NULL, 'You extend your arms and the battlefield responds—panels of translucent psionic stone rise from nothing, clicking into place like puzzle pieces until a fortress wall surrounds your position. The structure towers above, complete with crenellations and angled buttresses. Each block glows faintly with glyphs of will, humming with pressure as if bracing against reality itself. The citadel offers allies cover and limits enemy movement, reshaping the tactical field in an instant. When the construct fades, the blocks fracture into drifting shards of thoughtstuff, dissolving like sand in the tide.', 'Metacreativity'),
  (879, 'skill-6f885f2f582aa5e79169e67aa6367ab6624aeaa6a463842a6de1a8d089f7c24a', 'Eidolon Construct', 'psionic skill', 3, 'WIS', NULL, 'An imposing figure emerges beside you—a humanoid construct forged from glimmering psionic plates. Its eyes glow with borrowed will, its limbs powered by latticework energy. This eidolon acts as an autonomous ally, defending, striking, and interposing itself without direct command. Its form is unmistakably artificial, but it radiates presence and authority, causing hesitation among foes. The construct obeys broad intentions (defend me, attack them) rather than micromanaged instructions, freeing you to focus on the battle. When destroyed or dismissed, it breaks into shards of luminous crystal that scatter like fireflies.', 'Metacreativity'),
  (880, 'skill-80b8fe942aaa3a1075619825093df545139906e53bd5876273aa9644b52aed3f', 'Reality Armory', 'psionic skill', 3, 'WIS', NULL, 'Weapons and armor shimmer into existence around you and your allies—a storm of conjured blades, bows, and shields, each tailored to its wielder’s grip. The constructs appear weightless until grasped, then solidify with a satisfying heft. Armor molds to fit, scaling to protect the body without hindrance. These are not mundane tools but psionic resonances of ideal forms—always sharp, always balanced, always resilient. The sight of a squad suddenly armed by sheer thought is often enough to shift the tide of battle before the first blow is struck. When the duration ends, the armory dissolves like dust in sunlight.', 'Metacreativity'),
  (881, 'skill-134cb5e65965b22818225a08e397b8bc6b6041c77bbc965bdaf5aea3bbfeea4e', 'Colossus of Will', 'psionic skill', 3, 'WIS', NULL, 'You call upon the depths of your mind and the ground trembles as a towering psionic construct rises—a colossal golem of faceted crystal and light. Standing thirty feet tall, it moves with deliberate force, each step shaking the battlefield. Its fists strike like siege engines, and its body shields allies behind it. Though limited in awareness, it obeys your intent with simple clarity: guard, strike, or block. Foes behold not just a giant, but the embodiment of unyielding imagination. When the construct fades, shards of radiant crystal rain down, scattering like broken dreams.', 'Metacreativity'),
  (882, 'skill-987694baf7c4b3d322cc14e8b3f93d6df346c8ee9b0aa113c97e0dea4840749d', 'Reality Bastion', 'psionic skill', 3, 'WIS', NULL, 'You anchor your mind to the fabric of existence and unfold a bastion of psionic architecture—walls, towers, and radiant barriers interlock in a vast defensive zone. The fortress encompasses a wide area, creating ramparts and bulwarks that shift slightly to block incoming strikes. Inside the zone, allies feel a sense of safety as their steps fall in rhythm with the construct’s pulse. To enemies, the space becomes a gauntlet of shifting cover and choking routes. The bastion’s sheer presence alters the flow of battle, carving order into chaos. When it collapses, the sound is like glass breaking across the horizon.', 'Metacreativity'),
  (883, 'skill-178e65cd630ce8c78b4745586ce8cd44555fea5a83d6a5939b98a7ee719ae7c6', 'Eternal Citadel', 'psionic skill', 3, 'WIS', NULL, 'Your will pours outward in an overwhelming cascade, rewriting the battlefield into a sprawling psionic citadel. Towers rise with crystalline spires, walls knit together from lattices of pure thought, and vast gates seal with glowing glyphs. Within its bounds, allies feel bolstered, as though the fortress itself breathes with them; enemies are crushed beneath the pressure of absolute structure, every movement met with resistance. The citadel warps the field into an ordered domain under your control—corridors channel combatants, vantage towers grant advantage to allies, and walls bar escape. It is more than a construct: it is a living idea, a fortress of mindstuff projected into the world. When it collapses, shards linger as psychic ruins—unstable terrain that resonates for days, haunting the minds of those who fought there.', 'Metacreativity'),
  (884, 'skill-d16e025a344fad9bce7032ff6d5cd8270baede264d512c895b70bc7d8e9dc439', 'Psychoportation', 'discipline', 2, 'WIS', NULL, 'Psychoportation bends space through sheer intent. It enables movement without travel—blinking, shifting, or displacing across distances without physical action.', 'Psionic Focus'),
  (885, 'skill-b1b99033de4d2647c3faa57d479b20cfb6351cabd1f88545102d55735ba9a415', 'Dimensional Peek', 'psionic skill', 3, 'WIS', NULL, 'The psion stills their breath and lets their awareness slip sideways through the weave of space. A glossy ripple passes over their eyes like light across oil, and for an instant they perceive what lies just beyond a barrier, around a corner, or on the far side of a sealed door. Sound smears into a dull hum, colors flatten, and then snap back as the glimpse ends. On the battlefield, this lets them check a choke point or confirm an ambush without exposing their body. Outside combat, it reveals hidden alcoves, stashed packs, or lurking threats. The effect is brief and imperfect, more like a snapshot than a steady view.', 'Psychoportation'),
  (886, 'skill-8d78ea58fdc48d6ea2441286c89f1a0b8ecb96b71121ae17ee2a89a4e58aa2c0', 'Echo Step (Minor Boost)', 'psionic skill', 3, 'WIS', NULL, 'The psion gathers a taut crease of space beneath their heels, then releases it in a whispering pop. For a heartbeat their outline smears, leaving a faint after-image that seems to lag behind the body. The world feels a touch slower, footsteps landing in just the right gaps and angles. In combat, this micro-surge smooths a sprint from cover to cover or shaves the edge off an enemy’s timing. Outside battle it helps with tight jumps, quick dashes, or slipping through a crowd. The effect is subtle, not a full teleport, but it builds the reflexes psychoporters need for larger jumps.', 'Psychoportation'),
  (887, 'skill-f513555e16c9c75004898419634070076b1db2c09ae80cbab7bb4c90e2e6d6e3', 'Spatial Veil', 'psionic skill', 3, 'WIS', NULL, 'The psion pinches a fold of air and drapes it across themselves like a heat-haze cloak. Edges warp, lines misalign, and the eye slides across their outline as if focus refuses to land. On a crowded field this shimmer makes strikes just a hair off, arrows clipping where the body was a blink ago. The veil does not render them invisible; it merely scrambles the world’s attempt to pin their exact position. It is quick to raise and quick to fall, perfect for a decisive moment such as closing distance or slipping from a sightline. Though fleeting, it often turns a lethal blow into a near miss.', 'Psychoportation'),
  (888, 'skill-e14a51fded1fb9b43de815d3832da099053b583f1d2c01d0495a70f118df426c', 'Blink', 'psionic skill', 3, 'WIS', NULL, 'The psion inhales sharply and vanishes in a ripple of warped air, reappearing in the blink of an eye. To allies and enemies alike, it appears as though they skipped a frame of reality itself. This trick allows apprentices to dodge an incoming blow, escape a tight bind, or move into a better position. It is limited in range, but mastering it is the first step toward bending space itself.', 'Psychoportation'),
  (889, 'skill-fd5143c127c29994fb3e2dfff6028c1c8cc632a99607b4796e4f97571b79d7f2', 'Phase Hand', 'psionic skill', 3, 'WIS', NULL, 'The psion presses their palm to a wall or chain, and their hand slides through solid matter as if it were mist. The sensation is cold, tingling, and unsettling. Apprentices use this to scout past barriers or slip bindings, though the danger is real—if focus fails, the body protests violently against occupying two states at once.', 'Psychoportation'),
  (890, 'skill-05b07165b6111af731e3b836c789da89759397b5994d0022a147d16f31725f50', 'Anchor Blink', 'psionic skill', 3, 'WIS', NULL, 'The psion hurls a mental anchor at a chosen point, then reels themselves to it instantly, space collapsing in a whip-snap. A shimmer of distortion marks the arrival, like a stitch closing in reality. Apprentices use this to break grapples or close a gap, but misjudged anchors can leave them exposed.', 'Psychoportation'),
  (891, 'skill-4e44678f6f2fae78306e8fa299bae5a493d5eae1e1f2d0919910b95427e52554', 'Blink Assault', 'psionic skill', 3, 'WIS', NULL, 'The psion folds space around themselves, vanishing and reappearing in a flurry of disjointed steps that confound the eye. To enemies, it is as though three copies of the caster exist at once, each one striking from a different angle. In reality, the psion blinks between positions faster than thought, disorienting opponents and landing blows in their wake. The battlefield shakes with distorted echoes as their presence skips across the map. This spell makes the psychoporter a blur of offense, darting between foes before they can react.', 'Psychoportation'),
  (892, 'skill-6b690cf3759490c227c31ef10b1d103880374d43bc2a82332ed3f0db22e87c96', 'Phase Passage', 'psionic skill', 3, 'WIS', NULL, 'With a sweeping gesture, the psion draws a door in the air, space parting like a curtain. A shimmering gateway yawns open, its edges wavering as though underwater. For a brief time, allies may step through, emerging safely on the other side of a barrier or across dangerous ground. The passage is fragile and unstable, its edges sparking with warped light, but it can save an entire group in desperate situations.', 'Psychoportation'),
  (893, 'skill-cdb557ab5866c9f51869b0948f425b362b36cab107dd4b52c324a7cb7fe71278', 'Dimensional Anchor', 'psionic skill', 3, 'WIS', NULL, 'The psion slams a hand outward and the air shatters like glass, invisible lines snapping into place around the target. Space itself clenches, fixing them to one point and preventing escape by physical or magical means. A shimmering net of warped light crackles around the victim, binding them to their position as though nailed to reality itself. This spell is feared by fellow psions, for it denies their greatest defense—mobility.', 'Psychoportation'),
  (894, 'skill-daba4065f1e3045f38f47dca022c92c43625e43215cf8ef572ee0e74d4d5a1b8', 'Cataclysmic Rift', 'psionic skill', 3, 'WIS', NULL, 'The psion tears open a jagged wound in space, splitting the battlefield with a gaping chasm of distorted dimensions. Gravity howls inward, dragging combatants and objects toward the shimmering edge. The rift is not truly a hole in the ground but a breach in reality itself, its edges shimmering with impossible colors. Foes tumble screaming into nowhere, while allies cling desperately to stay clear. The ground vibrates, sound fractures, and for a brief moment, the world feels as though it will come apart.', 'Psychoportation'),
  (895, 'skill-430e5c9d2b77619b7988876df305f6f9135cc9ea4356170b1f0f952f67bb8e6f', 'Phase Exodus', 'psionic skill', 3, 'WIS', NULL, 'The psion lifts their arms as if opening curtains, and a shimmering aurora descends over their allies. With a thought, they vanish in a cascade of light, stepping all at once into a folded corridor of unreality. For a heartbeat they traverse an endless crystal hall, then emerge miles away in perfect formation. The shift shakes stomachs and rattles bones, but it pulls an entire company from certain death to safety in the blink of an eye.', 'Psychoportation'),
  (896, 'skill-6c99ce089cc004416fc1a004352ba030acdc66c4aa7a68abbe42a5a48c6333d4', 'Eternal Horizon Gate', 'psionic skill', 3, 'WIS', NULL, 'The psion spreads their hands wide, and reality groans as if under titanic strain. A colossal arch of blinding light rises, tall enough to scrape the sky, its interior filled with rolling storms of stars and shadow. The air warps, drawing nearby objects toward the gate like a tide. With one step, an army may vanish into new lands or strange realms; with another, a city may be evacuated in moments. The caster feels the weight of infinity pressing down, for the gate does not simply connect two points — it writes a permanent scar between them. Where once there was distance, now there is none. Legends tell of psychoporters who used this art to redraw the maps of nations in a single night. Few survive the toll, for to open the horizon is to invite the infinite.', 'Psychoportation'),
  (897, 'skill-d961e4e7e78d11c93df5877f25eb01bf206fb728e39ff48b193876e99bcdacae', 'Psychokinesis', 'discipline', 2, 'WIS', NULL, 'Psychokinesis is force without form—movement, vibration, and kinetic energy directed by thought alone. From lifting objects to striking enemies, the mind becomes a physical force.', 'Psionic Focus'),
  (898, 'skill-8bf251049a0649dccee94aca9284130c500692e115135b0f2ab7a850acd10083', 'Ember Spark', 'psionic skill', 3, 'WIS', NULL, 'From the psion’s hand flares a sudden glimmer of heat, a spark called from thought alone. The flame leaps into existence with a faint hiss as the air itself combusts under mental command. A streak of fire darts forward in a jagged line, striking a single target with searing precision. The flash illuminates nearby shadows, throwing the battlefield into brief relief. Enemies struck feel the sharp sting of burning flesh and the acrid smoke that clings to skin. Though minor, the damage is immediate and undeniable, a lesson in the destructive promise of elemental will. Tactically, this spell provides a quick ranged strike, offering the psion a reliable opener. Its reach allows the caster to stay just out of melee range, while still engaging enemies with force. Lore whispers that the first psychokinetics trained by igniting their own sparks as proof of awakening. It is a spell as much symbolic as functional: the flame that begins the greater blaze.', 'Psychokinesis'),
  (899, 'skill-ab984ae585323caf0f678c8a50ebb968747d2f63333e1f63ddd257ca405dc8d6', 'Stone Rattle', 'psionic skill', 3, 'WIS', NULL, 'With a single stomp or clenched thought, the psion calls the ground to life. Stones grind against one another, the earth quivers in protest, and a shudder ripples beneath the chosen target. Dust leaps upward as though startled, and cracks vein outward from the point of impact. The effect strikes balance and confidence, causing a brief stagger and a strike of bruising force. On the battlefield, this creates both a visual distraction and a functional disruption of footing. The sudden tremor makes enemies hesitate, giving allies a window to press the attack. Tactically, it is best used in melee to disorient a foe and make follow-up strikes more effective. Ancient training scrolls suggest Stone Rattle was favored by novices learning to link mind with matter, a simple but potent expression of earth’s resonance. The spell echoes a truth of psychokinesis: even the smallest vibration can alter the flow of combat.', 'Psychokinesis'),
  (900, 'skill-8e2e04d45655d58b5efc1a0a37f7363cb06fbcf57669fd2a0704341bf99a9d93', 'Gust Lash', 'psionic skill', 3, 'WIS', NULL, 'The psion sweeps their arm or focuses their will, and the air itself hardens into a cutting lash. A burst of pressure arcs outward in a sharp strike, striking the target with stinging impact. The sudden gust rattles clothing, snaps hair back, and forces the body to yield to invisible momentum. Enemies are shoved backward, their stance thrown off by the unexpected force. On the battlefield, Gust Lash is a control tool—used to break charges, push enemies away, or clear space for regrouping. The damage is absent by design; the value is distance and tempo. Tactically, it shines when employed to keep foes from closing into melee or to shove them into hazards. The lore of wind-wielders says this technique mirrors the “first breath of the storm,” a warning before greater power arrives. It is the subtle assertion of control: air as a weapon, not just a resource.', 'Psychokinesis'),
  (901, 'skill-704fd0ba46c369cd9b6a9d9dedd52802949a57f52597a952ac0b097789e533e5', 'Flame Jet', 'psionic skill', 3, 'WIS', NULL, 'With a snap of focus, the psion ignites raw oxygen and will into a stream of fire. A roaring jet of flame bursts outward in a short cone, lighting the battlefield in crackling orange light. The heat singes hair, chars armor, and blackens stone in its wake. Enemies within the jet stagger from the sudden blast, their footing weakened by searing pain. Tactically, this spell clears groups of tightly packed enemies and controls chokepoints. The spell is a direct escalation from the apprentice’s spark—no longer a flicker, but a blaze that consumes. Lore calls it the “psion’s torch,” the first sign they command more than minor embers.', 'Psychokinesis'),
  (902, 'skill-16523031643208c4817d95f57930009fbff6545daf7c0bbc06b957215376e106', 'Rock Shard', 'psionic skill', 3, 'WIS', NULL, 'With a sharp gesture, the psion rips loose a fraG.O.Dent of stone and hurls it forward with crushing speed. The shard whistles through the air before slamming into its target with bone-cracking force. Dust and splinters of rock scatter outward, leaving a visible scar upon the battlefield. Enemies hit feel the weight of earth turned against them, as though the mountain itself chose to strike. Tactically, this spell gives psions a ranged kinetic strike, useful when melee is too dangerous. Lore holds that many young earth-shapers first prove themselves by felling a beast with a conjured stone.', 'Psychokinesis'),
  (903, 'skill-487e0744c7fff4f5c33fbb97051930a4317c168e338b8bbe4fe80b95cf349ace', 'Wind Shear', 'psionic skill', 3, 'WIS', NULL, 'Air gathers in a vibrating hum, then lashes outward in a crescent wave of cutting force. The invisible strike slices through the battlefield, ruffling banners, tossing debris, and striking all caught within its sweep. Those struck feel both the sting of the slicing air and the shove of raw momentum. Tactically, Wind Shear is valued for crowd control, disrupting advancing lines and punishing clustered formations. Lore paints it as the echo of great storms—psions reaching into the breath of the sky to carve their foes apart.', 'Psychokinesis'),
  (904, 'skill-9e3071adb2eae986ec4b5a976fd9db68ac895db8921d21db6d0330ad6296975b', 'Molten Surge', 'psionic skill', 3, 'WIS', NULL, 'The psion slams their will into the earth, causing molten rock to burst upward in a fountain of fire and stone. The ground splits, spewing maG.O.Da and searing fraG.O.Dents in a roaring column. Enemies caught in the eruption are burned, battered, and forced to stagger back from the heat. The battlefield becomes a searing hazard, glowing cracks marking the terrain. Tactically, this spell is used to break clustered formations and deny ground, turning open space into a hazard zone. Lore whispers that this technique comes from ancient psions who sought to imitate volcanoes, channeling the destructive heart of the world itself.', 'Psychokinesis'),
  (905, 'skill-dcb1de51a750ccaa01b5fbc0b76f67cc39373c03107bec20ece026424cef77aa', 'Lightning Chain', 'psionic skill', 3, 'WIS', NULL, 'An arc of lightning leaps from the psion’s hand to strike a foe, then dances onward in jagged forks to strike others nearby. The air fills with the crackle of ozone and the blinding flash of electricity. Each target struck convulses under the shock, muscles locking, weapons clattering from nerveless hands. The battlefield becomes a dance of sparks as enemies are struck in sequence. Tactically, Lightning Chain punishes groups, spreading damage across multiple opponents with ruthless efficiency. Legends tell of storms given will, striking not once but many times in jagged rhythm.', 'Psychokinesis'),
  (906, 'skill-bd1b55f5ff246f80f8a7159375dbf1edf2272804b460ea9aea9aaaa7fb9bdf09', 'Crushing Grasp', 'psionic skill', 3, 'WIS', NULL, 'The psion extends an invisible hand of raw force that seizes an enemy, wrapping them in an intangible but unyielding grip. Bones creak as the unseen pressure tightens, holding the foe aloft or pinning them to the ground. The target struggles as if in the fist of a giant, unable to break free without immense effort. Around them, dust and debris whip about as the force manifests visibly to all. Tactically, this spell removes a single enemy from the fight, immobilizing them and slowly crushing their strength. Lore names this the “giant’s hand,” the psion made titan through will alone.', 'Psychokinesis'),
  (907, 'skill-bf4368f09dfb70c6234726c76cff9f053c3ba5b179743d5de29fde8e22958ad7', 'Maelstrom Vortex', 'psionic skill', 3, 'WIS', NULL, 'With a thunderous roar, the psion twists elemental forces into a whirling vortex of water, wind, and debris. The battlefield erupts as a storm-center forms, dragging enemies toward its heart. Those caught inside are battered by shards of stone, razor winds, and crushing water currents. The roar deafens allies and foes alike, the ground shuddering under its pull. Tactically, this spell dominates terrain, locking groups of enemies into a zone of chaos where movement is near impossible. It is best used to disrupt entire armies or break sieges. Lore paints this technique as the psion’s ultimate defiance, calling the chaos of nature itself to swallow all who stand against them.', 'Psychokinesis'),
  (908, 'skill-feaec7bb9901fa9c212d1fff07811489324b5109e67ccc06185db7a409a62771', 'Seismic Rupture', 'psionic skill', 3, 'WIS', NULL, 'The psion drives their will into the earth itself, causing an eruption of devastating earthquakes. The ground splits open, stone heaves upward, and shockwaves ripple outward in deadly pulses. Buildings crack, walls topple, and enemies stumble helplessly in the chaos. Fissures glow faintly as latent maG.O.Da seeps through, the earth itself screaming as it reshapes. Tactically, this spell devastates fortifications, topples lines of defense, and crushes those caught unaware. The quake reshapes the battlefield, leaving terrain forever changed. Lore marks this power as forbidden, for it blurs the line between psion and natural disaster.', 'Psychokinesis'),
  (909, 'skill-f367cb9aea06c8effcf7b8d101d2af501e4c594b7f0551a5985f4ca6dbd2aadb', 'Cataclysm', 'psionic skill', 3, 'WIS', NULL, 'With a single overwhelming exertion of will, the psion calls forth the fury of all four elements in catastrophic harmony. The ground splits into molten chasms as fire erupts skyward. Cyclones roar into being, ripping trees and fortifications from their foundations. Walls of water crash down in impossible tides, drowning the battlefield in chaos. Lightning arcs wildly from storm clouds that coil overhead, striking ground and flesh alike with relentless fury. The world itself seems to convulse, reshaped into a zone of annihilation. Tactically, Cataclysm is both battlefield eraser and ultimate deterrent, obliterating entire armies or fortresses in one act. Few survive its casting; fewer still survive its aftermath, where terrain lies forever scarred. Lore speaks of psions who invoked this only once, collapsing under the strain, their bodies burned out as conduits for destruction too great for any mortal. This spell is not just an attack — it is a rewriting of nature’s law under the weight of thought.', 'Psychokinesis'),
  (910, 'skill-1538828e092d8102d8dd9d5711ec4b55bea1892c53f14714b5e4690b845d06a9', 'Psychometabolism', 'discipline', 2, 'WIS', NULL, 'Psychometabolism controls the body from within—healing, enhancing, or adapting it through mental command. With this discipline, the mind rewrites the flesh.', 'Psionic Focus'),
  (911, 'skill-df1b04e371d1b17ad5b5bc37df8a4cc25b536b5d2fd165e3c40a218da37e49c0', 'Cellular Mend', 'psionic skill', 3, 'WIS', NULL, 'With a breath drawn inward, the psion visualizes strands of light knitting through torn flesh. A soft warmth radiates from within, not imposed from outside but summoned by the body’s own accelerated will to survive. Wounds close with faint luminescent lines, fading to scars that quickly soften. On the battlefield, this is a quick patch—not full restoration, but a stabilizing anchor that keeps an ally or the psion themselves in the fight. Practitioners describe the sensation as both exhausting and soothing, the body racing ahead of its natural pace. It is most effective for minor cuts and bruises, but can buy time against deeper injuries. The spell teaches discipline early on—every mend reminds the psion that flesh and thought are inseparable.', 'Psychometabolism'),
  (912, 'skill-a2741a2478bbef7b4326bc034389082ea0a9abf87f409346f1a8584d52de19e9', 'Adrenal Surge', 'psionic skill', 3, 'WIS', NULL, 'The psion focuses on their heartbeat, coaxing it into a rapid but controlled rhythm. Heat surges through the veins as muscle fibers tighten and reflexes sharpen. For a brief window, strength and speed flare to superhuman levels, empowering strikes or evasions that would otherwise be impossible. This spell manifests with a red flush to the skin, dilated pupils, and trembling readiness. On the battlefield, it is the difference between being caught and slipping free, or between landing a decisive blow and faltering. The drawback is equally clear—once the surge fades, the body aches with the rebound of forced exertion. Students of psychometabolism learn restraint here, for overuse burns the candle at both ends.', 'Psychometabolism'),
  (913, 'skill-6d4ab16fcae3a7266f52d1de5f4787f7a7c0c4287b32949e7ca90ca7b081dec5', 'Metabolic Purge', 'psionic skill', 3, 'WIS', NULL, 'Closing their eyes, the psion visualizes impurities as shadows within the bloodstream. With a mental push, sweat beads and a sharp chill runs through the body as toxins, alcohol, or fatigue burn away. The caster coughs or shivers as the body expels what does not belong, leaving them clearer, sharper, and lighter. In combat, this allows a poisoned ally to fight on, or the psion to shrug off exhaustion mid-battle. It is not without risk—the body feels wrung out afterward, as though sprinting a marathon in seconds. The spell is often accompanied by a faint smell of iron or bitter herbs, depending on the user’s psyche. Philosophically, it embodies the psychometabolist’s creed: that impurity is a choice, and resilience is discipline made flesh.', 'Psychometabolism'),
  (914, 'skill-236173072f3b1de82231bb3d41a44879f56ab82570b801b9a388ee885dfba27d', 'Cellular Regeneration', 'psionic skill', 3, 'WIS', NULL, 'Concentrating inward, the psion floods their cells with restorative energy, accelerating natural repair. Wounds close, bruises fade, and fatigue lightens as the body knits itself with uncanny speed. Skin glows faintly as if lit from beneath, and the target feels a buzzing warmth spreading through every limb. The healing is powerful but taxing; the body often needs extra rest after the process, as accelerated growth takes a toll. In battle, it can mean the difference between collapse and standing strong.', 'Psychometabolism'),
  (915, 'skill-75d5b54ddd2569173ae593c3f859ca1b30392ff690ebbcf515c9eab7e6abae6c', 'Iron Skin', 'psionic skill', 3, 'WIS', NULL, 'By sheer force of will, the psion hardens flesh and bone until they gleam faintly with a metallic sheen. Strikes that would normally cut or bruise rebound or scrape with sparks. To observers, the skin looks like living steel: rigid under blows yet supple in motion. When the effect fades, bruises blossom and the body aches from strain, as though it had borne the weight of armor from within.', 'Psychometabolism'),
  (916, 'skill-70ce96aa438eb2f82ff2099d61169bcde90a9261d764aa56b718dfffcadf1386', 'Metabolic Burn', 'psionic skill', 3, 'WIS', NULL, 'The psion accelerates their body’s metabolism to a fever pitch, burning reserves for explosive power. Muscles swell, eyes sharpen, and heat radiates from the skin. For a short time, the body pushes beyond its natural limits, granting both offense and speed. The aftermath is severe exhaustion: the body trembles, drenched in sweat, as though recovering from illness. Used wisely, it can end fights before its toll is felt.', 'Psychometabolism'),
  (917, 'skill-87e429faf88c600456c479068d7e12271796b90dd5853bfe71c40e63938f15d1', 'Hypermetabolic Overdrive', 'psionic skill', 3, 'WIS', NULL, 'The psion ignites every cell into furious overdrive: muscles flex beyond their safe capacity, heart and lungs pound like war drums, and eyes blaze with raw focus. The caster or chosen ally becomes a storm of motion and violence, striking harder and moving faster than biology should allow. Flesh steams with heat, weapons strike with unnatural precision, and enemies can scarcely keep up. When the overdrive ends, the body crashes—trembling and aching as if it burned weeks of energy in moments.', 'Psychometabolism'),
  (918, 'skill-a5af881f14b1c8d91ad4546d5ee7f64b16f121120fcc51096883f1069b2be554', 'Adaptive Regeneration', 'psionic skill', 3, 'WIS', NULL, 'The psion channels healing into not just recovery, but adaptation. Wounds close, scars fade, and the body re-grows stronger in the process: bones mend denser, skin thickens, and reflexes sharpen. The target feels a buzzing vitality as damage is undone and resilience reinforced; afterward, intense hunger and soreness arrive as the bill comes due.', 'Psychometabolism'),
  (919, 'skill-eccaceadc27cd604e07f33087af67402eb57c81d18d153f4fdc992bf557ec8c4', 'Biofeedback Field', 'psionic skill', 3, 'WIS', NULL, 'With a sharp exhalation, the psion projects metabolic control outward, creating a pulsing field of resilience. Allies within feel invigorated—breath deepens, muscles flood with energy, and bodies resist poison and fatigue. Enemies feel the air turn heavy and hostile, each motion dragging against them. When the field collapses, allies sag with momentary drain—but the fight often tilts before that moment.', 'Psychometabolism'),
  (920, 'skill-1756de5e0e9916a9f7ea8d14faa9b534b9071864dd898ab6e0747bb1957f170c', 'Metabolic Dominion', 'psionic skill', 3, 'WIS', NULL, 'The psion seizes control of all living metabolisms within reach, amplifying allies and suppressing enemies in one terrible act of will. Hearts thunder, muscles strain, and minds blaze in synCHAonized overdrive while foes choke on sluggish pulses. The battlefield becomes an echo of the psion’s internal rhythm—life itself beating to their cadence.', 'Psychometabolism'),
  (921, 'skill-b388d2fa1d8e4c8ed6adc82bbf0ff00359845f256e2ef740f505f55a973383b5', 'Regenerative Metamorphosis', 'psionic skill', 3, 'WIS', NULL, 'With immense focus, the psion rewrites flesh on the fly: wounds knit closed, organs reset, and even missing limbs can regrow in moments. Energy floods the target, pushing their biology into dangerous hypergrowth. While vitality surges and injuries vanish, the target risks collapsing under the weight of accelerated change.', 'Psychometabolism'),
  (922, 'skill-f5cb48d034349763ef67c4c6c38c28b3597dc6eb384f69cfc9e7af1b0ee8bfe8', 'Genesis Renewal', 'psionic skill', 3, 'WIS', NULL, 'The psion becomes a living fountain of biological will, rewriting the flesh of all within sight. Allies feel vitality surge through their bodies—organs reset, diseases unravel, and even the dying gasp as life returns. Lost limbs knit in blinding arcs of flesh-light, scars dissolve, and vitality blazes brighter than ever before. Enemies, however, feel their bodies betray them: poisons burn hotter, fatigue doubles, and their organs convulse as hostile metabolisms recoil from the psion’s dominance. The battlefield transforms into a domain where life itself bends to thought, reshaping every creature caught in the psion’s gaze. When the effect collapses, silence follows—the echo of countless heartbeats forced to march to a single rhythm. The psion stands drained, a husk of effort spent, their aura forever marked by the act.', 'Psychometabolism'),
  (923, 'skill-dca54cdd065030c75cc6f9de723e5f4bd5da0e217be7d2c3c021ae0b55e139e8', 'Telekinesis', 'discipline', 2, 'WIS', NULL, 'Telekinesis allows the user to move or manipulate objects with their mind. Precision, strength, and subtlety are all possible, depending on discipline and control.', 'Psionic Focus'),
  (924, 'skill-cc293fb3e12edea7695cb7384443aced441ac381b429c8f0771f1f3965a3b5f6', 'Kinetic Push', 'psionic skill', 3, 'WIS', NULL, 'With a flick of thought, the psion lashes out with invisible force, shoving a foe or object away as though struck by a giant unseen hand. Dust kicks up, robes billow, and weapons may be torn from grips as momentum carries the target backward. Often used to create space or break an enemy’s advance, the technique is a psionic staple.', 'Telekinesis'),
  (925, 'skill-758a42f8cc33ac04f4f06d3c479fdcc47ded238b71b56230f5f3bb7b6710758d', 'Force Grasp', 'psionic skill', 3, 'WIS', NULL, 'The psion extends their mind like an invisible hand, seizing hold of an object within reach. Small items may float gently into their palm, while heavier ones strain against unseen fingers. Onlookers see the object wobble, rise, and drift unnaturally through the air. A useful technique both in battle and in delicate tasks.', 'Telekinesis'),
  (926, 'skill-d92e0d3399b66d464dd207f9d08fecd8465b3b6f882b28e1ed0523147d708c7f', 'Deflect Projectile', 'psionic skill', 3, 'WIS', NULL, 'By sharpening their focus in a split-second, the psion swats away an incoming arrow, bolt, or small thrown weapon with raw telekinetic force. The effect is subtle, a ripple in the air and a sudden shift in trajectory. To allies, it is lifesaving; to enemies, it is infuriating to see their sure strike turned aside.', 'Telekinesis'),
  (927, 'skill-5b43b5fe7a7a4e33378c338b86b3730c6d1fd34f7a3ebc655c02bcdd24d8e509', 'Force Wave', 'psionic skill', 3, 'WIS', NULL, 'The psion compresses will into a snapping pressure front that bursts outward. Dust and grit whip into streamers as the wave forces bodies and gear back in a sudden lurch. Shields boom, boots skid, and formations buckle; it is space-making by brute intent. The effect is clean and nonlethal by default, but ruthless casters time it to push foes off ledges or into hazards. On a crowded field, it buys breathing room; in corridors, it clears choke points. Veterans learn to angle it, clipping only enemies.', 'Telekinesis'),
  (928, 'skill-283b9ccf4235fb7885ca5cc7607d255c7648cb4ae36b448ad8dddbaf33aa0d76', 'Telekinetic Pull', 'psionic skill', 3, 'WIS', NULL, 'The caster hooks a target with invisible force and yanks. Cloaks snap forward, footing breaks, and weapons or smaller objects jerk toward the psion’s waiting hand. It is disruptive, personal, and profoundly tactical: drag archers into melee, pull stragglers off cover, or rip a wand back across the gap. Observers feel a momentary pressure in their sternum, like a sudden elevator drop. Used well, this breaks lines and opens finishers.', 'Telekinesis'),
  (929, 'skill-eeb45284c8e94f96ecc4cc61e394ddb14faefd5040c6510066fbc3f145954b5a', 'Kinetic Armor', 'psionic skill', 3, 'WIS', NULL, 'The psion compacts the air and micro-currents around a body into a responsive skin of force. Arrows slur sideways, blades skid, and hammers lose bite as the field soaks momentum before it reaches flesh. The armor flickers like heat haze and hums in the bones when struck. It won’t stop a siege hit, but it turns lethal blows into bruises and buys time to reposition. As the field is will-shaped, it is silent and gear-agnostic.', 'Telekinesis'),
  (930, 'skill-c6797d7e3dfbe7917eeeffd39ca63622eb134327e076dfa283cf8dd19c5cfedd', 'Telekinetic Crush', 'psionic skill', 3, 'WIS', NULL, 'The psion’s focus locks onto a foe, invisible bands of pressure snapping around them. The air hums with strain as armor creaks, bones groan, and movement grinds to a halt. Victims feel as though an iron giant’s fist has closed upon them, crushing both breath and hope. It is not instant death, but suffocation and pain until will falters.', 'Telekinesis'),
  (931, 'skill-7c34f48e8eaf81fc60219539caa70758387268ccbd57b1f0f16cce98df17c8b9', 'Force Barrier', 'psionic skill', 3, 'WIS', NULL, 'The psion throws up a gleaming wall of compressed air, glasslike and invisible until struck. Arrows splinter, spells sputter, and charging warriors slam to a halt. Though fragile by grand-master standards, such barriers change the flow of a battle instantly—funneling foes, shielding allies, or sealing doorways with thought alone.', 'Telekinesis'),
  (932, 'skill-5f65bf24ea9ea971da284c01c63bebb42211774af1f8c0c020d606848dea891f', 'Mass Levitation', 'psionic skill', 3, 'WIS', NULL, 'The caster gestures broadly and the battlefield lifts. Loose weapons, rubble, and armored soldiers rise into the air like toys dangling from invisible strings. Gravity loosens its grip under the psion’s command, turning order to chaos. Allies can reposition midair while enemies flail helplessly, held in a pressurized pocket of skewed motion.', 'Telekinesis'),
  (933, 'skill-310fa152156ac8a66196d212c9602957460e4628f24f67f95863968a5919a9cc', 'Telekinetic Maelstrom', 'psionic skill', 3, 'WIS', NULL, 'With a roar of invisible pressure, the psion tears loose the battlefield itself. Rocks, weapons, and even bodies spiral upward in a violent storm of debris. Shards and rubble lash out randomly, battering all caught within the zone. Escape is possible, but movement feels like pushing through a hurricane of steel and stone. The air howls and twists as will-made currents shred formations and scatter courage.', 'Telekinesis'),
  (934, 'skill-75a6f427647c67c149f3703adb2e90d02708ac4c53ace99ab88b96ea1d77bc0b', 'Titan''s Grasp', 'psionic skill', 3, 'WIS', NULL, 'An enormous, spectral hand of force manifests, vast enough to seize siege engines or crush multiple foes together. Its fingers close with grinding inevitability, bones creaking and armor squealing as if under a mountain’s weight. Few can escape once caught; those who do carry the ache of pressure for days.', 'Telekinesis'),
  (935, 'skill-86d91e2f628861fbe695534388c49c7cfcdc6f6dcc36b0c3619fa81cc3affa72', 'Cataclysmic Convergence', 'psionic skill', 3, 'WIS', NULL, 'The psion unleashes layered fields of telekinetic domination. First, an all-encompassing gravity well seizes everything in range, pulling bodies and rubble inward. Simultaneously, a crushing force field locks targets in place, bones grinding and armor buckling. Finally, the zone itself twists with distorted vectors—arrows veer, stones float, and movement becomes impossible. The battlefield becomes a collapsing sphere of pressure and distortion, a storm of invisible hands dragging the world down.', 'Telekinesis'),
  (936, 'skill-2f4e79a308787b64c9ae60ebb2ea4f9f25d154f7cc0d2699ba2d586e42899749', 'Telepathy', 'discipline', 2, 'WIS', NULL, 'Telepathy opens pathways between minds. It enables silent communication, emotional sensing, or deeper mental exploration. Thoughts become language, and secrets less secure.', 'Psionic Focus'),
  (937, 'skill-5bfefcb5b0295b965c597da5578a59e081db8e377eec0664bd644d88ec2f536d', 'Mind Whisper', 'psionic skill', 3, 'WIS', NULL, 'A gossamer thread of intent stretches from the caster’s mind to the target, carrying words without sound and meaning without lips. The target hears a clear inner voice matching the caster’s tone, inflection, and cadence. The link conveys message content and emotional tone but does not read or receive thoughts in return. It works through noise, fog, and darkness so long as the target is within range. The effect is subtle to observers; only the target perceives the mental whisper. The caster must maintain light focus to keep the thread coherent for the brief window.', 'Telepathy'),
  (938, 'skill-c170dbc3cf39e83f29113c573081c065c23970c0b9b04958abff8c82a38da694', 'Surface Scan', 'psionic skill', 3, 'WIS', NULL, 'The caster brushes the surface of a target’s thoughts like fingertips skimming water, catching ripples of what is foremost in mind. FraG.O.Dents of inner monologue, flashes of intention, and the emotional “color” of the moment rise briefly into clarity. Lies become easier to sense by noticing discord between thought and speech. The contact is quick and surgical, leaving no lasting mark beyond a momentary chill or pressure behind the eyes. The scan does not pierce stored memory, only active thoughts.', 'Telepathy'),
  (939, 'skill-e5e2f917b9dce7441922711f95fff2af8db6e4b95e382e9d1b47dd0cf87e5954', 'Emotional Nudge', 'psionic skill', 3, 'WIS', NULL, 'With a delicate mental push, the caster stirs the target’s emotions. A spark of courage, a whisper of fear, or a sudden calm overtakes them briefly. The effect is fleeting but can turn hesitation into action or cool tempers in tense moments. It tilts choices without rewriting identity. Subtle practitioners pair it with timing to amplify its impact. Observers rarely notice more than a shift in posture or breath.', 'Telepathy'),
  (940, 'skill-6bfba4ab88fdace78281b8c40657f5f0136b4b23c6f7cb828f8b9bac44090642', 'Silent Chorus', 'psionic skill', 3, 'WIS', NULL, 'The caster threads a temporary mental channel between multiple allies, allowing silent communication without words. Each participant hears the others’ thoughts as whispered impressions, sharpened with intent and emotion. The network is short-lived but invaluable for tactical coordination, ambushes, or negotiations where speaking would betray intent. Thoughts broadcast are only those deliberately sent, not private musings, though untrained minds may slip.', 'Telepathy'),
  (941, 'skill-4ffaf746f0901406ce058f7e0f8aacad7ad8e17480535323bfb0dd3a24a134d5', 'Truth Sense', 'psionic skill', 3, 'WIS', NULL, 'By aligning perception to mental dissonance, the caster detects when words diverge from thought. The target’s speech seems shadowed by an echo of true intent, allowing the telepath to sense lies, omissions, or concealed motives. The effect does not reveal exact truths, only the presence of deceit or distortion. For interrogators and mediators, it is a razor-edge tool that cuts through manipulation without exposing full memory.', 'Telepathy'),
  (942, 'skill-fe08953028b95613019a61ebbcb90ce02394351f70cafb54b851f4d4c5e7f269', 'Mental Suggestion', 'psionic skill', 3, 'WIS', NULL, 'The caster plants a subtle thought inside the target’s mind — a whisper that feels like their own idea. The suggestion cannot override core beliefs, but it can sway decisions, urge hesitation, or nudge behavior in the moment. The effect is fragile: a strong will or conflicting motive may shrug it off, but when it lands, it shapes choice without force.', 'Telepathy'),
  (943, 'skill-e52e28d8f2425557b9ba977a129e176192fef7ebcb7645ed2012d5175603c62c', 'Memory Weave', 'psionic skill', 3, 'WIS', NULL, 'The caster threads into the target’s memory, surfacing vivid recollections while blurring or stitching details together. The telepath can reinforce a moment to clarity, edit minor details, or soften painful recollections. Though incapable of wholesale rewriting at this tier, it allows targeted tampering—an interrogator’s truth extraction or a healer’s trauma softening. Victims often emerge uncertain whether their memory was altered.', 'Telepathy'),
  (944, 'skill-94198d73d021c274bac38b1b5969fa3e4323bc7d1185f85a1a2e53d70abb6f71', 'Psychic Domination', 'psionic skill', 3, 'WIS', NULL, 'The caster clamps a mental vise on the target’s executive will, binding their next choice to a single, simple command. It does not erase identity or grant freeform puppeteering; it forces compliance for the moment, narrowing options to the directive given. The pressure feels like iron bands around thought—obedience seems inevitable, resistance like struggling underwater.', 'Telepathy'),
  (945, 'skill-5bcd4f227956d4aa96c302f27b4b8b2207df8666a5aecaf1f76587364718cabb', 'Telepathic Storm', 'psionic skill', 3, 'WIS', NULL, 'The caster detonates a field of psychic static—intrusive thoughts, discordant echoes, and emotional spikes—across the battlefield. Minds reel; coordination falters; actions slip through shaking hands. The storm presses invisibly on every skull within the radius, leaving even veterans blinking and off-balance.', 'Telepathy'),
  (946, 'skill-f0cd3aedb39e2accd14c17258f22b02cb309bb59d045142eedd4fff6621975e6', 'Mindquake', 'psionic skill', 3, 'WIS', NULL, 'The caster detonates a shockwave of psionic force across every mind within reach. The psychic tremor rattles thought itself, causing seizures of memory, speech collapse, and disorientation. Combatants drop weapons, falter mid-strike, or clutch their heads as the quake reverberates. The air seems silent, yet inside every skull a roaring fracture splits reason apart.', 'Telepathy'),
  (947, 'skill-ca803beac4a6779e5e7de266db3dfc349948d1d46389e100419dccd35084f7c0', 'Crown of Thorns', 'psionic skill', 3, 'WIS', NULL, 'The caster forges a burning mental crown of invasive thought upon a single target’s psyche. The victim feels every idea pierce like barbs, their will tethered by pain and compulsion. Each step, each decision comes with agony unless aligned with the caster’s implanted directive. Allies see the target’s eyes glow with strain as their own mind screams rebellion.', 'Telepathy'),
  (948, 'skill-36f55daf2926d39698d3ad511d789513c079baa240c712fc60abcc028ee1905d', 'Hive Dominion', 'psionic skill', 3, 'WIS', NULL, 'The caster imposes a vast psionic lattice across every mind in sight, bending individuals into a temporary hive under their dominion. Thoughts become strands in a web with the caster as the central node. Victims lose the ability to act independently; their wills synCHAonize to the caster’s commands. The lattice bleeds psychic pressure, inflicting pain and fatigue while drawing life energy into the caster to sustain the construct. Independent thought is not only bound but destroyed, rewritten into chorus. Allies feel their choices blunted, enemies collapse into forced unity, and the battlefield trembles as hundreds of lives march to one alien cadence. The effect strains even the caster, blood seeping from eyes and ears as their mind stretches to contain the chorus. Once released, victims often remember fraG.O.Dents as if their bodies were marionettes, their voices stolen by another.', 'Telepathy'),
  (949, 'skill-8f287d12950102f5d45a3c98fcb48e75d7b45abe60f3bc517f11ce668497d877', 'Oneirics', 'discipline', 2, 'WIS', NULL, 'Oneirics reaches into dreams and the liminal edge of sleep. It enables inducing or navigating dreams and extracting truths from them—the imagined shaping the waking.', 'Psionic Focus'),
  (950, 'skill-2447c7dd142c14f7602894325ccea9b33d0037b6886af451a87ad2d7f1d83565', 'Somnolent Touch', 'psionic skill', 3, 'WIS', NULL, 'With a brush of the hand, the caster induces a sudden wave of drowsiness. The target’s eyelids grow heavy, thoughts blur, and their movements falter as if slipping toward sleep. This does not render them unconscious, but it drags their reflexes into treacle for a heartbeat of battle.', 'Oneirics'),
  (951, 'skill-a11fb8ef444b507bd038d91d771a70d8272a92350a7c4eb066cc86e423e0aaf1', 'Whisper of Night', 'psionic skill', 3, 'WIS', NULL, 'A faint murmur seeps into the target’s mind like a drifting dream fragment. The whisper distracts, conjuring vague imagery of shadowy figures or forgotten voices. The illusions are subtle and fleeting, just enough to pull focus at the crucial moment.', 'Oneirics'),
  (952, 'skill-63aa471ddd41e3c0071edd991b01588c0452b267bad528d53f650d55aa2cc45a', 'Lucid Spark', 'psionic skill', 3, 'WIS', NULL, 'The caster sharpens an ally’s awareness as though waking them into a lucid dream. Senses flare, reaction times tighten, and distracting noise falls away. For a brief window, they move as if the field were a scene they’ve chosen to navigate.', 'Oneirics'),
  (953, 'skill-4a4654e7252de52492c8669fb7edf6c041f6e378bfac3ca938680cdca9993fb1', 'Dream Snare', 'psionic skill', 3, 'WIS', NULL, 'The caster weaves a psychic tether into the target’s mind, anchoring them in a tight loop of repeating moments. For a heartbeat of battle the victim can’t quite step cleanly into waking action—their limbs feel caught in molasses, focus sliding as phantom echoes overlay reality.', 'Oneirics'),
  (954, 'skill-3f30388fddef095be59511a45bf51d4977d7f0d23a03650b44326b8aa24dc095', 'Night Terror', 'psionic skill', 3, 'WIS', NULL, 'The caster thrusts a shard of nightmare into the target’s senses: a rush of shadow, falling corridors, or a remembered scream. Though illusory, the terror knots muscles and scatters attention, turning precision into doubt for the span of a clash.', 'Oneirics'),
  (955, 'skill-61d6033f4f788e3505c51f5bc33824520c6abb6cd85105ce30aba49ef8562371', 'Shared Dream', 'psionic skill', 3, 'WIS', NULL, 'The caster braids two minds into a flickering, shared vignette—just long enough for an ally to read the flow together while an enemy stumbles over borrowed thoughts. The moment passes like a blink, but the alignment (and dissonance) lingers through the step.', 'Oneirics'),
  (956, 'skill-96b31399cf8d5c9beab12532c161c15883f6bcda3bb92966caec1aea6f0678c2', 'Dream Bastion', 'psionic skill', 3, 'WIS', NULL, 'The caster manifests a fortified dreamscape around themselves and chosen allies, shielding them from hostile intrusion. Within the Bastion, thoughts feel sharper and illusions falter. Enemies attempting to pierce or manipulate minds find their efforts dulled.', 'Oneirics'),
  (957, 'skill-f8bc113eff65d1f5733e881cfbddd8019bc60e9f846361346aecf3014882d96f', 'Nightmare Sculpt', 'psionic skill', 3, 'WIS', NULL, 'The caster crafts a vivid nightmare illusion, draping an area in warped, surreal imagery—walls melting, shadows whispering, ground fracturing beneath false steps. Those inside struggle to distinguish truth, risking panic or hesitation.', 'Oneirics'),
  (958, 'skill-fe8d332f90fb81d2a91cbfa9404516183a6c2390dd9e5886e589a90af28afe10', 'Dreamwalk', 'psionic skill', 3, 'WIS', NULL, 'The caster tears open the veil of sleep, stepping partially into another’s dream and dragging them along. For the duration, both caster and target exist in a liminal state—half waking, half dreaming—able to strike across both realms but vulnerable to collapse if concentration falters.', 'Oneirics'),
  (959, 'skill-ab9f692c1b247c43e0c566d93263c550ad480e953009438d6bfd6c25ab4dd3ff', 'Cathedral of Sleep', 'psionic skill', 3, 'WIS', NULL, 'A cathedral of silent bells and moonlit aisles descends over the battlefield, built from the shared architecture of sleeping minds. Pillars rise and bend the angles of space as motes of dream-dust hush footfalls and soften the edges of thought. Choirless echoes hum at the threshold of hearing, turning commands into muffled intentions. Within the nave, vision doubles and then blurs, as though every motion leaves a drowsy afterimage. The air itself thickens like velvet, inviting stillness. Those who resist the hush feel the weight of ritual time pressing down on their muscles. Those who fail are caught in a loop of entering and re-entering the same second, stunned as the bells never quite ring. At the spell’s heart, the caster’s focus serves as the high altar that anchors the entire structure. Should that focus slip, the pews splinter and the dream collapses back into raw night. Even the wakeful admit: for a moment, the world knelt.', 'Oneirics'),
  (960, 'skill-0335f81d60e60738a932d8f6516c0848ebbbfe7ad242a1c1ae587a5d49179a03', 'Labyrinth of the Sleeper', 'psionic skill', 3, 'WIS', NULL, 'The caster unfolds a cubic maze of dream-corridors over the field, every turn repeating into itself like a thought you cannot quite finish. Floors seem to tilt a few degrees off possible, doors open back into the same room, and distances breathe in and out. Footfalls are swallowed; shouts arrive a measure too late. Enemies feel their intention drift sideways as the maze leans them away from exits. The illusion wrings certainty out of sightlines while the space itself presses like gentle water against every motion. Those who fail to assert their will find their steps locking in place, as if the next square refuses to exist until they truly choose it. The maze is generous to none, but the caster holds the key and knows where the walls are thinnest. With time, even steel learns to yawn. When it fades, the world feels painfully sharp for a beat, like waking too fast. The map never existed—except that you were on it.', 'Oneirics'),
  (961, 'skill-f77986d475619191e77a5a1bf834d62b318f7aac287fd5238064f46129b94451', 'Eternal Dreamfall', 'psionic skill', 3, 'WIS', NULL, 'The caster collapses the border between waking and dreaming across an entire battlefield. The sky ripples into shifting auroras of memory, ground dissolves into corridors of half-remembered dreams, and every creature is pulled into a shared tapestry of illusion and truth. Allies move with uncanny foresight, guided by echoes of futures that have not yet happened. Enemies falter as their wills fragment between countless dream-selves, their movements slowed, their bodies drained, and their minds at risk of being lost forever in infinite recursion. Only the caster’s focus anchors the dreamfall; if broken, the illusion collapses violently, leaving both friend and foe stunned by the aftershock.', 'Oneirics'),
  (962, 'skill-daf4c717d35ead804b70ee954e21e72b560240b2f58f8b2a9be8646d205288ec', 'Umbrakinesis', 'discipline', 2, 'WIS', NULL, 'Umbrakinesis commands shadow and absence of light. It can dim, cloak, or harden darkness into tools and barriers—the unseen becoming your instrument.', 'Psionic Focus'),
  (963, 'skill-f3dcec89b33a3cb045bb741670245cc1334e651c1b706cb382427d4a15791b29', 'Shadow Grasp', 'psionic skill', 3, 'WIS', NULL, 'Thin tendrils of darkness extend from the caster’s hand, latching onto a foe with ephemeral force. The shadows cling like wet cloth and tug at the target’s limbs, making movement briefly difficult.', 'Umbrakinesis'),
  (964, 'skill-56ffe6881a1a05f62fddf7b9d4b27e834d1dba4964bcba91a6f3d1d1485e294d', 'Umbral Cloak', 'psionic skill', 3, 'WIS', NULL, 'A haze of shadow wraps around the caster, softening their outline and dimming their presence. Edges blur into surrounding gloom, making them harder to target during the fleeting veil.', 'Umbrakinesis'),
  (965, 'skill-0db43e151ceb7e6fede1e3c0e459e67cc883d05b422c6b7d5bd507dd82bf0581', 'Flicker Step', 'psionic skill', 3, 'WIS', NULL, 'The caster melts into a nearby patch of shadow and reappears up to a few paces away with a ripple of darkness. It is a quick, limited step that relies on connected shadows.', 'Umbrakinesis'),
  (966, 'skill-2fc2d631c0f3c09caa947e7a3d998bfcd5a74dcb3830d43d34d5125b68bdd807', 'Shadow Snare', 'psionic skill', 3, 'WIS', NULL, 'From the ground, shadowy tendrils lash out in a spreading fan, tangling around nearby foes. The bindings pull taut; movement falters as the dark grips and drags at ankles and wrists.', 'Umbrakinesis'),
  (967, 'skill-c82d264a9fa816e00cc8a6c0af33be0439235834c6fcf3fdddcbe08c04046c7a', 'Cloak of Midnight', 'psionic skill', 3, 'WIS', NULL, 'An enveloping mantle of shadow spreads over multiple allies, dimming their outlines and swallowing footfalls. Enemies struggle to land clean hits as the night itself seems to slide across the veiled forms.', 'Umbrakinesis'),
  (968, 'skill-248b290c11b5bc97892a9d277941a6acff4a886df10c74da0e40fe5e448d7770', 'Umbral Step', 'psionic skill', 3, 'WIS', NULL, 'The caster and a chosen ally slip into connected shadows and reappear a short distance away, silhouettes shredding into smoke before reforming. It’s a swift, practiced tandem step through the dark.', 'Umbrakinesis'),
  (969, 'skill-b8cd448c6fc95f7f5fceb1736aeef912cde513f2b4403460218fa0c036527a35', 'Eclipse Shroud', 'psionic skill', 3, 'WIS', NULL, 'The caster draws shadows from every corner, weaving them into a dome of suffocating gloom. Within, allies move unseen while enemies falter, their strikes wild and senses dulled. The shroud blurs vision, muffles sound, and weighs on the will.', 'Umbrakinesis'),
  (970, 'skill-39932904e8d5444c66caf47061db388138b3d67c1dc5d1121fe9ac78f47d1c19', 'Nightfang Manifest', 'psionic skill', 3, 'WIS', NULL, 'The caster rips a fragment of shadow loose, shaping it into a snarling beast of teeth and smoke. The phantom lunges at foes, biting with ephemeral jaws and tearing through courage as much as flesh. It is a temporary, vicious summon.', 'Umbrakinesis'),
  (971, 'skill-e992bc763e6892645fb6268284f180352f041c7bff50248f7c8a9cc4e8feac4e', 'Shadow Maw', 'psionic skill', 3, 'WIS', NULL, 'An immense rift opens beneath the foe, jaws of darkness snapping upward to drag them down. The maw clamps with spectral teeth and shadowstuff, pinning the victim in place while gnawing away both body and resolve.', 'Umbrakinesis'),
  (972, 'skill-9eb22637dcbc55dc799635de30d7fa3b9eeb9f276a6c948171c2ea6331fc0a2d', 'Shadow Cataclysm', 'psionic skill', 3, 'WIS', NULL, 'Shadows erupt in a devastating surge, forming a massive storm of claws, tendrils, and shrieking void-winds. Within the storm, enemies are clawed, blinded, and dragged by ephemeral forces while allies risk being caught in the chaos. The battlefield becomes a writhing field of darkness where direction and courage collapse.', 'Umbrakinesis'),
  (973, 'skill-9b9aa6389d01057d7f35270049766ac3fc3f5faa308b0030a10d519a2cabf2f0', 'Eternal Eclipse', 'psionic skill', 3, 'WIS', NULL, 'The caster blots out light itself across the battlefield, creating a dome where vision, sound, and even hope falter. Enemies stumble, allies vanish into concealment, and only those attuned to shadow can move with confidence. The eclipse feels like the sky itself collapsing inward, crushing will as much as sense.', 'Umbrakinesis'),
  (974, 'skill-a5d97c4910f98415d4b77267cedf170bd38d922e2e6b8cc042903f5697691c8f', 'Oblivion Eclipse', 'psionic skill', 3, 'WIS', NULL, 'The caster pulls all shadows across the battlefield into a single cosmic convergence. A vast dome of living night descends, swallowing light, sound, and matter into suffocating nullity. Within, foes are crushed by shadow-tendrils, drained of vitality, and risk being erased entirely. Allies move unseen but must resist the same consuming dark. The eclipse does not simply obscure—it threatens to overwrite existence itself.', 'Umbrakinesis'),
  (975, 'skill-d4cc56aa47e0b5c789d492c0b1363ec44b73cd41adfdaa02860ed36d523ebf4c', 'Anger', 'resonance', 2, 'CHA', NULL, 'You channel the raw fury buried in the human voice—vibrations that shatter calm and ignite conflict. This resonance stirs adrenaline, provokes confrontation, and can push allies or enemies to reckless extremes.', 'Resonant Performance'),
  (976, 'skill-4d42673c68d4290cd86764ffb8ee6a91dd66fda7c1bac033a91bb29b2a06ce81', 'Spark of Wrath', 'reverberation', 3, 'CHA', NULL, 'The bard’s sharp note or cutting phrase ignites a target’s inner fury. Muscles tense, resolve flares, and each strike carries a little more weight. Though simple, it is the first step of turning emotion into a weapon.', 'Anger'),
  (977, 'skill-8f8ba5d4374f42db4cee5f47fe8f6776b8de29844a3c86fb16f7703317160ea3', 'Heckle', 'reverberation', 3, 'CHA', NULL, 'The bard unleashes a biting insult or mocking chord that rattles an opponent. The target’s anger spikes but turns unfocused, leaving them less precise in the moment.', 'Anger'),
  (978, 'skill-77b548cbed4d5863f8abe2bbaf844026a64d5695344206be72d4bcac653fa50a', 'Ember of Fury', 'reverberation', 3, 'CHA', NULL, 'The bard strikes a resonant war-beat that quickens pulses among nearby allies. Feet tap, breath quickens, and initiative sharpens as the ember of fury spreads.', 'Anger'),
  (979, 'skill-242f110aecbc5a89d54013f2f3a4ae3a331ac6e09f9d14ca8d9bbd0fc3e51e38', 'Stoke the Line', 'reverberation', 3, 'CHA', NULL, 'The bard hammers out a driving battle-chant that swells into a shared fury. The sound tightens grips, sets teeth, and turns hesitation into hot resolve. Within the circle of sound, allies’ strikes grow surer and land harder, their cadence syncing to the aggressive rhythm. The aura doesn’t overwhelm judgment; it focuses anger into clean, deliberate action. Shields bunch together, spears tilt forward, and a red shimmer pulses at the edge of vision. The chant is infectious but controlled, a forge that tempers rather than shatters. Even the timid find a spark—enough to push, enough to hold. As the round crests, the heat recedes, but the echo lingers in memory and stance. Used well, it flips a stalemate into a push. Used poorly, it can bait allies into overextending.', 'Anger'),
  (980, 'skill-7e3c41fb73e30aeca3d4703b4c45e38eda0dd1dfbb80e2e15a1b5595dc3ea76f', 'Incendiary Rebuke', 'reverberation', 3, 'CHA', NULL, 'The bard lashes a foe with a scorching phrase—anger spikes, but it scatters their focus. The target bristles, grip tightens, and precision bleeds away. The insult is crafted to hook pride, not panic, so it doesn’t freeze them—it just makes their next choices worse. Blades come in heavy, not careful; spells fling fast, not true. The sound hangs in the air like heat off stone, then snaps shut around the target’s aura. Allies feel the tension break; opportunity opens. The bard watches for the stumble—this is the beat to press. With discipline, the party converts frustration into advantage. With carelessness, the foe’s rage may still explode in a lucky swing.', 'Anger'),
  (981, 'skill-93fe5f62e30b46253fb2ecbd0b04fadef60b80177360b14e2950c98893c31fc5', 'Sweeping Roar', 'reverberation', 3, 'CHA', NULL, 'The bard erupts with a wall of sound that hits like a shoulder-check from the front line. The wave doesn’t just frighten—it weaponizes anger into motion. Shields jolt, feet skid, and those unready crash to the floor as the roar plows through the rank. It’s a clean blast: no blood, just force, dust, and pride. Veterans brace and hold; the unsteady go tumbling. The air ripples crimson for a heartbeat then clears, leaving openings where order just was. Used to break a shield wall or to create breathing room, it is the sound of momentum changing hands. Overuse can leave the bard winded and predictable; timed right, it’s a fight-winner.', 'Anger'),
  (982, 'skill-7f43fe2c02e5ccf4569519209adf5c23cea85c608a948ca192154640f16db7f9', 'Battle Hymn of Fury', 'reverberation', 3, 'CHA', NULL, 'The bard unleashes a pounding anthem that spreads like fire across the battlefield. Allies seize the rhythm, weapons crash harder, and hesitation burns away. The song does not merely embolden—it fuses rage into a collective tide. The chant spreads through stomps, claps, or drumbeats, saturating the area in martial fury.', 'Anger'),
  (983, 'skill-80447e56e23e6372c3da14994a40bfb25c8e4136c31f791aa770e3b4bfcf98ef', 'Vexing Aria', 'reverberation', 3, 'CHA', NULL, 'A jagged performance—half shriek, half string-cutting chord—splinters the composure of foes. Rage surges uncontrolled, breaking precision and timing. The aria does not silence them; it drives them into clumsy overreach.', 'Anger'),
  (984, 'skill-00d3575fe4ac68edb94865f5e10a5b4e95bd131cf3a49e5daa25a00bf1c83ed4', 'Ragequake', 'reverberation', 3, 'CHA', NULL, 'The bard roars, striking the ground or stomping a rhythm that bursts outward in a shockwave of fury. The quake doesn’t just shake the earth—it shakes composure. Those caught stumble, collapse, or are driven back by the sheer ferocity resonating from the bard.', 'Anger'),
  (985, 'skill-0c83ef55af662c93837f5ba945d8374dfd27ba86a8ed2f289533d7788cca4f10', 'Wrath Unleashed', 'reverberation', 3, 'CHA', NULL, 'The bard bellows a resonant fury that floods allies with disciplined wrath while shaking enemy composure. Within the crimson sphere, friends strike harder, faster, and truer; foes grit teeth and overreach as precision frays. The chant is a forge’s roar, turning a scattered melee into a rolling advance.', 'Anger'),
  (986, 'skill-3b13d7c9bca8af02a1e9cc4643e773cae98fbb2c30e644ac30e2f5ef4395ce7b', 'Seismic Fury', 'reverberation', 3, 'CHA', NULL, 'The bard slams rhythm into the earth; a wrathquake blasts outward, hurling bodies, cracking lines, and leaving a churning zone of hostile footing. Dust blooms red in torchlight, stones jitter, and even veterans feel their stance go uncertain as anger hums beneath their boots.', 'Anger'),
  (987, 'skill-bb525cbe4185d85b5a97498769f40bd9624e2fb5c925e59d00e7383be752c993', 'Rage Dominion', 'reverberation', 3, 'CHA', NULL, 'The bard crowns the battlefield with a dominion of wrath. A blood-red wave surges outward, saturating the air with heat, grit, and pounding drum-beat thunder. Within the sphere, allies feel a disciplined surge—fury sharpened to precision—while enemies lose control, their rage devolving into sloppy violence. Weapons strike truer, blows land heavier, and timing sharpens under the bard’s rhythm. The ground trembles, dust hangs in the air, and every heartbeat falls in sync with the furious chorus. A second pulse follows: a crushing command that staggers foes, dropping some to knees while freezing others mid-motion. The zone itself warps—space thickens, movement drags, and occasional stutters in time cause actions to falter. For three rounds the battlefield belongs to the bard; even when the chorus fades, echoes haunt both steel and spirit.', 'Anger'),
  (988, 'skill-58d54e7c7553ce1fd758e8710a6a249e059578aead259fdf21a3fbd755be8129', 'Fear', 'resonance', 2, 'CHA', NULL, 'A performance laced with dread, causing the unseen to feel closer and the known to feel unsafe. This resonance fractures bravery and distorts judG.O.Dent—summoning silence or panic in its wake.', 'Resonant Performance'),
  (989, 'skill-549197266b0924ec6b1e57bcca8cb0d8ce6a25a30a9ca6ebeee72c2d0d9889cf', 'Echo of Unease', 'reverberation', 3, 'CHA', NULL, 'The bard hums a low, wavering note that seems to echo in the listener’s bones. An invisible weight presses on the mind, magnifying every shadow and whisper until hesitation takes hold. Though subtle, the dread can tilt the balance in tense moments.', 'Fear'),
  (990, 'skill-f39789404f00bbc0bcc5200ea77b6a89ebdeaee1f4e2c05ce2b0c5dfc4eefc54', 'Shuddering Chord', 'reverberation', 3, 'CHA', NULL, 'A sharp, discordant note rips through the air, sending a jolt of panic through the target’s nerves. The effect is immediate: a stumble and a hard fall as instinct overrides poise. The terror fades quickly, but the opening it creates can be decisive.', 'Fear'),
  (991, 'skill-56e1efd75493703645662421c316a481fd5c23012a859e33a3848a1044027cdb', 'Lingering Paranoia', 'reverberation', 3, 'CHA', NULL, 'The bard’s cadence crawls under the skin, tightening breath and quickening glances. Every step feels watched; confidence erodes in a heartbeat-long shiver that throws timing off.', 'Fear'),
  (992, 'skill-30a2962396164825fb25d18d0f2bc1f7430d905d1c3386c5906749e6461d3c6a', 'Phantom Footfalls', 'reverberation', 3, 'CHA', NULL, 'A hushed performance sends ghostly steps echoing just behind the target, always a half-pace late. Their pulse races, their grip slips, and every glance back finds only empty air. Panic disrupts poise, forcing costly mistakes.', 'Fear'),
  (993, 'skill-9de8b1542fd87026403a38b6c1eeb0cc42f775eeee8f32f4b207b109cd961654', 'Crushing Dread', 'reverberation', 3, 'CHA', NULL, 'The bard’s dirge drags like a weight on the chest. Muscles weaken, knees tremble, and the heart feels heavy as if the air itself resists motion. The victim staggers under a burden no one else can see.', 'Fear'),
  (994, 'skill-cd397544517fb3d1a447bc2b2e547a40e608f25f64b6317d11332b36d600f01b', 'Terror Pulse', 'reverberation', 3, 'CHA', NULL, 'A jagged chord bursts outward, splintering courage in all who hear it. For a heartbeat the world narrows to pounding blood and the urge to flee. Most shake it off quickly, but that heartbeat is all the bard needs.', 'Fear'),
  (995, 'skill-b08dd34c781c499c4bda79488e4d2266ae225252b43c7f57ba4614bb2cbba779', 'Chains of Dread', 'reverberation', 3, 'CHA', NULL, 'The bard’s chords twist into spectral rattling, summoning phantom chains that lash around those nearby. The chains are not real—yet the weight of terror binds flesh and mind alike. Victims struggle to move, convinced their limbs are shackled.', 'Fear'),
  (996, 'skill-74c511af61fd85e6b634e489859e6597387c76776769e7505285f1b981ea9af7', 'Harrowing Dirge', 'reverberation', 3, 'CHA', NULL, 'The bard unleashes a low, continuous dirge that seeps into the target’s soul. Breath grows shallow, limbs weaken, and every instinct screams to retreat. The song erodes strength, will, and timing all at once until only dread remains.', 'Fear'),
  (997, 'skill-61fde935da32d8e29edc80fd2b0928f886cd613e177e321a078b9a3dfc0ac51b', 'Phantasmal Host', 'reverberation', 3, 'CHA', NULL, 'The bard crescendos into a horrific chord that tears at the veil of imagination. Around the bard, enemies see spectral figures closing in—wraithlike soldiers of nightmare. Though unreal, their terror has weight: foes stumble, falter, and strike poorly.', 'Fear'),
  (998, 'skill-dd13d6a9611a94c48fa7af3279033db8a3901c10d2724e034b5bebf773bee515', 'Cacophony of Nightmares', 'reverberation', 3, 'CHA', NULL, 'The bard unleashes a hideous chorus of layered screams, whispers, and sobs that erupt in the minds of all nearby. Each victim sees their deepest fear reflected in phantom form, while their bodies lock under the imagined assault and the air itself seems to press in.', 'Fear'),
  (999, 'skill-178e129b80d8c8a32b50d023de4c116cdb0c7247036cd56cefc3bb3c1a2ef446', 'Grasp of the Pale Host', 'reverberation', 3, 'CHA', NULL, 'From the bard’s performance surge spectral arms—pale, eyeless figures that claw and drag at those nearby. Though unreal, the terror binds as if real while the space around the victims thickens, dragging at their steps and breath.', 'Fear'),
  (1000, 'skill-92bdb1e423ff78ae76b1e94b2498f1ae77a440053dedc926cc39dcfb5aadaf55', 'Nightmare Dominion', 'reverberation', 3, 'CHA', NULL, 'The bard unleashes the ultimate chord of terror, collapsing the battlefield into a waking nightmare. The air curdles into shadow, phantasms swarm, and time itself drags beneath the weight of collective dread. Every enemy sees their worst fear stalking them, while allies feel their courage tested by the same oppressive vision. Movement halts, resolve breaks, and the world becomes a prison of fear.', 'Fear'),
  (1001, 'skill-b113405b6f9114b2abac7676f6868df33b0dde53f2e0ddd0f5340392563ab5f3', 'Joy', 'resonance', 2, 'CHA', NULL, 'Through brightness of tone and uplifting cadence, you stir laughter, courage, and spontaneous connection. This resonance cuts through despair and can lift entire groups into sudden unity or euphoria.', 'Resonant Performance'),
  (1002, 'skill-1c1e717ac99caaf75d3fe35cde2ef8b69605c8c772f325f8dfb1a2907de8450b', 'Spark of Laughter', 'reverberation', 3, 'CHA', NULL, 'With a playful note or witty flourish, the bard sparks laughter in their target. Shoulders lighten, breath eases, and the weight of battle briefly lifts. Though fleeting, the joy kindles resilience, granting just enough strength to stand firm.', 'Joy'),
  (1003, 'skill-1b62802ba317ae0e1a6398b795ae49ffbf1a4c6524b4e1bd46085ef3e90e5cdc', 'Gentle Reprieve', 'reverberation', 3, 'CHA', NULL, 'The bard hums a soft phrase, a balm of sound that soothes an ally’s weariness. Tension unwinds, and the heart steadies. The joy does not heal wounds, but it restores spirit, easing pain’s edge for a moment of reprieve.', 'Joy'),
  (1004, 'skill-cde6737e88876babd134dfc63972a51e048f9cf44c50645204d2dcc90a5ca702', 'Joyful Guard', 'reverberation', 3, 'CHA', NULL, 'The bard strums a playful trill or claps in rhythm, weaving joy into a protective veil. For a fleeting moment, laughter seems to hang in the air like a shield, catching blows before they land. Allies feel their courage reinforced, knowing even harm bends beneath the weight of happiness.', 'Joy'),
  (1005, 'skill-e0f6cbd620ac7066ae4636d500f32a12c8149c494f1b680b2e1bf39c26a9fd9c', 'Chorus of Delight', 'reverberation', 3, 'CHA', NULL, 'With a rising refrain, the bard’s music spills outward, harmonizing hearts in a radiant chord. Allies feel their movements sync as if part of a single rhythm. The melody uplifts, pushing hesitation aside with laughter and confidence.', 'Joy'),
  (1006, 'skill-d4a792de800b47f654a1ff08c4aa1ec0cf138a713bacdc73b3e782248fbc52f3', 'Festival Spark', 'reverberation', 3, 'CHA', NULL, 'The bard strikes up a tune that feels like the opening of a festival—drums, strings, or clapping that ignite a spark of celebration. Even in dire battle, spirits flare. Allies grin, cheer, and rally, fighting harder as if the world itself applauds them.', 'Joy'),
  (1007, 'skill-6ef97bbe632d8d917c0a683fdbfc9ebced6deae1d29cc14c73387ba925364f7e', 'Echo of Resilience', 'reverberation', 3, 'CHA', NULL, 'The bard’s note reverberates in the soul like a remembered triumph. Pain dulls, breath steadies, and allies feel courage swell. This is not raw healing—it is defiance in sound, a will to endure that pain cannot silence.', 'Joy'),
  (1008, 'skill-3693ab3e70fb0af6f9f1892fabd606805498f7f8a4cc56b0df5c03af4f2a04f4', 'Radiant Harmony', 'reverberation', 3, 'CHA', NULL, 'The bard releases a powerful harmony that unites allies in radiant joy, their movements sharpened and their spirits lifted in perfect sync.', 'Joy'),
  (1009, 'skill-1f560979a2845aa746f393d20daca378c1d93aa48d626f6a7fcef2348539c3b0', 'Carnival of Courage', 'reverberation', 3, 'CHA', NULL, 'The bard conjures the spirit of a grand festival, where music and courage drive away despair. Allies fight as if emboldened by the cheers of an unseen crowd.', 'Joy'),
  (1010, 'skill-fcbd1ec70a4fdbb6543a4888ccb2df9699b35511f083ce1a113a8a7d0b73e32f', 'Ballad of Shared Triumph', 'reverberation', 3, 'CHA', NULL, 'A triumphant ballad heals several allies at once, sharing the vitality of joy across the battlefield.', 'Joy'),
  (1011, 'skill-aafe1c4e77e02274dbe22260cd421037e06af8cbcb4bb50ff2050c0608ddfb91', 'Symphony of Exultation', 'reverberation', 3, 'CHA', NULL, 'A sweeping, exultant performance floods the field with relentless joy—precision, speed, force, and poise moving as one—and even dread struggles to take hold.', 'Joy'),
  (1012, 'skill-2ae51e37d5582a21f279bbf1b83358a9282b6262981e49cc5f54de01e9154716', 'Revelry Unending', 'reverberation', 3, 'CHA', NULL, 'A tidal festival of sound and motion turns the ground itself into a jubilant arena—attacks hit harder, armor holds truer, wounds mend, and the very space invites dancers to flow.', 'Joy'),
  (1013, 'skill-34e9062e5a5e4f586e0d4a5a03cd6f751ca4b08b19da037943d4c0e58c380d1b', 'Eternal Jubilee', 'reverberation', 3, 'CHA', NULL, 'The bard unleashes the supreme festival of existence, a resonance so vast that joy itself becomes the battlefield’s heartbeat. Allies surge with unity, wounds close in radiant laughter, despair shatters, and even foes stagger in awe as sorrow cannot hold its shape.', 'Joy'),
  (1014, 'skill-686f746a95b6f836d7d70567c302c3f9ebb5ee0def3d1220ee9d4e9f34f5e131', 'Love', 'resonance', 2, 'CHA', NULL, 'A gentle but powerful resonance that opens hearts and builds trust. Whether kindling connection or softening hardened spirits, the resonance of love works through empathy more than force.', 'Resonant Performance'),
  (1015, 'skill-56bced705ad19533973306302dddb6d0119d3272a3798ae85316601b19b1f13f', 'Heart’s Whisper', 'reverberation', 3, 'CHA', NULL, 'With a gentle chord or whispered lyric, the bard reaches into a single ally’s heart. A warmth blossoms in their chest, steadying breath and calming fear. Though no great wound is mended, the target feels supported, their resolve no longer wavering. This reverberation is often used before battle or in moments of quiet grief.', 'Love'),
  (1016, 'skill-05cbc606c5a286d0460fb351511812c37771d8fdf91a976511ca6f31e1896a11', 'Bond of Trust', 'reverberation', 3, 'CHA', NULL, 'The bard weaves a short refrain of loyalty, binding allies in trust. Two companions feel their confidence grow as they act in harmony, encouraged by the resonance. Movements synCHAonize subtly, attacks land more decisively, and they find comfort in shared purpose.', 'Love'),
  (1017, 'skill-c52c006bd52e408cf8820176dacf4c5ed60d67ae92df91604784b23ed7baf811', 'Unveiled Affection', 'reverberation', 3, 'CHA', NULL, 'The bard strikes a simple but resonant chord that draws forth hidden feelings. A single target’s emotional guard weakens, revealing hints of what they truly hold within. Allies may sense hesitation, affection, or even suppressed devotion. While not harmful, it can be a potent tool for connection or uncovering truth.', 'Love'),
  (1018, 'skill-c55facac1d4a94d39eae8b5e76b6d65e089320459cc53fa317d882dea25f6c1c', 'Harmony’s Embrace', 'reverberation', 3, 'CHA', NULL, 'The bard strums a rising chord that enfolds allies within reach. Those touched by the resonance feel fear fade and their courage ignite. Their steps fall in rhythm with one another, striking more surely and moving with confidence born of unity.', 'Love'),
  (1019, 'skill-86b6e800964da24878ecb9a213f84f8c82ddead32db59aebb0f92cb5626bd54b', 'Mending Serenade', 'reverberation', 3, 'CHA', NULL, 'A gentle melody spreads like a warm tide, softening pain and stitching wounds of both body and heart. The bard’s song fills the air with reassurance, easing the strain of battle and giving allies the strength to continue.', 'Love'),
  (1020, 'skill-ba17b3b59769f913b28988f0d1017ee307dd782bd96bb5751a107e022160a347', 'Revelation of Hearts', 'reverberation', 3, 'CHA', NULL, 'Striking a clear, resonant note, the bard exposes the truths that linger beneath words. Those caught in the tone find their pretenses slipping, unable to fully hide their emotions or intent. The spell is not cruel — it reveals only surface feelings — but it can turn suspicion to trust or expose subtle deception.', 'Love'),
  (1021, 'skill-c8622c54e05fc0cefbba87f60f7fcee1104bb50d1da0b087912ed75eda9ce8d6', 'Symphony of Devotion', 'reverberation', 3, 'CHA', NULL, 'The bard weaves a layered harmony that fills allies with determination. Each note bolsters their strikes and movements, uniting them in one rhythm of purpose. The song drowns out hesitation, lifting the group into a shared momentum.', 'Love'),
  (1022, 'skill-3a408057ee2887d700f7f427d44467cc0f901e83cd6b8ce737a4609262a905a6', 'Healing Chorus', 'reverberation', 3, 'CHA', NULL, 'With a sweeping melody, the bard calls forth a wave of restorative sound. The resonance pours over allies like warm light, mending flesh and spirit alike. Wounds knit partially closed, while hearts steady with courage to continue.', 'Love'),
  (1023, 'skill-69f022bdceed82ff63f0c4e71500b17c50d9c33992e6b509ab18f766e9a8f468', 'Revelation Aria', 'reverberation', 3, 'CHA', NULL, 'The bard releases a resonant aria that pierces through deception. Within its reach, lies falter, hidden emotions surface, and facades collapse. Allies see one another with raw clarity, while foes cannot conceal their intent.', 'Love'),
  (1024, 'skill-aa521dd18d2164ca6429212966b66cffaa9409757262cefbc091d0137a773642', 'Eternal Vow', 'reverberation', 3, 'CHA', NULL, 'The bard sings a vow so profound that bonds between allies become unbreakable. Each ally feels their life tied to the others—when one falters, another steadies them. Wounds are shared, courage is pooled, and betrayal becomes nearly impossible under the sacred harmony. Enemies attempting to divide them find their influence broken.', 'Love'),
  (1025, 'skill-59039c8108eacabc95dac55cd253524c8528019ca55b257583919e00c569e588', 'Aria of Sacred Union', 'reverberation', 3, 'CHA', NULL, 'A sweeping aria binds allies’ hearts in radiant trust while exposing enemies’ malice. Allies become harder to break apart, gaining initiative and resilience, while foes within are forced into honesty—deception or betrayal withers in their throats.', 'Love'),
  (1026, 'skill-f35bd33843a56da68c1420abb7492ca99052a4ccd88c2916180d534e8ce11ee1', 'Concordance of One Heart', 'reverberation', 3, 'CHA', NULL, 'The bard exhales a world-filling chord that binds every soul within sight into a single, luminous accord. The sound is not tender—it is sovereign: a living vow that stitches allies together and stills hostile intent. Armor hums, breath steadies, and movements synCHAonize as if guided by one unseen conductor. Wounds soften as strength passes between comrades, and each strike finds purpose born of trust. Masks crack; even foes feel their motives laid bare beneath the current of undeniable empathy. The air thickens like warm glass as space itself bows, slowing hostile motion and holding violence at bay. Every heartbeat inside the field becomes a drum in the same song, and the song refuses to break. To challenge it is to stand against the simple truth that love, shared, is stronger than fear, alone. When the last overtone fades, those who stood together carry its resonance in their bones.', 'Love'),
  (1027, 'skill-2cdbdd82910725464b02099ee9baf90cf29520d623b110d972c222d34f6425eb', 'Sorrow', 'resonance', 2, 'CHA', NULL, 'A haunting melody that calls forth memory, loss, and longing. This resonance reveals hidden pain, stirs reflection, or bonds strangers through shared grief. It is the silence between notes that carries the deepest power.', 'Resonant Performance'),
  (1028, 'skill-c3b178f6706681f3b98c9ea7814138320a860d9b8613dfd75853fae508779ade', 'Tearful Lament', 'reverberation', 3, 'CHA', NULL, 'The bard’s voice cracks with aching sorrow, tugging at the heartstrings of a chosen listener. A weight settles on their chest as tears well unbidden, clouding judgment and dulling their resolve for a fleeting moment. While it does no lasting harm, the lament forces them into a brief wave of grief, blurring their focus.', 'Sorrow'),
  (1029, 'skill-21faaca9ba98affd16e24998b68d9294cd9be978fcd8aa3fb1dd587d247505e3', 'Echo of Mourning', 'reverberation', 3, 'CHA', NULL, 'A soft, haunting phrase ripples through the air, settling into the heart of an ally or foe. For allies, it provides a strange catharsis—tears shed ease a burden they did not know they carried. For foes, the same tears blur their vision and slow their strikes. In both cases, the echo leaves silence in its wake, a hollow reminder of grief shared.', 'Sorrow'),
  (1030, 'skill-482fea42810adb14782045b943f5c6d448fb80a514337521c5250684363456f6', 'Steal the Smile', 'reverberation', 3, 'CHA', NULL, 'With a dissonant chord or mocking line, the bard strips the warmth from their foe’s heart. The target feels their spirit sag, movements dulled by the absence of joy. A cruel twist of resonance that leaves one empty-handed in the fight.', 'Sorrow'),
  (1031, 'skill-65028d86b75affd140b480f229106e746513bd9330f8541d34167fd9e0c04118', 'Dirge of Weariness', 'reverberation', 3, 'CHA', NULL, 'A mournful chant pours from the bard, heavy as chains. All within its reach feel the creeping weight of despair, their arms sagging and their steps faltering. Even the keenest blades seem dulled under the dirge’s pull, leaving combatants weary and hesitant. Though brief, the dirge is a chilling taste of hopelessness.', 'Sorrow'),
  (1032, 'skill-323bcce7c158fcaf7b765468fa5d739083f2d7c3bc57dd504fd779b601bf2faa', 'Lamenting Shackles', 'reverberation', 3, 'CHA', NULL, 'The bard’s sorrow-laden tones solidify as spectral chains of grief that coil around a target. The chains drag at heart and limb alike, sapping strength while binding the will to act. Struggling against them only deepens the sense of futility.', 'Sorrow'),
  (1033, 'skill-7ec5d2643f69271d5eb84f9d1cc5a505e9484f5d474bdac72811aabcccbaeb0a', 'Wail of the Forsaken', 'reverberation', 3, 'CHA', NULL, 'The bard unleashes a piercing cry of grief that echoes like a battlefield dirge. The sound rattles weapons in hands, pulls at the heart, and brings soldiers to their knees with despair. Those caught in the sound suffer blurred vision, faltering aim, and a crawling weakness in their limbs.', 'Sorrow'),
  (1034, 'skill-0a7190a13fd877b7d6e0db3ee36d1235d9a5a8f62dcc94f021bdd54134bf7218', 'Chains of Melancholy', 'reverberation', 3, 'CHA', NULL, 'A haunting song manifests as spectral chains that lash out to bind multiple foes at once. Each victim feels both physical restraint and the weight of despair pressing down on their hearts. Breaking free requires not just strength, but the will to overcome sorrow itself.', 'Sorrow'),
  (1035, 'skill-5c59ae49eecd02d6b0aeaf5a79371179a69d71701eb1ba2a14b26b81e9e6433a', 'Dirge of the Hollow Heart', 'reverberation', 3, 'CHA', NULL, 'The bard sings a hollow hymn that gnaws at the soul. Within its reach, enemies are not just weakened — they begin to question the worth of fighting at all. Weapons sag, eyes lose fire, and every strike feels meaningless. The dirge turns battle into a scene of futility.', 'Sorrow'),
  (1036, 'skill-cc88274fdcf889848f2b72b8c313777760126ba3fcb1d3b6514f0555d217e3bd', 'Elegy of Despair', 'reverberation', 3, 'CHA', NULL, 'The bard’s voice becomes a death knell, a dirge so heavy that even the strongest falter beneath it. A black pall falls across the battlefield as the song resonates, draining resolve and withering strength. Warriors who once fought with fire in their eyes now stumble, blades feeling like lead. The elegy does not kill—it convinces soldiers that they are already defeated.', 'Sorrow'),
  (1037, 'skill-723e2c711e65f459d5ddf94e8639946174764f35d3c8ad6eb18153c9034ea49d', 'Funeral Chains', 'reverberation', 3, 'CHA', NULL, 'The bard’s sorrow becomes a storm of spectral chains wrought from grief itself. They lash outward in all directions, binding dozens at once. Each chain drags at flesh and spirit alike, slowing steps, sapping willpower, and fixing enemies in place. Even those who break free feel the rattle of the shackles in their bones, haunted by the echo of despair.', 'Sorrow'),
  (1038, 'skill-0eb3a565264175243eac497006ee4c82bb4437c07544c3a4a531a0f9ae431143', 'Cataclysm of Grief', 'reverberation', 3, 'CHA', NULL, 'The bard releases the ultimate dirge, a grief so profound it becomes a world-shaking force. The sky dims, the air trembles, and all within miles feel the weight of endless funerals pressing upon their soul. Enemies collapse in despair, allies weep uncontrollably, and the battlefield becomes a monument of sorrow. Blades slip from hands, knees buckle, and even the earth itself seems to mourn under the strain of the song. The cataclysm does not just hinder—it overwrites the mood of the world for minutes after the sound fades.', 'Sorrow'),
  (1039, 'skill-3354dbc82ee33f3b3165af4c3c6396388707b80b539676e6127098956d8ac9f9', 'Harmonic', 'resonance', 2, 'CHA', NULL, 'The purest form of balanced resonance—neither emotion nor intent, just raw vibrational symmetry. Harmonic resonance stabilizes or amplifies other performances, and can retune spaces or spirits to a higher state.', 'Resonant Performance'),
  (1040, 'skill-9f3eb2731a45a21193b2160c16f09d3314225a1a8503c38b950f9ecbd45d41d2', 'Resonant Shiver', 'reverberation', 3, 'CHA', NULL, 'A sharp note makes a fragile object quiver and shake, often cracking or breaking outright. To sturdier items, the vibration is little more than a rattle, but the sympathetic sound can echo across a room.', 'Harmonic'),
  (1041, 'skill-64f0556a8decf91c1d88447f741847b58d1cb25502dce060a379154825d76f58', 'Quantum Hum', 'reverberation', 3, 'CHA', NULL, 'The bard hums a low tone that ripples across the floor. Those nearby feel balance falter as vibrations disorient their steps. No harm is done, but accuracy suffers briefly.', 'Harmonic'),
  (1042, 'skill-e41e1f775779bbb5216eb203de3a893b32e3419cedb81694959cbd18de31d8e6', 'Tuning Note', 'reverberation', 3, 'CHA', NULL, 'The bard strikes a pure note into a nearby ally, aligning their inner rhythm. Breathing steadies and strength refocuses, mending the body slightly and boosting performance.', 'Harmonic'),
  (1043, 'skill-6c180c5e9db4b3c7aa6ada92a42063ff616d1e18468904d288f55c0633918e5d', 'Harmonic Lattice', 'reverberation', 3, 'CHA', NULL, 'The bard steps into stance and releases a measured chord that knits the air into a pressurized field. Dust eddies draw geometric patterns as the pressure gradient firms into a palpable zone. Within the boundary, footsteps feel heavy, leaps shorten, and thrown objects arc low as if the world turned thicker. The sound isn’t loud so much as exact—the kind of tone you feel in your teeth and knees. Armor plates creak; cloaks drag; arrows veer a hair off course. The lattice doesn’t crush or harm by itself; it simply reshapes movement, forcing combatants to commit to each stride. Tactical lines bend around the zone, giving the bard’s allies room to reposition and punish overextensions. Observers note a faint shimmer, like heat-haze with a grid hiding in it. On release, the air snaps back to normal, leaving the slightest taste of copper on the tongue. Veterans learn to ride the rhythm; fools try to power through and lose tempo.', 'Harmonic'),
  (1044, 'skill-1be9040bcc7d7c9403ad78bd44604a2ff7c0fb9d0c74f21a53bf9a54fd9936da', 'Dissonant Disarm', 'reverberation', 3, 'CHA', NULL, 'A clipped, discordant click shivers through steel and sinew at once. The bard aims the beat at a held weapon, making it buzz against the wielder’s grip like a hornet. Fingers reflexively open or the haft twists just enough to pitch free. The sound is small but humiliating, like being out of tune in front of a crowd. Sparks may flicker along the guard as micro-vibrations misalign skin and metal. Shields thump against arms; knives skitter across the floor; bows dip off target. The opening is brief but decisive, resetting the tempo of the exchange. Those ready for it can try to clamp down, but the beat is faster than the thought to resist. The resonance fades without lingering harm—only pride stings. Wise fighters learn to listen for that click and adjust their grip.', 'Harmonic'),
  (1045, 'skill-a07df771a4e875d50bc07f2de9e0edd7adbcc70b114fce5e7195a0548837fc5d', 'Chord of Coherence', 'reverberation', 3, 'CHA', NULL, 'The bard sustains a pure, centered tone that gathers listeners onto the same beat. Breaths synCHAonize, feet plant with intention, and eyes sharpen as micro-tremors clarify posture. Subtle overtones sweep the area, teasing out hidden currents—footfalls behind a curtain, a crosswind through an arrow-slit, a hinge that’s been lifted and set back. Allies feel a nudge of confidence as their micro-timing snaps into alignment. The space itself seems tidier, like clutter getting pushed to the edges of awareness. For a heartbeat, teamwork becomes obvious: who should press, who should anchor, who should feint. The tone never overwhelms speech; it nestles under it, a spine of sound. When it stops, the world feels fractionally duller but more understandable. The memory of the chord lingers as a cue to act cleanly.', 'Harmonic'),
  (1046, 'skill-c9ad56d7ad7544284c8e7874481032797ee821b026449c86fc67ffc8409291d4', 'Resonant Shatter', 'reverberation', 3, 'CHA', NULL, 'The bard singles out a weapon, shield, or object and strikes its resonant frequency. As the sound locks in, the vibration spreads outward, shaking nearby items in sympathy. The chosen target suffers most, while objects in reach quiver and splinter in lesser fashion. Allies hear the glass-like chime echo out, already knowing which cover is unsafe.', 'Harmonic'),
  (1047, 'skill-adc93b9d1162efa701bc4969da5201b4fae1b8718bffef2898f0442b6f54ecc4', 'Harmonic Shielding', 'reverberation', 3, 'CHA', NULL, 'The bard anchors protective vibrations onto one ally, wrapping them in a shimmering lattice of sound. From that ally, the harmonics radiate outward, damping strikes against their companions as well. Arrows bend slightly, weapons lose edge, and heavy blows arrive dulled. The lattice holds as long as the bard sustains the tone.', 'Harmonic'),
  (1048, 'skill-e8db4ac41455147f32970a127be83ce82b8568728a4d5f1e179b24b6f3db1f4f', 'Quantum Chorus', 'reverberation', 3, 'CHA', NULL, 'The bard seizes the tempo of battle by locking onto a foe’s rhythm. The chosen enemy feels their movements stagger and slip off-beat. The disruption spreads in sympathetic echoes, slowing their nearby allies, while the bard’s own companions feel a counter-pulse quickening their step. The chorus multiplies—out of one target, a battlefield ripple.', 'Harmonic'),
  (1049, 'skill-7bd4673cabee20f7ffbe944db0637a4f6a9a6ea794726d32a5fbc60acebd90fd', 'Fracture of the Infinite', 'reverberation', 3, 'CHA', NULL, 'The bard releases a note that should not exist, a pitch threaded between harmonics of the cosmos. The chosen object or creature becomes the anchor, and vibrations ripple outward in impossible waves. Nearby matter resonates, not breaking immediately but phasing through unstable states. Fragile structures crumble, weapons bend mid-swing, and even the air warps with translucent fractures. Those within the zone feel as though the world itself has been detuned, their bones vibrating in sympathy with the song. The effect is devastating but short-lived, as the universe recoils from the imposed resonance. When silence falls, the battlefield feels unnervingly hollow, as though part of reality was torn out of tune.', 'Harmonic'),
  (1050, 'skill-d791049eea0b5560ed6a006262da7debaff8611a0429bd3a4f2da3e05c3ca6a6', 'Symphony of Alignment', 'reverberation', 3, 'CHA', NULL, 'The bard summons a chorus of layered harmonics that bend not just sound, but probability itself. Allies in the field find their strikes land with eerie inevitability, while enemies falter as if forced out of rhythm with reality. The vibrations hum within bone and blood, aligning intention to outcome for a fleeting moment. The battlefield becomes a stage of inevitability: arrows curve mid-flight, swords slip perfectly into gaps, and shields lift just in time. Yet the price of such alignment is weight—the song presses heavily on all minds, threatening to collapse focus into a single, suffocating tone. When it ends, combatants stagger as though waking from a dream, remembering the inevitability of every motion.', 'Harmonic'),
  (1051, 'skill-386393e56b3e73264506a04c0ba8fa19d86daf1a2275ecb46b2b5aa1405a0ee0', 'Quantum Convergence', 'reverberation', 3, 'CHA', NULL, 'The bard strikes a note so pure it resonates with the lattice of reality itself. The chosen foe becomes the fulcrum of impossible vibration—every particle tugged between harmony and dissonance. From that anchor, concentric pulses radiate, drawing allies and enemies alike into the quantum storm. Blades bend mid-swing, glass melts without heat, and even time skips in fractured beats. Allies feel fleeting surges of clarity as their movements align with the resonance, while enemies stagger, their forms half-phased, voices distorted into echoes of themselves. The battlefield is transformed into a hall of mirrors where existence hums between what is and what could be. The convergence cannot last long—if sustained, it would tear the world into incoherent frequency.', 'Harmonic'),
  (1052, 'skill-b7b1a327d665c0ea7fa279598637532b78122d446968b269e2e07f371a9d4c62', 'Attribute Boosters', 'special ability', NULL, NULL, NULL, 'Attribute Boosters are special abilities that mark a single attribute a character can temporarily enhance through an active roll-over check. The player writes the chosen attribute after “Attribute Booster” (e.g., “Attribute Booster – Strength”). On a successful roll, the attribute increases by half the points allocated to this ability for 2 minutes or 1 combat step per success rolled. Example: 20 points in a Strength booster with a roll of 90% and 2 successes grants +10 Strength for the duration. Higher investments allow boosting multiple attributes at once following the scaling chart.', NULL),
  (1053, 'skill-f01425853059f00fd54ed3cb605c02e394b5a536bfae5542cc0e29148a71ddb7', 'Berserker Rage', 'special ability', NULL, NULL, NULL, 'Berserker Rage is a powerful combat ability that greatly enhances a character’s Strength, Dexterity, and Constitution, but carries the risk of losing control. Upon activation, these attributes increase by half the points allocated in this ability for 3 minutes or 2 combat steps per success rolled. The user must make a control roll; high success extends duration and keeps attacks focused, while failure results in indiscriminate attacks against all creatures in sight. Example: A roll of 75 against a needed 20 maintains controlled rage for an extended time; a roll of 55 may cause uncontrolled assault for several rounds. Berserker Rage is a high-risk, high-reward ability that can turn the tide of battle but may also endanger allies.', NULL),
  (1054, 'skill-d4eaf6cabcf9486cab92533e9302ab3cce1869fd71b123d5da2e1c24c8e3be37', 'Shape Shifting', 'special ability', NULL, NULL, NULL, 'Shape Shifting allows a character to alter aspects of their physical form temporarily, from minor cosmetic changes to full body transformations. Possible alterations include turning body parts into weapons, changing appearance, or taking on entirely different forms. At 0–10% skill, only minor changes like elongating hair or hardening fingernails are possible; higher skill increases complexity and control. A failed roll may trap the character in their altered form until a successful reversion roll is made. G.O.D and player should agree on limits based on campaign setting—some worlds may allow limitless transformations, others only cosmetic shifts. This ability is highly versatile for problem-solving, infiltration, and creative combat tactics.', NULL),
  (1055, 'skill-c3498d23facc805e89a840dfed7a268d6272451f6503beaef3055426c780683b', 'Wild Talents', 'special ability', NULL, NULL, NULL, 'Wild Talents are special abilities that mark a single innate magical, psionic, or bardic resonance effect chosen by the player at character creation or advancement. The player writes the specific effect after “Wild Talent” (e.g., “Wild Talent – Fire”). On a successful roll-over check, the user may manifest effects from the chosen sphere, discipline, or resonance without learning the full path. Points in this ability are multiplied by a set factor to determine the effective mana rating for that effect. For example, 10 points with a ×3 multiplier provides an effective 30 mana rating. Failure consequences are set by the G.O.D. and may range from minor mishaps to severe backfires.', NULL),
  (1056, 'skill-18640da16baead4833ac4017556c2acd9c4c514a9f0d5f350af1edce6289603e', 'Super Powers', 'special ability', NULL, NULL, NULL, 'Super Powers are special abilities that mark a single extraordinary non-magical ability chosen by the player at character creation or advancement. The player writes the specific ability after “Super Power” (e.g., “Super Power – Laser Eyes”). Each Super Power functions as an active-use roll-over check, with potency scaling to points invested. Common examples include elemental projection, enhanced senses, or physical feats beyond normal limits. To maintain balance, each Super Power has defined limits, weaknesses, or environmental conditions for use, set in agreement between the player and the G.O.D. On success, the chosen power functions at its current scaling; on failure, no effect occurs and the attempt may incur a minor drawback.', NULL),
  (1057, 'skill-06c3e5c4cc55386d688f38a5f7c1860a0c1c4f3cfb56704874f0b98a59675ae0', 'Telepathic Bond', 'special ability', NULL, NULL, NULL, 'Telepathic Bond allows a user to create mental links with other beings to share thoughts, emotions, and sensory experiences. At 10% skill, the bond is with one target within 10 ft, sharing basic thoughts/emotions. At 25%, range is 25 ft and complex ideas can be conveyed. At 50%, multiple targets can be bonded, max number based on points invested, with a 50 ft range. At 75%, sensory sharing is possible and range extends to 100 ft. At 100%, unlimited targets can be bonded within 500 ft, and sensory experiences can be swapped between bonded individuals. A failed roll can cause harmful feedback loops (all targets overwhelmed by emotions/sensory input) or inability to disconnect, risking exposure of private thoughts. This ability is powerful for coordination, espionage, and deep character connections but carries risks that keep it balanced.', NULL),
  (1058, 'skill-c1e4a637836b906692d075677e62a64dde12758654b460aec88fab5c0e1ef546', 'Shadow Manipulation', 'special ability', NULL, NULL, NULL, 'Shadow Manipulation allows the user to control and shape shadows for concealment, illusions, or creating tangible constructs from darkness. At 10%, the user can manipulate existing shadows within 10 ft for minor illusions or concealment. At 25%, range extends to 25 ft and small shadow constructs (weapons, tools) become possible. At 50%, range is 50 ft with larger constructs, powerful illusions, and the ability to blind or restrain a target in shadows. At 75%, range increases to 100 ft, shadow duplicates and short-range teleportation via shadows become possible. At 100%, range expands to 500 ft with the creation of powerful shadow creatures, large constructs, and wide-area darkness. Limitations include vulnerability to bright light, which weakens or disrupts control. A failed roll can result in loss of control, revealing the user''s position, creating hazardous constructs, or causing unpredictable shadow behavior.', NULL),
  (1059, 'skill-af7dcbd2fa96355dbadfdbf0bbd5f85c1fbea02052d3d9d59e8d351cf365f52c', 'Energy Channeling', 'special ability', NULL, NULL, NULL, 'Energy Channeling allows the user to manipulate one or more forms of energy (kinetic, thermal, electrical, magical, etc.) for offense, defense, or utility. At 10%, they can channel one energy type for minor effects (sparks, small temp changes, minor strength boosts). At 25%, they can channel two energy types and generate more potent effects (small electrical shocks, energy barriers, stronger physical boosts). At 50%, they can channel three energy types, create energy blasts, absorb/redirect attacks, or heal minor wounds. At 75%, they can channel four energy types, manifest energy constructs, shield allies, or manipulate energy within objects/creatures. At 100%, they can channel five energy types with vast control, including transforming into pure energy, controlling area-wide flows, or altering fundamental energy properties. Risks include energy overload, loss of control, backlashes, or injuries. Vulnerable to enemies who can nullify or counteract energy.', NULL),
  (1060, 'skill-c3ab1051b642cce7b99e9fc509521934adb0eb15acf83e0d7c863d5ee67e43c8', 'Gravity Manipulation', 'special ability', NULL, NULL, NULL, 'Gravity Manipulation gives the user control over gravitational forces. At 10%, they can subtly alter the weight of small objects to make them easier or harder to move. At 25%, they can affect larger objects or people, making them float or feel heavy. At 50%, they can create localized zones of altered gravity to hinder or aid movement/combat. At 75%, they can walk on walls/ceilings or briefly fly by manipulating gravitational pull. At 100%, they can create intense gravitational fields capable of crushing or repelling targets and objects. Effectiveness may vary in unusual gravity environments (space, other planets), where the G.O.D may require higher roll success or add restrictions.', NULL),
  (1061, 'skill-6c1dacd4f3c243010f517b548fa49137711777e27fe8a5716fb24672c9501a61', 'Spell Weaving', 'special ability', NULL, NULL, NULL, 'Spell Weaving allows a trained caster to merge multiple effects from a single system (Magic, Psionics, or Bardic Resonance) into a single casting. The effects must all be from spheres, disciplines, or resonances in which the caster is trained. Points invested in this ability determine how many effects can be woven at once. This ability is purchased separately for each system. Magic weaving combines magical spheres; psionic weaving combines psionic disciplines; bardic weaving combines bardic resonances. Failed weaving attempts may cause severe backlash or unintended combined effects at the G.O.D.’s discretion.', NULL),
  (1062, 'skill-fc93920b366e38275b5fde03c46d287b9c3dc140a9bdbc6591f518707f3de2aa', 'Adrenaline Surge', 'special ability', NULL, NULL, NULL, 'Adrenaline Surge taps into the body’s primal survival mechanisms, flooding the user’s system with a rush of energy, heightened awareness, and raw power. In the moments it’s active, every heartbeat feels like a drumbeat of war—reflexes sharpen, movement speeds up, and strikes hit harder. The rush comes at a cost: once the effect ends, fatigue sets in, forcing the body to recover from the sudden expenditure of resources. At higher mastery, the surge lasts longer, hits harder, and becomes easier to control, allowing the user to push themselves to incredible feats without collapsing afterward.', NULL),
  (1063, 'skill-eb3b147894db858b1ad61b6492976d494e023c4177f12288ef7092df6c964c00', 'Arcane Ward', 'special ability', NULL, NULL, NULL, 'Arcane Ward manifests as a shimmering barrier of magical force that wraps around the user or their allies, absorbing incoming damage before it can reach flesh or armor. The ward can block both physical and magical attacks, its strength and durability scaling with the user’s mastery. While active, it glows faintly, deflecting blows and dispersing spells into harmless sparks. At greater mastery, the barrier becomes capable of reflecting a portion of the damage back to attackers, turning defense into offense.', NULL),
  (1064, 'skill-3a37187cf67b6700b6fc06b8494eeff0544d15c9456e6973759e9075b24de81f', 'Battlefield Intuition', 'special ability', NULL, NULL, NULL, 'Battlefield Intuition grants the user an almost supernatural sense of the ebb and flow of combat, allowing them to anticipate enemy moves and adjust tactics before a blow is even thrown. This heightened awareness lets them dodge attacks more effectively and predict patterns in their opponents’ behavior. At higher mastery, this ability can feel like glimpsing the future, letting the user position themselves with surgical precision in any fight.', NULL),
  (1065, 'skill-d438d699f5d5424b97e99bc361a1a147d3460423e709626f4ec46d2c407f5c7d', 'Elemental Affinity', 'special ability', NULL, NULL, NULL, 'Elemental Affinity forges a deep bond between the user and a single chosen element—fire, frost, acid, lightning, or another force of nature. This affinity enhances all abilities tied to that element, increasing their damage and resistance to it. Over time, the user becomes so in tune with the element that they can shrug off lesser harmful effects entirely. Mastery represents near-complete symbiosis with the element, making the user a living embodiment of its power.', NULL),
  (1066, 'skill-e7c83e272dc4d9ec2c49ed32345c918389e37506430e17fdf4a57e36d284802c', 'Feral Instinct', 'special ability', NULL, NULL, NULL, 'Feral Instinct awakens the primal senses buried deep within the user’s mind, enhancing smell, hearing, and sight to near-animal levels. The user can track prey through scent trails, hear the quietest movements, and see in near darkness. As mastery increases, they can map an entire area through their senses alone, gaining unparalleled awareness of threats. At full mastery, these senses become so sharp they can resist sensory overload from blinding light or deafening noise.', NULL),
  (1067, 'skill-18afcb7faa4474fc35b3dfe3ea841bff40201bfe922e308f8c5bb6e27d7150a1', 'Kinetic Burst', 'special ability', NULL, NULL, NULL, 'Kinetic Burst unleashes a concentrated wave of physical or magical kinetic energy in a single explosive strike. The force radiates outward, dealing heavy damage and knocking enemies back. At higher levels, the radius and strength of the burst grow, staggering multiple foes at once and controlling the flow of battle. At its peak, Kinetic Burst becomes a devastating tool for clearing space and breaking enemy formations.', NULL),
  (1068, 'skill-0ab62b286492e694b96299b20a624504a79fb73b81bc3ad7877f312e9a029d6f', 'Phase Step', 'special ability', NULL, NULL, NULL, 'Phase Step allows the user to briefly step out of the physical plane, becoming intangible and able to pass through solid objects or avoid attacks entirely. With greater mastery, the user can move farther, phase through thicker barriers, and even teleport short distances. At the highest level, this technique enables extended phasing and multiple rapid teleports within the same engagement.', NULL),
  (1069, 'skill-f4c8e9de99a3b017c6366e6acc345131af514652b349adb58c023156db35da68', 'Psychic Shield', 'special ability', NULL, NULL, NULL, 'Psychic Shield projects a mental barrier around the user’s mind, blocking intrusive thoughts, telepathic surveillance, fear effects, and attempts at mind control. As the shield strengthens with mastery, it can repel increasingly powerful psychic assaults. At full power, the mind is entirely closed to unwanted influence, granting the user absolute sovereignty over their own thoughts and emotions.', NULL),
  (1070, 'skill-764df5722ab7675135c6e566768ae2477b3bae67ac69f5a1440fb56a8c35e610', 'Time Dilation', 'special ability', NULL, NULL, NULL, 'Time Dilation manipulates the user’s perception of time, making the outside world seem to slow while their own movements remain at normal speed. At low mastery, this grants quicker reaction times and faster strikes. At higher levels, it approaches the realm of “bullet time,” allowing the user to act while opponents appear frozen. At its peak, the user can operate for precious seconds in completely frozen moments, moving and acting while all else is still.', NULL),
  (1071, 'skill-266ffb94ecd4c7f6af9f4ec28ffbd7d6279ba97eb7eb5e79935af8eb03c1ac95', 'Weapon Bond', 'special ability', NULL, NULL, NULL, 'Weapon Bond forges an unbreakable connection between the user and a chosen weapon. The bond enhances accuracy, allows the weapon to be recalled instantly if disarmed, and eventually enables it to be imbued with magical or elemental effects. At maximum mastery, the user and weapon move as one—every strike perfectly timed, every defense instinctive.', NULL),
  (1072, 'skill-c92b31027bdf533829a2b28ca501144b0fa44c1f7aa21712717997d183b94e37', 'Combat Casting', 'special ability', NULL, NULL, NULL, 'Combat Casting is the refined art of channeling and releasing magical power in the heat of battle without sacrificing speed or accuracy. It allows the caster to weave spells seamlessly into melee or ranged engagements, reducing the penalties normally suffered when casting under pressure or while threatened. As mastery improves, the caster gains the ability to maintain concentration under duress, cast while moving, and even counter enemy attacks with instantaneous spells. At the highest levels, the user can unleash magic as fluidly as swinging a blade, making them a relentless threat in close quarters or chaotic combat situations.', NULL),
  (1073, 'skill-87caf3efcec93976a2b41878c2a9dc4a0f3492b4953eb2caee1345f1a631f125', 'Blood Frenzy', 'special ability', NULL, NULL, NULL, 'Blood Frenzy is a savage combat state triggered when the user draws or suffers blood in battle. Once activated, the user’s strength, speed, and ferocity spike dramatically, but their self-control diminishes. The more damage dealt or taken, the deeper the frenzy becomes, making attacks faster and more brutal at the cost of defensive precision. At high mastery, the user can channel the frenzy without losing control, becoming a relentless predator on the battlefield.', NULL),
  (1074, 'skill-d3272d1ab665c172bd15ed19471055dc508533f0df0a595632b3b41da9d7dd75', 'Iron Will', 'special ability', NULL, NULL, NULL, 'Iron Will is the mental fortitude to resist fear, intimidation, and coercion in all forms. Whether under magical compulsion, psychological warfare, or raw intimidation, the user’s resolve holds firm. At higher mastery, they can shrug off effects that would break lesser minds, and at full mastery, they become nearly unshakable.', NULL),
  (1075, 'skill-b6549931943c19b89009a173065be8eec27b033f37e3f3d55c27d7c07a98e854', 'Weapon Mastery', 'special ability', NULL, NULL, NULL, 'Weapon Mastery represents unparalleled skill and precision with a chosen type of weapon—swords, bows, axes, etc. Each level increases attack accuracy, damage, and access to special maneuvers. At the highest level, the weapon feels like an extension of the user’s own body.', NULL),
  (1076, 'skill-07f478d36d1c9efaf87127c94e977d57882ff24dc01ecec4e5c57dfef330ad08', 'Shadow Step', 'special ability', NULL, NULL, NULL, 'Shadow Step is the art of slipping into the darkness to instantly reappear from another shadow within range. It blends stealth, speed, and misdirection, making it ideal for ambushes and escapes. At higher mastery, the user can step farther, more often, and even attack while transitioning.', NULL),
  (1077, 'skill-857eb842844e9776ebd745fd0abf0c66c282189b1d25fc1c9d2ab84cdf206a72', 'Aura of Defiance', 'special ability', NULL, NULL, NULL, 'Aura of Defiance radiates unshakable resolve, bolstering the morale and courage of allies while instilling doubt in foes. Within its range, allies resist fear and gain improved defense, while enemies suffer hesitation and reduced combat efficiency. The aura strengthens with skill, eventually creating a zone where allies fight with unbreakable spirit and enemies feel compelled to retreat.', NULL),
  (1078, 'skill-2a24c46e0573d91c05c50e2edb1acceb5bf4c89a840d149ac60bb32c73093236', 'Runic Empowerment', 'special ability', NULL, NULL, NULL, 'Runic Empowerment grants the ability to inscribe glowing runes of power onto weapons, armor, or surfaces, infusing them with magical enhancements. Runes can grant boosts such as elemental damage, protection, or utility effects. At low mastery, runes are temporary and weak; at high mastery, they become longer-lasting, more potent, and capable of holding multiple effects. At full mastery, the runes are permanent until dispelled and can shape the flow of battle.', NULL),
  (1079, 'skill-76a65e9ccc9014c9e5156fe4d081e7e98fc709b83338752467c180dc66ca9017', 'Spell Echo', 'special ability', NULL, NULL, NULL, 'Spell Echo allows the caster to instantly recast the last spell they successfully cast without repeating the full casting process. At low mastery, the echo is weaker and costs extra mana; at high mastery, it is equally strong and costs less. At full mastery, the echo can be cast for free once per combat.', NULL),
  (1080, 'skill-0c7b876a3a77b040ba4ead044147e39f5139127bab7a9b65a659eeeb870497d1', 'Blood Pact', 'special ability', NULL, NULL, NULL, 'Blood Pact allows the user to bind their vitality to fuel power, sacrificing health to enhance abilities or magic. At low mastery, small health sacrifices yield moderate boosts; at high mastery, larger boosts are possible with reduced risk. At full mastery, the pact can briefly grant overwhelming power at near-death cost.', NULL),
  (1081, 'skill-4955dae02366c9fbe4629a96b6607ca7e77945de4606792a0328a4422ea6b244', 'Tactical Reload', 'special ability', NULL, NULL, NULL, 'Tactical Reload grants the user extreme efficiency when reloading weapons or resetting combat tools. At low mastery, reloads are slightly faster; at high mastery, they are instant and can include weapon swaps. At full mastery, reloading can occur mid-action without breaking flow.', NULL),
  (1082, 'skill-dc0ff04c346a564701e33af6c6a7f107441a722232786172e51cbaa24b35a9fa', 'Illusion Weaving', 'special ability', NULL, NULL, NULL, 'Illusion Weaving lets the user create and control complex illusions. At low mastery, illusions are simple and static; at high mastery, they are multi-sensory, interactive, and can cover large areas. At full mastery, illusions can fully deceive even magical senses until directly contradicted.', NULL),
  (1083, 'skill-a86558a1c6b394bab0d779c8d03b381cc27f2b0a3916b55a00b0cecadd1b23c3', 'Blade Dance', 'special ability', NULL, NULL, NULL, 'Blade Dance is a fluid combat style focusing on rapid movement and precise strikes. The user becomes a blur, delivering multiple attacks while evading counters. At low mastery, movement is quicker; at high mastery, attacks chain flawlessly with dodges. At full mastery, the user becomes nearly untouchable while striking multiple foes.', NULL),
  (1084, 'skill-ebb55d99ca7db2e93272ed06fd093f30a89ba8bef8fb79b23dafc9fe2c7bf12d', 'Mana Surge', 'special ability', NULL, NULL, NULL, 'Mana Surge allows the user to temporarily draw deeply from their internal or ambient mana reserves, greatly amplifying the potency of their spells. This surge is dangerous if uncontrolled, as the sudden influx can destabilize magical channels and cause backlash. At lower mastery, the boost is brief and taxing, leaving the caster fatigued; at higher mastery, the surge lasts longer, costs less, and can be precisely timed to unleash devastating spells. At full mastery, the caster can channel immense magical force without suffering exhaustion.', NULL),
  (1085, 'skill-0671d73197eeb906d33f6edf2ac948e7773c4d72f8d60b2c88b6a5848143b230', 'Guardian’s Stance', 'special ability', NULL, NULL, NULL, 'Guardian’s Stance transforms the user into an unyielding bulwark, improving their ability to block, parry, and resist knockback while also protecting nearby allies. At low mastery, it is simply a firmer defensive posture; at higher mastery, the stance can deflect heavy blows and shield multiple allies from harm. At full mastery, the guardian becomes nearly immovable, holding ground against overwhelming force.', NULL),
  (1086, 'skill-34b25e034a588d58189a4c448a2604929e75cf855310be2288245f6a7b8e728e', 'Vital Strike', 'special ability', NULL, NULL, NULL, 'Vital Strike is the art of striking precisely at an opponent’s weak points to maximize damage. At lower mastery, accuracy improves against exposed targets; at higher mastery, strikes are more likely to land critical hits and bypass armor. At full mastery, the user can pierce even heavily reinforced defenses with deadly efficiency.', NULL),
  (1087, 'skill-cc4cb53550b52ea5494a4ffc3eaac9b2a977017fc9d6050fb06712463f10ba2a', 'Battle Trance', 'special ability', NULL, NULL, NULL, 'Battle Trance is a focused mental state in which the user perceives combat with perfect clarity, anticipating threats before they strike. At low mastery, reaction speed and awareness improve; at higher mastery, the user can respond before an enemy fully commits to an attack. At full mastery, the user’s movements flow instinctively, chaining offense and defense seamlessly.', NULL),
  (1088, 'skill-3507eb9bf5a8697ee4f67635b19da839fd0d6f3fc4dd27a688e8e1d3d4793d86', 'Arcane Overload', 'special ability', NULL, NULL, NULL, 'Arcane Overload allows the caster to intentionally push their magical channels beyond safe limits, unleashing raw, unstable energy for overwhelming power. At lower mastery, the overload is brief and often leaves the caster drained; at higher mastery, the duration, control, and destructive potential increase. At full mastery, the caster can maintain an overload long enough to change the outcome of an entire battle, though the risk of catastrophic magical backlash remains.', NULL),
  (1089, 'skill-a3bf5bca0bc2f32b981dc298eb31cb018de4cb49bf84e73ce7c8f8cecf79bfb5', 'Spirit Bond', 'special ability', NULL, NULL, NULL, 'Spirit Bond forges a deep link between the user and a chosen spirit, familiar, or bonded creature, allowing them to share strength, senses, and even magical effects. At lower mastery, the bond is limited to emotional and sensory connection; at higher mastery, shared abilities and mutual empowerment become possible. At full mastery, the bond is seamless, allowing the two to fight, sense, and act as one.', NULL),
  (1090, 'skill-4a3a8add08844698b30db98c38154df991d8ba3d1b41316dba991b8312ee22fa', 'Battle Cry', 'special ability', NULL, NULL, NULL, 'Battle Cry channels raw emotion into a rallying shout that bolsters allies and intimidates foes. At lower mastery, it grants a minor morale boost; at higher mastery, it can break enemy resolve and strengthen allied combat prowess. At full mastery, a single cry can turn the tide of battle.', NULL),
  (1091, 'skill-05229cdf47fe86f722a14d17047841a55d7cc42f42ffa3a0ba6d95ec72dca811', 'Mind Pierce', 'special ability', NULL, NULL, NULL, 'Mind Pierce focuses psionic or magical energy into a direct mental attack, disrupting thoughts, breaking concentration, or damaging the mind itself. At lower mastery, it causes mild disorientation; at higher mastery, it can cause confusion, fear, or even unconsciousness. At full mastery, it can shatter a target’s mental defenses entirely.', NULL),
  (1092, 'skill-3f45514b748a2e99fe66c77b4f740237f58cf1e5c4192f97fcb902978b83f9f1', 'Earthshatter', 'special ability', NULL, NULL, NULL, 'Earthshatter channels immense force into the ground, creating a localized seismic shockwave. At lower mastery, it knocks enemies off balance; at higher mastery, it can damage structures and send foes sprawling. At full mastery, the impact can cause devastating battlefield-wide tremors.', NULL),
  (1093, 'skill-5aff6faa05fcc1cd03319b758ae0b1926d712d6db5f2d1d5bb3ce743940ee2e8', 'Soul Rend', 'special ability', NULL, NULL, NULL, 'Soul Rend is a devastating ability that targets the very essence of a being, bypassing physical armor to inflict direct harm on their soul or life force. At low mastery, it causes discomfort and minor spiritual disruption; at higher mastery, it can weaken vitality, sever magical bonds, and even cause lasting spiritual injury. At full mastery, Soul Rend can cripple an opponent’s spirit entirely, leaving them powerless.', NULL),
  (1094, 'skill-3967efeb0c08e745aa92092884017a8a01b9762a571231a1469f31d4186c2bdf', 'Wind Walk', 'special ability', NULL, NULL, NULL, 'Wind Walk transforms the user’s movement into swift, near-silent gliding on air currents. At lower mastery, it grants speed boosts; at higher mastery, it allows brief levitation and mid-air direction changes. At full mastery, Wind Walk enables rapid, evasive movement and near-flight capabilities.', NULL),
  (1095, 'skill-b1de9af2c2ec659d0c616aa060d4f2c7fcb0cd45852d9c600a9fc965c15e4e0f', 'Mana Burn', 'special ability', NULL, NULL, NULL, 'Mana Burn channels volatile anti-magic into a target, draining their magical reserves and converting part of it into damage. At low mastery, it burns small amounts of mana; at higher mastery, it devastates magical resources and causes physical harm. At full mastery, Mana Burn can cripple a caster entirely.', NULL),
  (1096, 'skill-db01517ec595c8eb3e78218a50af42464eb6683a301136fe6d872b539c4a305d', 'Mirror Strike', 'special ability', NULL, NULL, NULL, 'Mirror Strike is a deceptive combat technique that allows the user to instantly replicate an opponent’s attack and return it with equal or greater force. At low mastery, it can mimic only basic melee strikes; at higher mastery, it can copy complex techniques, ranged attacks, and even certain magical effects. At full mastery, Mirror Strike reflects attacks almost perfectly, turning an enemy’s power against them in real time.', NULL),
  (1097, 'skill-86bfc7e8e769b5171d0fdc651023c8592acac0861b7b2636fa9cf224dc0ca4a0', 'Spirit Chain', 'special ability', NULL, NULL, NULL, 'Spirit Chain binds the user’s essence to another creature, allowing them to share damage, senses, or even abilities for a limited duration. At low mastery, only basic sense-sharing is possible; at higher mastery, pain, health, and magical effects can be linked. At full mastery, the bond is seamless and can be used tactically for both protection and coordination.', NULL),
  (1098, 'skill-33c02ea94afb36193e4914daee07d73927c5ef7ceb57262ffa4761f7477863c1', 'Void Step', 'special ability', NULL, NULL, NULL, 'Void Step shifts the user partially into a void dimension, allowing them to vanish from the material plane for a moment and reappear elsewhere. At low mastery, this allows quick dodges; at higher mastery, longer shifts through void space are possible, bypassing barriers entirely. At full mastery, Void Step can be used to reappear at extreme distances or even behind dimensional seals.', NULL),
  (1099, 'skill-5c7fbdef9bb6df18415fab54a7a8d11441a87f5b071323c28bae26cb11c5639f', 'Celestial Beacon', 'special ability', NULL, NULL, NULL, 'Celestial Beacon summons a radiant pillar of light imbued with divine energy, bolstering allies and burning foes. At low mastery, it heals minor wounds or causes light damage to undead; at higher mastery, it greatly boosts morale, heals large areas, and smites enemies with divine power. At full mastery, the beacon’s presence can shift the course of battle entirely.', NULL),
  (1100, 'skill-a6d926358d5dd779bc8dfdec59a3b8b9fe5cf1134bbefeb993fcfe1d40c6c368', 'Runic Overload', 'special ability', NULL, NULL, NULL, 'Runic Overload forces a magical rune or glyph to release all stored power at once, causing a massive but unstable effect. At low mastery, the overload creates a small shockwave; at higher mastery, it can destroy magical constructs, shatter wards, or create area devastation. At full mastery, Runic Overload can rupture even ancient wards or catastrophically disrupt battlefield magic.', NULL),
  (1101, 'skill-ca2f4fec4f93eb864e978b1e3832e603111ae4856661929c1193581c9520f36f', 'Blood Oath', 'special ability', NULL, NULL, NULL, 'Blood Oath is a binding pact sealed in the life essence of two or more beings. Once made, the oath enforces promises with supernatural compulsion, rewarding loyalty and punishing betrayal. At lower mastery, the effects are symbolic; at higher mastery, breaking the oath inflicts severe physical, magical, or spiritual damage. At full mastery, the Blood Oath becomes nearly impossible to break without death or powerful ritual.', NULL),
  (1102, 'skill-378fec4d66e2790813066becdc659c1aad2c5322270854ec99439961e249ae60', 'Seismic Slam', 'special ability', NULL, NULL, NULL, 'Seismic Slam channels force into the ground, creating shockwaves that knock down, injure, or disrupt enemies. At low mastery, it causes a small tremor; at higher mastery, it can throw opponents into the air, break formations, or collapse structures. At full mastery, it can shatter terrain, open fissures, and devastate large battlefields.', NULL),
  (1103, 'skill-160ef61a399484401ce1ba63579742bcd339359e0d8f597e960ac18320714133', 'Hunter’s Mark', 'special ability', NULL, NULL, NULL, 'Hunter’s Mark is a tracking enchantment or instinctive focus that locks the user onto a target. At low mastery, it marks for short-term pursuit; at higher mastery, the mark persists across terrain, barriers, and magical concealment. At full mastery, the user always knows the target’s location, direction, and condition until death.', NULL),
  (1104, 'skill-60651d582adcb25b223d014d2a34d8360baac6e7fce94248e88808cdafaf9a29', 'Stormcaller', 'special ability', NULL, NULL, NULL, 'Stormcaller allows the user to summon and control localized weather phenomena, starting with light wind or rain and advancing to full-scale storms. At low mastery, it can create minor cover or discomfort; at higher mastery, it can disrupt visibility, hinder movement, and deal elemental damage. At full mastery, it can command massive lightning strikes, torrential rains, and hurricane-level winds over wide areas.', NULL),
  (1105, 'skill-0f5025540a184a6627ce2fbdd3957bf796c3879a9bfee0eb11920550773e0cf4', 'Harbinger Elf Berserker Rage', 'special ability', NULL, NULL, NULL, 'Harbinger Elf Berserker Rage is a unique fury channeled exclusively against undead creatures and necromantic forces. This rage cannot be used against living beings and is fueled by an innate connection to life. At 10%, the Elf gains a 10% bonus to all actions against undead and develops Undead Sensitivity, sensing nearby undead. At 25%, bonus increases to 25%, and hidden or obscured undead can be detected. At 50%, bonus rises to 50%, and undead locations can be pinpointed with instinctual accuracy. At 75%, bonus reaches 75%, sensing undead over great distances. At 100%, bonus is 100%, and undead can be detected with perfect clarity regardless of obstacles or distance. Bright light, holy wards, or anti-undead magic may not interfere with sensing but can still reduce combat efficiency. The rage remains a focused, devastating weapon against undeath, making Harbinger Elves unmatched undead hunters.', NULL),
  (1106, 'skill-df057dc614faa0c48f5ced653fe201548d5bef00ae8c18608a5b9dec8be37371', 'Blood Legacy', 'special ability', NULL, NULL, NULL, 'Blood Legacy is the born vampire’s unique ability to absorb the memories, skills, and experiences of those they feed upon, bypassing the need for conventional training. At its earliest level, this manifests as the retention of basic memories and simple skills, granting rudimentary proficiency without formal practice. With increased mastery, more complex skills and intermediate abilities can be taken directly from the victim’s mind, and feeding on another vampire transfers up to a quarter of their skill level. At advanced levels, even refined, high-level knowledge can be integrated seamlessly, allowing the vampire to perform with the ease of a seasoned practitioner. Near mastery, the vampire can pull not only skills but personal insight, creativity, and tactical experience, making them an unpredictable and dangerous foe. At the highest tier, the vampire becomes a living archive of countless lives, drawing on a vast pool of abilities and perspectives, though at the cost of carrying the echoes of those consumed.', NULL),
  (1107, 'skill-3b377d5304aea39d56a7080eb1ecae6a8985588f95e2000ffb068d1ded91edc3', 'Vampiric Charm', 'special ability', NULL, NULL, NULL, 'Vampiric Charm is an innate ability of born vampires, functioning like the Sphere of Charm and allowing the vampire to attempt any spell or ability from that sphere. At 10%, they can attempt basic charm spells and influence weak-willed targets; failure results in the vampire being charmed by the target. At 25%, stronger-willed individuals can be influenced, with increased charm effectiveness but the same reversal risk. At 50%, charm can affect groups and more complex spells; presence becomes nearly irresistible. At 75%, even the most strong-willed can be charmed, with precise multi-target manipulation. At 100%, the vampire can charm with maximum effectiveness, even against the most resistant minds, though reversal remains possible. The ability embodies a balance of great influence and dangerous vulnerability.', NULL),
  (1108, 'skill-78834f11349d05009572a5df213ebfbcc908fe4f2f38624e3c4b83d226a2aaac', 'Vampiric Forms', 'special ability', NULL, NULL, NULL, 'Vampiric Forms allows a vampire to transform into various forms as mastery increases. At 10%, they can shift into Bat Form for mobility and stealth. At 25%, Mist Form is unlocked, allowing vaporous escape and movement through small spaces. At 50%, they gain an Animal Form of choice, providing versatility for combat or stealth. At 75%, the vampire can fly in humanoid form, granting unmatched aerial mobility. At 100%, they unlock Terrifying Aura: a fear effect lasting 15 minutes or 2 combat steps per success, in a radius of 10 ft per success; those affected must beat the vampire’s roll with a Wisdom check to resist. Each form grants unique advantages for combat, exploration, and psychological warfare.', NULL),
  (1109, 'skill-e28654ff78b2203165d000fe9ffa936c5e5c2cd633e8bf814ab61aefbbc54dcd', 'Direct Casting', 'special ability', NULL, NULL, NULL, 'Direct Casting allows a spellcaster to cast any spell, including raw magic, without spending mana — one spell per success rolled. On failure, the caster’s mana drops to 0. At 100% mastery, failure is only possible on a roll of 001. This makes it a high-risk, high-reward ability that, when mastered, changes the nature of magical combat and resource management.', NULL),
  (1110, 'skill-81be858b7029a8125c845e6ed543014b2b67de1e56220451a2116db5148ffba9', 'Purification/Corruption', 'special ability', NULL, NULL, NULL, 'Purification/Corruption allows the user to influence sentient beings or substances over an area of 10 ft per success rolled. Effects are permanent unless undone. Can be used to purify or corrupt — e.g., cleanse poisoned water or taint it. Fearai characters have wings that visually reflect their moral path when using this power. Creative use is encouraged, with potential large-scale impact.', NULL),
  (1111, 'skill-a7698191b8ae60ede2a68b9580b544869bc857c7c16b1e289e8147dd7d7e6023', 'Shift Forms', 'special ability', NULL, NULL, NULL, 'The Shift Forms ability grants the character the power to transform between multiple distinct forms. At 10%, they begin with an animal form and a humanoid form, providing the foundation of their shapeshifting power. At 50%, they unlock a third transformation. At 75%, they gain their ultimate form. In the second and third forms, natural attacks such as claws (3 damage) and bites (4 damage) gain a Strength bonus. This ability offers diverse tactical options and rich role-playing potential as the character adapts forms to overcome different challenges.', NULL),
  (1112, 'skill-2ce9f3285d98e74b0120d8775301f490713e1e54083dce886e65a4a374443a0b', 'Natural Camouflage', 'special ability', NULL, NULL, NULL, 'Natural Camouflage allows the character to blend seamlessly into their surroundings, progressively enhancing stealth. At 10%, they gain subtle concealment; at 25%, they blend naturally with most environments; at 50%, they move almost undetected across varied terrain; at 75%, they achieve near-invisibility; and at 100%, they become virtually undetectable in any setting. This skill provides significant advantages in ambushes, reconnaissance, or evasion, and is valuable in both combat and non-combat scenarios.', NULL),
  (1113, 'skill-62eb90b2fb0e77f809a2536e6f9aa7d8ac48e900f3e5ccf7a2d83075f4462be7', 'Sense Undead', 'special ability', NULL, NULL, NULL, 'Sense Undead grants the character the ability to detect undead presence. At 10%, they sense undead vaguely within 30 ft; at 25%, within 60 ft with rough quantity info; at 50%, within 100 ft with type and strength tier; at 75%, within 150 ft with exact location and control source; and at 100%, within 300 ft with full details, including faint traces of undeath. This ability is invaluable in undead-heavy environments for anticipating threats and gaining tactical advantages.', NULL),
  (1114, 'skill-d82b839d4c24614fa17ca1bc3c77c020b47306dc7c69f70d0533192ca8ea307a', 'Dark Vision', 'special ability', NULL, NULL, NULL, 'Dark Vision grants the character the ability to see in low-light or total darkness without relying on natural light sources. Its range and clarity improve with mastery, making it invaluable for underground exploration, nocturnal missions, or dark environments. At 10% they see clearly in dim light, at 25% they perceive shapes in darkness, at 50% they see in darkness as twilight, at 75% they see clearly in total darkness up to 60 ft, and at 100% they see in total darkness as daylight up to 120 ft, unaffected by magical darkness.', NULL),
  (1115, 'skill-ac192289e7d5cfa0669f84c330877772601bf9efb52d24a6b20875430394f380', 'Magic Immunity', 'special ability', NULL, NULL, NULL, 'Magic Immunity provides progressive resistance to hostile magic, culminating in total immunity at mastery. At 10% the character reduces harmful magic effects by 10%; at 25% by 25%; at 50% by 50%; at 75% they are immune to weaker spells and take only 25% damage from strong ones; at 100% they are immune to all hostile magic. This rare defensive ability is invaluable against spellcasters and magical creatures.', NULL),
  (1116, 'skill-267118ff075c612d8283bb7e442abe0f5059952837958bafb7b0671ebbef3c7b', 'Hovering', 'special ability', NULL, NULL, NULL, 'Hovering allows the character to suspend themselves in the air without wings or devices, improving in duration, height, and maneuverability with mastery. At 10% they hover inches above ground for 30s; at 25% they hover 1 ft for 1 min with slight maneuvering; at 50% they hover 3 ft for minutes with moderate speed; at 75% they hover indefinitely up to 10 ft with high agility; at 100% they hover up to 30 ft with precision control and great speed.', NULL),
  (1117, 'skill-da9ab66dce59ae34542621f41f4359fda80dcddd16e6240aaf14e84cb7cc22d6', 'Water Breathing', 'special ability', NULL, NULL, NULL, 'Water Breathing enables the character to breathe underwater, improving in duration, comfort, and adaptability with mastery. At 10% they can breathe underwater for 10 min; at 25% for 30 min with efficient swimming; at 50% for 1 hr with deep diving capability; at 75% indefinitely with enhanced swim speed; at 100% fully adapted to underwater life, immune to pressure/depth effects, and equally at home in fresh or saltwater.', NULL),
  (1118, 'skill-03b6b3e9163de296faebe3502b998148ae0a756cbb82382a18622a4c19e1cbee', 'Flight', 'special ability', NULL, NULL, NULL, 'Flight grants the character the ability to fly, providing unmatched mobility and tactical advantages. Progression increases distance, control, speed, altitude, and carrying capacity. At 10% they can fly 100 ft with limited control; at 25% they fly 500 ft with better maneuverability and light carrying; at 50% they fly for miles at high speed with advanced maneuvers and heavy loads; at 75% they fly indefinitely at great speeds with full aerial combat capabilities; at 100% they have complete mastery, limitless altitude, extreme speed, unmatched agility, and full load capacity.', NULL),
  (1119, 'skill-c756671b04321575e83b016b33067d83019593d403d57142b2807208a06e9d62', 'Natural Leader', 'special ability', NULL, NULL, NULL, 'Leadership allows a character to inspire, rally, and guide others, enhancing morale, coordination, and combat performance. At 10% they inspire small groups within 10 ft with minor morale boosts; at 25% they inspire larger groups within 30 ft and issue basic commands; at 50% they rally squads within 60 ft with major morale boosts and strong coordination; at 75% they command battalions within 100 ft, granting large morale boosts, stamina, and resistance to fear/confusion; at 100% they command armies or factions within 300 ft, inspiring near-total loyalty and resistance to most psychological/magical effects.', NULL),
  (1120, 'skill-7df9ad06354cdd4a1dc0274d4fa60b6509316d4a47d6feb0e8005522801e0879', 'Poison Immunity', 'special ability', NULL, NULL, NULL, 'Poison Immunity progressively shields the character from toxins, venoms, and poisonous environments. At 10% they resist weak poisons (10% effect reduction); at 25% they resist moderate poisons (25% reduction); at 50% they resist a wide range of deadly toxins (50% reduction); at 75% they are immune to most poisons, only rare/magical toxins affect them (75% reduction); at 100% they are immune to all natural and magical poisons.', NULL),
  (1121, 'skill-8d4eab24d7109f581f52058ac548e3b3d912c6947970b2f6c5d3dd68cf77cce4', 'Charm Ability', 'special ability', NULL, NULL, NULL, 'Charm Ability enables the character to influence emotions, thoughts, and actions through charisma or magic. At 10% they charm one target briefly for friendliness; at 25% they charm two targets longer, persuading minor favors; at 50% they charm up to five targets for hours with moderate influence; at 75% they charm up to ten targets or resistant individuals for a day, willing to follow significant requests; at 100% they charm entire crowds or strong-willed targets for days, capable of overriding loyalties.', NULL),
  (1122, 'skill-c330809a21a46c427f7167f588599a49eed23b60470e92b0b855e881bc4103e5', 'Keen Hearing', 'special ability', NULL, NULL, NULL, 'Keen Hearing sharpens the auditory senses beyond natural limits, enabling the user to detect sounds most would never notice. At its earliest stages, this means catching faint noises at modest distances, like a twig snapping or the creak of a door hinge. As mastery develops, the user can distinguish individual sounds even in crowded or noisy environments, isolating a single voice or footstep from a chaotic soundscape. At higher levels, the sense penetrates through light barriers such as thin walls or foliage, granting an edge in both exploration and combat. True masters can identify the source and nature of a sound with pinpoint accuracy over vast distances, detecting even a racing heartbeat or the whisper of movement hundreds of feet away.', NULL),
  (1123, 'skill-ac0a3e8a339d5760bfec7fca7ac38494c09fa07289eb97c2fec42fd86cfaec9b', 'Keen Sense of Smell', 'special ability', NULL, NULL, NULL, 'Keen Sense of Smell grants an extraordinary olfactory range, allowing the user to perceive, separate, and interpret scents with remarkable precision. Initially, this manifests as detecting strong or distinctive odors within close proximity, useful for basic tracking or environmental awareness. With training, the user can differentiate and follow multiple scent trails simultaneously, even in complex environments. At advanced levels, faint or masked scents become clear, enabling accurate pursuit of targets and detection of hidden dangers. At its peak, the sense extends over great distances, cutting through barriers and revealing detailed chemical or biological information about the source, making it invaluable for hunters, trackers, and scouts.', NULL),
  (1124, 'skill-776235435739f44acaa6cd8d04d7d4e4aaf14f9f1e3fd93bd6d22537392361e6', 'Keen Eyesight', 'special ability', NULL, NULL, NULL, 'Keen Eyesight heightens visual acuity to superhuman levels, enabling detection of fine details and subtle movements far beyond normal range. At low mastery, the user enjoys sharper vision and clarity over medium distances, spotting things others would miss. Progression brings the ability to track minute motion and identify hidden threats such as traps or concealed objects. Higher levels enhance performance in low-light conditions, allowing precision even in dim environments. At maximum mastery, the user perceives with perfect clarity over extreme distances in any lighting, making them virtually immune to visual deception.', NULL),
  (1125, 'skill-59e9c87b172cda8c8c48428b649cc51b78b84b4b15a6567b494147559d5f2d53', 'Vampiric Magical Immunities', 'special ability', NULL, NULL, NULL, 'Vampiric Magical Immunities offer a supernatural resilience to most forms of magic, honed by an innate predatory resistance to arcane forces. At low mastery, this grants a modest resistance to harmful magical effects, though vulnerabilities to Life and Fire magic remain extreme. As mastery increases, the user shrugs off a greater proportion of magical assaults, deflecting enchantments, curses, and elemental attacks alike. High mastery renders all but the most potent magic nearly harmless, forcing even powerful mages to rely on the user’s weaknesses to inflict harm. At peak performance, the user approaches complete immunity to every magical discipline except Life and Fire—against which they remain dangerously susceptible.', NULL),
  (1126, 'skill-661081977d5904d181a409cc57f0234fcdb1b6179a70fe0fc254790d74a2cdb5', 'Dragon Fire', 'special ability', NULL, NULL, NULL, 'Dragon Fire channels the primal destructive force of flame into a breath weapon of increasing potency and control. At lower levels, the user can exhale short bursts of searing heat capable of scorching foes and igniting flammable surfaces. With practice, the flames intensify, spreading over wider areas and delivering sustained burning damage. Advanced mastery allows the wielder to manipulate the breadth and shape of their flame, creating walls of fire or precision bursts. At its apex, Dragon Fire becomes an inferno that can engulf entire battlefields, overwhelming enemies and altering the environment itself with sheer heat and devastation.', NULL),
  (1127, 'skill-3ac9f0973a913a2c784d50460d7453b5978abbc336d851483c3bad55eee116a5', 'Dragon Acid', 'special ability', NULL, NULL, NULL, 'Dragon Acid manifests as a highly corrosive breath weapon, dissolving organic and inorganic material alike. At early stages, it can inflict painful burns and light damage, but its true danger lies in the lingering effect that continues to erode armor, weapons, and flesh over time. With increased skill, the acid grows stronger and lasts longer, able to eat through hardened steel or stone. Expert practitioners can target specific weak points, rendering even the most durable defenses useless. At full mastery, the acid becomes a battlefield hazard in its own right, leaving lasting damage to terrain, structures, and any foe unfortunate enough to be caught in its path.', NULL),
  (1128, 'skill-600cc6ecf638954095e25a1a360738c0d4479375979d8fc793355f81259d81ff', 'Dragon Spark', 'special ability', NULL, NULL, NULL, 'Dragon Spark unleashes lightning in concentrated bursts or branching arcs, capable of chaining between multiple targets. Initially, it delivers a quick jolt—enough to stun and cause moderate harm. As skill improves, the electrical discharge grows in intensity and reach, finding new targets through conductive materials like metal armor or wet surfaces. Mastery enables fine control, allowing the wielder to strike individual foes with surgical precision or spread damage across a cluster of enemies. At its highest level, Dragon Spark can black out entire areas, overload equipment, and render heavily armored units helpless before the raw power of the storm.', NULL),
  (1129, 'skill-0ffc46b6ca107aa322e62a8f6b96117e96c63278ec174e3e1bff1dc66eea3981', 'Dragon Frost', 'special ability', NULL, NULL, NULL, 'Dragon Frost breathes forth a chilling wind capable of slowing, freezing, and immobilizing targets. Beginners can coat foes in ice and reduce mobility, making them easier to strike or evade. With practice, the frost grows more intense, spreading across wider areas and freezing surfaces solid. At advanced stages, the wielder can trap multiple targets in ice simultaneously, controlling the flow of battle through terrain manipulation. At peak strength, Dragon Frost can encase entire groups or structures in solid ice, halting movement entirely and reshaping the battlefield into a frozen domain.', NULL),
  (1130, 'skill-857cc0be2737c618231a3e2c013d78c319b7aa9384a49e34767deaba42115673', 'Dragon Sleep', 'special ability', NULL, NULL, NULL, 'Dragon Sleep is a mystical exhalation that bypasses armor and physical defenses, sending foes into a deep, magical slumber. At the most basic level, it affects a single target for a short duration. With greater control, the effect can spread to multiple targets, each falling into a longer and harder-to-resist sleep. Mastery allows the wielder to suppress wakefulness entirely in an area, creating moments of tactical dominance without inflicting physical harm. At full power, Dragon Sleep can incapacitate entire squads, forcing enemies into helplessness for extended periods and leaving them vulnerable to capture or strategic repositioning.', NULL),
  (1131, 'skill-017881543b6002105c21838d4b82c1414895025f9f92cf52ca31a5aab3e4425c', 'Elemental Dragon Breath', 'special ability', NULL, NULL, NULL, 'Elemental Dragon Breath allows the user to weave multiple elemental forces—fire, acid, frost, lightning, and beyond—into a single devastating attack. Beginners channel a single element, tailoring their assault to the foe’s weaknesses. As mastery grows, multiple elements can be layered together, overwhelming defenses that rely on resistance to only one type of damage. High-level practitioners can dynamically shift elements mid-attack, adapting instantly to the flow of battle. At its ultimate level, Elemental Dragon Breath unleashes every elemental force at once in a catastrophic display, obliterating anything in its path.', NULL),
  (1132, 'skill-b8de62960a577598b3d4b3d55155cbc1d2ce85cf5f82e3242a2c32746ee6a710', 'Full Sphere Access', 'special ability', NULL, NULL, NULL, 'Full Sphere Access unlocks the wielder’s ability to command magical spheres beyond the limits of their intellect or training. At low levels, this means learning an additional sphere and applying extra skill to spell rolls. With progression, more spheres become available, increasing magical versatility and strategic depth. Higher mastery reduces the mana cost of casting, allowing for more frequent or sustained spell use. At its height, Full Sphere Access grants complete control over every magical sphere and allows certain spells to be cast without expending mana at all, creating a nearly limitless reservoir of magical potential.', NULL),
  (1133, 'skill-ccb2b6e437baa2d9dd492345f47a979a9c4419a5a44009ad3c4156cdffce6fff', 'Echolocation', 'special ability', NULL, NULL, NULL, 'Echolocation allows the user to navigate and perceive surroundings via sound wave emissions and echo interpretation, functioning even in complete darkness. At 10%, the user detects large objects and general surroundings to avoid obstacles. At 25%, they detect smaller objects and moving targets, improving awareness. At 50%, they identify materials or creature types in the vicinity. At 75%, they can pinpoint structural or anatomical weak points, gaining combat or strategic bonuses. At 100%, they can emit a focused sonic blast to damage or disorient enemies. Effectiveness decreases in noisy or sound-dampened environments, possibly requiring higher roll success or imposing penalties.', NULL),
  (1134, 'skill-af40c9ad6057b1a9cea731453c3bade9207cf8742ea52303c8d42dad2310e7bd', 'Umbral Veil', 'special ability', NULL, NULL, NULL, 'Umbral Veil is the art of vanishing into absence itself—whether slipping between real shadows, cloaking within the static of a glitched datafeed, or bending perception so that the mind refuses to notice you. At lower mastery, it’s little more than enhanced stealth, but still enough to fade from casual sight or slip past inattentive guards. As skill deepens, the veil becomes an active shroud that distorts both light and digital signals, masking movement and presence even from advanced detection systems. Masters of the veil can walk through security checkpoints or across a battlefield unseen, using darkness and distortion as both shield and weapon. At its peak, Umbral Veil doesn’t simply hide you—it convinces the world you were never there to begin with.', NULL),
  (1135, 'skill-22affd70f307bb4b3729ce5b42c03a8192f3d0b96349142b22bb8c5e9bef853e', 'Glamour Shift', 'special ability', NULL, NULL, NULL, 'Glamour Shift is the disciplined fusion of illusion and physical modulation, allowing the user to alter their form as effortlessly as changing clothes. At its most basic, it smooths imperfections or tweaks small details—enough to bypass casual recognition. With training, these changes expand into complete masks: voice, gait, posture, and even the micro-expressions that betray impostors. True masters can assume a flawless likeness of another, fooling both human senses and sophisticated biometric scanners for extended periods. Whether for infiltration, performance, or survival, Glamour Shift turns identity into a fluid tool—letting its wielder become anyone, anywhere, at any time.', NULL),
  (1136, 'skill-f93e3c3c647a320eb0f12e2b8183234688ff363e8aa86585f746f04171cb4bc7', 'Moonshadow Omen', 'special ability', NULL, NULL, NULL, 'Moonshadow Omen allows the Argent Sanguis to channel lunar resonance, weaving glimpses of possible futures directly into their actions. This foresight grows stronger with mastery, from momentary flashes to complete pre-battle awareness. At 10%, they can manipulate fate in small bursts, granting quick corrections to immediate mistakes. At 25%, they can enter a half-lucid trance to read surface thoughts and spot hidden ethereal dangers. At 50%, they extend their foresight as a protective veil to nearby allies, enhancing defense and evasion. At 75%, they can alter the flow of battle itself by forcing an enemy to change course mid-action. At 100%, they enter a state of perfect prophecy, acting before others can move and perceiving all within their reach with absolute clarity. Activation is at will; failure results in prophetic overload—stunned for 1 combat step and –10 to all rolls until scene end.', NULL);

-- A source identity distinguishes canonical records from user-created Skills,
-- even when both intentionally use the same display name.
INSERT OR IGNORE INTO skills (
    name,
    classification,
    tier,
    primary_attribute,
    secondary_attribute,
    definition,
    created_by_user_id,
    source_system,
    source_external_id
)
SELECT
    name,
    classification,
    tier,
    primary_attribute,
    secondary_attribute,
    definition,
    NULL,
    'serrian-tide-core',
    source_external_id
FROM _serrian_tide_skill_seed
ORDER BY ordinal;

INSERT OR IGNORE INTO skill_relationships (
    skill_id,
    related_skill_id,
    relationship_type,
    sort_order
)
SELECT
    child.id,
    parent.id,
    'parent',
    0
FROM _serrian_tide_skill_seed child_seed
JOIN skills child
  ON child.source_system = 'serrian-tide-core'
 AND child.source_external_id = child_seed.source_external_id
JOIN _serrian_tide_skill_seed parent_seed
  ON parent_seed.name = child_seed.parent_name COLLATE NOCASE
JOIN skills parent
  ON parent.source_system = 'serrian-tide-core'
 AND parent.source_external_id = parent_seed.source_external_id
WHERE child_seed.parent_name IS NOT NULL;

DROP TABLE _serrian_tide_skill_seed;
